def _clean_workflow_field(value: Any) -> str:
    return str(value or "").strip().strip("*` ")


def _extract_labeled_value(text: str, *labels: str) -> str:
    wanted = {str(label or "").strip() for label in labels if str(label or "").strip()}
    for raw_line in str(text or "").splitlines():
        line = raw_line.strip().lstrip("-*• ")
        match = re.match(r"^([^：:]{1,40})\s*[：:]\s*(.+?)\s*$", line)
        if match and match.group(1).strip() in wanted:
            return _clean_workflow_field(match.group(2))
    return ""


def _extract_markdown_table_value(text: str, *labels: str) -> str:
    wanted = {str(label or "").strip() for label in labels if str(label or "").strip()}
    for raw_line in str(text or "").splitlines():
        line = raw_line.strip()
        if not line.startswith("|"):
            continue
        cells = [_clean_workflow_field(cell) for cell in line.strip("|").split("|")]
        if len(cells) >= 2 and cells[0] in wanted:
            return cells[1]
    return ""


