def _workflow_handoff_fields(
    metadata: dict[str, Any],
    *,
    original: str,
    intake_note: str,
) -> dict[str, Any]:
    """Build clean business fields from the intake turn's durable evidence."""

    customer_name = _clean_workflow_field(metadata.get("customer_name")) or _extract_labeled_value(
        original,
        "客户名称",
        "客户名",
    )
    brand_name = _clean_workflow_field(metadata.get("brand_name")) or _extract_markdown_table_value(
        intake_note,
        "品牌名称",
        "品牌名",
    ) or _extract_labeled_value(original, "品牌名称", "品牌名")
    industry = _clean_workflow_field(metadata.get("industry")) or _extract_markdown_table_value(
        intake_note,
        "行业 / 产品",
        "行业/产品",
        "行业",
    ) or _extract_labeled_value(original, "行业 / 产品", "行业/产品", "行业")
    return {
        "customer_name": customer_name or "客户",
        "brand_name": brand_name or "见需求单",
        "industry": industry or "见需求单",
        "notes": ("已审需求单：\n" + intake_note) if intake_note else original,
    }


# The order field that carries the parent contract of a child order (written by the invoke node only).
PARENT_CONTRACT_FIELD = "_workflow_parent"


def _workflow_parent_contract(task: Any, node: dict[str, Any], target: str, *, order: Any | None = None) -> dict[str, Any]:
    """Build the bounded, durable parent context for one child workflow.

    This is business lineage, not a second runtime hierarchy.  In particular we
    do not overwrite Task.parent_id / parent_session_id: those fields belong to
    the execution engine's own company-mode topology.

    ``order`` is the order the invoking task works for, when the caller could establish it. A work item only
    carries its order, customer and environment if the order has an allowance or a browser delegation; without
    either, the child order used to be created for no customer at all -- invisible to that customer's accounts and
    missing from their portfolio. What the task says itself still comes first.
    """
    metadata = dict(getattr(task, "metadata", {}) or {})
    for key, value in (("order_id", getattr(order, "order_id", "")), ("customer_id", getattr(order, "customer_id", "")),
                       ("environment_id", getattr(order, "environment_id", ""))):
        if str(value or "").strip() and not str(metadata.get(key, "") or "").strip():
            metadata[key] = str(value).strip()
    task_id = str(getattr(task, "id", "") or "").strip()
    node_id = str(node.get("id", "") or "").strip()
    order_id = str(metadata.get("order_id", "") or "").strip()
    correlation_id = str(metadata.get("correlation_id", "") or order_id or task_id).strip()
    artifact_refs: list[str] = []
    raw_refs = list(metadata.get("artifact_refs", []) or [])
    raw_refs.extend(list(dict(node.get("invoke", {}) or {}).get("artifact_refs", []) or []))
    for raw in raw_refs:
        value = str(raw or "").replace("\\", "/").strip()
        path = Path(value)
        if not value or path.is_absolute() or ".." in path.parts:
            continue
        if value not in artifact_refs:
            artifact_refs.append(value[:500])
        if len(artifact_refs) >= 100:
            break
    return {
        "schema_version": 1,
        "parent_task_id": task_id,
        "parent_session_id": str(getattr(task, "session_id", "") or "").strip(),
        "parent_order_id": order_id,
        "node_id": node_id,
        "target_workflow_id": str(target or "").strip(),
        "customer_id": str(metadata.get("customer_id", "") or "").strip(),
        "environment_id": str(metadata.get("environment_id", "") or "").strip(),
        # An order's allowance is not written here. It can be replaced or lifted while the order runs, and this
        # contract is durable: it is part of what makes a re-run of the same node recover the same child order, so a
        # value that changes under it would turn that recovery into "a different child order". The child takes the
        # allowance from this task as it is when the child starts (``_apply_workflow_parent_contract``).
        "budget_id": "" if _is_order_allowance(metadata) else str(metadata.get("budget_id", "") or "").strip(),
        "correlation_id": correlation_id,
        "causation_id": f"workflow-node:{task_id}:{node_id}",
        "artifact_refs": artifact_refs,
    }


def _workflow_invocation_key(parent: dict[str, Any]) -> str:
    identity = {
        "schema_version": 1,
        "parent_task_id": str(parent.get("parent_task_id", "") or ""),
        "node_id": str(parent.get("node_id", "") or ""),
        "target_workflow_id": str(parent.get("target_workflow_id", "") or ""),
    }
    digest = hashlib.sha256(
        json.dumps(identity, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
    ).hexdigest()
    return f"workflow-node:{digest}"


def _add_execution_turn_aliases(
    payload: dict[str, Any],
    runtime_task_id: Any | None = None,
) -> dict[str, Any]:
    """Add canonical UI aliases for runtime Task / execution turn identity."""
    task_id = str(
        runtime_task_id
        or payload.get("runtime_task_id")
        or payload.get("execution_turn_id")
        or payload.get("task_id")
        or ""
    ).strip()
    if task_id:
        payload.setdefault("runtime_task_id", task_id)
        payload.setdefault("execution_turn_id", task_id)
    return payload


def _is_cjk_title_char(ch: str) -> bool:
    cp = ord(ch)
    return (
        0x3400 <= cp <= 0x4DBF
        or 0x4E00 <= cp <= 0x9FFF
        or 0xF900 <= cp <= 0xFAFF
        or 0x3040 <= cp <= 0x30FF
        or 0xAC00 <= cp <= 0xD7AF
    )


def _compact_session_title(content: str, *, max_units: int = 10, fallback: str = "New Chat") -> str:
    text = re.sub(r"\s+", " ", str(content or "")).strip()
    if not text:
        return fallback
    if max_units <= 0:
        return fallback

    units = 0
    index = 0
    cut_index = len(text)
    while index < len(text):
        ch = text[index]
        if ch.isspace():
            index += 1
            continue
        if _is_cjk_title_char(ch):
            units += 1
            index += 1
            if units == max_units:
                cut_index = index
                break
            continue
        if (ch.isalnum() or ch == "_") and not _is_cjk_title_char(ch):
            while (
                index < len(text)
                and (text[index].isalnum() or text[index] == "_")
                and not _is_cjk_title_char(text[index])
            ):
                index += 1
            units += 1
            if units == max_units:
                cut_index = index
                break
            continue
        index += 1

    compact = text[:cut_index].strip() or fallback
    has_more_units = any(
        _is_cjk_title_char(ch) or ((ch.isalnum() or ch == "_") and not _is_cjk_title_char(ch))
        for ch in text[cut_index:]
    )
    return f"{compact}..." if has_more_units else compact


