class _AckRecorder:
    """Stands in for a client socket when a handler is invoked internally.

    Handlers answer with ``_send_ack``, which writes to the socket it was
    given; the master-control turn needs that answer as data, so it hands
    the handler this object and reads the last acknowledgement back.
    """

    closed = False
    closing = False

    def __init__(self, on_behalf_of: Any = None) -> None:
        self.messages: list[dict[str, Any]] = []
        # Whose socket this is standing in for. The router authorizes the
        # incoming message before any of this runs, so a handler reached
        # internally is acting for that person -- but the owner check resolves
        # an account from the object it is handed, and a recorder is in no
        # account map. Without this an owner's own console action is refused
        # as `owner_required` the moment authentication is switched on.
        self.on_behalf_of = on_behalf_of

    async def send_json(self, payload: dict[str, Any]) -> None:
        self.messages.append(dict(payload or {}))

    @property
    def last_ack(self) -> dict[str, Any] | None:
        for message in reversed(self.messages):
            if message.get("type") == "ack":
                return dict(message.get("payload") or {})
        return None


class _WSInbox:
    """One connection's incoming messages.

    A ping is answered by the reader the moment it arrives. Everything else is
    handled by one worker, one message at a time, in arrival order -- the order
    the reader used to handle them in itself. While they wait, identical reads
    are merged: a request exactly equal (type and every field) to one still
    queued is folded into it instead of being handled again. That covers
    ``session_detail`` (the page re-asks for a session's whole transcript on
    every message and status change; each answer costs the server ~0.6 s of
    CPU on a real project) and ``collab_sync`` (~1.3 s each). A merged
    ``session_detail`` still gets its own answer, because the page pairs those
    answers with its requests one to one; the page pairs nothing with
    ``collab_sync`` answers, so one answer serves them all. A request already
    being handled is never merged into: whatever asks after it started gets an
    answer built after it asked.

    Since AV : the owner's actions go first. Anything that is not a
    known pure read (``PURE_READ_TYPES``) -- an answer to a card, an order
    action, a switch of project -- is handled before the reads still waiting
    (reads keep their order among themselves, and so do actions); a click used
    to wait behind half a minute of queued syncs and the page gave up on its
    receipt. A read is not merged into a copy queued before an action that
    arrived between them. When the socket has closed, the reads still waiting
    are dropped (nobody is there to see the answer); actions are still handled.
    """

    MERGEABLE_TYPES = frozenset({"session_detail", "collab_sync"})
    ANSWER_EACH_MERGED = frozenset({"session_detail"})
    # Only requests that change nothing the owner could miss: safe to answer
    # after a later action, and to drop once the page is gone. Everything else
    # (including reads that leave an audit record, such as order_list) counts
    # as an action.
    PURE_READ_TYPES = MERGEABLE_TYPES | frozenset({
        "project_index",
        "org_info",
        "list_projects",
        # S3-2A: reads of the project centre; they record nothing.
        "project_profile_get",
        "project_connections_get",
        "list_agents",
        "session_list",
        "my_tasks_list",
        "blockers_list",
        # S3-3A 总控: the standing reads of 「等你处理」 and where a card lives; they record nothing.
        "owner_attention_list",
        "checkpoint_locate",
        "gate_status",
        "duty_log_list",
        "workflow_list",
        "settings_get",
        "org_saved_list",
        "reorg_list",
        "browser_session_list",
        "external_team_activity_get",
    })
    MAX_WAITING = 200

    def __init__(self, handler: Any, ws: Any) -> None:
        from collections import deque

        self._handler = handler
        self._ws = ws
        # Each item: [raw, parsed, merge_key, merged_count, is_read].
        self._reads: deque[list[Any]] = deque()
        self._actions: deque[list[Any]] = deque()
        self._waiting_by_key: dict[str, list[Any]] = {}
        self._wakeup = asyncio.Event()
        self._room = asyncio.Event()
        self._room.set()
        self._finishing = False
        self._abandoned = False
        self._failure: BaseException | None = None
        self.reads_dropped = 0
        self._worker = asyncio.create_task(self._run(), name="ampuly-ws-inbox")

    @property
    def waiting(self) -> int:
        return len(self._reads) + len(self._actions)

    @classmethod
    def _is_pure_read(cls, parsed: Any) -> bool:
        return isinstance(parsed, dict) and parsed.get("type") in cls.PURE_READ_TYPES

    def _socket_open(self) -> bool:
        try:
            return bool(self._handler._ws_is_open(self._ws))
        except Exception:
            return True

    @staticmethod
    def _decode(raw: Any) -> Any:
        try:
            return json.loads(raw)
        except (TypeError, ValueError):
            return None

    def _merge_key(self, parsed: Any) -> str | None:
        if not isinstance(parsed, dict) or parsed.get("type") not in self.MERGEABLE_TYPES:
            return None
        try:
            return json.dumps(parsed, sort_keys=True, default=str)
        except (TypeError, ValueError):
            return None

    async def accept(self, raw: Any) -> None:
        """Take one text frame from the reader."""
        parsed = self._decode(raw)
        if isinstance(parsed, dict) and parsed.get("type") == "ping":
            await self._handler._answer_ws_ping(self._ws)
            return
        is_read = self._is_pure_read(parsed)
        if not is_read:
            # An action in between: a later read must not fold into a copy
            # queued before it, or it would be answered with what was true
            # before the action.
            self._waiting_by_key.clear()
        key = self._merge_key(parsed) if is_read else None
        if key is not None:
            waiting = self._waiting_by_key.get(key)
            if waiting is not None:
                waiting[3] += 1
                return
        # A page flooding the socket is held at the reader again, as before.
        while self.waiting >= self.MAX_WAITING and not self._worker.done():
            self._room.clear()
            await self._room.wait()
        item: list[Any] = [raw, parsed, key, 0, is_read]
        (self._reads if is_read else self._actions).append(item)
        if key is not None:
            self._waiting_by_key[key] = item
        self._wakeup.set()

    def _next_item(self) -> list[Any] | None:
        # The owner's actions first; reads in arrival order after them.
        if self._actions:
            return self._actions.popleft()
        if self._reads:
            return self._reads.popleft()
        return None

    def _drop_waiting_reads(self) -> None:
        dropped = sum(1 + int(item[3]) for item in self._reads)
        self._reads.clear()
        self._waiting_by_key.clear()
        self._room.set()
        if dropped:
            self.reads_dropped += dropped
            logger.debug("WS closed: {} queued read(s) dropped unanswered", dropped)

    async def _run(self) -> None:
        try:
            while True:
                item = self._next_item()
                if item is None:
                    if self._finishing:
                        return
                    self._wakeup.clear()
                    await self._wakeup.wait()
                    continue
                self._room.set()
                raw, parsed, key, _merged, is_read = item
                if key is not None and self._waiting_by_key.get(key) is item:
                    del self._waiting_by_key[key]
                if is_read and self._finishing and not self._socket_open():
                    # The page is gone: nobody will read this answer.
                    self.reads_dropped += 1 + int(item[3])
                    continue
                # Read after the item left the waiting map: nothing merges into it any more.
                merged = int(item[3])
                message_type = parsed.get("type") if isinstance(parsed, dict) else None
                await self._handler._route_message(
                    self._ws,
                    raw,
                    parsed=parsed if isinstance(parsed, dict) else None,
                    reply_copies=merged if message_type in self.ANSWER_EACH_MERGED else 0,
                )
        except asyncio.CancelledError:
            if not self._abandoned and not bool(getattr(self._handler, "_shutting_down", False)):
                # A request's own cancellation used to escape the reader and end the
                # connection; end it here too, so the page reconnects instead of
                # waiting on a queue nobody serves.
                logger.warning("WS connection task cancelled unexpectedly")
                self._close_socket_soon()
            raise
        except Exception as exc:
            # Same outcome as when the reader handled requests itself: the error
            # ends the connection and handle_ws logs it (``finish`` re-raises).
            self._failure = exc
            self._close_socket_soon()

    def _close_socket_soon(self) -> None:
        close = getattr(self._ws, "close", None)
        if not callable(close):
            return
        try:
            result = close()
            if inspect.isawaitable(result):
                asyncio.ensure_future(result)
        except Exception:
            logger.opt(exception=True).debug("WS close after a failed request did not go through")

    async def finish(self) -> None:
        """The socket closed: handle the actions that had already arrived, then stop.

        Reads still waiting are dropped when the socket is really closed; a
        socket still open (the reader stopped for another reason) gets them all.
        """
        self._finishing = True
        if not self._socket_open():
            self._drop_waiting_reads()
        self._wakeup.set()
        await asyncio.wait({self._worker})
        if self._worker.cancelled():
            return
        failure, self._failure = self._failure, None
        if failure is not None:
            raise failure

    def abandon(self) -> None:
        """Stop without handling what is still queued (the connection task itself is ending)."""
        self._abandoned = True
        if not self._worker.done():
            self._worker.cancel()


class _EventLoopWatchdog:
    """Says in the log when the event loop stops answering, and what was holding it.

    The console once kept one core at 100% for tens of minutes, the page lost
    its connection every minute or two, and nothing in the log said what the
    process was doing. A daemon thread posts a probe to the loop every
    ``interval`` seconds; a probe still unanswered after ``threshold`` seconds
    means the loop has been held that long -- by one long callback or by a
    queue of them. It then logs one WARNING (at most one per ``warn_every``
    seconds) naming the WS requests being handled at that moment, the task the
    loop is running and the innermost ``stack_frames`` frames of the loop
    thread's stack. Every ``cpu_window`` seconds it also logs how much CPU this
    process used over that window: a WARNING above ``cpu_warn_ratio`` of one
    core, INFO otherwise.
    """

    def __init__(
        self,
        loop: asyncio.AbstractEventLoop,
        *,
        threshold: float = 2.0,
        interval: float = 0.5,
        stack_frames: int = 15,
        warn_every: float = 60.0,
        cpu_window: float = 300.0,
        cpu_warn_ratio: float = 0.8,
        describe_actions: Any = None,
        is_stopping: Any = None,
        clock: Any = None,
        cpu_clock: Any = None,
    ) -> None:
        import threading

        # Wall clock and this process's CPU clock; tests pass their own (AV).
        self._clock = clock if callable(clock) else time.monotonic
        self._cpu_clock = cpu_clock if callable(cpu_clock) else time.process_time
        # Built on the loop's own thread: that is the stack a stall is read from.
        self._loop = loop
        self._loop_thread_id = threading.get_ident()
        self._threshold = float(threshold)
        self._interval = float(interval)
        self._stack_frames = max(1, int(stack_frames))
        self._warn_every = float(warn_every)
        self._cpu_window = float(cpu_window)
        self._cpu_warn_ratio = float(cpu_warn_ratio)
        self._describe_actions = describe_actions
        self._is_stopping = is_stopping
        self._probe_posted_at: float | None = None
        self._last_warning_at: float | None = None
        self._stop = threading.Event()
        self._thread: Any = None
        self.stalls_reported = 0
        self.cpu_reports = 0

    @property
    def alive(self) -> bool:
        thread = self._thread
        return thread is not None and thread.is_alive()

    def start(self) -> None:
        import threading

        if self.alive:
            return
        self._stop.clear()
        self._thread = threading.Thread(target=self._run, name="ampuly-loop-watchdog", daemon=True)
        self._thread.start()

    def stop(self, timeout: float = 2.0) -> None:
        import threading

        self._stop.set()
        thread = self._thread
        if thread is not None and thread.is_alive() and thread is not threading.current_thread():
            thread.join(timeout)

    def _probe_answered(self) -> None:
        # Runs on the loop.
        self._probe_posted_at = None

    def _run(self) -> None:
        cpu_since_wall = self._clock()
        cpu_since_used = self._cpu_clock()
        while not self._stop.wait(self._interval):
            try:
                if self._loop.is_closed() or (callable(self._is_stopping) and self._is_stopping()):
                    return
                now = self._clock()
                posted = self._probe_posted_at
                if posted is None:
                    self._probe_posted_at = now
                    try:
                        self._loop.call_soon_threadsafe(self._probe_answered)
                    except RuntimeError:
                        return  # the loop has closed
                elif now - posted >= self._threshold:
                    self._report_stall(now - posted, now)
                if now - cpu_since_wall >= self._cpu_window:
                    cpu_since_wall, cpu_since_used = self._report_cpu(cpu_since_wall, cpu_since_used, now)
            except Exception:
                logger.opt(exception=True).debug("loop watchdog: one check failed")

    def _report_stall(self, held_for: float, now: float) -> None:
        import sys
        import traceback

        if self._last_warning_at is not None and now - self._last_warning_at < self._warn_every:
            return
        self._last_warning_at = now
        self.stalls_reported += 1
        stack = "(the loop thread's stack could not be read)"
        try:
            frame = sys._current_frames().get(self._loop_thread_id)
            if frame is not None:
                frames = traceback.extract_stack(frame)[-self._stack_frames:]
                stack = "".join(traceback.format_list(frames)).rstrip()
        except Exception:
            pass
        actions = ""
        if callable(self._describe_actions):
            try:
                actions = str(self._describe_actions() or "")
            except Exception:
                actions = "?"
        running = ""
        try:
            task = asyncio.current_task(self._loop)
            if task is not None:
                coro = task.get_coro()
                running = f"{task.get_name()} {getattr(coro, '__qualname__', '')}".strip()
        except Exception:
            running = ""
        logger.warning(
            "Event loop held for {:.1f}s; WS requests in progress: {}; running task: {}; "
            "loop thread stack (innermost last):\n{}",
            held_for,
            actions or "none",
            running or "none",
            stack,
        )

    def _report_cpu(self, since_wall: float, since_used: float, now: float) -> tuple[float, float]:
        used_now = self._cpu_clock()
        wall = max(1e-9, now - since_wall)
        used = max(0.0, used_now - since_used)
        ratio = used / wall
        self.cpu_reports += 1
        if ratio > self._cpu_warn_ratio:
            logger.warning(
                "Console process used {:.1f}s of CPU in the last {:.0f}s ({:.0%} of one core)",
                used, wall, ratio,
            )
        else:
            logger.info(
                "Console process used {:.1f}s of CPU in the last {:.0f}s ({:.0%} of one core)",
                used, wall, ratio,
            )
        return now, used_now


def master_history_rows(raw_history: Any) -> list[dict[str, Any]]:
    """The conversation rows a master turn is shown, with what each reply looked at.

    A reply row records the tools it called (names and read/write) in its
    metadata; carrying the names along lets a later turn -- on either
    path -- see that an answer came from `master_list_orders`, not from
    memory. Names only: results are not replayed into a later prompt.
    """
    rows: list[dict[str, Any]] = []
    for m in list(raw_history or []):
        if not isinstance(m, dict) or m.get("sender") not in ("user", "assistant"):
            continue
        row: dict[str, Any] = {
            "role": ("user" if m.get("sender") == "user" else "assistant"),
            "content": str(m.get("content", ""))[:600],
        }
        calls = dict(m.get("metadata", {}) or {}).get("master_tool_calls")
        if isinstance(calls, list):
            names = [str(c.get("name", "") or "") for c in calls if isinstance(c, dict) and c.get("name")]
            if names:
                row["tools"] = names[:12]
        rows.append(row)
    return rows


# P-f : one stored message of a project's 总控 conversation, read by its id or by what its files still say --
# not by scanning the newest few hundred rows. Read with the chat store's own row reader; a store without one (a
# stand-in) is read the old way.
_MASTER_MESSAGE_COLUMNS = "message_id, channel_id, sender, sender_name, content, timestamp, reply_to_id, mentions, metadata"


def _master_channels_clause(project_id: str) -> tuple[str, tuple[Any, ...]]:
    """SQL for "a channel of one of this project's 总控 conversations" (总控对话栏, policy): its first
    conversation's ``master:{pid}`` or a later one's ``master:{pid}:{thread}`` (``master_control.master_channel_id``).
    A prefix compared with ``substr``, never ``LIKE``: an underscore in a project id is not a wildcard."""
    from ampuly.plugins.office_ui.master_control import master_channel_id

    base = master_channel_id(project_id)
    return "(channel_id = ? OR substr(channel_id, 1, ?) = ?)", (base, len(base) + 1, base + ":")


async def _master_message_by_id(chat_store: Any, project_id: str, message_id: str) -> dict[str, Any] | None:
    """The 总控 message with this id, however old it is and in whichever of the project's 总控 conversations it was
    said; None when there is none. Message ids are unique, so the id alone finds the conversation too."""
    from ampuly.plugins.office_ui.master_control import master_channel_id

    db = getattr(chat_store, "_db", None)
    to_dict = getattr(chat_store, "_row_to_message_dict", None)
    if db is not None and callable(to_dict):
        clause, params = _master_channels_clause(project_id)
        cursor = await db.execute(
            f"SELECT {_MASTER_MESSAGE_COLUMNS} FROM messages WHERE message_id = ? AND project_id = ? AND {clause} LIMIT 1",
            (message_id, project_id, *params),
        )
        row = await cursor.fetchone()
        return to_dict(row) if row is not None else None
    # A stand-in store without the row reader: the first conversation only, read the old way.
    rows = await chat_store.get_channel_messages(master_channel_id(project_id), limit=200, project_id=project_id)
    return next((row for row in rows if str(row.get("message_id", "") or "") == message_id), None)


async def _master_channel_of_message(chat_store: Any, project_id: str, message_id: str) -> str:
    """The 总控 conversation (its channel) a message was said in; the project's first conversation when the message
    is not found (a turn with no stored message, a stand-in store). What a draft made by 安安 records as the
    conversation it came from (``conversation_id`` of a connector candidate or an improvement proposal)."""
    from ampuly.plugins.office_ui.master_control import master_channel_id

    clean = str(message_id or "").strip()
    if clean and chat_store is not None:
        try:
            found = await _master_message_by_id(chat_store, project_id, clean)
        except Exception:  # noqa: BLE001 - provenance falls back to the first conversation; the draft still stands
            found = None
        channel = str((found or {}).get("channel_id", "") or "")
        if channel:
            return channel
    return master_channel_id(project_id)


async def _master_thread_of_message(chat_store: Any, project_id: str, message_id: str) -> str:
    """The 总控 conversation (its thread id) a message was said in -- for a turn, the conversation it runs in, whose
    id is the turn's console session id. "" when it cannot be said (no stored message, a stand-in store without the
    conversation column): the caller then means the project's first conversation, as before conversations were split.
    """
    of_channel = getattr(chat_store, "master_thread_of_channel", None)
    if chat_store is None or not callable(of_channel) or not str(message_id or "").strip():
        return ""
    pid = str(project_id or "default")
    try:
        row = await of_channel(pid, await _master_channel_of_message(chat_store, pid, message_id))
    except Exception:  # noqa: BLE001 - unknown is the first conversation; nothing is refused for it
        logger.opt(exception=True).warning("master control: the conversation of a message could not be read")
        return ""
    return str((row or {}).get("thread_id", "") or "")


async def _master_messages_left_reading(chat_store: Any, project_id: str) -> list[dict[str, Any]]:
    """The 总控 messages -- of every 总控 conversation of the project -- whose files a status still says 排队 / 解析中
    (a cheap pre-filter; the caller checks each)."""
    from ampuly.plugins.office_ui.master_control import master_channel_id

    db = getattr(chat_store, "_db", None)
    to_dict = getattr(chat_store, "_row_to_message_dict", None)
    if db is not None and callable(to_dict):
        clause, params = _master_channels_clause(project_id)
        cursor = await db.execute(
            f"SELECT {_MASTER_MESSAGE_COLUMNS} FROM messages WHERE project_id = ? AND {clause} "
            "AND metadata LIKE ? AND (metadata LIKE ? OR metadata LIKE ?) ORDER BY timestamp ASC",
            (project_id, *params, '%"attachments_read"%', '%"queued"%', '%"reading"%'),
        )
        return [to_dict(row) for row in await cursor.fetchall()]
    rows = await chat_store.get_channel_messages(master_channel_id(project_id), limit=500, project_id=project_id)
    return [row for row in rows if isinstance(row, dict) and dict(row.get("metadata") or {}).get("attachments_read")]


async def _master_messages_with_attachment(chat_store: Any, project_id: str, attachment_id: str) -> list[dict[str, Any]]:
    """The 总控 messages -- of every 总控 conversation of the project -- whose metadata names this attachment id, newest
    first (a cheap pre-filter on the stored text; the caller checks each). A stand-in store: the first conversation's
    newest 200, as before."""
    from ampuly.plugins.office_ui.master_control import master_channel_id

    db = getattr(chat_store, "_db", None)
    to_dict = getattr(chat_store, "_row_to_message_dict", None)
    if db is not None and callable(to_dict):
        clause, params = _master_channels_clause(project_id)
        cursor = await db.execute(
            f"SELECT {_MASTER_MESSAGE_COLUMNS} FROM messages WHERE project_id = ? AND {clause} "
            "AND instr(metadata, ?) > 0 ORDER BY timestamp DESC, rowid DESC LIMIT 50",
            (project_id, *params, json.dumps(str(attachment_id))),
        )
        return [to_dict(row) for row in await cursor.fetchall()]
    rows = await chat_store.get_channel_messages(master_channel_id(project_id), limit=200, project_id=project_id)
    return list(reversed([row for row in rows if isinstance(row, dict)]))


async def _master_thread_row(chat_store: Any, project_id: str, thread_id: str) -> dict[str, Any] | None:
    """This project's 总控 conversation ``thread_id`` in the column (总控对话栏), or None: not one of this project's,
    not a well-formed id, or a store that keeps no column (a stand-in) or cannot be read now."""
    from ampuly.plugins.office_ui.master_threads import valid_thread_id

    getter = getattr(chat_store, "get_master_thread", None)
    clean = str(thread_id or "").strip()
    if not callable(getter) or not valid_thread_id(clean):
        return None
    try:
        return await getter(str(project_id or "default"), clean)
    except Exception:  # noqa: BLE001 - an unreadable column answers "not found"; the caller says so or falls back
        logger.opt(exception=True).warning("master control: the conversation column could not be read")
        return None


async def _master_thread_touch(
    chat_store: Any, project_id: str, thread_id: str, *, at: Any = None, first_words: str = "",
) -> None:
    """Something was said in this 总控 conversation: its last activity moves on, and a conversation with no title yet
    takes the first owner message cut to 24 characters (``master_threads.first_words``). Never takes a turn down."""
    from ampuly.plugins.office_ui.master_threads import first_words as cut

    touch = getattr(chat_store, "touch_master_thread", None)
    if not callable(touch) or not str(thread_id or "").strip():
        return
    try:
        when = float(at) if at is not None else None
    except (TypeError, ValueError):
        when = None
    try:
        await touch(str(project_id or "default"), str(thread_id), at=when, title_if_empty=cut(first_words) if first_words else "")
    except Exception:  # noqa: BLE001 - the column's order is display; the words are stored
        logger.opt(exception=True).warning("master control: the conversation's last activity was not recorded")


class MasterAnswer(tuple):
    """What a master write handler returns -- the tuple every caller unpacks -- plus ``detail`` for the model.

    The handler's sentence is what the owner reads under 安安's reply (the loop's receipts), so it is said in the
    owner's words: no candidate ids, fingerprints or engine codes. ``detail`` carries what only the model needs --
    the ids it may refer to next, the engine's own wording of a refusal -- and the loop hands it back beside the
    receipt, never inside it.
    """

    detail: dict[str, Any]

    def __new__(cls, items: tuple, detail: dict[str, Any] | None = None) -> "MasterAnswer":
        answer = super().__new__(cls, items)
        answer.detail = dict(detail or {})
        return answer


def _master_note(ok: bool, zh_text: str, en_text: str, **facts: Any) -> MasterAnswer:
    """``(ok, note)`` in the console's language; in Chinese the English wording and the ids go to ``detail``."""
    from ampuly.i18n_runtime import is_zh

    detail = {key: value for key, value in facts.items() if value not in (None, "", [], {})}
    if is_zh():
        detail["message"] = en_text
        return MasterAnswer((bool(ok), zh_text), detail)
    return MasterAnswer((bool(ok), en_text), detail)


# An improvement proposal's status in the owner's words (the page says the same: lib/improvementProposal.ts).
_PROPOSAL_STATUS_ZH = {"draft": "草稿", "materialized": "候选已生成", "approved": "已批准", "rejected": "已打回"}


# An id the owner must never read: a uuid, a fingerprint, a candidate's hex tail.
_INTERNAL_ID = re.compile(
    r"[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-"
    r"|(?<![0-9a-zA-Z])(?=[0-9a-f]*[0-9])(?=[0-9a-f]*[a-f])[0-9a-f]{12,}(?![0-9a-zA-Z])"
)


def _owner_words(text: Any) -> str:
    """The engine's own reason when it is already said in Chinese (many refusals are); '' otherwise.

    Chinese means mostly Chinese: an English message that quotes one Chinese title is still English, and a sentence
    carrying an internal id is not passed on either -- the caller's own wording stands in for both.
    """
    clean = str(text or "").strip()
    chinese = sum(1 for ch in clean if "一" <= ch <= "鿿")
    if not chinese:
        return ""
    latin = sum(1 for ch in clean if ch.isascii() and ch.isalpha())
    if latin > 2 * chinese or _INTERNAL_ID.search(clean):
        return ""
    return clean


def _owner_clock(value: Any) -> str:
    """A stored timestamp as the owner reads it: 「9月27日 10:00」, with the year only when it is not this one."""
    text = str(value or "").strip()
    try:
        moment = datetime.fromisoformat(text)
    except ValueError:
        return text
    year = f"{moment.year}年" if moment.year != datetime.now().year else ""
    return f"{year}{moment.month}月{moment.day}日 {moment:%H:%M}"


class MasterReceipt(str):
    """A control verb's receipt -- the plain string every caller joins into the reply -- plus ``detail`` for the model.

    The string is what the owner reads under 安安's reply; ``detail`` keeps the engine's own code and the English
    wording, and the loop hands it to the model beside the receipt (master_loop.write), never inside it.
    """

    detail: dict[str, Any]

    def __new__(cls, text: str, detail: dict[str, Any] | None = None) -> "MasterReceipt":
        receipt = super().__new__(cls, text)
        receipt.detail = dict(detail or {})
        return receipt


def _master_order_flows(handler: Any, project_id: str) -> list[dict[str, Any]]:
    """The flows this project takes orders on, for the single-call master turn (policy, M1).

    The same answer master_list_order_flows gives the loop (master_order_draft.order_flows). Never raises: a console
    whose flows cannot be read gives the turn none, and a draft is then refused by the handler in words.
    """
    from ampuly.plugins.office_ui import master_order_draft as drafting

    registry = getattr(handler, "_workflow_registry", None)
    if not callable(registry):
        return []
    try:
        return list(drafting.order_flows(list(registry()), project_id, drafting.adoption_reader(handler))["order_flows"])
    except Exception:  # noqa: BLE001 - no flows is an honest answer; the turn still runs
        logger.opt(exception=True).warning("master: order flows unreadable for the single-call turn")
        return []


class _MasterBuildHost:
    """This console as a build job sees it (总控施工模式, policy, B1: master_build.BuildHost).

    The one place a build reaches the handler's members. Messages go into the project's 总控 conversation and are
    broadcast like any of 安安's; the activity ack goes to the socket that started or continued the job.
    """

    def __init__(self, handler: Any) -> None:
        self._handler = handler

    def ampuly_home(self) -> Path:
        # No guess at a default: a build's records and drafts live in the engine's own home or nowhere.
        home = getattr(getattr(self._handler, "engine", None), "ampuly_home", None)
        if not home:
            raise RuntimeError("the console's engine has no home; build mode is unavailable")
        return Path(home)

    def packages(self) -> list[Any]:
        return list(self._handler._workflow_registry())

    def business(self) -> Any:
        return self._handler._accounts().business

    async def engine(self, project_id: str) -> Any:
        return await self._handler._engine_for_project(project_id)

    def team_org(self, team: str) -> tuple[str, Path | None]:
        from ampuly.plugins.office_ui.flow_compiler import flow_draft_team

        chosen, _roles = flow_draft_team(str(team or "").strip())
        if not chosen:
            return "", None
        try:
            return chosen, _saved_org_path(chosen, strict=False)
        except ValueError:
            return chosen, None

    async def post(self, project_id: str, text: str, metadata: dict[str, Any], *, thread_id: str = "") -> None:
        from ampuly.i18n_runtime import is_zh
        from ampuly.plugins.office_ui.master_build import project_is_here
        from ampuly.plugins.office_ui.master_control import master_channel_id

        pid = str(project_id or "default")
        if not project_is_here(self.ampuly_home(), pid):
            # A project deleted under a build: a late message would make its deleted conversation again.
            logger.info(f"master build: no message into project {pid!r}; the project is gone")
            return
        chat_store = self._handler.chat_store
        # 总控对话栏: the conversation the job was started from. A job with none (recorded before conversations were
        # split), or one whose conversation is not in the column any more, speaks in the project's first conversation.
        thread = await _master_thread_row(chat_store, pid, thread_id) if thread_id else None
        if thread is not None and not thread.get("legacy"):
            channel = str(thread["channel_id"])
            await chat_store.ensure_master_channel(project_id=pid, channel_id=channel)
        else:
            channel = master_channel_id(pid)
            await chat_store.ensure_master_channel(project_id=pid)
        row = await chat_store.insert_message(
            channel_id=channel, sender="assistant", sender_name="总控" if is_zh() else "Master Control",
            content=text, metadata=metadata, project_id=pid,
        )
        if thread is not None:
            await _master_thread_touch(chat_store, pid, str(thread["thread_id"]), at=row.get("created_at"))
        await self._handler.broadcast({"type": "session_message", "payload": row})

    async def activity(self, ws: Any, fields: dict[str, Any]) -> None:
        if ws is None or getattr(ws, "closed", False):
            return
        await self._handler._send_ack(ws, **fields)

    async def threads_changed(self, ws: Any, project_id: str) -> None:
        """A build's state changed (总控对话栏): the project's conversation column is sent again to the socket that
        started or continued the build, so its 「有施工在跑 / 等你回话」 dots follow without the page asking."""
        if ws is None or getattr(ws, "closed", False):
            return
        await WSHandler._master_send_thread_list(self._handler, ws, str(project_id or "default"))

    def spawn(self, coro: Any) -> asyncio.Task[Any]:
        return self._handler._track(coro)

    def settings(self) -> dict[str, Any]:
        from ampuly.plugins.office_ui.settings_service import build_setting

        return {"model": build_setting("master_build_model"), "model_calls": build_setting("master_build_model_calls")}


# Why a control verb (approve / deny a checkpoint, stop an order, interrupt or steer its turn) did not go through, in
