def _budget_error_zh(text: Any, *, nested: bool = False, reason: bool = False) -> str:
    """What a budget said, as the owner reads it (``snapshot_builder.budget_error_zh``); ``reason``: a hold's or a
    close's reason, whose untranslated text is said to be a reason rather than a step that failed."""
    from ampuly.plugins.office_ui.snapshot_builder import BUDGET_REASON_UNKNOWN_ZH, BUDGET_UNKNOWN_ZH, budget_error_zh

    return budget_error_zh(text, nested=nested, unknown=BUDGET_REASON_UNKNOWN_ZH if reason else BUDGET_UNKNOWN_ZH)


def _budget_refusal(raw: Any) -> dict[str, str]:
    """A budget route's refusal: ``error`` in the owner's words for the page, ``engine_error`` as it was said."""
    said = str(raw or "").strip()
    return {"error": _budget_error_zh(said) or said, "engine_error": said}


def _budget_for_owner(budget: Any, *, nested: bool = False) -> Any:
    """One budget as the page shows it: ``state_reason`` in the owner's words, the stored text as ``state_reason_raw``.
    ``nested``: the reason goes inside another sentence, where an untranslated one is left out."""
    if not isinstance(budget, dict):
        return budget
    raw = str(budget.get("state_reason", "") or "")
    # Nested inside the engine's own sentence (「…（{reason}）。」): no full stop of its own, or it reads 「。）。」.
    said = _budget_error_zh(raw, nested=True).rstrip("。") if nested else (_budget_error_zh(raw, reason=True) or raw)
    return {**budget, "state_reason": said, "state_reason_raw": raw}


def _budgets_for_owner(budgets: Any) -> list[Any]:
    return [_budget_for_owner(item) for item in list(budgets or [])]


def _budget_context_note(pause_request: Any) -> dict[str, str]:
    """A pause request's note as its card shows it (``snapshot_builder.budget_context_note``)."""
    from ampuly.plugins.office_ui.snapshot_builder import budget_context_note

    return budget_context_note(pause_request)


def _socket_behind(ws: Any) -> Any:
    """The client socket an object stands for -- itself, for a real socket.

    Handlers reached internally are handed an _AckRecorder in place of a
    socket, and every identity question here resolves an account by looking
    the socket up in a map the recorder is not in. Without this an owner's
    own console action is refused as owner_required the moment
    authentication is switched on, and an employee's customer scope silently
    becomes unrestricted-looking rather than theirs.

    Resolving is all this does. A recorder standing in for nobody is nobody.
    """
    return getattr(ws, "on_behalf_of", None) or ws


def _socket_principal_state(handler: Any) -> tuple[Any, Any, dict[int, tuple[Any, Any]]]:
    """Existing server store only; no constructor, token copy or owner mint."""
    store = getattr(handler, "_account_store", None)
    if type(store) is not _SocketAccountStore:
        raise SocketPrincipalBindingError("unavailable") from None
    state = getattr(handler, "_socket_principal_bindings_state", None)
    if state is None:
        state = (store, SocketPrincipalBindings(store), {})
        handler._socket_principal_bindings_state = state
    if (
        type(state) is not tuple or len(state) != 3 or state[0] is not store
        or type(state[1]) is not SocketPrincipalBindings
        or state[1]._store is not store
        or type(state[2]) is not dict
        or len(state[2]) > _MAX_SOCKET_PRINCIPAL_BINDINGS
    ):
        raise SocketPrincipalBindingError("invalid_source") from None
    return state


def _socket_principal_entry(entries: Any, raw_ws: Any) -> tuple[Any, Any] | None:
    """One identity lookup; strong references exclude socket id reuse."""
    if type(entries) is not dict or len(entries) > _MAX_SOCKET_PRINCIPAL_BINDINGS:
        raise SocketPrincipalBindingError("invalid_source") from None
    key = id(raw_ws)
    if key not in entries:
        return None
    entry = entries[key]
    if (
        type(entry) is not tuple or len(entry) != 2 or entry[0] is not raw_ws
        or type(entry[1]) is not _SocketPrincipalBinding
    ):
        raise SocketPrincipalBindingError("invalid_source") from None
    return entry


def _current_socket_principal(
    handler: Any, ws: Any, *, expected_binding: Any = None,
) -> Any:
    """Fresh mutable Account, not permission; invalid bound is never None."""
    state = _socket_principal_state(handler)
    _, manager, entries = state
    raw_ws = _socket_behind(ws)
    entry = _socket_principal_entry(entries, raw_ws)
    if expected_binding is not None:
        if type(expected_binding) is not _SocketPrincipalBinding:
            raise SocketPrincipalBindingError("invalid_source") from None
        if entry is None or entry[1] is not expected_binding:
            raise SocketPrincipalBindingError("binding_changed") from None
    # A logout keeps this expected reference as a tombstone. Even if the leaf
    # slot is gone, resolve raises rather than allowing bootstrap fallback.
    binding = entry[1] if entry is not None else None
    account = manager.resolve(raw_ws, expected_binding=binding)
    if (
        _socket_principal_state(handler) is not state
        or _socket_principal_entry(entries, raw_ws) is not entry
    ):
        raise SocketPrincipalBindingError("binding_changed") from None
    if account is not None and entry is None:
        raise SocketPrincipalBindingError("invalid_source") from None
    return account


async def _current_socket_principal_async(
    handler: Any, ws: Any, *, reader: Any, expected_binding: Any,
) -> Any:
    """First egress observation; all slot/token checks stay on the loop."""
    state = _socket_principal_state(handler)
    _, manager, entries = state
    raw_ws = _socket_behind(ws)
    entry = _socket_principal_entry(entries, raw_ws)
    if (type(expected_binding) is not _SocketPrincipalBinding
            or entry is None or entry[1] is not expected_binding):
        raise SocketPrincipalBindingError("binding_changed") from None
    account = await SocketPrincipalBindings.resolve_async(
        manager, raw_ws, reader=reader, expected_binding=expected_binding,
    )
    if (_socket_principal_state(handler) is not state
            or _socket_principal_entry(entries, raw_ws) is not entry):
        raise SocketPrincipalBindingError("binding_changed") from None
    return account


def _bind_socket_principal(handler: Any, ws: Any, token: Any) -> tuple[Any, Any]:
    _, manager, entries = _socket_principal_state(handler)
    raw_ws = _socket_behind(ws)
    before = _socket_principal_entry(entries, raw_ws)
    if before is None and len(entries) >= _MAX_SOCKET_PRINCIPAL_BINDINGS:
        raise SocketPrincipalBindingError("capacity_exceeded") from None
    binding = manager.bind(raw_ws, token)
    # Publish before the second current read: a now-expired/revoked principal
    # must stay known-bound even though its success ACK was never sent.
    entries[id(raw_ws)] = (raw_ws, binding)
    account = _current_socket_principal(handler, ws, expected_binding=binding)
    if account is None:
        raise SocketPrincipalBindingError("unavailable") from None
    return account, binding


def _forget_socket_principal(
    handler: Any, ws: Any, *, expected_binding: Any, disconnect: bool = False,
) -> bool:
    _, manager, entries = _socket_principal_state(handler)
    raw_ws = _socket_behind(ws)
    if type(expected_binding) is not _SocketPrincipalBinding:
        raise SocketPrincipalBindingError("invalid_source") from None
    entry = _socket_principal_entry(entries, raw_ws)
    if entry is None or entry[1] is not expected_binding:
        return False
    forgotten = manager.forget(raw_ws, expected_binding=expected_binding)
    if disconnect and _socket_principal_entry(entries, raw_ws) is entry:
        # False also covers an already-forgotten logout tombstone. Never pop
        # a later rebind's entry, including a same-token later login.
        del entries[id(raw_ws)]
    return forgotten


async def _socket_logout_cleanup_handler(handler: Any, ws: Any, data: dict) -> None:
    """Server-selected invalid-binding cleanup, not a role/worker grant."""
    await handler._handle_auth_logout(ws, data, _binding_cleanup_only=True)


def _ws_owner_actor(handler: Any, ws: Any) -> dict[str, str] | None:
    """The person behind a socket for owner-only actions.

    An authenticated account counts by its role; a socket without one is the
    local console owner only while no accounts exist. A real store's cache is
    not authority, and a stale binding never becomes an owner.
    """
    try:
        account = _current_socket_principal(handler, ws)
    except SocketPrincipalBindingError as exc:
        # Store-less handler (console double/CLI): see store_less_owner_actor.
        if exc.code != "unavailable" or getattr(handler, "_account_store", None) is not None:
            return None
        return store_less_owner_actor(handler, ws)
    except Exception:
        return None
    if account is not None:
        return {
            "kind": "authenticated_account",
            "login": account.login,
            "role": account.role,
        }
    getter = getattr(handler, "_accounts", None)
    if not callable(getter):
        return None
    try:
        if getter().auth_required():
            return None
    except Exception:
        return None
    return {"kind": "local_console_owner", "login": "owner", "role": "owner"}


def ws_customer_scope(handler: Any, ws: Any) -> tuple[str, ...]:
    """Customers this socket may see; empty means unrestricted.

    Read Previously, the customer filter came from the request, so an
    employee could ask for another customer's orders and the server obeyed.
    """
    # Do not turn an invalid binding into unrestricted-looking (). Callers
    # must refuse this fixed failure, not substitute the old cached Account.
    return scope_with_store_less_fallback(_current_socket_principal, handler, ws)


def resolve_customer_scope(allowed: tuple[str, ...], requested: str) -> tuple[str, bool]:
    """Intersect an account's binding with what the request asked for.

    Returns ``(effective_customer_id, denied)``.  A bound account asking for
    a customer outside its binding is denied rather than silently narrowed,
    so the caller never believes it saw that customer's whole picture.  A
    bound account asking for nothing is narrowed to its own binding when it
    holds exactly one customer; with several, the caller must name one.
    """
    clean = str(requested or "").strip()
    if not allowed:
        return clean, False
    if clean:
        return (clean, False) if clean in allowed else ("", True)
    return (allowed[0], False) if len(allowed) == 1 else ("", True)


def _is_order_allowance(metadata: dict[str, Any]) -> bool:
    from ampuly.layer4_tools.spend_guard import is_order_allowance

    return is_order_allowance(metadata)


def project_customer_denied(handler: Any, ws: Any, project_id: str) -> tuple[bool, str]:
    """Whether this socket may enter a project; returns ``(denied, customer_id)``.

    A project *is* a customer's delivery space: its memory, its workspace and
    its artifacts live there.  Narrowing the order list alone left the files
    reachable to anyone who switched projects, so a bound account is checked
    against the project's own binding.  Fail closed on both sides -- an
    unbound project is not "everyone's", it is "not yet assigned", and a
    bound account has no business in it.
    """
    from ampuly.plugins.office_ui.scope import resolve_customer

    allowed = ws_customer_scope(handler, ws)
    if not allowed:
        return False, ""
    try:
        bound = str(handler._accounts().business.project_customer(project_id) or "").strip()
    except Exception:
        # Fail closed: a bound account may not enter what cannot be attributed.
        return True, ""
    # One rule, shared with every other entry: see ampuly/plugins/office_ui/scope.py
    decision = resolve_customer(account_customers=allowed, project_customer=bound)
    return decision.denied, bound


def names_another_customers_project(handler: Any, ws: Any, project_id: str) -> bool:
    """Whether a customer-bound socket is naming a project that belongs to somebody else's customer.

    Entering a project is checked by ``project_customer_denied``; but every other request names its own
    ``project_id``, so a bound account could read another customer's acceptance or audit trail without ever
    switching there. This is the rule for those requests: a project bound to a customer outside the account's
    binding is refused before any handler runs. An unbound project is not refused here -- the bound employee's own
    task list is asked for from wherever the console stands -- and what lives in it is narrowed per record instead.
    """
    allowed = ws_customer_scope(handler, ws)
    if not allowed or not str(project_id or "").strip():
        return False
    try:
        bound = str(handler._accounts().business.project_customer(project_id) or "").strip()
    except Exception:
        return True  # fail closed: a bound account may not read what cannot be attributed
    return bool(bound) and bound not in allowed


def visible_projects_for_scope(handler: Any, ws: Any, projects: list[dict]) -> list[dict]:
    """The project entries this socket may see, each carrying its binding."""
    try:
        bindings = handler._accounts().business.project_customers()
    except Exception:
        bindings = {}
    allowed = ws_customer_scope(handler, ws)
    out: list[dict] = []
    for entry in projects:
        pid = str(entry.get("id", "") or entry.get("project_id", "") or "")
        customer = str(bindings.get(pid, "") or "")
        row = {**entry, "customer_id": customer}
        if allowed and customer not in allowed:
            continue
        out.append(row)
    return out


def _freeze_order_steps(
    order_root: Path, order_id: str, steps: list[dict[str, Any]], *, workflow_id: str = "", workflow_version: str = ""
) -> bool:
    """Write the order's step table once; return whether this call wrote it.

    Display only: the console shows an order's files step by step from it. A relaunch never rewrites a valid table, so
    it stays the one the order started with even when the package changes. The table is written to a staging file,
    flushed to disk and published only where none exists (a hard link fails on an existing name), so a crash never
    leaves a table cut short; one its reader would not read (``_step_table_is_valid``: the reader's rule) is replaced.
    """
    from ampuly.core.config import replace_with_retry
    from ampuly.core.order_layout import STEP_TABLE, step_segment

    rows = []
    for node in steps or []:
        if not isinstance(node, dict):
            continue
        node_id = str(node.get("id", "") or "").strip()
        if not node_id:
            continue
        rows.append({
            "id": node_id,
            "segment": step_segment(node.get("id", "")),  # computed as the runtime computes it for the task
            "name": str(node.get("name", "") or node_id),
            "writes": [str(x) for x in list(node.get("writes", []) or []) if str(x).strip()],
            "deliverables": [str(x) for x in list(node.get("deliverables", []) or []) if str(x).strip()],
        })
    payload = json.dumps(
        {"schema": 1, "order_id": order_id, "workflow_id": workflow_id, "workflow_version": workflow_version, "steps": rows},
        ensure_ascii=False, indent=2,
    )
    path = order_root / STEP_TABLE
    if path.exists() and _step_table_is_valid(path, order_id):
        return False
    # The runtime-internal prefix keeps the staging file out of every model's listing and reach.
    staged = order_root / f".ampuly-write-order-steps-{uuid.uuid4().hex}.tmp"
    try:
        with open(staged, "x", encoding="utf-8") as handle:
            handle.write(payload)
            handle.flush()
            os.fsync(handle.fileno())
        try:
            os.link(staged, path)
            return True
        except FileExistsError:
            pass
        except OSError:
            if not path.exists():
                replace_with_retry(staged, path)  # a volume without hard links
                return True
        if _step_table_is_valid(path, order_id):
            return False
        replace_with_retry(staged, path)
        return True
    finally:
        staged.unlink(missing_ok=True)


def _step_table_is_valid(path: Path, order_id: str) -> bool:
    """Whether the table at ``path`` is one its reader takes: the reader's own rule (``order_folder.read_step_table``,
    C5-2) -- a plain file with one name, within its size, a JSON object of schema 1 (not ``true``) naming this order. A
    table the reader would call invalid, too large, a link or missing is rewritten at launch, never kept."""
    from ampuly.core.order_layout import STEP_TABLE
    from ampuly.plugins.office_ui.order_folder import read_step_table

    return path.name == STEP_TABLE and read_step_table(path.parent, order_id).ok


def _workflow_browser_scope(
    steps: list[dict[str, Any]] | None, *, workflow_id: str = "", workflow_version: str = ""
) -> dict[str, Any]:
    """The browser delegation a flow writes on its order's run at launch; ``{}`` for a flow with no connector step.

    B5 : the sites the flow's connector steps name (``allowed_domains``, read by ``connector_summary``
    exactly as the running step reads them -- nothing is parsed here) are joined into the same record the console's
    ``master_delegate_browser`` writes, under its keys. The work items inherit that record from the order
    (``browser_scope.inherit_browser_scope``), the domain gate admits those hosts, and the network permission card
    is not asked again for them (``native_permissions.browser_scope_delegated``). It never widens a step: a connector
    step's own sites still narrow its browser below the order (``browser_bridge.CONNECTOR_DOMAINS_FLAG``). PULY (JEV)
    may pick a connector step's low-risk browser steps unless the owner says no (policy).
    """
    from datetime import timezone

    from ampuly.plugins.office_ui.browser_connector import connector_summary

    hosts: set[str] = set()
    for node in list(steps or []):
        if not isinstance(node, dict):
            continue
        summary = connector_summary(node)
        if summary is None:
            continue
        hosts.update(str(host) for host in list(summary.get("allowed_domains", []) or []) if str(host or "").strip())
    if not hosts:
        return {}
    return {
        "browser_allowed_domains": sorted(hosts),
        "browser_allow_decider": True,
        "browser_delegated_by": f"workflow:{workflow_id}@{workflow_version}",
        "browser_delegated_at": datetime.now(timezone.utc).isoformat(),
    }


def order_id_from_artifact_path(path: str) -> str:
    """``orders/wo-2026…/output/x.png`` -> ``wo-2026…``; ``""`` when not an order file.

    Every project folder keyed by order counts (order_layout.ORDER_KEYED_ROOTS): an order's acceptance history and
    exports belong to its customer as much as its deliverables do (data phase 1).
    """
    from ampuly.core.order_layout import classify
    from ampuly.plugins.office_ui.artifacts_service import artifact_path_parts

    if not str(path or "").strip():
        return ""
    parts = artifact_path_parts(path)
    return str(classify("/".join(parts)).get("order_id", "") or "")


def _is_portfolio_export(path: str) -> bool:
    from ampuly.core.order_layout import PORTFOLIO_EXPORTS, classify
    from ampuly.plugins.office_ui.artifacts_service import artifact_path_parts

    if not str(path or "").strip():
        return False
    return classify("/".join(artifact_path_parts(path))).get("area") == PORTFOLIO_EXPORTS


def artifact_customer_denied(handler: Any, ws: Any, project_id: str, path: str) -> tuple[bool, str]:
    """Whether this socket may read a deliverable; returns ``(denied, customer_id)``.

    Deliverables live under ``orders/<order_id>/``, so a file inherits its
    order's customer. Without this an employee bound to one customer could
    still read another customer's files by path. Files outside
    an order carry no customer and stay project-scoped.
    """
    allowed = ws_customer_scope(handler, ws)
    if not allowed:
        return False, ""
    try:
        order_id = order_id_from_artifact_path(path)
        portfolio = _is_portfolio_export(path)
    except ValueError:
        return True, ""
    if portfolio:
        # Named by an opaque hash: the order, and so the customer, cannot be recovered from the path.
        return True, ""
    if not order_id:
        return False, ""
    try:
        order = handler._console_api().order(order_id, project_id=project_id) or {}
    except Exception:
        # Fail closed: a bound account may not read what cannot be attributed.
        return True, ""
    customer = str(order.get("customer_id", "") or "").strip()
    return (customer not in allowed), customer


def filter_artifact_index_for_scope(handler: Any, ws: Any, project_id: str, index: Any) -> Any:
    """Drop deliverables belonging to customers this socket is not bound to.

    Group counts are recomputed from what survives, so the panel never shows
    a count the viewer cannot open.
    """
    allowed = ws_customer_scope(handler, ws)
    if not allowed or not isinstance(index, dict):
        return index
    files = [f for f in list(index.get("files", []) or []) if isinstance(f, dict)]
    kept = [f for f in files if not artifact_customer_denied(handler, ws, project_id, str(f.get("path", "") or ""))[0]]
    if len(kept) == len(files):
        return index
    counts: dict[str, int] = {}
    for item in kept:
        counts[str(item.get("group", "") or "")] = counts.get(str(item.get("group", "") or ""), 0) + 1
    groups = [
        {**group, "count": counts.get(str(group.get("name", "") or ""), 0)}
        for group in list(index.get("groups", []) or [])
        if isinstance(group, dict) and counts.get(str(group.get("name", "") or ""), 0) > 0
    ]
    return {**index, "files": kept, "groups": groups}


def _ws_is_owner(handler: Any, ws: Any) -> bool:
    """Sixteen Builder handlers used to demand an authenticated account and so
    refused every owner action on a loopback console."""
    actor = _ws_owner_actor(handler, ws)
    return bool(actor) and actor.get("role") == "owner"


async def _ws_refuse_other_projects_flow(
    handler: Any, ws: Any, *, action: str, project_id: str, workflow_id: str, doing: str = "动", **extra: Any,
) -> bool:
    """One project is one customer: a flow another project owns is refused at every console entry that acts on a flow
    by id (usable_by_project, as the list, orders, trials and preflight already do). Sends the refusal and returns True
    when the flow is another project's; a flow that is not loaded is left to the entry's own not-found path. The
    sentence reaches the owner as it is, so it is said in words; ``error_code`` is the stable name for scripts.
    """
    from ampuly.plugins.office_ui.workflow_packages import usable_by_project

    find_package = getattr(handler, "_workflow_package", None)
    found = find_package(workflow_id) if callable(find_package) else None
    # A package without a manifest (a test double) has no owner and is taken as global.
    if found is None or not isinstance(getattr(found, "manifest", None), dict) or usable_by_project(found, project_id):
        return False
    await handler._send_ack(
        ws, ok=False, action=action, project_id=project_id, workflow_id=workflow_id,
        error=f"这条流程属于别的项目，这里不能{doing}它", error_code="other_projects_flow", **extra,
    )
    return True


def _folder_token(project_id: str, scope: str, target: Path) -> str:
    """What the owner confirmed: this project, this scope, this folder. Minted by the plan, checked by the set."""
    import hashlib

    raw = "|".join([str(project_id), str(scope), os.path.normcase(os.path.abspath(str(target)))])
    return hashlib.sha256(raw.encode("utf-8")).hexdigest()[:20]


def _data_customer(payload: dict[str, Any], lookup: Any, request: Any) -> str:
    """The customer an observation belongs to: for the material area, the customer behind the folder's segment."""
    from ampuly.core.order_layout import PROJECT_MATERIALS
    from ampuly.plugins.office_ui import data_actions

    found = str(payload.get("customer_id", "") or "")
    if str(payload.get("area", "") or "") == PROJECT_MATERIALS:
        return data_actions.customer_of_material(found, lookup, request.project_customer)
    return found


def _ws_actor_login(handler: Any, ws: Any) -> str:
    """Who to record as the actor: the account login, or ``owner`` on a loopback console."""
    actor = _ws_owner_actor(handler, ws) or {}
    return str(actor.get("login", "") or "").strip() or "owner"


def _json_coerce(value: Any) -> Any:
    """json.dumps fallback: dates become ISO strings, sets lists, anything else its repr."""
    if isinstance(value, (datetime, date)):
        return value.isoformat()
    if isinstance(value, (set, frozenset, tuple)):
        return list(value)
    if isinstance(value, bytes):
        return value.decode("utf-8", "replace")
    return str(value)


def unserializable_paths(payload: Any, *, limit: int = 8) -> list[str]:
    """Dotted paths of every leaf ``json.dumps`` would reject, for the log line."""
    found: list[str] = []

    def walk(node: Any, path: str) -> None:
        if len(found) >= limit:
            return
        if isinstance(node, dict):
            for key, child in node.items():
                walk(child, f"{path}.{key}" if path else str(key))
            return
        if isinstance(node, (list, tuple)):
            for index, child in enumerate(node):
                walk(child, f"{path}[{index}]")
            return
        if node is None or isinstance(node, (str, int, float, bool)):
            return
        found.append(f"{path or '$'}<{type(node).__name__}>")

    walk(payload, "")
    return found



def _browser_connector_card() -> dict[str, Any]:
    from ampuly.plugins.office_ui.browser_connector import library_entry

    return library_entry()

_UI_READ_BINDING_UNSET = object()


class WSHandler:
    """Routes all WebSocket messages between frontend and AMPULY."""

    _UI_SEND_TIMEOUT_SEC = 5.0

    def __init__(
        self,
        engine: AmpulyEngine,
        agent_store: AgentStore,
        chat_store: ChatStore,
        event_adapter: EventAdapter,
    ) -> None:
        self.engine = engine
        self._root_engine = engine
        self._active_project_id = str(engine.project_id or "default").strip() or "default"
        self._project_switch_lock = asyncio.Lock()
        self.agent_store = agent_store
        self.chat_store = chat_store
        self.event_adapter = event_adapter
        self._clients: set[aiohttp.web.WebSocketResponse] = set()
        self._client_project_ids: dict[Any, str] = {}
        # Console accounts (architecture step 1): who is on each connection.
        self._client_accounts: dict[Any, Any] = {}
        self._account_store: Any = None
        self._client_switch_seq: dict[Any, str] = {}
        self._client_project_index_tasks: dict[Any, asyncio.Task[Any]] = {}
        self._client_initial_state_tasks: dict[Any, asyncio.Task[Any]] = {}
        self._exec_mode: str = "task"  # restored from DB in restore_persisted_mode()
        self._company_profile: str = "corporate"
        self._task_preferred_agent: str = "native"
        self._background_tasks: set[asyncio.Task[Any]] = set()
        self._task_bg_map: dict[str, set[asyncio.Task[Any]]] = {}
        self._task_bg_context: dict[asyncio.Task[Any], dict[str, Any]] = {}
        self._handoff_route_tasks: dict[asyncio.Task[Any], str] = {}
        self._broadcast_seq: int = 0
        self._broadcast_lock = asyncio.Lock()
        self._task_locks: dict[str, asyncio.Lock] = {}
        # Tracks which asyncio.Task currently holds the per-task lock. If the
        # prior holder finishes/crashes without reaching the finally block that
        # pops the lock, the next acquirer would block forever. We detect that
        # case by checking ``holder.done()`` in ``_get_task_lock`` and replace
        # the stale lock before the new acquirer blocks.
        self._task_lock_holders: dict[str, asyncio.Task[Any]] = {}
        self._config_lock = asyncio.Lock()
        self._active_runtime_children: dict[str, str] = {}
        self._secretary_session_id: str | None = None
        self._secretary_session_ids: dict[str, str] = {}
        # Cache only. The truth is a SessionRecord marked master_control;
        # this is consulted first and repopulated from the store on a miss,
        # so a restart re-attaches instead of forking a second conversation.
        self._master_session_ids: dict[str, str] = {}
        # The one Task each project's looping console conversation runs on,
        # held across turns because the loop mutates its metadata (the ledger,
        # the seed-dedupe, the runtime state). A fresh copy per turn would
        # lose them while still looking healthy.
        self._master_loop_tasks: dict[str, Any] = {}
        self._session_to_task: dict[str, str] = {}
        self._ui_task_aliases: dict[str, str] = {}
        self._progress_buffer: dict[str, list[dict[str, Any]]] = {}
        self._progress_project_ids: dict[str, str] = {}
        self._runtime_status_sync_task: asyncio.Task[Any] | None = None
        self._duty_watch_task: asyncio.Task[Any] | None = None
        # X05: consoles watching a session's live picture, and the registry telling
        # this console when any session's state moves so the owner's client opens
        # the browser pane by itself.
        self._browser_viewers: dict[str, set[Any]] = {}
        try:
            self._subscribe_browser_sessions()
        except Exception:  # noqa: BLE001 - a registry that cannot be reached at start is reported by the first browser call
            logger.warning("browser sessions: the console could not subscribe to session state changes")
        self._duty_state: Any = None
        self._duty_log: list[dict[str, Any]] = []
        # Self-healing is deliberately bounded per handler instance.  These
        # used to be class attributes, which let one project/console instance
        # suppress recovery in another instance in the same process.
        self._heal_marks: dict[str, float] = {}
        self._auto_resumed: set[str] = set()
        self._auto_resume_blocked_tasks: set[str] = set()
        self._self_heal_escalations: set[str] = set()
        self._runtime_status_sync_prev: dict[str, str] = {}
        self._assistant_delta_buffers: dict[tuple[str, str, str], dict[str, Any]] = {}
        self._assistant_delta_flush_tasks: dict[tuple[str, str, str], asyncio.Task[None]] = {}
        self._assistant_delta_seq: int = 0
        self._ASSISTANT_DELTA_FLUSH_INTERVAL_SEC = 0.05
        self._stop_requested_task_ids: set[str] = set()
        self._company_stop_intents: dict[str, dict[str, Any]] = {}
        self._company_stop_finalize_tasks: dict[str, asyncio.Task[Any]] = {}
        self._company_suspend_reply_locks: dict[str, asyncio.Lock] = {}
        # Buffer progress entries before UPSERTing to SQLite. Raised from 1
        # so bursts (codex streaming thinking chunks, multi-line tool output)
        # don't hammer the DB once per entry, but kept small enough that a
        # task sitting idle between work items still shows up on the Activity
        # panel without waiting for 10 entries to accumulate. A periodic
        # flush in ``_periodic_flush_loop`` catches tasks that emit sparsely
        # so at most ``_PROGRESS_FLUSH_INTERVAL_SEC`` of entries are held
        # in RAM before they're persisted and visible on page refresh.
        self._PROGRESS_FLUSH_THRESHOLD = 2
        self._PROGRESS_FLUSH_INTERVAL_SEC = 3.0
        self._RUNTIME_STATUS_SYNC_INTERVAL_SEC = 12.0
        self._progress_flush_task: asyncio.Task[None] | None = None
        self._shutting_down: bool = False
        self._active_message_tasks: set[asyncio.Task[Any]] = set()
        self.dispatcher = Dispatcher(engine, chat_store)
        self.services_context = OfficeServiceContext(
            engine=engine,
            agent_store=agent_store,
            chat_store=chat_store,
            event_adapter=event_adapter,
            mode_state=ModeState(
                exec_mode=self._exec_mode,
                company_profile=self._company_profile,
                task_preferred_agent=self._task_preferred_agent,
            ),
        )
        self.services_context.config_lock = self._config_lock
        self.services_context.background_tasks = self._background_tasks
        self.services_context.task_bg_map = self._task_bg_map
        self.services_context.task_bg_context = self._task_bg_context
        self.services_context.session_to_task = self._session_to_task
        self.services_context.active_runtime_children = self._active_runtime_children
        self.services_context.stop_requested_task_ids = self._stop_requested_task_ids
        self.services_context.task_locks = self._task_locks
        self.services_context.task_lock_holders = self._task_lock_holders
        self.services_context.wire_engine_callbacks = self._wire_engine_callbacks  # type: ignore[attr-defined]
        # Every service lookup goes through the console's one source of project engines (project_engines.py).
        self.services_context.project_engine_lookup = self._service_engine_for_project
        self.services_context.load_active_org_config = lambda org_id: self._load_active_org_config_into_engine(org_id)
        self.services_context.set_active_saved_org_name = self._service_set_active_saved_org_name
        self.services_context.get_active_saved_org_name = self._service_get_active_saved_org_name
        self.services_context.project_workplace_hook = lambda project_id: get_project_workplace(project_id)  # type: ignore[attr-defined]
        self.services_context.on_engine_activated = self._on_service_engine_activated
        self.services_context.persist_runtime_config = self._persist_runtime_config
        self.services_context.rebind_engine_config = self._rebind_engine_config
        self.services_context.sync_role_map = self._sync_role_map
        self.services_context.ensure_custom_role_agents = self._ensure_custom_role_agents
        self.services_context.broadcast_snapshot = self._broadcast_snapshot
        self.services_context.cancel_session_tasks = self._cancel_session_tasks
        self.services_context.cancel_task_tree = self._cancel_task_tree
        self.services = OfficeServices(self.services_context)
        self._wire_engine_callbacks(engine)
        self._console_api_cache: Any = None
        self._bind_node_invoke_callback(engine)

    def _connector_refusal(self, channel_name: str) -> str:
        switch = self._accounts().business.connector_switch(str(channel_name or ""))
        return "" if switch["enabled"] else "connector is switched off"

    def _bind_effect_verification_sources(self, engine: Any) -> None:
        """C10: a browser submit may expect a business event -- an order in a state -- and the
        source of that fact is this plugin's business store, not the page. Bound here, next to the
        budget hold, so a console restart re-binds it; the provider only asks by name."""
        from ampuly.effects.browser_submit import register_verification_source

        business = getattr(self._accounts(), "business", None)
        if business is None:
            return

        def order_in_state(args: dict[str, Any]) -> tuple[bool, dict[str, Any]]:
            order_id = str(args.get("order_id", "") or "").strip()
            wanted = str(args.get("status", "") or "").strip()
            if not order_id or not wanted:
                return False, {"reason": "order_id and status are required"}
            order = business.get_order(order_id)
            if order is None:
                return False, {"reason": "order_not_found", "order_id": order_id}
            actual = str(getattr(order, "status", "") or "")
            return actual == wanted, {"order_id": order_id, "status": actual, "wanted": wanted}

        register_verification_source("business_order", order_in_state)

    def _bind_effect_budget_hold(self, engine: Any) -> None:
        """When an external write's receipt is lost, put the run's budget on hold.

        The effect approval service records outcome_unknown; the budget lives
        here. This binds the two: the checkpoint names its task, the task
        carries the budget it was launched with, and the budget stops taking
        reservations until a person verifies (A12). Bound the same way the
        connector switch is, so a console restart re-binds it.
        """
        # Rebinding always revokes the old reader, including an unsuccessful
        # bind. Each engine owns its own closure and revocation marker.
        previous = getattr(engine, "_effect_budget_reader_binding", None)
        engine.effect_budget_reader = None
        engine._effect_budget_reader_binding = None
        if type(previous) is dict:
            previous["active"] = False
        service = getattr(engine, "effect_approval_service", None)
        store = getattr(engine, "store", None)
        if service is None or store is None:
            return
        business = self._accounts().business

        async def _hold(checkpoint: Any, execution: Any) -> None:
            task_id = str(getattr(checkpoint, "task_id", "") or "").strip()
            if not task_id:
                raise RuntimeError("checkpoint names no task, so no budget can be found")
            task = await store.get_task(task_id)
            budget_id = str(dict(getattr(task, "metadata", {}) or {}).get("budget_id", "") or "").strip()
            if not budget_id:
                # Not a failure: a run launched without a budget has nothing
                # to hold. Said plainly so the record does not read as a hold.
                raise RuntimeError(f"task {task_id} carries no budget")
            detail = str(getattr(execution, "detail", "") or "outcome unknown")
            effect_id = str(getattr(getattr(execution, "record", None), "effect_id", "") or "")
            reason = f"effect {effect_id or '?'} outcome unknown: {detail}"[:300]
            held = await asyncio.to_thread(business.mark_budget_pending_verification, budget_id, reason=reason, effect_id=effect_id)
            if held is None:
                raise RuntimeError(f"budget {budget_id} not found")

        service.on_outcome_unknown = _hold

        # The existing unknown-outcome writer above remains separate. Only an
        # original, concrete account/business source may supply observations.
        try:
            from .accounts import AccountStore
            from .business_store import BusinessStore
            from .console_session_store import workspace_path_identity

            accounts = getattr(self, "_account_store", None)
            if (type(accounts) is not AccountStore or type(business) is not BusinessStore
                    or accounts.business is not business):
                return
            account_home, account_path = accounts.home, accounts.path
            business_path = business.path
            engine_home = getattr(engine, "ampuly_home", None)
            project_id = getattr(engine, "project_id", None)
            gateway = getattr(engine, "effect_gateway", None)
            if (type(project_id) is not str or not project_id.strip()
                    or project_id != project_id.strip() or gateway is None
                    or getattr(service, "gateway", None) is not gateway):
                return

            def canonical(value):
                if type(value) not in (type(Path()), str):
                    raise ValueError
                path = Path(value)
                if path.drive.startswith("\\\\") or (path.drive and not path.root):
                    raise ValueError
                return os.path.normcase(os.path.normpath(str(path.absolute())))

            home = canonical(account_home)
            if (canonical(engine_home) != home
                    or canonical(business_path) != canonical(account_home / "business.db")
                    or canonical(account_path) != canonical(account_home / "accounts.json")):
                return
            workspace = workspace_path_identity(business_path)
            runtime_path = getattr(store, "db_path", None)
            runtime_connection = getattr(store, "_db", None)
            read_snapshot = BusinessStore.read_effect_budget_snapshot
        except Exception:
            return  # No read capability is installed on an unavailable source.

        marker = {"active": True}

        def assert_binding():
            try:
                if (not marker["active"]
                        or getattr(engine, "_effect_budget_reader_binding", None) is not marker
                        or getattr(engine, "effect_budget_reader", None) is not _read_budget
                        or getattr(self, "_account_store", None) is not accounts
                        or accounts.business is not business or accounts.home is not account_home
                        or accounts.path is not account_path or business.path is not business_path
                        or getattr(engine, "ampuly_home", None) is not engine_home
                        or canonical(engine_home) != home or canonical(account_home) != home
                        or getattr(engine, "project_id", None) != project_id
                        or getattr(engine, "store", None) is not store
                        or getattr(store, "db_path", None) != runtime_path
                        or getattr(store, "_db", None) is not runtime_connection
                        or getattr(engine, "effect_approval_service", None) is not service
                        or getattr(engine, "effect_gateway", None) is not gateway
                        or getattr(service, "gateway", None) is not gateway
                        or BusinessStore.read_effect_budget_snapshot is not read_snapshot
                        or workspace_path_identity(business_path) != workspace):
                    raise ValueError
            except Exception:
                # Restoring an old attribute cannot revive a detected stale
                # source; a fresh explicit bind is required.
                marker["active"] = False
                raise RuntimeError("effect_budget_unavailable") from None

        def read_in_thread(budget_id):
            assert_binding()
            try:
                result = read_snapshot(
                    business, budget_id, project_id=project_id,
                    _account_store=accounts, expected_workspace_binding=workspace,
                )
            except Exception:
                assert_binding()
                raise
            assert_binding()
            return result

        async def _read_budget(budget_id):
            try:
                assert_binding()
                result = await asyncio.to_thread(read_in_thread, budget_id)
                assert_binding()
                return result
            except asyncio.CancelledError:
                raise
            except Exception:
                # Invalid input, foreign budgets and transient lock errors do
                # not revoke an otherwise unchanged workspace binding.
                assert_binding()
                raise RuntimeError("effect_budget_unavailable") from None

        engine._effect_budget_reader_binding = marker
        engine.effect_budget_reader = _read_budget
        try:
            assert_binding()
        except RuntimeError:
            engine.effect_budget_reader = None
            engine._effect_budget_reader_binding = None

    def _bind_connector_switch(self, engine: Any) -> None:
        """Let the outbound path ask whether a connector may send at all.

        The manager and direct notification/card clients all consult the
        same business-store switch rather than caching an enabled flag.
        """
        manager = getattr(engine, "channel_manager", None)
        if manager is None or not hasattr(manager, "outbound_allowed"):
            return
        business = self._accounts().business

        def _refusal(channel_name: str) -> str:
            switch = business.connector_switch(str(channel_name or ""))
            if switch["enabled"]:
                return ""
            reason = switch["reason"] or "no reason was recorded"
            return f"{channel_name} is switched off ({reason}, by {switch['actor'] or 'someone'})"

        manager.outbound_allowed = _refusal

    # ── the contact book ──

    async def _handle_contact_list(self, ws: Any, data: dict) -> None:
        """Who we know, and on which inboxes, for the customers this socket sees."""
        project_id = self._request_project_id(data)
        await self._send_ack(
            ws, ok=True, action="contact_list", project_id=project_id,
            contacts=self._accounts().business.list_contacts(customer_ids=ws_customer_scope(self, ws)),
        )

    async def _handle_contact_bind(self, ws: Any, data: dict) -> None:
        """Attach one provider identity to one person (owner only).

        Owner-only because binding an inbox to the wrong customer routes their
        replies -- and eventually their files -- to somebody else.
        """
        from ampuly.plugins.office_ui.business_store import OrderTransitionError

        project_id = self._request_project_id(data)
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="contact_bind", project_id=project_id, error="owner_required")
            return
        business = self._accounts().business
        actor = _ws_actor_login(self, ws)
        try:
            if str(data.get("customer_id", "") or "").strip():
                business.add_contact(
                    contact_id=str(data.get("contact_id", "") or ""),
                    customer_id=str(data.get("customer_id", "") or ""),
                    display_name=str(data.get("display_name", "") or ""),
                    actor=actor,
                )
            if str(data.get("identity", "") or "").strip():
                business.bind_identity(
                    channel=str(data.get("channel", "") or ""),
                    identity=str(data.get("identity", "") or ""),
                    contact_id=str(data.get("contact_id", "") or ""),
                    actor=actor,
                )
        except OrderTransitionError as exc:
            await self._send_ack(ws, ok=False, action="contact_bind", project_id=project_id, error=str(exc))
            return
        await self._send_ack(
            ws, ok=True, action="contact_bind", project_id=project_id,
            contacts=business.list_contacts(customer_ids=ws_customer_scope(self, ws)),
        )

    async def _handle_message_correlate(self, ws: Any, data: dict) -> None:
        """Which order an inbound message is about, and how sure that is."""
        from ampuly.plugins.office_ui.contact_identity import correlate_message

        project_id = self._request_project_id(data)
        result = correlate_message(
            self._accounts().business,
            channel=str(data.get("channel", "") or ""),
            identity=str(data.get("identity", "") or ""),
            reply_to=str(data.get("reply_to", "") or ""),
            thread_id=str(data.get("thread_id", "") or ""),
        )
        allowed = set(ws_customer_scope(self, ws))
        customer = str(result.get("contact", {}).get("customer_id", "") or "")
        if allowed and customer and customer not in allowed:
            # This account may not learn that this identity belongs to
            # somebody, let alone to whom.
            result = {"contact": {"known": False}, "order_id": "", "strength": "none", "reason": "out_of_scope"}
        await self._send_ack(
            ws, ok=True, action="message_correlate", project_id=project_id, correlation=result,
        )

    # ── the process factory ──

    async def _handle_process_spec_list(self, ws: Any, data: dict) -> None:
        """Every description, each showing what it still cannot answer."""
        from ampuly.plugins.office_ui.process_candidate import candidate_template_catalog

        project_id = self._request_project_id(data)
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="process_spec_list", project_id=project_id, error="owner_required")
            return
        template_error = ""
        try:
            # A flow derived for another project is that customer's: it is not offered as a template here.
            from ampuly.plugins.office_ui.workflow_packages import usable_by_project

            templates = candidate_template_catalog([
                package for package in await asyncio.to_thread(self._workflow_registry)
                if usable_by_project(package, project_id)
            ])
        except (OSError, ValueError):
            # A broken catalogue must not hide saved descriptions or expose paths.
            templates = []
            template_error = "template_catalog_unavailable"
        await self._send_ack(
            ws, ok=True, action="process_spec_list", project_id=project_id,
            specs=self._accounts().business.list_process_specs(),
            templates=templates, template_error=template_error,
        )

    async def _handle_process_spec_get(self, ws: Any, data: dict) -> None:
        from ampuly.plugins.office_ui.process_spec import diff_specs, from_payload, unresolved

        project_id = self._request_project_id(data)
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="process_spec_get", project_id=project_id, error="owner_required")
            return
        stored = self._accounts().business.process_spec(
            str(data.get("spec_id", "") or ""), str(data.get("version", "") or ""),
        )
        if stored is None:
            await self._send_ack(ws, ok=False, action="process_spec_get", project_id=project_id, error="not_found")
            return
        try:
            spec = from_payload(stored["spec"])
        except Exception as exc:
            await self._send_ack(ws, ok=False, action="process_spec_get", project_id=project_id, error=str(exc))
            return
        previous = self._accounts().business.previous_process_spec(spec.spec_id, spec.version)
        previous_unreadable = ""
        try:
            comparison = diff_specs(from_payload(previous["spec"]) if previous else None, spec)
        except Exception as exc:
            # An older revision the current rules no longer accept is not a
            # reason to withhold the one that was asked for. The diff is
            # reported as unavailable, with why; the rest is returned.
            previous_unreadable = str(exc)[:300]
            comparison = None
        await self._send_ack(
            ws, ok=True, action="process_spec_get", project_id=project_id,
            spec=stored, review={**unresolved(spec), "diff": comparison,
                                 "previous_version": previous["version"] if previous else "",
                                 "previous_unreadable": previous_unreadable},
            rounds=self._accounts().business.builder_rounds(spec.spec_id),
        )

    async def _handle_process_spec_save(self, ws: Any, data: dict) -> None:
        """Save a description as written, unfinished included (owner only).

        Refusing to store an unfinished one would push people back to editing
        YAML, which is the thing this replaces. The gaps are reported, not
        used as a reason to lose the work.
        """
        from ampuly.plugins.office_ui.business_store import OrderTransitionError

        project_id = self._request_project_id(data)
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="process_spec_save", project_id=project_id, error="owner_required")
            return
        try:
            stored = self._accounts().business.save_process_spec(
                data.get("spec", {}), actor=_ws_actor_login(self, ws),
            )
        except OrderTransitionError as exc:
            await self._send_ack(ws, ok=False, action="process_spec_save", project_id=project_id, error=str(exc))
            return
        await self._send_ack(
            ws, ok=True, action="process_spec_save", project_id=project_id,
            spec=stored, specs=self._accounts().business.list_process_specs(),
        )

    async def _handle_process_spec_candidate(self, ws: Any, data: dict) -> None:
        """Compile exactly one saved revision into a template-backed draft."""
        from ampuly.plugins.office_ui.process_spec import from_payload
        from ampuly.plugins.office_ui.process_candidate import create_process_candidate

        project_id = self._request_project_id(data)
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="process_spec_candidate", project_id=project_id, error="owner_required")
            return
        version = str(data.get("version", "") or "")
        stored = self._accounts().business.process_spec(str(data.get("spec_id", "") or ""), version) if version else None
        if stored is None:
            await self._send_ack(ws, ok=False, action="process_spec_candidate", project_id=project_id, error="saved_spec_version_required")
            return
        try:
            api = self._console_api()
            template = api.package(str(data.get("template_id", "") or ""))
            if template is None:
                raise ValueError("workflow template not found")
            from ampuly.plugins.office_ui.workflow_packages import usable_by_project

            if not usable_by_project(template, project_id):
                # The catalogue above does not offer it; asking for it by id is refused the same way.
                raise ValueError("这条业务流是另一个项目专用的，不能在本项目用作模板")
            candidate = await asyncio.to_thread(
                create_process_candidate, from_payload(stored["spec"]), template,
                ampuly_home=api.ampuly_home, draft_id=str(data.get("draft_id", "") or ""), actor=_ws_actor_login(self, ws),
                generate_missing_skills=bool(data.get("generate_skills", False)),
            )
        except (OSError, TypeError, ValueError) as exc:
            await self._send_ack(ws, ok=False, action="process_spec_candidate", project_id=project_id, error=str(exc))
            return
        await self._send_ack(ws, ok=True, action="process_spec_candidate", project_id=project_id,
                             spec_id=stored["spec_id"], version=version, draft_id=candidate.id,
                             workflow=candidate.to_payload(), unlocks_release=False,
                             generated_skills=[item["id"] for item in list(
                                 dict(candidate.manifest.get("provenance") or {}).get("generated_skills") or [])])

    async def _handle_builder_trial(self, ws: Any, data: dict) -> None:
        """Try a description offline and say what it established (owner only).

        The trial runs against the offline environment only. It cannot reach a
        real Provider from here, and a green result is recorded as simulated.
        """
        from ampuly.plugins.office_ui.builder_loop import BuilderError
        from ampuly.plugins.office_ui.builder_trial import run_saved_trial
        from ampuly.plugins.office_ui.business_store import OrderTransitionError
        from ampuly.plugins.office_ui.process_spec import from_payload

        project_id = self._request_project_id(data)
        correlation = {"request_id": str(data.get("request_id", "") or "")[:128],
                       "spec_id": str(data.get("spec_id", "") or ""),
                       "version": str(data.get("version", "") or "")}
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="builder_trial", project_id=project_id, **correlation, error="owner_required")
            return
        try:
            business = self._accounts().business
            stored = await asyncio.to_thread(business.process_spec, str(data.get("spec_id", "") or ""), str(data.get("version", "") or ""))
        except Exception as exc:
            # A refusal the console can match to its request, not a bare
            # dispatcher error that leaves the trial button waiting.
            await self._send_ack(ws, ok=False, action="builder_trial", project_id=project_id, **correlation, error=str(exc) or type(exc).__name__)
            return
        if stored is None:
            await self._send_ack(ws, ok=False, action="builder_trial", project_id=project_id, **correlation, error="not_found")
            return
        try:
            spec = from_payload(stored["spec"])
        except Exception as exc:
            await self._send_ack(ws, ok=False, action="builder_trial", project_id=project_id, **correlation, error=str(exc))
            return
        actor = _ws_actor_login(self, ws)
        try:
            receipt = await run_saved_trial(
                business, spec, actor=actor, runner_factory=self._offline_trial_runner,
            )
        except (OrderTransitionError, BuilderError) as exc:
            await self._send_ack(ws, ok=False, action="builder_trial", project_id=project_id, **correlation, error=str(exc))
            return
        try:
            rounds = await asyncio.to_thread(business.builder_rounds, spec.spec_id)
        except Exception as exc:
            # The trial settled; a listing that failed afterwards is said, not
            # allowed to turn the receipt into an uncorrelated error.
            rounds = []
            receipt["rounds_unavailable"] = str(exc)[:300]
        await self._send_ack(
            ws, ok=True, action="builder_trial", project_id=project_id,
            **receipt, spec_id=spec.spec_id, version=spec.version,
            request_id=correlation["request_id"],
            rounds=rounds,
        )

    async def _handle_builder_trial_resume(self, ws: Any, data: dict) -> None:
        """Continue an attempt parked at a human node with the owner's decision (owner only).

        The decision is handed to the node the way a console answer is: 打回
        fails it closed, anything else releases it. A continuation is a new
        Builder round on the same description version; it goes through the
        same claim, so two people cannot continue one attempt at once.
        """
        from ampuly.plugins.office_ui.builder_loop import BuilderError
        from ampuly.plugins.office_ui.builder_trial import run_saved_trial
        from ampuly.plugins.office_ui.business_store import OrderTransitionError
        from ampuly.plugins.office_ui.process_spec import from_payload

        project_id = self._request_project_id(data)
        correlation = {"request_id": str(data.get("request_id", "") or "")[:128],
                       "spec_id": str(data.get("spec_id", "") or ""),
                       "version": str(data.get("version", "") or "")}
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="builder_trial_resume", project_id=project_id, **correlation, error="owner_required")
            return
        decision = str(data.get("decision", "") or "").strip()
        try:
            attempt = int(data.get("attempt", 0) or 0)
        except (TypeError, ValueError):
            attempt = 0
        if attempt < 1 or len(decision) < 2:
            await self._send_ack(ws, ok=False, action="builder_trial_resume", project_id=project_id, **correlation,
                                 error="要说明是哪一次试跑，以及放行还是打回、为什么")
            return
        engine = getattr(self, "engine", None)
        llm = getattr(engine, "llm", None)
        home = getattr(engine, "ampuly_home", None)
        if llm is None or not isinstance(home, (str, Path)):
            await self._send_ack(ws, ok=False, action="builder_trial_resume", project_id=project_id, **correlation,
                                 error="这个引擎没有模型，试跑只做了结构检查，没有可以继续的执行")
            return
        try:
            business = self._accounts().business
            stored = await asyncio.to_thread(business.process_spec, correlation["spec_id"], correlation["version"])
        except Exception as exc:
            await self._send_ack(ws, ok=False, action="builder_trial_resume", project_id=project_id, **correlation, error=str(exc) or type(exc).__name__)
            return
        if stored is None:
            await self._send_ack(ws, ok=False, action="builder_trial_resume", project_id=project_id, **correlation, error="not_found")
            return
        try:
            spec = from_payload(stored["spec"])
        except Exception as exc:
            await self._send_ack(ws, ok=False, action="builder_trial_resume", project_id=project_id, **correlation, error=str(exc))
            return
        from ampuly.plugins.office_ui.trial_runner import ResumeTrialRunner

        actor = _ws_actor_login(self, ws)
        try:
            receipt = await run_saved_trial(
                business, spec, actor=actor,
                runner_factory=lambda: ResumeTrialRunner(llm=llm, ampuly_home=Path(home), attempt=attempt, reply=decision),
            )
        except (OrderTransitionError, BuilderError) as exc:
            await self._send_ack(ws, ok=False, action="builder_trial_resume", project_id=project_id, **correlation, error=str(exc))
            return
        try:
            rounds = await asyncio.to_thread(business.builder_rounds, spec.spec_id)
        except Exception as exc:
            rounds = []
            receipt["rounds_unavailable"] = str(exc)[:300]
        await self._send_ack(
            ws, ok=True, action="builder_trial_resume", project_id=project_id,
            **receipt, spec_id=spec.spec_id, version=spec.version, attempt=attempt,
            request_id=correlation["request_id"], rounds=rounds,
        )

    def _offline_trial_runner(self):
        """The product's own scheduler in a home of its own, or a shape check that says it is only that.

        With a model on the engine, a trial puts the compiled draft through
        CompanyWorkItemExecutor and NativeRuntimeV2 under
        ``<ampuly_home>/builder_trials``: no customer, no account, no money, only
        file tools fenced to the attempt's workspace. Without a model there
        is no run, and the result says ``validated`` rather than anything
        greener.
        """
        engine = getattr(self, "engine", None)
        llm = getattr(engine, "llm", None)
        home = getattr(engine, "ampuly_home", None)
        if llm is not None and isinstance(home, (str, Path)):
            from ampuly.plugins.office_ui.trial_runner import CompanyTrialRunner

            return CompanyTrialRunner(llm=llm, ampuly_home=Path(home))

        def run(workflow: dict) -> tuple[bool, str, str]:
            for node in list(workflow.get("nodes", []) or []):
                if not list(node.get("deliverables", []) or []) and not list(node.get("tools", []) or []):
                    return (False, str(node.get("id", "")), "the step promises nothing to deliver")
            from ampuly.plugins.office_ui.builder_loop import ValidationOnly
            raise ValidationOnly("compile_and_shape_only; the engine has no model, so no Provider turn, tool execution or human gate was exercised")

        return run

    async def _handle_connector_switch_list(self, ws: Any, data: dict) -> None:
        """Which connectors somebody has switched off, and why."""
        project_id = self._request_project_id(data)
        await self._send_ack(
            ws, ok=True, action="connector_switch_list", project_id=project_id,
            switches=self._accounts().business.list_connector_switches(),
        )

    async def _handle_connector_switch_set(self, ws: Any, data: dict) -> None:
        """Stop or resume one connector (owner only)."""
        from ampuly.plugins.office_ui.business_store import OrderTransitionError

        resolve_engine = getattr(self, "_engine_for_request", None)
        if callable(resolve_engine):
            run_engine, project_id = await resolve_engine(data)
        else:  # bounded unit/service adapters may expose only the active engine
            run_engine, project_id = self.engine, self._request_project_id(data)
        connector_name = str(data.get("connector", "") or "")
        # 4.7-AS: the owner's desktop channel is a switch, not a registered connector -- nothing is bound before it
        # opens -- and what goes wrong with it is said in the owner's words (the page shows ``error`` as it is).
        from ampuly.plugins.office_ui.desktop_connector import CHANNEL_SWITCH as DESKTOP_CHANNEL_SWITCH

        desktop = connector_name.strip() == DESKTOP_CHANNEL_SWITCH
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="connector_switch_set", project_id=project_id,
                                 **({"error": "只有负责人能打开或关上本机桌面通道。", "code": "owner_required"} if desktop
                                    else {"error": "owner_required"}))
            return
        runtime_binder = getattr(self, "_bind_registered_connector_runtime", None)
        if not desktop and bool(data.get("enabled", True)) and callable(runtime_binder):
            try:
                runtime_binder(run_engine, project_id)
            except Exception as exc:  # binding failed before the switch was widened
                await self._send_ack(
                    ws, ok=False, action="connector_switch_set", project_id=project_id,
                    error=f"connector_runtime_binding_failed: {exc}",
                )
                return
        try:
            switch = self._accounts().business.set_connector_enabled(
                connector_name,
                bool(data.get("enabled", True)),
                actor=_ws_actor_login(self, ws),
                reason=str(data.get("reason", "") or ""),
            )
        except OrderTransitionError as exc:
            if desktop:
                words = {"say why this connector is being switched off": "关上本机桌面通道要写明原因。",
                         "actor is required": "认不出是谁在操作，请重新登录后再试。"}
                await self._send_ack(ws, ok=False, action="connector_switch_set", project_id=project_id,
                                     error=words.get(str(exc), "本机桌面通道没能切换，请稍后再试。"), code=str(exc)[:200])
                return
            await self._send_ack(ws, ok=False, action="connector_switch_set", project_id=project_id, error=str(exc))
            return
        # Re-bind so the change takes effect on the next message, not the next
        # restart: the switch is reached for while something is going wrong.
        self._bind_connector_switch(run_engine)
        await self._send_ack(
            ws, ok=True, action="connector_switch_set", project_id=project_id,
            switch=switch, switches=self._accounts().business.list_connector_switches(),
        )

    @staticmethod
    def _browser_session_registry():
        from ampuly.layer4_tools import browser as browser_tools

        return browser_tools._browser_sessions

    def _browser_binding_for_request(self, project_id: str, data: dict, *, require_control: bool = False):
        registry = self._browser_session_registry()
        binding = registry.binding_for_key(str(data.get("binding_key", "") or ""))
        if binding is None or binding.project_id != project_id:
            raise ValueError("browser_session_not_found")
        if require_control:
            registry.assert_control(binding, data.get("resource_id"), data.get("control_fence"))
        return registry, binding

    async def _browser_anchor_for_task(self, task_id: str, project_id: str = "") -> dict[str, str]:
        """Resolve the one durable order owning this browser task, or fail closed."""
        store = getattr(getattr(self, "engine", None), "store", None)
        from ampuly.plugins.office_ui.browser_anchor import resolve_browser_order_anchor

        return await resolve_browser_order_anchor(
            store,
            task_id=str(task_id or "").strip(),
            project_id=str(project_id or "").strip(),
        )


    async def _handle_desktop_session_control(self, ws: Any, data: dict) -> None:
        """Owner takeover / hand-back for a desktop step. Never a model tool."""
        project_id = self._request_project_id(data)
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="desktop_session_control", project_id=project_id, error="owner_required")
            return
        command = str(data.get("command", "") or "").strip()
        task_id = str(data.get("task_id", "") or "").strip()
        note = str(data.get("note", "") or "").strip()[:300]
        if command not in {"takeover", "hand_back", "status"}:
            await self._send_ack(ws, ok=False, action="desktop_session_control", project_id=project_id,
                                 task_id=task_id, error="desktop_command_invalid")
            return
        if not task_id:
            await self._send_ack(ws, ok=False, action="desktop_session_control", project_id=project_id,
                                 error="task_id_required")
            return
        try:
            engine, project_id = await self._engine_for_request(data)
        except Exception as exc:
            await self._send_ack(ws, ok=False, action="desktop_session_control", project_id=project_id,
                                 task_id=task_id, error=str(exc) or "engine_unavailable")
            return
        store = getattr(engine, "store", None)
        getter = getattr(store, "get_task", None) if store is not None else None
        if not callable(getter):
            await self._send_ack(ws, ok=False, action="desktop_session_control", project_id=project_id,
                                 task_id=task_id, error="task_store_unavailable")
            return
        task = await getter(task_id)
        if task is None:
            await self._send_ack(ws, ok=False, action="desktop_session_control", project_id=project_id,
                                 task_id=task_id, error="task_not_found")
            return
        task_project = str(getattr(task, "project_id", "") or "").strip()
        if task_project and task_project != project_id:
            await self._send_ack(ws, ok=False, action="desktop_session_control", project_id=project_id,
                                 task_id=task_id, error="task_project_mismatch")
            return
        from ampuly.plugins.office_ui.desktop_connector import desktop_hand_back, desktop_status, desktop_takeover
        if command == "status":
            result = desktop_status(task)
        elif command == "takeover":
            result = desktop_takeover(task)
        else:
            result = desktop_hand_back(task)
        ok = bool(result.get("ok"))
        payload = {
            "action": "desktop_session_control", "project_id": project_id, "task_id": task_id,
            "command": command, "state": result.get("state"), "controller": result.get("controller"),
            "fresh_look_required": result.get("fresh_look_required"),
            "window_title": result.get("window_title"),
            "screen_hash": result.get("screen_hash"),
            "frame_delivered": result.get("frame_delivered"),
            "last_refusal": result.get("last_refusal"),
            "app": result.get("app"),
        }
        if note:
            payload["note"] = note
        if not ok:
            payload["error"] = str(result.get("refused") or result.get("note") or "desktop_control_failed")
            if result.get("refused"):
                payload["refused"] = result.get("refused")
            if result.get("note"):
                payload["detail"] = result.get("note")
        await self._send_ack(ws, ok=ok, **payload)

    async def _handle_browser_account_inspect(self, ws: Any, data: dict) -> None:
        """Read saved account facts for one existing task; never load an engine or choose an account."""
        from ampuly.layer4_tools.browser_sessions import BrowserBinding, BrowserSessionRefused

        fields = {name: data.get(name) for name in ("project_id", "task_id", "binding_key", "request_id")}

        def valid_text(value: Any, limit: int) -> bool:
            return (type(value) is str and 0 < len(value) <= limit and value == value.strip()
                    and not any(ord(c) < 32 or ord(c) == 127 for c in value))

        # Echo only bounded routing fields, never caller-supplied scope, paths or credentials.
        reply = {name: value if valid_text(value, 256) else "" for name, value in fields.items()}
        reply["action"] = "browser_account_inspect"
        try:
            if not _ws_is_owner(self, ws):
                await self._send_ack(ws, ok=False, error="owner_required", **reply)
                return
            if (not all(valid_text(value, 128 if name == "request_id" else 256)
                        for name, value in fields.items())
                    or len(fields["binding_key"]) != 16
                    or any(c not in "0123456789abcdef" for c in fields["binding_key"])):
                await self._send_ack(ws, ok=False, error="account_request_invalid", **reply)
                return
            project_id, task_id = fields["project_id"], fields["task_id"]
            raw_ws = _socket_behind(ws)

            def selected_project() -> Any:
                projects = getattr(self, "_client_project_ids", None)
                return projects.get(raw_ws) if isinstance(projects, dict) else None

            if selected_project() != project_id:
                await self._send_ack(ws, ok=False, error="account_project_changed", **reply)
                return
            # Deliberately do not use _engine_for_request / loaded(): they may build,
            # reopen or attach runtime parts. This read only uses the already active engine.
            engine = getattr(self, "engine", None)
            store = getattr(engine, "store", None)
            connection = getattr(store, "_db", None)

            def ready() -> bool:
                value = getattr(store, "is_ready", False)
                return (value() if callable(value) else value) is True

            getter = getattr(store, "get_task", None)
            if (getattr(engine, "project_id", None) != project_id
                    or getattr(store, "project_id", None) != project_id
                    or connection is None or not ready() or not callable(getter)):
                await self._send_ack(ws, ok=False, error="account_task_source_not_ready", **reply)
                return
            task = await getter(task_id)
            # The task lookup yields. Re-authorize against the original live source before
            # reading even account-presence facts; no fallback to a replacement store.
            if not _ws_is_owner(self, ws):
                await self._send_ack(ws, ok=False, error="owner_required", **reply)
                return
            if (selected_project() != project_id or getattr(self, "engine", None) is not engine
                    or getattr(engine, "project_id", None) != project_id
                    or getattr(engine, "store", None) is not store
                    or getattr(store, "project_id", None) != project_id
                    or getattr(store, "_db", None) is not connection or not ready()):
                await self._send_ack(ws, ok=False, error="account_source_changed", **reply)
                return
            if task is None:
                await self._send_ack(ws, ok=False, error="task_not_found", **reply)
                return
            if getattr(task, "id", None) != task_id or getattr(task, "project_id", None) != project_id:
                await self._send_ack(ws, ok=False, error="account_task_scope_mismatch", **reply)
                return
            binding = BrowserBinding.for_task(task)
            if (not all(valid_text(value, 256) for value in (
                    binding.project_id, binding.customer_id, binding.environment_id, binding.task_id))
                    or binding.key() != fields["binding_key"]):
                await self._send_ack(ws, ok=False, error="account_binding_mismatch", **reply)
                return
            inspection = self._browser_session_registry().inspect_account(binding)
        except BrowserSessionRefused as exc:
            allowed = {
                "invalid_scope", "scope_conflict", "account_scope_mismatch", "account_source_not_ready",
                "account_recovery_required", "account_source_unavailable", "account_store_not_ready",
                "account_observation_changed", "account_inspection_invalid",
            }
            reason = exc.reason if exc.reason in allowed else "account_inspect_unavailable"
            await self._send_ack(ws, ok=False, error=reason, **reply)
            return
        except Exception:
            # Filesystem/store exceptions can contain private paths. Never echo their text.
            await self._send_ack(ws, ok=False, error="account_inspect_unavailable", **reply)
            return
        await self._send_ack(ws, ok=True, inspection=inspection, **reply)

    async def _handle_browser_session_list(self, ws: Any, data: dict) -> None:
        """Owner-only projection of browser resources in this project."""
        project_id = self._request_project_id(data)
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="browser_session_list", project_id=project_id, error="owner_required")
            return
        registry = self._browser_session_registry()
        rows = [
            {**row, "agent": _browser_gateway_facts(registry, row.get("binding_key", ""))}
            for row in registry.operator_sessions()
            if row["project_id"] == project_id
        ]
        from ampuly.plugins.office_ui.browser_anchor import resolve_browser_node

        store = getattr(getattr(self, "engine", None), "store", None)
        for row in rows:
            anchor = await self._browser_anchor_for_task(row.get("task_id", ""), project_id)
            row["order_id"], row["anchor_session_id"] = anchor["order_id"], anchor["anchor_session_id"]
            # Data phase 1: "order_id" stays the anchor task the frontend matches; this is the business order.
            row["business_order_id"] = await WSHandler._business_order_for_browser(
                self, str(row.get("task_id", "") or ""), str(anchor.get("order_id", "") or ""), project_id,
            )
            # Q05 B5: which step of the flow the page belongs to (its work item's own record).
            row.update(await resolve_browser_node(store, task_id=str(row.get("task_id", "") or ""), project_id=project_id))
        enriched = {row["binding_key"]: row for row in rows}
        rows = [{"order_id": "", "anchor_session_id": "", "business_order_id": "",
                 **enriched.get(current["binding_key"], {}), **current,
                 "agent": _browser_gateway_facts(registry, current["binding_key"])}
                for current in registry.operator_sessions() if current["project_id"] == project_id]
        limits_of = getattr(registry, "limits", None)
        await self._send_ack(
            ws, ok=True, action="browser_session_list", project_id=project_id,
            sessions=rows, combination=_browser_combination_evidence(getattr(self, "engine", None)),
            limits=limits_of() if callable(limits_of) else {},
        )

    async def _business_order_for_browser(self, task_id: str, anchor_task_id: str, project_id: str) -> str:
        """The business order (``wo-…``) a browser session works for, or "" (data phase 1).

        The session's own task first (its order, or the run it belongs to), then the order whose run is the session's
        anchor. Read-only and never a reason to fail: without one, the console keeps the anchor task's folder.
        """
        from ampuly.core.order_layout import order_segment_ok

        order = None
        store = getattr(getattr(self, "engine", None), "store", None)
        task = None
        if store is not None and task_id:
            try:
                task = await store.get_task(task_id)
            except Exception:  # noqa: BLE001
                task = None
        if task is not None:
            order = await WSHandler._order_of_work_item(self, task)
        if order is None and anchor_task_id:
            try:
                order = self._console_api().business.order_for_launched_task(anchor_task_id, project_id=project_id)
            except Exception:  # noqa: BLE001
                order = None
        order_id = str(getattr(order, "order_id", "") or "").strip() if order is not None else ""
        return order_id if order_segment_ok(order_id) else ""

    async def _browser_person_drives(self, registry: Any, binding: Any, command: str, note: str, *,
                                     resource_id: str, control_fence: str) -> dict[str, Any]:
        from urllib.parse import urlsplit

        from ampuly.computer_use import browser_bridge as _bridge

        entry = registry.assert_control(binding, resource_id, control_fence, human=True)
        runtime = getattr(entry, "runtime", None)
        if runtime is None or getattr(entry, "unavailable", ""):
            # A close in flight (or failed): a command queued behind it would only race it.
            raise ValueError("browser_view_unavailable")
        # A person working the page is activity: idle expiry must not close the browser under them (C16).
        touch = getattr(registry, "touch", None)
        if callable(touch):
            touch(binding)
        try:
            with _browser_dispatch_scope(registry, binding, resource_id, control_fence, human=True):
                return await self._browser_person_command(registry, binding, entry, runtime, command, note)
        finally:
            current = registry._entries.get(binding.key())
            if current is not entry or getattr(current, "runtime", None) is not runtime or getattr(current, "unavailable", ""):
                # The session's browser was closed while this ran or waited (the runtime is retired, so nothing launched;
                # belt and braces for a runtime that is not): close it again. The view is gone either way.
                try:
                    await runtime.close()
                except Exception:  # noqa: BLE001 - closed as far as it will close; the person is told either way
                    pass
                raise ValueError("browser_view_unavailable")

    async def _browser_person_command(self, registry: Any, binding: Any, entry: Any, runtime: Any, command: str, note: str) -> dict[str, Any]:
        from urllib.parse import urlsplit

        from ampuly.computer_use import browser_bridge as _bridge

        # The same exemption on the runtime's own request gate, so a link the person clicks is judged the way
        # their typed address is. Every agent action clears this again (_apply_runtime_policies), so it cannot
        # be left on once control comes back.
        person_drives = getattr(runtime, "set_person_driving", None)
        if callable(person_drives):
            person_drives(True)
        if command in {"navigate", "open_tab"}:
            url = str(note or "").strip()
            if url and "://" not in url:
                url = "https://" + url
            if not url:
                raise ValueError("url_required")
            # P2 护栏一: the person the owner handed this session to is the authority on it; the delegated
            # hosts still bind, the page rules do not. Without this, 帮忙登录 and 短信验证 -- the hand-offs the
            # connector declares a person for -- are refused to the person too.
            registry.check_navigation(binding, url, by_person=True)
            if command == "navigate":
                await runtime.navigate(url=url)
            else:
                await runtime.open_tab(url)
            _bridge.gateway_annotate(binding, {"type": "person_drove", "command": command, "host": (urlsplit(url).hostname or "")})
        elif command == "back":
            await runtime.navigate_back()
        elif command == "reload":
            await runtime.reload()
        elif command == "switch_tab":
            await runtime.switch_tab(int(str(note or "0").strip() or 0))
        elif command == "close_tab":
            await runtime.close_tab(int(str(note or "0").strip() or 0))
        if command not in {"navigate", "open_tab"}:
            _bridge.gateway_annotate(binding, {"type": "person_drove", "command": command})
        return {**registry.state_of(binding), "tabs": registry._tabs_of(entry)}

    async def _browser_allow_hosts(self, registry: Any, binding: Any, hosts_text: str, *, actor: str,
                                   resource_id: str, control_fence: str) -> dict[str, Any]:
        from datetime import datetime, timezone

        from ampuly.computer_use import browser_bridge as _bridge
        from ampuly.layer4_tools.browser_sessions import BrowserSessionRefused
        from ampuly.plugins.office_ui.master_control import clean_browser_domains

        entry = registry.assert_control(binding, resource_id, control_fence)
        runtime = entry.runtime

        def check_current() -> None:
            current = registry.assert_control(binding, resource_id, control_fence)
            if current is not entry or current.runtime is not runtime or current.unavailable:
                raise BrowserSessionRefused("Browser control changed", reason="browser_control_changed")

        check_current()
        added = clean_browser_domains(hosts_text)
        if not added:
            raise ValueError("no_hostnames_to_allow")
        touch = getattr(registry, "touch", None)
        if callable(touch):
            touch(binding)  # the owner widening the hosts is activity (C16)
        store = getattr(getattr(self, "engine", None), "store", None)
        getter = getattr(store, "get_task", None)
        saver = getattr(store, "save_task", None)
        task = await getter(binding.task_id) if callable(getter) and binding.task_id else None
        check_current()
        if task is None or not callable(saver):
            raise ValueError("order_not_found_for_session")
        metadata = dict(getattr(task, "metadata", {}) or {})
        current = [str(d) for d in list(metadata.get("browser_allowed_domains") or []) if str(d or "").strip()]
        merged = list(dict.fromkeys(current + added))
        metadata.update({"browser_allowed_domains": merged, "browser_delegated_by": actor,
                         "browser_hosts_widened_at": datetime.now(timezone.utc).isoformat()})
        check_current()
        task.metadata = metadata
        check_current()
        try:
            await saver(task)
            check_current()
            _bridge.note_delegation(binding, metadata)
            check_current()
            registry.bind_domains(binding, merged)
            lease = _bridge.sync_lease(registry, binding)
            check_current()
            setter = getattr(runtime, "set_egress_hosts", None)
            if callable(setter):
                setter(getattr(lease, "allowed_hosts", merged) or merged)
            check_current()
            reloader = getattr(runtime, "reload", None)
            opener = getattr(runtime, "is_open", False)
            is_open = bool(opener() if callable(opener) else opener)
            check_current()
            if callable(reloader) and is_open:
                # The first rejected navigation has no open page to reload. The same request guard
                # also runs after the runtime lock, so a queued reload cannot outlive its control.
                with _browser_dispatch_scope(registry, binding, resource_id, control_fence):
                    await reloader()
            check_current()
            _bridge.gateway_annotate(binding, {"type": "hosts_widened", "by": actor, "added": added})
        except Exception:
            # A save may already have committed. Never report a stale continuation as success,
            # or imply that its stored delegation was rolled back when its outcome is uncertain.
            raise BrowserSessionRefused("Host update outcome is unknown; refresh before continuing",
                                        reason="browser_hosts_update_unknown") from None
        return {**registry.state_of(binding), "allowed_domains": merged, "added": added}

    async def _handle_browser_session_control(self, ws: Any, data: dict) -> None:
        """Move one browser through the human-handoff lifecycle, never a business gate."""
        project_id = self._request_project_id(data)
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="browser_session_control", project_id=project_id, error="owner_required")
            return
        command = str(data.get("command", "") or "").strip()
        early_cancelled = 0
        note = str(data.get("note", "") or "").strip()[:300]
        prior_control_events = 0
        try:
            registry, binding = WSHandler._browser_binding_for_request(self, project_id, data, require_control=True)
            resource_id, control_fence = data["resource_id"], data["control_fence"]
            prior_control_events = len(registry.control_events(binding))
            if command == "hand_to_human":
                from ampuly.computer_use import browser_bridge as _bridge

                facts = await _bridge.page_facts_for_handoff(getattr(registry._entries.get(binding.key()), "runtime", None))
                registry.assert_control(binding, resource_id, control_fence)
                state = registry.hand_to_human(binding, note=note, facts=facts)
            elif command == "human_returned":
                state = registry.human_returned(binding, note=note)
            elif command == "hand_back":
                # C07 / X05: the person says they are done. The page's own facts are recorded and shown to the
                # owner as a RECOMMENDATION only -- the review showed a page can forge every one of
                # them (path, cookie count, structure) with no login. So this never grants control; it moves to
                # human_returned with the advisory on record, and the owner's explicit verify_identity is what
                # restores the agent. hand_back is the one-click way to reach that decision with the facts already read.
                from ampuly.computer_use import browser_bridge as _bridge

                after = await _bridge.page_facts_for_handoff(getattr(registry._entries.get(binding.key()), "runtime", None))
                registry.assert_control(binding, resource_id, control_fence)
                recommend, checks = _bridge.handoff_adjudication(registry.handoff_facts(binding), after,
                                                                 registry.state_of(binding).get("allowed_domains"))
                summary = ", ".join(f"{k}={v}" for k, v in sorted(checks.items()))
                state = registry.human_returned(binding, note=(note + "; " if note else "") + summary)
                state["checks"] = checks
                state["recommend"] = recommend
            elif command == "verify_identity":
                # C07: the page's own facts (address left the login page, same site, cookies grew) are
                # compared with what was recorded at the hand-off and written into the record next to
                # the owner's decision; the decision stays the owner's.
                from ampuly.computer_use import browser_bridge as _bridge

                after = await _bridge.page_facts_for_handoff(getattr(registry._entries.get(binding.key()), "runtime", None))
                registry.assert_control(binding, resource_id, control_fence)
                checks = _bridge.handoff_checks(registry.handoff_facts(binding), after)
                if note:
                    checks["operator_note"] = note
                state = registry.verify_identity(binding, ok=bool(data.get("ok", False)), checks=checks)
                state["checks"] = checks
            elif command == "revoke_and_close":
                if len(note) < 2:
                    raise ValueError("revocation_reason_required")
                # Cancel first, then revoke and close: an agent action still running is receipted cancelled before the
                # close can let it finish, so what it read or did is never handed back to the model (C13).
                early_cancelled = _cancel_browser_actions_for_binding(binding, reason=f"{command}: {note or 'owner'}")
                state = await registry.revoke_and_close(binding, reason=note)
            elif command in {"navigate", "back", "reload", "switch_tab", "open_tab", "close_tab"}:
                # X05: the pane's own address bar, back, reload and tab strip. Only while the registry says
                # a person holds the page; the same domain gate the agent's navigate goes through (W05).
                state = await self._browser_person_drives(registry, binding, command, note,
                                                         resource_id=resource_id, control_fence=control_fence)
            elif command == "allow_hosts":
                # X05 / C26: the page's resources came from hosts the owner never named (a CDN), so the
                # request-level policy refused them and the page stayed blank. The owner adds those hosts
                # here -- the same delegation record, the same hostnames-only cleaning (C01) -- and the page
                # is loaded again under the wider scope. The policy itself does not loosen.
                state = await self._browser_allow_hosts(registry, binding, note, actor=_ws_actor_login(self, ws),
                                                       resource_id=resource_id, control_fence=control_fence)
            elif command == "renew_lease":
                state = registry.renew_lease(binding, note=note)
            elif command in {"demo_start", "demo_stop"}:
                # X07: the owner records this session's admitted actions into a sealed demo.
                from ampuly.computer_use import browser_bridge as _bridge

                demo = (_bridge.demo_start(binding, recorded_by=_ws_actor_login(self, ws), label=note) if command == "demo_start"
                        else _bridge.demo_stop(binding))
                state = {**registry.state_of(binding), "demo": demo}
            elif command == "retry_close":
                closed = await registry.close(binding)
                state = {**registry.state_of(binding), "closed": closed}
            else:
                raise ValueError("unsupported_browser_session_command")
        except Exception as exc:
            reason = _browser_error_reason(exc)
            await self._send_ack(
                ws, ok=False, action="browser_session_control", project_id=project_id,
                command=command, error=reason,
            )
            return
        # D5 / S14: the session-state copy is a bounded convenience and is
        # deleted when a session closes.  The Gateway Journal owns the durable
        # audit fact, including who made the successful control decision.
        from ampuly.computer_use import browser_bridge as _bridge

        controls = registry.control_events(binding)
        cached = controls[-1] if len(controls) > prior_control_events else {}
        audit_recorded = _bridge.journal_control(
            binding, action=str(cached.get("action", "") or command), actor=_ws_actor_login(self, ws),
            at=cached.get("at"),
        )
        # C13 / C12: the Gateway follows the registry as one act. A hand-off or a
        # revocation also cancels whatever agent action is still in flight for
        # this binding, and the lease the Gateway checks is refreshed now rather
        # than at the next tool call. A bookkeeping failure never eats the ack.
        gateway_cancelled = 0
        if command in {"hand_to_human", "revoke_and_close"}:
            gateway_cancelled = _cancel_browser_actions_for_binding(binding, reason=f"{command}: {note or 'owner'}")
            gateway_cancelled += early_cancelled
        _sync_browser_gateway_lease(registry, binding)
        rows = [
            row for row in registry.operator_sessions()
            if row["project_id"] == project_id
        ]
        await self._send_ack(
            ws, ok=True, action="browser_session_control", project_id=project_id,
            command=command, binding_key=str(data.get("binding_key", "") or ""),
            state=state, sessions=rows, agent_actions_cancelled=gateway_cancelled,
            control_audit_recorded=audit_recorded,
        )

    async def _handle_browser_candidate_control(self, ws: Any, data: dict) -> None:
        """X07: the owner compiles a sealed demo into a candidate, admits a candidate, or lists them.

        The console is the only caller of the product's admission authority; a
        candidate is re-read from disk and its digest checked before admission;
        an external-effect step is admitted only with the approval reference the
        owner names. Nothing here replays anything.
        """
        from ampuly.computer_use.candidates import admit_from_console, compile_from_demo, list_candidates

        project_id = self._request_project_id(data)
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="browser_candidate_control", project_id=project_id, error="owner_required")
            return
        command = str(data.get("command", "") or "").strip()
        try:
            if command == "compile":
                result = compile_from_demo(str(data.get("demo_id", "") or ""))
            elif command == "admit":
                raw_refs = dict(data.get("approval_refs", {}) or {})
                refs = {int(k): str(v) for k, v in raw_refs.items() if str(v or "").strip()}
                from ampuly.application.effect_approval import EFFECT_APPROVAL_CHECKPOINT_TYPE, EffectApprovalService
                from ampuly.effects.models import EffectState

                facts: dict[str, dict[str, Any]] = {}
                store = getattr(getattr(self, "engine", None), "store", None)
                journal = getattr(getattr(getattr(self, "engine", None), "effect_gateway", None), "journal", None)
                for ref in sorted(set(refs.values())):
                    try:
                        checkpoint = await store.get_execution_checkpoint(
                            ref, project_id=project_id, checkpoint_type=EFFECT_APPROVAL_CHECKPOINT_TYPE,
                        )
                        recorded = dict((checkpoint.payload or {}).get("effect", {}) or {}) if checkpoint is not None else {}
                        effect_id = str(recorded.get("effect_id", "") or "")
                        effect = await asyncio.to_thread(journal.get, effect_id) if journal is not None and effect_id else None
                        if checkpoint is None or effect is None:
                            continue
                        EffectApprovalService._assert_checkpoint_binds_effect(checkpoint, effect)
                        facts[ref] = {"kind": effect.kind,
                                      "authorized": bool(effect.is_authorized and effect.state is not EffectState.REJECTED),
                                      "observation_hash": str(effect.payload.get("observation_hash", "") or "")}
                    except Exception:  # noqa: BLE001 - an unprovable reference is absent facts, never trusted
                        continue
                result = admit_from_console(str(data.get("candidate_id", "") or ""), admitted_by=_ws_actor_login(self, ws),
                                            approval_refs=refs, approval_facts=facts)
            elif command == "list":
                result = {"candidates": list_candidates()}
            elif command in {"run", "resume"}:
                result = await self._run_candidate(project_id, {**data, "resume": command == "resume"})
            elif command == "repair":
                # C20: a stopped replay is repaired by a fresh demo compiled into a new candidate whose
                # difference from the admitted one is spelled out; the owner admits it separately.
                from ampuly.computer_use.repair import propose_repair

                result = propose_repair(old_candidate_id=str(data.get("candidate_id", "") or ""), demo_id=str(data.get("demo_id", "") or ""),
                                        stopped_reason=str(data.get("stopped_reason", "") or ""))
            else:
                raise ValueError("unsupported_browser_candidate_command")
        except Exception as exc:  # noqa: BLE001 - the ack carries the reason; nothing ran
            reason = str(getattr(exc, "reason", "") or str(exc) or type(exc).__name__)[:300]
            await self._send_ack(ws, ok=False, action="browser_candidate_control", project_id=project_id, command=command, error=reason)
            return
        await self._send_ack(ws, ok=True, action="browser_candidate_control", project_id=project_id, command=command, **result)

    async def _run_candidate(self, project_id: str, data: dict) -> dict[str, Any]:
        """X07: replay an admitted candidate on one bound browser session, deterministically.

        The run is bound to the candidate on disk, its admission and the Effect
        claim the owner names (G12); the steps go through the same tools the
        agent uses, so every policy holds; drift or an unexpected page stops it.
        """
        from ampuly.computer_use.candidates import candidate_path, load_admission, load_candidate
        from ampuly.computer_use import browser_bridge
        from ampuly.computer_use.replay import replay_candidate
        from ampuly.computer_use.replay_journal import ReplayRunJournal
        from ampuly.computer_use.workflow_contracts import RunBinding, WorkflowRefused
        from ampuly.layer4_tools import browser as browser_tools
        from ampuly.layer4_tools.browser_sessions import BrowserBinding
        import secrets

        run_journal = ReplayRunJournal()
        resume = data.get("resume") is True
        resumed_state = None
        if resume:
            run_id = str(data.get("run_id", "") or "").strip()
            resumed_state = run_journal.load(run_id)
            candidate_id = resumed_state.candidate_id
            supplied_candidate_id = str(data.get("candidate_id", "") or "").strip()
            if supplied_candidate_id and supplied_candidate_id != candidate_id:
                raise WorkflowRefused("replay_run_binding_mismatch", run_id)
        else:
            candidate_id = str(data.get("candidate_id", "") or "").strip()
            run_id = f"run-{candidate_id}-{secrets.token_hex(8)}"
        path = candidate_path(candidate_id)
        if not path.is_file():
            raise WorkflowRefused("candidate_not_found", candidate_id)
        candidate = load_candidate(path)
        candidate_id = candidate.candidate_id
        admission = load_admission(candidate_id)
        if admission is None:
            raise WorkflowRefused("run_without_valid_admission", candidate_id)
        registry, binding = self._browser_binding_for_request(project_id, data)
        getter = getattr(getattr(self, "engine", None), "store", None)
        task = await getter.get_task(binding.task_id) if getter is not None and binding.task_id else None
        if task is None:
            raise WorkflowRefused("run_without_task", binding.task_id)
        task_binding = BrowserBinding.for_task(task)
        if task_binding.key() != binding.key():
            raise WorkflowRefused("run_binding_mismatch", binding.key())
        run = RunBinding(run_id=run_id, candidate=candidate, admission=admission,
                         scope_digest=browser_bridge.workflow_scope_for(task_binding), effect_claim=f"run:{run_id}")
        paused_effect = None
        if resumed_state is not None and resumed_state.status == "paused_for_approval":
            effect_journal = getattr(getattr(getattr(self, "engine", None), "effect_gateway", None), "journal", None)
            if effect_journal is None or not resumed_state.effect_id:
                raise WorkflowRefused("replay_effect_unavailable", run_id)
            try:
                paused_effect = await asyncio.to_thread(effect_journal.get, resumed_state.effect_id)
            except Exception as exc:  # noqa: BLE001 - recovery requires the authoritative Effect fact
                raise WorkflowRefused("replay_effect_unavailable", type(exc).__name__) from None
        inputs = {int(k): str(v) for k, v in dict(data.get("inputs", {}) or {}).items()}
        if not browser_bridge.note_replay_run(task_binding, run_id):
            raise WorkflowRefused("run_already_active", task_binding.key())
        try:
            outcome = await replay_candidate(
                run=run,
                task=task,
                tools=browser_tools,
                runtime_for=browser_tools._runtime_for,
                inputs=inputs,
                run_journal=run_journal,
                binding_key=task_binding.key(),
                paused_effect=paused_effect,
            )
        finally:
            browser_bridge.clear_replay_run(task_binding, run_id)
        # C20: a run of a repair candidate is the original acceptance run again; the repair record keeps it.
        from ampuly.computer_use.repair import record_rerun

        should_record_rerun = not resume or resumed_state is None or resumed_state.status not in {"complete", "stopped"}
        rerun = record_rerun(candidate_id, outcome) if should_record_rerun else None
        if rerun is not None:
            outcome = {**outcome, "repair": {"repairs": rerun.get("repairs", ""), "acceptance_passed": bool(rerun.get("acceptance_passed")),
                                             "reruns": len(rerun.get("acceptance_reruns", []) or [])}}
        return outcome

    def _subscribe_browser_sessions(self, registry: Any = None) -> None:
        registry = registry if registry is not None else self._browser_session_registry()
        subscriber = getattr(registry, "subscribe", None)
        if callable(subscriber):
            subscriber(self._on_browser_session_changed)

    def _on_browser_session_changed(self, row: dict[str, Any]) -> None:
        """Registry callback (sync). The push runs as its own task on the console's loop."""
        try:
            loop = asyncio.get_running_loop()
        except RuntimeError:
            return
        task = loop.create_task(self._push_browser_session_change(dict(row)))
        keep = getattr(self, "_background_tasks", None)
        if isinstance(keep, set):
            keep.add(task)
            task.add_done_callback(keep.discard)

    async def _push_browser_session_change(self, row: dict[str, Any]) -> None:
        """X05: owner consoles of the session's project hear the move; staff hear nothing; no page content travels."""
        project_id = str(row.get("project_id", "") or "")
        anchor = await self._browser_anchor_for_task(str(row.get("task_id", "") or ""), project_id)
        try:
            registry, binding = WSHandler._browser_binding_for_request(self, project_id, row, require_control=True)
        except Exception:
            return
        envelope = {"type": "browser_session_changed", "payload": {
            "project_id": project_id, "binding_key": str(row.get("binding_key", "") or ""), "task_id": str(row.get("task_id", "") or ""),
            "resource_id": row["resource_id"], "control_fence": row["control_fence"],
            "account": row.get("account"),
            "order_id": anchor["order_id"], "anchor_session_id": anchor["anchor_session_id"],
            "state": str(row.get("state", "") or ""), "note": str(row.get("note", "") or "")[:300],
            "allowed_domains": list(row.get("allowed_domains", []) or []), "live": bool(row.get("live", False))}}
        for ws in list(getattr(self, "_clients", set()) or ()):
            if not _ws_is_owner(self, ws):
                continue
            active = getattr(self, "_client_active_project_id", None)
            if not callable(active) or str(active(ws) or "") != project_id:
                continue
            try:
                registry.assert_control(binding, row["resource_id"], row["control_fence"])
                await self._safe_send_json(ws, envelope)
            except Exception:  # noqa: BLE001 - a console that went away is not this session's problem
                pass

    async def _handle_browser_view_start(self, ws: Any, data: dict) -> None:
        """X05: the session's live picture in the owner's own console. Owner only; frames go to the
        console that asked and to nothing else; the model's observation path is untouched."""
        project_id = self._request_project_id(data)
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="browser_view_start", project_id=project_id, error="owner_required")
            return
        stream_lock = None
        acquired = False
        try:
            registry, binding = WSHandler._browser_binding_for_request(self, project_id, data, require_control=True)
            resource_id, control_fence = data["resource_id"], data["control_fence"]
            stream_lock = _browser_stream_lock(self, binding.key(), resource_id)
            await stream_lock.acquire()
            acquired = True
            registry.assert_control(binding, resource_id, control_fence)
            entry = registry._entries.get(binding.key())
            runtime = getattr(entry, "runtime", None)
            starter = getattr(runtime, "start_screencast", None)
            if not callable(starter) or entry.unavailable:
                raise ValueError("browser_view_unavailable")
            touch = getattr(registry, "touch", None)
            if callable(touch):
                touch(binding)  # the owner opening the live view is activity (C16)
            key = binding.key()
            if not hasattr(self, "_browser_viewers"):
                self._browser_viewers = {}
            stream_key = (key, resource_id, control_fence)
            for old in list(self._browser_viewers):
                if isinstance(old, tuple) and old[0] == key and old != stream_key:
                    self._browser_viewers.pop(old, None)
            viewers = self._browser_viewers.setdefault(stream_key, set())
            viewers.add(ws)

            async def on_frame(data_b64: str, metadata: dict[str, Any]) -> None:
                def current() -> bool:
                    try:
                        live = registry.assert_control(binding, resource_id, control_fence)
                        return (live is entry and live.runtime is runtime and not live.unavailable
                                and self._browser_viewers.get(stream_key) is viewers)
                    except Exception:
                        return False
                if not current():
                    return
                gone = []
                for viewer in list(viewers):
                    active = getattr(self, "_client_active_project_id", None)
                    if (not _ws_is_owner(self, viewer) or not callable(active)
                            or str(active(viewer) or "") != project_id):
                        # It was the owner when it asked. Since then it logged out, an employee logged in on the
                        # same connection, or the console got its first account: the page images are not its to
                        # see, and it cannot stop the stream itself -- stopping is an owner's action too.
                        gone.append(viewer)
                        continue
                    try:
                        if not current():
                            return
                        await self._safe_send_json(viewer, {"type": "browser_frame", "payload": {
                            "project_id": project_id, "resource_id": resource_id, "control_fence": control_fence,
                            "binding_key": key, "data": data_b64, "width": metadata.get("deviceWidth"), "height": metadata.get("deviceHeight"),
                            "scroll_x": metadata.get("scrollOffsetX", 0), "scroll_y": metadata.get("scrollOffsetY", 0)}})
                    except Exception:  # noqa: BLE001 - a viewer that went away is dropped, the page goes on
                        gone.append(viewer)
                for viewer in gone:
                    viewers.discard(viewer)
                if gone and not viewers and current() and not stream_lock.locked():
                    # nobody is left to watch: stop producing page images, as browser_view_stop does
                    async with stream_lock:
                        if current() and not viewers:
                            self._browser_viewers.pop(stream_key, None)
                            stopper = getattr(runtime, "stop_screencast", None)
                            if callable(stopper):
                                try:
                                    await stopper()
                                except Exception:  # noqa: BLE001 - the page goes on whether or not the picture stops
                                    logger.opt(exception=True).debug("live view {} could not be stopped", key)

            started = await starter(on_frame)
            registry.assert_control(binding, resource_id, control_fence)
            if registry._entries.get(key) is not entry or entry.runtime is not runtime:
                raise ValueError("browser_control_changed")
        except Exception as exc:  # noqa: BLE001
            reason = _browser_error_reason(exc)
            await self._send_ack(ws, ok=False, action="browser_view_start", project_id=project_id, error=reason)
            return
        finally:
            if acquired:
                stream_lock.release()
        await self._send_ack(ws, ok=True, action="browser_view_start", project_id=project_id, binding_key=binding.key(),
                             resource_id=resource_id, control_fence=control_fence, **started)

    async def _handle_browser_view_stop(self, ws: Any, data: dict) -> None:
        project_id = self._request_project_id(data)
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="browser_view_stop", project_id=project_id, error="owner_required")
            return
        stream_lock = None
        acquired = False
        try:
            registry, binding = WSHandler._browser_binding_for_request(self, project_id, data, require_control=True)
            key = binding.key()
            resource_id, control_fence = data["resource_id"], data["control_fence"]
            stream_lock = _browser_stream_lock(self, key, resource_id)
            await stream_lock.acquire()
            acquired = True
            registry.assert_control(binding, resource_id, control_fence)
            stream_key = (key, resource_id, control_fence)
            if not hasattr(self, "_browser_viewers"):
                self._browser_viewers = {}
            viewers = self._browser_viewers.get(stream_key)
            if viewers is None:
                raise ValueError("browser_view_not_started")
            viewers.discard(ws)
            if not viewers:
                entry = registry._entries.get(key)
                stopper = getattr(getattr(entry, "runtime", None), "stop_screencast", None)
                if callable(stopper):
                    await stopper()
                if self._browser_viewers.get(stream_key) is viewers:
                    self._browser_viewers.pop(stream_key, None)
                registry.assert_control(binding, resource_id, control_fence)
        except Exception as exc:  # noqa: BLE001
            await self._send_ack(ws, ok=False, action="browser_view_stop", project_id=project_id, error=_browser_error_reason(exc))
            return
        finally:
            if acquired:
                stream_lock.release()
        await self._send_ack(ws, ok=True, action="browser_view_stop", project_id=project_id, binding_key=binding.key(),
                             resource_id=resource_id, control_fence=control_fence)

    async def _handle_browser_view_input(self, ws: Any, data: dict) -> None:
        """The person operating the page from the console. Only the owner, only while the registry says a
        person holds the page (awaiting_human); the agent's tools are refused meanwhile. The event's
        content -- what was typed -- is forwarded and never written anywhere."""
        project_id = self._request_project_id(data)
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="browser_view_input", project_id=project_id, error="owner_required")
            return
        try:
            registry, binding = WSHandler._browser_binding_for_request(self, project_id, data, require_control=True)
            resource_id, control_fence = data["resource_id"], data["control_fence"]
            entry = registry.assert_control(binding, resource_id, control_fence, human=True)
            injector = getattr(getattr(entry, "runtime", None), "inject_input", None)
            if not callable(injector):
                raise ValueError("browser_view_unavailable")
            # A person typing into the page is activity: idle expiry must not close the browser under them (C16).
            touch = getattr(registry, "touch", None)
            if callable(touch):
                touch(binding)
            with _browser_dispatch_scope(registry, binding, resource_id, control_fence, human=True):
                result = await injector(dict(data.get("event", {}) or {}))
        except Exception as exc:  # noqa: BLE001 - the reason names the rule, never the input
            reason = _browser_error_reason(exc)
            await self._send_ack(ws, ok=False, action="browser_view_input", project_id=project_id, error=reason[:120])
            return
        await self._send_ack(ws, ok=True, action="browser_view_input", project_id=project_id,
                             binding_key=binding.key(), resource_id=resource_id, control_fence=control_fence, **result)

    async def _handle_browser_view_pick(self, ws: Any, data: dict) -> None:
        """X05 pointer picking: the owner points at the live view and the console says what element sits
        there -- tag, role, a little text -- read-only (element_at / elementFromPoint), never a click or a
        page write. Owner only; the coordinate is a viewport point the live view mapped, and the element
        text is already clipped by element_at (C27)."""
        project_id = self._request_project_id(data)
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="browser_view_pick", project_id=project_id, error="owner_required")
            return
        try:
            registry, binding = WSHandler._browser_binding_for_request(self, project_id, data, require_control=True)
            resource_id, control_fence = data["resource_id"], data["control_fence"]
            entry = registry._entries.get(binding.key())
            picker = getattr(getattr(entry, "runtime", None), "element_at", None)
            if not callable(picker) or entry.unavailable:
                raise ValueError("browser_view_unavailable")
            touch = getattr(registry, "touch", None)
            if callable(touch):
                touch(binding)  # pointing at the page is activity (C16)
            with _browser_dispatch_scope(registry, binding, resource_id, control_fence):
                element = await picker(float(data.get("x", 0) or 0), float(data.get("y", 0) or 0))
        except Exception as exc:  # noqa: BLE001 - the reason names the rule, never the page
            reason = _browser_error_reason(exc)
            await self._send_ack(ws, ok=False, action="browser_view_pick", project_id=project_id, error=reason[:120])
            return
        await self._send_ack(ws, ok=True, action="browser_view_pick", project_id=project_id,
                             binding_key=binding.key(), resource_id=resource_id, control_fence=control_fence, element=element or {})

    async def _handle_browser_screenshot_read(self, ws: Any, data: dict) -> None:
        """X05: the owner sees the session's own masked screenshot. Owner only; the name is a bare file
        name resolved inside that binding's artifact directory and re-checked after resolution; the
        file is the runtime's own (masked before it existed); bounded in size; nothing else is served."""
        import base64

        project_id = self._request_project_id(data)
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="browser_screenshot_read", project_id=project_id, error="owner_required")
            return
        name = str(data.get("name", "") or "").strip()
        try:
            registry, binding = self._browser_binding_for_request(project_id, data)
            from ampuly.computer_use.browser_bridge import _artifact_dir_for

            if not name or Path(name).name != name or not name.lower().endswith(".png"):
                raise ValueError("screenshot_name_invalid")
            root = _artifact_dir_for(binding).resolve()
            target = (root / name).resolve()
            if target.parent != root or not target.is_file():
                raise FileNotFoundError(name)
            raw = target.read_bytes()
            if len(raw) > 8 * 1024 * 1024:
                raise ValueError("screenshot_too_large")
            data_url = "data:image/png;base64," + base64.b64encode(raw).decode("ascii")
        except Exception as exc:  # noqa: BLE001 - the ack carries the reason; nothing else is read
            reason = str(getattr(exc, "reason", "") or str(exc) or type(exc).__name__)[:200]
            await self._send_ack(ws, ok=False, action="browser_screenshot_read", project_id=project_id, error=reason)
            return
        await self._send_ack(ws, ok=True, action="browser_screenshot_read", project_id=project_id, binding_key=binding.key(),
                             name=name, size=len(raw), data_url=data_url)

    async def _browser_audit_for_binding(self, registry: Any, binding: Any) -> dict[str, Any]:
        """Build the one sanitized browser story used by both view and export."""
        from ampuly.computer_use import browser_bridge
        from ampuly.computer_use.audit import audit_trail

        engine = getattr(self, "engine", None)
        journal = getattr(getattr(engine, "effect_gateway", None), "journal", None)
        key = binding.key()
        effects: list[Any] = []
        effect_events: dict[str, list[Any]] = {}
        lister = getattr(journal, "list_effects", None)
        if callable(lister):
            for record in lister(kind="browser.submit"):
                if str(dict(record.payload or {}).get("binding_key", "") or "") == key:
                    effects.append(record)
                    effect_events[record.effect_id] = journal.list_events(record.effect_id)
        metadata: dict[str, Any] = {}
        getter = getattr(getattr(engine, "store", None), "get_task", None)
        if callable(getter) and binding.task_id:
            task = await getter(binding.task_id)
            metadata = dict(getattr(task, "metadata", {}) or {}) if task is not None else {}
        return audit_trail(
            binding_key=key,
            task_id=str(binding.task_id or ""),
            gateway_events=browser_bridge.events_for(binding),
            effects=effects,
            effect_events=effect_events,
            task_metadata=metadata,
            session=registry.state_of(binding),
            combination=_browser_combination_evidence(engine),
            console_events=registry.control_events(binding),
            # The task's metadata names the order step's download folder after a restart (data phase 1).
            artifacts=browser_bridge.session_artifacts(binding, task_metadata=metadata or None),
        )

    async def _handle_browser_audit_trail(self, ws: Any, data: dict) -> None:
        """C24: one browser session's whole story -- Gateway events, submits and their approvals,
        the delegated scope, who holds the page -- joined into one ordered view for the owner."""
        project_id = self._request_project_id(data)
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="browser_audit_trail", project_id=project_id, error="owner_required")
            return
        try:
            registry, binding = self._browser_binding_for_request(project_id, data)
            trail = await WSHandler._browser_audit_for_binding(self, registry, binding)
        except Exception as exc:  # noqa: BLE001 - the ack carries the reason; a view never changes state
            reason = str(getattr(exc, "reason", "") or str(exc) or type(exc).__name__)[:300]
            await self._send_ack(ws, ok=False, action="browser_audit_trail", project_id=project_id, error=reason)
            return
        await self._send_ack(ws, ok=True, action="browser_audit_trail", project_id=project_id, trail=trail)

    async def _handle_browser_audit_export(self, ws: Any, data: dict) -> None:
        """Persist the sanitized story below its authoritative order, never a caller path."""
        project_id = self._request_project_id(data)
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="browser_audit_export", project_id=project_id, error="owner_required")
            return
        try:
            from ampuly.computer_use.audit_export import export_audit_trail

            registry, binding = self._browser_binding_for_request(project_id, data)
            trail = await WSHandler._browser_audit_for_binding(self, registry, binding)
            anchor = await self._browser_anchor_for_task(str(binding.task_id or ""), project_id)
            order_id = str(anchor.get("order_id", "") or binding.task_id or "").strip()
            if not order_id:
                raise ValueError("browser_order_not_found")
            # Under the business order's folder when the session works for one (data phase 1); the anchor task's
            # folder otherwise, as before.
            business_order_id = await WSHandler._business_order_for_browser(
                self, str(binding.task_id or ""), order_id, project_id,
            )
            export_trail = {**trail, "task_id": order_id}
            result = await asyncio.to_thread(
                export_audit_trail,
                export_trail,
                order_root=get_project_workplace(project_id) / "orders" / (business_order_id or order_id),
                order_id=business_order_id,
            )
            path = Path(result["path"])
        except Exception as exc:  # noqa: BLE001 - bounded reason only; no local path is returned
            reason = str(getattr(exc, "reason", "") or str(exc) or type(exc).__name__)[:300]
            await self._send_ack(ws, ok=False, action="browser_audit_export", project_id=project_id, error=reason)
            return
        await self._send_ack(
            ws,
            ok=True,
            action="browser_audit_export",
            project_id=project_id,
            binding_key=binding.key(),
            order_id=order_id,
            business_order_id=business_order_id,
            name=path.name,
            sha256=str(result["sha256"]),
            created=bool(result["created"]),
        )

    async def _handle_effect_look_back(self, ws: Any, data: dict) -> None:
        """C10: the owner asks whether an effect whose outcome is unknown actually happened.

        The provider looks at the world again; complete evidence resolves the
        effect as applied, anything weaker leaves it unknown with the evidence
        attached. Nothing is applied again, whatever the answer.
        """
        project_id = self._request_project_id(data)
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="effect_look_back", project_id=project_id, error="owner_required")
            return
        effect_id = str(data.get("effect_id", "") or "").strip()
        gateway = getattr(getattr(self, "engine", None), "effect_gateway", None)
        look_back = getattr(gateway, "look_back", None)
        if not effect_id or not callable(look_back):
            await self._send_ack(ws, ok=False, action="effect_look_back", project_id=project_id,
                                 error="effect_id_required" if not effect_id else "effect_gateway_unavailable")
            return
        account = getattr(self, "_client_accounts", {}).get(ws)
        try:
            confirmation = data.get("owner_confirmation")
            if confirmation is None:
                verification = await look_back(effect_id, requested_by=str(getattr(account, "login", "") or "owner"))
            else:
                # A person's explicit receipt review is recorded as their word,
                # separately from a provider's automatic verification. It never
                # changes the proposed input or calls the provider again.
                from ampuly.effects.models import EffectVerification, EffectState, VerificationStatus
                if type(confirmation) is not dict or set(confirmation) != {"happened", "evidence_sha256", "reference", "note"}:
                    raise ValueError("invalid_owner_confirmation")
                digest = confirmation.get("evidence_sha256")
                reference = confirmation.get("reference")
                note = confirmation.get("note")
                if (type(confirmation.get("happened")) is not bool or type(digest) is not str
                        or re.fullmatch(r"[0-9a-f]{64}", digest) is None
                        or type(reference) is not str or re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_.-]{0,127}", reference) is None
                        or type(note) is not str or not 20 <= len(note.strip()) <= 500):
                    raise ValueError("explicit_receipt_review_required")
                actor = _ws_actor_login(self, ws)
                record = await asyncio.to_thread(gateway.journal.get, effect_id)
                if (record.project_id != project_id or record.kind != "browser.submit"
                        or record.provider != "browser:submit" or record.state != EffectState.OUTCOME_UNKNOWN):
                    raise ValueError("owner_review_effect_scope_refused")
                if not actor or not _ws_is_owner(self, ws) or _ws_actor_login(self, ws) != actor:
                    raise ValueError("owner_authorization_changed")
                details = {"source": "owner_attestation", "requested_by": actor,
                           "happened": confirmation["happened"], "evidence_sha256": digest,
                           "reference": reference, "note": note.strip()}
                updated = await asyncio.to_thread(gateway.journal.record_look_back, effect_id,
                    status=VerificationStatus.COMPLETE, details=details)
                verification = EffectVerification(effect_id=effect_id, status=VerificationStatus.COMPLETE,
                    details={**details, "resolved": True, "state": updated.state.value})
        except Exception as exc:  # noqa: BLE001 - the ack carries the reason; nothing was applied
            reason = str(getattr(exc, "reason", "") or str(exc) or type(exc).__name__)[:300]
            await self._send_ack(ws, ok=False, action="effect_look_back", project_id=project_id, effect_id=effect_id, error=reason)
            return
        # A12 / C10: the budget hold placed for this effect's unknown outcome is lifted only when the
        # look-back resolved it by evidence; anything weaker leaves the hold for a person.
        released: list[dict[str, Any]] = []
        if verification.details.get("resolved"):
            business = getattr(self._accounts(), "business", None)
            release = getattr(business, "release_budget_hold_for_effect", None)
            if callable(release):
                try:
                    released = await asyncio.to_thread(release, effect_id, reason=f"look-back by {getattr(account, 'login', '') or 'owner'} resolved effect {effect_id} as {verification.details.get('state', 'resolved')}")
                except Exception as exc:  # noqa: BLE001 - the resolution stands; a hold that could not be lifted is said
                    released = [{"error": f"{type(exc).__name__}: {exc}"[:200]}]
        await self._send_ack(
            ws, ok=True, action="effect_look_back", project_id=project_id, effect_id=effect_id,
            status=verification.status.value, resolved=bool(verification.details.get("resolved")),
            state=str(verification.details.get("state", "")), details=dict(verification.details),
            budget_holds_released=released,
        )

    async def _handle_local_browser_consent(self, ws: Any, data: dict) -> None:
        from ampuly.plugins.office_ui.local_browser_consent_ws import handle_local_browser_consent
