    async def _handle_connector_candidate_register(self, ws: Any, data: dict) -> None:
        from ampuly.plugins.office_ui.connector_candidate import (
            ConnectorCandidateError,
            candidate_by_id,
            register_candidate,
        )
        from ampuly.plugins.office_ui.connector_contract import ContractError, sample_client

        resolve_engine = getattr(self, "_engine_for_request", None)
        if callable(resolve_engine):
            run_engine, project_id = await resolve_engine(data)
        else:
            run_engine, project_id = self.engine, self._request_project_id(data)
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="connector_candidate_register", project_id=project_id, error="owner_required")
            return
        root, registry = self._connector_candidate_roots(project_id)
        try:
            candidate = candidate_by_id(root, str(data.get("candidate_id", "") or ""))
            entry = register_candidate(
                candidate,
                registry,
                actor=_ws_actor_login(self, ws),
                expected_fingerprint=str(data.get("expected_fingerprint", "") or ""),
                health_client=sample_client(credential="local-contract-test"),
                base_url="http://connector-contract.invalid",
                credential="local-contract-test",
            )
        except (ConnectorCandidateError, ContractError) as exc:
            await self._send_ack(ws, ok=False, action="connector_candidate_register", project_id=project_id, error=str(exc))
            return
        runtime_binding: dict[str, Any] = {}
        runtime_binding_error = ""
        try:
            runtime_binder = getattr(self, "_bind_registered_connector_runtime", None)
            bindings = runtime_binder(run_engine, project_id) if callable(runtime_binder) else []
            runtime_binding = next(
                (row for row in bindings if row.get("connector") == entry.get("connector")),
                {},
            )
        except Exception as exc:  # registration is durable; report binding separately
            runtime_binding_error = str(exc)[:300]
        await self._send_ack(
            ws, ok=True, action="connector_candidate_register", project_id=project_id,
            registration=entry,
            note="registered disabled; activation remains a separate owner action",
            runtime_binding=runtime_binding,
            runtime_binding_error=runtime_binding_error,
        )

