    # ── Kanban ────────────────────────────────────────────────────────

    async def _handle_kanban_create_task(self, ws: Any, data: dict) -> None:
        try:
            _engine, pid = await self._engine_for_request(data)
            result = await self.services.kanban.create_task(
                project_id=pid,
                title=data.get("title", "Untitled"),
                description=data.get("description", ""),
                task_id=data.get("task_id"),
                board_id=data.get("board_id", pid),
                assignee_ids=data.get("assignee_ids", []),
            )
            self._session_to_task.update(self.services_context.session_to_task)
            await self._publish_service_result(result)
        except ServiceError as exc:
            await self._send_service_error(ws, exc, action="kanban_create_task")

    async def _handle_kanban_move_task(self, ws: Any, data: dict) -> None:
        try:
            _engine, project_id = await self._engine_for_request(data)
            result = await self.services.kanban.move_task(
                project_id=project_id,
                task_id=data.get("task_id", ""),
                column_id=data.get("column_id", ""),
            )
            await self._publish_service_result(result)
            await self._send_ack(ws, ok=True, **result.payload)
        except ServiceError as exc:
            await self._send_service_error(ws, exc, action="kanban_move_task")

    # ── Agent Management ──────────────────────────────────────────────

    async def _build_org_info_payload(self) -> dict[str, Any]:
        """Build the full org_info payload via OrgService."""
        result = await self._ensure_office_services().org.info()
        return result.payload

    async def _broadcast_org_info(self) -> None:
        """Build org_info payload and broadcast to ALL connected clients."""
        result = await self._ensure_office_services().org.info(include_events=True)
        await self._publish_service_result(result)

    async def _broadcast_snapshot(self) -> None:
        snapshot = await build_snapshot(
            self.engine, self.agent_store, self.chat_store, self.event_adapter
        )
        snapshot["exec_mode"] = self._exec_mode
        snapshot["company_profile"] = self._company_profile
        snapshot["task_preferred_agent"] = self._task_preferred_agent
        await self.broadcast({"type": "snapshot", "payload": snapshot})
        await self._broadcast_owner_interaction_baseline(
            engine=self.engine,
            project_id=self._normalize_project_id(getattr(self.engine, "project_id", None)),
        )

    async def _ensure_custom_role_agents(self) -> list[dict[str, Any]]:
        if self._exec_mode not in {"org", "custom"} or not self.engine.org_engine:
            return await self.agent_store.get_all()
        agents = await self.agent_store.ensure_custom_role_agents(self.engine.org_engine)
        await self._sync_role_map()
        return agents

    async def _handle_list_agents(self, ws: Any, data: dict) -> None:
        result = await self._ensure_office_services().agent.list()
        await self._send_service_ack(ws, result)

    # ── Company Runtime Mode ─────────────────────────────────────────────────

    async def _handle_set_mode(self, ws: Any, data: dict) -> None:
        new_mode = data.get("mode", "task")
        new_profile = data.get("profile", "corporate")
        org_id = self._normalize_session_org_id(
            data.get("org_id") or data.get("organization_id")
        )
        new_preferred_agent = self._normalize_session_preferred_agent(
            data.get("preferred_agent", self._task_preferred_agent),
            default=self._task_preferred_agent,
        )
        ok = await self._apply_mode_switch(new_mode, new_profile, new_preferred_agent, org_id=org_id)
        if not ok:
            await self._send_ack(
                ws,
                ok=False,
                error=getattr(self, "_last_org_load_error", "") or "org_not_found",
                org_id=org_id,
            )
            return
        active_org_id = (org_id or await self._get_active_saved_org_name()) if self._exec_mode == "org" else ""
        await self._send_ack(
            ws,
            ok=True,
            mode=self._exec_mode,
            profile=self._company_profile,
            org_id=active_org_id,
            preferred_agent=self._task_preferred_agent,
        )

    async def _apply_mode_switch(
        self,
        new_mode: str,
        new_profile: str,
        new_preferred_agent: str,
        *,
        sync_config: bool = True,
        org_id: str | None = None,
    ) -> bool:
        # Mode is a default for new turns. Existing sessions carry their own
        # persisted mode/profile, so switching the toolbar must not interrupt or
        # rewrite running task state.
        previous_mode = getattr(self, "_exec_mode", "task")
        previous_profile = getattr(self, "_company_profile", "corporate")
        previous_preferred_agent = getattr(self, "_task_preferred_agent", "native")
        new_mode = self._normalize_session_exec_mode(new_mode)
        self._last_org_load_error = ""
        if sync_config and new_mode == "org" and org_id:
            config_dir = Path(getattr(self.engine, "ampuly_home", None) or Path.cwd() / ".ampuly") / "config"
            if not org_config_path(config_dir, org_id).exists():
                self._last_org_load_error = "org_not_found"
                return False
        new_profile = "custom" if new_mode == "org" else self._normalize_session_company_profile(new_profile)
        self._exec_mode = new_mode
        self._company_profile = new_profile
        self._task_preferred_agent = new_preferred_agent
        if hasattr(self, "services_context"):
            self.services_context.mode_state.exec_mode = self._exec_mode
            self.services_context.mode_state.company_profile = self._company_profile
            self.services_context.mode_state.task_preferred_agent = self._task_preferred_agent
        await self._persist_mode()

        # Sync company_profile in config so _effective_roles() uses the right mode
        if sync_config and self.engine.org_engine:
            async with self._config_lock:
                if new_mode == "org":
                    loaded = self._load_active_org_config_into_engine(org_id)
                    if not loaded:
                        self._exec_mode = previous_mode
                        self._company_profile = previous_profile
                        self._task_preferred_agent = previous_preferred_agent
                        if hasattr(self, "services_context"):
                            self.services_context.mode_state.exec_mode = self._exec_mode
                            self.services_context.mode_state.company_profile = self._company_profile
                            self.services_context.mode_state.task_preferred_agent = self._task_preferred_agent
                        await self._persist_mode()
                        return False
                    elif org_id:
                        await self._set_active_saved_org_name(org_id)
                elif new_mode == "company":
                    self._restore_company_config_into_engine(new_profile)
                else:
                    self._restore_company_config_into_engine("")
                # Mode switching persists only the selected UI mode. It must not
                # rewrite company/org architecture files.

        # Reload agents for the new mode
        if self.engine.org_engine:
            preset = self._resolve_preset_name()
            await self.agent_store.load_preset(preset, self.engine.org_engine)

        await self._prune_stale_agent_store_entries()
        if self._exec_mode in {"org", "custom"}:
            await self._ensure_custom_role_agents()

        # Sync role→agent mapping for EventAdapter
        await self._sync_role_map()

        # B4: Clean orphan references — clear assigned_to on pending tasks
        # whose role no longer exists, and prune stale DM channels
        new_agents = await self.agent_store.get_all()
        valid_agent_ids = {a["agent_id"] for a in new_agents}
        valid_role_ids = {a.get("ampuly_role_id", a["agent_id"]) for a in new_agents}
        if self.engine.store:
            pending_tasks = await self.engine.store.get_tasks(project_id=self.engine.project_id or "default")
            for task in pending_tasks:
                if not task.assigned_to or task.assigned_to in valid_role_ids:
                    continue
                task_meta = dict(getattr(task, "metadata", {}) or {})
                # Finished rows and runtime auxiliary rows (CEO assessments,
                # meeting turns) are fenced beneath a run lease that is long
                # gone; rewriting them here would raise lease-lost and abort
                # the whole switch. They are history, not assignments.
                if str(getattr(task, "status", "") or "") in {"done", "cancelled", "failed"}:
                    continue
                if task_meta.get("runtime_auxiliary_task") or task_meta.get("company_runtime_auxiliary_task"):
                    continue
                task.assigned_to = ""
                try:
                    await self.engine.store.save_task(task)
                except CompanyRunControllerLeaseLost as exc:
                    logger.warning("mode switch: left task {} untouched ({})", str(task.id)[:8], exc)
        await self.chat_store.prune_stale_channels(valid_agent_ids, project_id=self.engine.project_id or "default")
        # Ensure activity channel exists (session channels are on-demand)
        await self.chat_store.ensure_activity_channel(project_id=self.engine.project_id or "default")

        # Broadcast snapshot + full collab_sync so frontend refreshes everything
        snapshot = await build_snapshot(
            self.engine, self.agent_store, self.chat_store, self.event_adapter
        )
        snapshot["exec_mode"] = self._exec_mode
        snapshot["company_profile"] = self._company_profile
        snapshot["task_preferred_agent"] = self._task_preferred_agent
        await self.broadcast({"type": "snapshot", "payload": snapshot})

        collab = await build_collab_sync(
            self.engine,
            self.agent_store,
            self.chat_store,
            self.event_adapter,
            exec_mode=self._exec_mode,
        )
        await self.broadcast({"type": "collab_sync_push", "payload": collab})
        await self._broadcast_owner_interaction_baseline(
            engine=self.engine,
            project_id=self._normalize_project_id(getattr(self.engine, "project_id", None)),
            after_sync=collab,
        )
        await self._broadcast_org_info()
        return True

    async def _prune_stale_agent_store_entries(self) -> None:
        if not self.engine.org_engine or not hasattr(self, "agent_store"):
            return

        effective_role_ids = {agent.role_id for agent in self.engine.org_engine.list_agents()}
        try:
            effective_employee_ids = {employee.employee_id for employee in self.engine.config.org.employees}
        except Exception:
            effective_employee_ids = set()

        for stale in await self.agent_store.get_all():
            emp_id = str(stale.get("employee_id") or "").strip()
            role_id = str(stale.get("ampuly_role_id") or stale.get("agent_id") or "").strip()
            is_stale = (
                (emp_id and emp_id not in effective_employee_ids)
                or (not emp_id and role_id and role_id not in effective_role_ids)
            )
            if is_stale:
                try:
                    await self.agent_store.remove_agent(stale["agent_id"])
                except Exception:
                    logger.debug(f"Failed to prune stale agent {stale.get('agent_id')}")

        if self._exec_mode in {"org", "custom"}:
            await self.agent_store.sync_custom_shadow()

    def _target_mode_for_profile(self, profile: str | None) -> tuple[str | None, str | None]:
        if profile == "custom":
            return "org", "custom"
        if profile == "corporate":
            return "company", "corporate"
        return None, None

    def _rebind_engine_config(self, config: Any) -> None:
        self.engine.config = config
        org_engine = getattr(self.engine, "org_engine", None)
        if org_engine is not None:
            org_engine.config = config
        talent_market = getattr(self.engine, "talent_market", None)
        if talent_market is not None:
            talent_market.config = config
        if hasattr(self.engine, "_runtime_config_signature"):
            self.engine._runtime_config_signature = None

    def _restore_company_config_into_engine(self, company_profile: str) -> None:
        config_dir = Path(getattr(self.engine, "ampuly_home", None) or Path.cwd() / ".ampuly") / "config"
        try:
            loaded_config = AmpulyConfig.load(config_dir) if config_dir.exists() else AmpulyConfig()
        except Exception as exc:
            logger.warning(f"Failed to reload company architecture after leaving org mode: {exc}")
            loaded_config = self.engine.config
        loaded_config.org.company_profile = company_profile
        self._rebind_engine_config(loaded_config)
        if self.engine.org_engine:
            self.engine.org_engine.reload_from_config()
            configure_tools = getattr(self.engine.org_engine, "configure_task_mode_tools", None)
            task_tools = getattr(self.engine, "_task_mode_tool_names", None)
            if callable(configure_tools) and callable(task_tools):
                configure_tools(task_tools())

    def _load_active_org_config_into_engine(self, organization_id: str | None = None) -> bool:
        config_dir = Path(getattr(self.engine, "ampuly_home", None) or Path.cwd() / ".ampuly") / "config"
        self._last_org_load_error = ""
        try:
            payload, source_path = load_org_config_payload(config_dir, organization_id)
            loaded_config = apply_org_config_payload_to_config(
                self.engine.config,
                payload,
                source_path=source_path,
            )
            validate_runnable_org_config(loaded_config, organization_id=organization_id or "")
        except FileNotFoundError:
            self._last_org_load_error = "org_not_found"
            return False
        except Exception as exc:
            self._last_org_load_error = str(exc)
            logger.warning(f"Failed to load org architecture for org mode: {exc}")
            return False
        self._rebind_engine_config(loaded_config)
        if self.engine.org_engine:
            self.engine.org_engine.reload_from_config()
        return True

    def _resolve_preset_name(self) -> str:
        """Map current mode to agent_store preset name.

        task    → "single" (1 executor)
        company → profile name ("corporate")
        org     → "custom" (user-managed agents)
        """
        if self._exec_mode in {"org", "custom"}:
            return "custom"
        if self._exec_mode == "company":
            return self._company_profile  # "corporate"
        return "single"  # task mode uses single-agent preset

    async def _handle_run_task(self, ws: Any, data: dict) -> None:
        title = data.get("title", "")
        description = data.get("description", "")
        mode = data.get("mode", self._exec_mode)
        profile = data.get("profile", self._company_profile)
        org_id = self._normalize_session_org_id(data.get("org_id") or data.get("organization_id"))
        task_id = data.get("task_id")
        run_engine, run_project_id = await self._engine_for_request(data)
        self._track(self._run_task(
            title,
            description,
            mode,
            profile,
            task_id=task_id,
            run_engine=run_engine,
            run_project_id=run_project_id,
            org_id=org_id,
        ))
        await self._send_ack(ws, ok=True)

    # ── Cross-Office ──────────────────────────────────────────────────

    async def _handle_cross_office(self, ws: Any, data: dict) -> None:
        """Visual-only: broadcasts collab event for frontend animation. No engine dispatch."""
        await self.broadcast({"type": "cross_office_collab", "payload": {
            "agent_ids": data.get("agent_ids", []),
            "task_id": data.get("task_id", ""),
            "action": data.get("action", ""),
        }})

    # ══════════════════════════════════════════════════════════════════════
    # Private helpers
    # ══════════════════════════════════════════════════════════════════════

    def _controller_active_task_run_registry(self) -> Any | None:
        root_engine = getattr(self, "_root_engine", None) or getattr(self, "engine", None)
        registry = getattr(root_engine, "_active_task_run_registry", None)
        return registry if isinstance(registry, ActiveTaskRunRegistry) else None

    def _release_current_execution_handoff(self) -> None:
        registry = self._controller_active_task_run_registry()
        release = getattr(registry, "release_current_handoff", None)
        if callable(release):
            release()

    def _track_ui_projection(self, coro: Any) -> asyncio.Task[Any] | None:
        """Bound best-effort UI work without retaining an execution handoff.

        The decision is already durable. Reconnect reads rebuild this projection;
        neither this task nor its failure grants or revokes execution authority.
        """
        tasks = getattr(self, "_background_tasks", None)
        if tasks is None:
            tasks = set()
            self._background_tasks = tasks
        if (getattr(self, "_shutting_down", False) or type(tasks) is not set
                or sum(not task.done() and task.get_name() == "office-ui-projection"
                       for task in tasks) >= 64):
            if inspect.iscoroutine(coro):
                coro.close()
            logger.debug("UI projection deferred; durable facts remain readable")
            return None
        # A UI projection must not inherit a company execution/handoff context.
        import contextvars
        try:
            task = asyncio.create_task(coro, name="office-ui-projection", context=contextvars.Context())
        except Exception:
            if inspect.iscoroutine(coro):
                coro.close()
            logger.opt(exception=True).warning("UI projection unavailable; durable decision is unchanged")
            return None
        tasks.add(task)
        def finished(done: asyncio.Task[Any]) -> None:
            tasks.discard(done)
            if not done.cancelled():
                error = done.exception()
                if error is not None:
                    logger.opt(exception=error).warning("UI projection failed; durable decision is unchanged")
        task.add_done_callback(finished, context=contextvars.Context())
        return task

    def _track(self, coro: Any) -> asyncio.Task[Any]:
        """Create a tracked background task that auto-removes itself on completion."""
        handoff_registry = self._controller_active_task_run_registry()
        handoff_token = (
            handoff_registry.retain_current_handoff()
            if handoff_registry is not None
            else None
        )
        try:
            task = asyncio.create_task(coro)
        except BaseException:
            if handoff_registry is not None and handoff_token is not None:
                handoff_registry.release_handoff(handoff_token)
            if inspect.iscoroutine(coro):
                coro.close()
            raise
        if handoff_registry is not None and handoff_token is not None:
            def _release_execution_handoff(
                done_task: asyncio.Task[Any],
                *,
                registry: ActiveTaskRunRegistry = handoff_registry,
                token: str = handoff_token,
            ) -> None:
                registry.release_handoff(token)
                task_context = getattr(self, "_task_bg_context", None)
                if isinstance(task_context, dict):
                    context = task_context.get(done_task)
                    if isinstance(context, dict):
                        context.pop("execution_handoff_token", None)
                        if not context:
                            task_context.pop(done_task, None)

            task.add_done_callback(
                _release_execution_handoff
            )
            # This task owns the accepted engine handoff even before callers
            # such as _track_session add their richer session context.  Keep it
            # in the existing execution-owned task index so shutdown cannot
            # close the store while its cancellation cleanup is still running.
            task_context = getattr(self, "_task_bg_context", None)
            if isinstance(task_context, dict):
                context = task_context.setdefault(task, {})
                context["execution_handoff_token"] = handoff_token
        # Work scheduled after the gate closes is rejected.  A coroutine
        # retained by a pre-shutdown reservation is the one exception: it must
        # reach registry.register (or exit) before checkpoint snapshotting.
        if self._shutting_down and handoff_token is None:
            task.cancel()
        self._background_tasks.add(task)
        task.add_done_callback(self._on_bg_task_done)
        return task

    def _cancel_client_project_index(self, ws: Any) -> None:
        task = self._client_project_index_tasks.pop(ws, None)
        if task is not None and not task.done():
            task.cancel()

    def _track_client_project_index(
        self,
        ws: Any,
        coro: Any,
    ) -> asyncio.Task[Any]:
        self._cancel_client_project_index(ws)
        task = self._track(coro)
        self._client_project_index_tasks[ws] = task

        def _cleanup(done: asyncio.Task[Any]) -> None:
            if self._client_project_index_tasks.get(ws) is done:
                self._client_project_index_tasks.pop(ws, None)

        task.add_done_callback(_cleanup)
        return task

    def _track_client_initial_state(
        self,
        ws: Any,
        coro: Any,
    ) -> asyncio.Task[Any]:
        ws = _socket_behind(ws)
        prior = self._client_initial_state_tasks.pop(ws, None)
        if prior is not None and not prior.done():
            prior.cancel()
        task = self._track(coro)
        # A transient admission barrier, never an auth or delivery receipt.
        setattr(task, "_ui_initial_snapshot_ready", asyncio.Event())
        setattr(task, "_ui_initial_snapshot_delivered", False)
        self._client_initial_state_tasks[ws] = task

        def _cleanup(done: asyncio.Task[Any]) -> None:
            ready = getattr(done, "_ui_initial_snapshot_ready", None)
            if isinstance(ready, asyncio.Event):
                ready.set()  # Also release on failure/cancel; final fences still decide.
            if self._client_initial_state_tasks.get(ws) is done:
                self._client_initial_state_tasks.pop(ws, None)

        task.add_done_callback(_cleanup)
        return task

    def _track_session(
        self,
        task_id: str,
        coro: Any,
        *,
        project_id: str | None = None,
        engine: Any | None = None,
    ) -> asyncio.Task[Any]:
        """Like _track but keeps all live tasks for explicit cancellation."""
        source_lock = WSHandler._source_task_lock_for(self, task_id)
        if source_lock is not None:
            bg = None
            callback_installed = False
            try:
                if (type(self._task_bg_context) is not dict
                        or type(self._task_bg_map) is not dict
                        or type(self._background_tasks) is not set
                        or not inspect.iscoroutine(coro)):
                    raise RuntimeError("source task lock unavailable") from None
                group = self._task_bg_map.get(task_id)
                if group is not None and type(group) is not set:
                    raise RuntimeError("source task lock unavailable") from None
                prepared_context = {
                    "task_id": task_id,
                    "project_id": self._normalize_project_id(
                        project_id or getattr(engine, "project_id", None)),
                    "engine": engine,
                }
                bg = WSHandler._track(self, coro)
                if not issubclass(type(bg), asyncio.Task):
                    raise RuntimeError("source task lock unavailable") from None
                asyncio.Task.add_done_callback(bg, lambda done:
                    WSHandler._discard_session_bg_task(
                        self, task_id, done, _source_lock=source_lock))
                callback_installed = True
                retained_context = self._task_bg_context.get(bg)
                if retained_context is not None and type(retained_context) is not dict:
                    raise RuntimeError("source task lock unavailable") from None
                context = dict(retained_context or {})
                context.update(prepared_context)
                self._task_bg_context[bg] = context
                task_group = self._task_bg_map.setdefault(task_id, set())
                task_group.add(bg)
                return bg
            except BaseException:
                try:
                    if bg is not None and issubclass(type(bg), asyncio.Task):
                        if not callback_installed:
                            asyncio.Task.add_done_callback(bg, lambda done:
                                WSHandler._discard_session_bg_task(
                                    self, task_id, done, _source_lock=source_lock))
                        if not asyncio.Task.done(bg):
                            asyncio.Task.cancel(bg)
                    elif inspect.iscoroutine(coro) and inspect.getcoroutinestate(coro) == inspect.CORO_CREATED:
                        coro.close()
                    WSHandler._prune_source_task_lock(self, task_id, source_lock)
                except BaseException:
                    pass
                raise
        bg = self._track(coro)
        context = dict(self._task_bg_context.get(bg) or {})
        context.update({
            "task_id": task_id,
            "project_id": self._normalize_project_id(project_id or getattr(engine, "project_id", None)),
            "engine": engine,
        })
        self._task_bg_context[bg] = context
        task_group = self._task_bg_map.setdefault(task_id, set())
        task_group.add(bg)
        bg.add_done_callback(lambda t: self._discard_session_bg_task(task_id, t))
        return bg

    def _discard_session_bg_task(
        self, task_id: str, task: asyncio.Task[Any], *,
        _source_lock: asyncio.Lock | None = None,
    ) -> None:
        if _source_lock is None:
            retained_context = self._task_bg_context.get(task)
            if type(retained_context) is dict:
                captured_lock = retained_context.get("_source_task_lock")
                if type(captured_lock) is asyncio.Lock:
                    _source_lock = captured_lock
        if _source_lock is not None:
            try:
                self._task_bg_context.pop(task, None)
                task_group = self._task_bg_map.get(task_id)
                if task_group is not None:
                    task_group.discard(task)
                    if not task_group:
                        self._task_bg_map.pop(task_id, None)
            except BaseException:
                pass
            try:
                WSHandler._prune_source_task_lock(self, task_id, _source_lock)
            except BaseException:
                pass
            return
        self._task_bg_context.pop(task, None)
        task_group = self._task_bg_map.get(task_id)
        if task_group is None:
            return
        task_group.discard(task)
        if not task_group:
            self._task_bg_map.pop(task_id, None)

    def _cancel_session_tasks(self, task_id: str) -> None:
        task_group = self._task_bg_map.pop(task_id, set())
        for bg_task in list(task_group):
            try:
                if not bg_task.done():
                    bg_task.cancel()
            except Exception:
                logger.opt(exception=True).debug(f"Failed to cancel background task for {task_id}")

    @staticmethod
    def _is_ws_disconnect_error(exc: BaseException) -> bool:
        message = str(exc or "").strip().lower()
        if type(exc).__name__ in {"ClientConnectionResetError", "ConnectionResetError"}:
            return True
        return any(
            token in message
            for token in (
                "cannot write to closing transport",
                "closing transport",
                "websocket connection is closed",
                "connection reset by peer",
                "broken pipe",
            )
        )

    @staticmethod
    def _is_closed_database_error(exc: BaseException) -> bool:
        message = str(exc or "").strip().lower()
        return any(
            token in message
            for token in (
                "cannot operate on a closed database",
                "closed database",
                "no active connection",
            )
        )

    def _is_expected_shutdown_error(self, exc: BaseException) -> bool:
        return self._shutting_down and (
            self._is_ws_disconnect_error(exc) or self._is_closed_database_error(exc)
        )

    @staticmethod
    def _ws_flag_is_set(value: Any) -> bool:
        return isinstance(value, bool) and value

    @classmethod
    def _ws_is_open(cls, ws: Any) -> bool:
        return not (
            cls._ws_flag_is_set(getattr(ws, "closed", False))
            or cls._ws_flag_is_set(getattr(ws, "closing", False))
        )

    async def _safe_send_json(self, ws: Any, payload: dict[str, Any]) -> bool:
        if not self._ws_is_open(ws):
            self._clients.discard(ws)
            return False
        try:
            result = ws.send_json(payload)
            if inspect.isawaitable(result):
                await result
            return True
        except (TypeError, ValueError) as exc:
            # One value that json cannot encode must never take the whole
            # console down.  On 2026-09-06 a datetime inside the welcome
            # snapshot made every connection die during the initial push, so
            # the browser reconnected every three seconds and nothing loaded.
            # Name the offending paths in the log, send a coerced copy.
            paths = unserializable_paths(payload)
            logger.error(
                "WS payload {} carried non-JSON values at {}: {}",
                str(payload.get("type", "") or "?"),
                ", ".join(paths[:8]) or "?",
                exc,
            )
            coerced = json.loads(json.dumps(payload, default=_json_coerce))
            result = ws.send_json(coerced)
            if inspect.isawaitable(result):
                await result
            return True
        except Exception as exc:
            if self._is_ws_disconnect_error(exc) or self._shutting_down:
                self._clients.discard(ws)
                logger.debug(f"Skipped WS send during disconnect/shutdown: {type(exc).__name__}: {exc!r}")
                return False
            raise

    async def shutdown(self, timeout: float = 15.0) -> None:
        """Checkpoint owned runtimes, then stop all WS work before DB shutdown."""
        import aiohttp

        self._shutting_down = True
        principal_reader = getattr(self, "_principal_reader", None)
        if principal_reader is not None:
            principal_reader.close()
        usage_walks = getattr(self, "_data_usage_walks", None)
        if usage_walks is not None:
            # A usage walk is a plain scan in a thread: the flag ends it where it stands, and nothing is owed.
            usage_walks.close()
        # The registered console extensions stop what they hold (extensions.py: on_shutdown), e.g. an outbound link; one
        # that fails is logged and the stop goes on.
        from ampuly.plugins.office_ui import extensions as _extensions

        _extensions.shutdown(self._extension_host())
        pending_handlers = [
            task
            for task in self._active_message_tasks
            if task is not asyncio.current_task() and not task.done()
        ]

        def execution_owned_tasks() -> set[asyncio.Task[Any]]:
            owned = set(self._task_bg_context)
            for task_group in self._task_bg_map.values():
                owned.update(task_group)
            return {
                task
                for task in owned
                if task is not asyncio.current_task() and not task.done()
            }

        # A preaccepted handler can replace its handoff reservation with the
        # real execution task while the admission barrier drains.  Union this
        # pre-barrier view with the post-checkpoint view so neither owner can
        # disappear from the cancellation set during that handoff.
        execution_tasks_before_prepare = execution_owned_tasks()

        # Atomically close execution admission, then wait only for requests
        # accepted before that close to either register their first real engine
        # coroutine or exit.  There is intentionally no timeout window here:
        # registration drains the reservation, so long execution is not part
        # of this wait.
        active_run_registry = self._controller_active_task_run_registry()
        close_and_wait = getattr(
            active_run_registry,
            "close_admission_and_wait_for_handoffs",
            None,
        )
        if callable(close_and_wait):
            # Close synchronously, then cancel accepted requests which are
            # still queued before their first engine registration.  In
            # particular, a duplicate Continue can be waiting behind the
            # per-runtime reply lock for the entire first execution; waiting
            # for that reservation here would deadlock shutdown before it can
            # checkpoint and cancel the live owner.
            active_run_registry.close_admission()
            is_handoff_pending = getattr(
                active_run_registry,
                "is_handoff_pending",
                None,
            )
            pending_handoff_tasks: set[asyncio.Task[Any]] = set()
            pending_handoff_tokens: set[str] = set()
            if callable(is_handoff_pending):
                for task, context in list(self._task_bg_context.items()):
                    token = (
                        context.get("execution_handoff_token")
                        if isinstance(context, dict)
                        else None
                    )
                    if (
                        task is not asyncio.current_task()
                        and not task.done()
                        and is_handoff_pending(token)
                    ):
                        pending_handoff_tasks.add(task)
                        pending_handoff_tokens.add(str(token))
                handoff_routes = getattr(self, "_handoff_route_tasks", {})
                if isinstance(handoff_routes, dict):
                    for task, token in list(handoff_routes.items()):
                        if (
                            task is not asyncio.current_task()
                            and not task.done()
                            and is_handoff_pending(token)
                        ):
                            pending_handoff_tasks.add(task)
                            pending_handoff_tokens.add(token)
            for task in pending_handoff_tasks:
                task.cancel()
            revoke_handoff = getattr(active_run_registry, "revoke_handoff", None)
            if callable(revoke_handoff):
                for token in pending_handoff_tokens:
                    revoke_handoff(token)
            await close_and_wait()

        # The controller registry is the only source of truth for executions
        # owned by this process.  Persist one checkpoint per active company
        # scope while every execution coroutine and its store are still alive.
        root_engine = getattr(self, "_root_engine", None) or self.engine
        try:
            await root_engine.prepare_active_company_runtimes_for_shutdown()
        except Exception:
            logger.opt(exception=True).error(
                "Refusing to cancel WS execution because company runtime checkpointing failed"
            )
            raise

        # No execution coroutine may get another scheduling turn after its
        # checkpoint/holds are durable.  Build the cancellation set and set
        # every cancellation flag synchronously, before awaiting progress
        # flushing, client close handshakes, or any other UI cleanup.
        execution_tasks = execution_tasks_before_prepare | execution_owned_tasks()
        tracked_tasks = set(self._background_tasks)
        tracked_tasks.update(execution_tasks)
        tracked_tasks.update(pending_handlers)
        tracked_tasks = {
            task
            for task in tracked_tasks
            if task is not asyncio.current_task() and not task.done()
        }
        for task in tracked_tasks:
            task.cancel()
        if self._progress_flush_task and not self._progress_flush_task.done():
            self._progress_flush_task.cancel()

        # Await execution cleanup first so broker finally blocks reap process
        # groups while the engine/store are guaranteed to remain available.
        if execution_tasks:
            _done, still_cleaning = await asyncio.wait(
                execution_tasks,
                timeout=max(0.0, float(timeout)),
            )
            if still_cleaning:
                message = (
                    "Timed out waiting for "
                    f"{len(still_cleaning)} execution task(s) to finish cancellation cleanup"
                )
                logger.error(message)
                raise RuntimeError(message)

        if self._progress_flush_task:
            try:
                await self._progress_flush_task
            except (asyncio.CancelledError, Exception):
                pass
            self._progress_flush_task = None

        if self._duty_watch_task:
            self._duty_watch_task.cancel()
            try:
                await self._duty_watch_task
            except (asyncio.CancelledError, Exception):
                pass
            self._duty_watch_task = None
        if self._runtime_status_sync_task:
            # Cancel rather than await: the sync interval is long enough that
            # waiting for a natural wake-up would stall shutdown.
            self._runtime_status_sync_task.cancel()
            try:
                await self._runtime_status_sync_task
            except (asyncio.CancelledError, Exception):
                pass
            self._runtime_status_sync_task = None

        clients = list(self._clients | getattr(self, "_ui_send_closing", set()))
        close_deadline = asyncio.get_running_loop().time() + max(0.0, float(timeout))
        for ws in clients:
            try:
                remaining = max(0.0, close_deadline - asyncio.get_running_loop().time())
                async with asyncio.timeout(min(self._UI_SEND_TIMEOUT_SEC, remaining)):
                    await ws.close(
                        code=aiohttp.WSCloseCode.GOING_AWAY,
                        message=b"server shutting down",
                    )
            except Exception as exc:
                if not self._is_ws_disconnect_error(exc):
                    logger.debug(f"Failed to close WS client cleanly: {type(exc).__name__}: {exc!r}")

        ui_background_tasks = tracked_tasks - execution_tasks
        if ui_background_tasks:
            _done, still_running = await asyncio.wait(
                ui_background_tasks,
                timeout=max(0.0, float(timeout)),
            )
            if still_running:
                logger.warning(
                    "Timed out waiting for {} non-execution WS background task(s) to stop",
                    len(still_running),
                )
        tails = list(getattr(self, "_ui_send_tails", {}).values())
        if tails:
            await asyncio.wait(tails, timeout=max(0.0, float(timeout)))
        closing = getattr(self, "_ui_send_closing", set())
        closing.update(ws for ws in clients if self._ws_is_open(ws))
        closing.difference_update(ws for ws in list(closing) if not self._ws_is_open(ws))
        if principal_reader is not None:
            await principal_reader.wait_closed(timeout=min(5.0, max(0.0, float(timeout))))
        if closing:
            raise RuntimeError("UI peer close incomplete; transport state retained")

    @staticmethod
    def _store_is_ready(store: Any | None) -> bool:
        """Treat initialized stores as ready, even without an explicit flag."""
        if not store:
            return False
        ready = getattr(store, "is_ready", None)
        if callable(ready):
            return bool(ready())
        if ready is None:
            return True
        return bool(ready)

    @staticmethod
    def _chat_store_is_ready(chat_store: Any | None) -> bool:
        if chat_store is None:
            return False
        ready = getattr(chat_store, "is_ready", None)
        if callable(ready):
            try:
                if not bool(ready()):
                    return False
            except Exception:
                return False
        elif ready is not None and not bool(ready):
            return False
        db = getattr(chat_store, "_db", None)
        if db is None:
            return False
        connection = getattr(db, "_connection", True)
        return connection is not None

    @staticmethod
    def _task_has_comms_workspace(task: Any | None) -> bool:
        if task is None:
            return False
        metadata = dict(getattr(task, "metadata", {}) or {})
        return bool(
            str(metadata.get("comms_workspace_root") or "").strip()
            or str(metadata.get("target_output_dir") or "").strip()
            or str(metadata.get("setup_workspace_prepared") or "").strip()
        )

    @staticmethod
    def _shared_root_ui_task_id(task: Any | None) -> str:
        if task is None:
            return ""
        metadata = dict(getattr(task, "metadata", {}) or {})
        if not bool(metadata.get("shared_role_session", False)):
            return ""
        session_id = str(getattr(task, "session_id", "") or "").strip()
        root_session_id = str(metadata.get("company_runtime_root_session_id", "") or "").strip()
        origin_task_id = str(metadata.get("origin_task_id", "") or "").strip()
        if origin_task_id and root_session_id and session_id == root_session_id:
            return origin_task_id
        return ""

    @staticmethod
    def _task_mode_origin_ui_task_id(task: Any | None) -> str:
        if task is None:
            return ""
        metadata = dict(getattr(task, "metadata", {}) or {})
        task_id = str(getattr(task, "id", "") or "").strip()
        origin_task_id = str(metadata.get("origin_task_id", "") or "").strip()
        if not origin_task_id or origin_task_id == task_id:
            return ""
        mode = str(metadata.get("mode", "") or "").strip().lower()
        exec_mode = str(metadata.get("exec_mode", "") or "").strip().lower()
        execution_mode = str(metadata.get("execution_mode", "") or "").strip().lower()
        task_mode_contract = str(metadata.get("task_mode_contract", "") or "").strip()
        if (
            mode == "task"
            or exec_mode in {"task", "project", "single"}
            or execution_mode in {"task", "task_mode", "project"}
            or task_mode_contract == "single_full_capability_main_agent"
        ):
            return origin_task_id
        return ""

    def _ui_task_id_for_task(self, task: Any | None) -> str:
        if task is None:
            return ""
        task_id = str(getattr(task, "id", "") or "").strip()
        ui_task_id = self._shared_root_ui_task_id(task) or self._task_mode_origin_ui_task_id(task) or task_id
        if task_id and ui_task_id and ui_task_id != task_id:
            self._ui_task_aliases[task_id] = ui_task_id
        return ui_task_id

    async def _follow_order_run(self, task_id: str, run_status: str, *, project_id: str) -> None:
        """Let an order follow its own production run (started -> producing, finished -> delivering).

        Only the run's own task id is looked up, never the UI alias a work item maps to: a finished work item is
        not a finished order. A failure here must not disturb the run, so it is logged and dropped.
        """
        clean = str(task_id or "").strip()
        if not clean or str(run_status or "").strip().lower() not in {"running", "done"}:
            return
        try:
            await asyncio.to_thread(self._console_api().follow_order_run, clean, run_status, project_id=project_id)
        except Exception:
            logger.opt(exception=True).warning("could not move the order of run {} on {}", clean[:8], run_status)

    async def _ui_task_id_for_runtime_task_id(self, task_id: str | None, *, engine: Any | None = None) -> str:
        raw_task_id = str(task_id or "").strip()
        if not raw_task_id:
            return ""
        mapped = str(self._ui_task_aliases.get(raw_task_id) or "").strip()
        if mapped:
            return mapped
        runtime_engine = engine or self.engine
        store = getattr(runtime_engine, "store", None)
        get_task = getattr(store, "get_task", None)
        if callable(get_task):
            try:
                task = await get_task(raw_task_id)
            except Exception:
                task = None
            mapped = self._ui_task_id_for_task(task)
            if mapped:
                return mapped
        return raw_task_id

    def _on_bg_task_done(self, task: asyncio.Task[Any]) -> None:
        """Callback for tracked background tasks: cleanup + log unhandled errors.

        For session tasks, also broadcasts an error message and idle status
        so the frontend doesn't stay stuck on "thinking" forever.
        """
        self._background_tasks.discard(task)
        if task.cancelled():
            return
        exc = task.exception()
        if exc is not None:
            logger.opt(exception=exc).error(f"Background task failed: {exc}")
            # Notify frontend for session tasks so UI doesn't stay stuck on "thinking"
            context = self._task_bg_context.get(task) or {}
            task_id = self._find_task_id_for_bg_task(task)
            if task_id:
                asyncio.ensure_future(self._notify_session_bg_failure(
                    task_id,
                    exc,
                    project_id=str(context.get("project_id") or "").strip() or None,
                ))

    def _find_task_id_for_bg_task(self, bg_task: asyncio.Task[Any]) -> str | None:
        """Find the task_id associated with a background task."""
        context = self._task_bg_context.get(bg_task)
        if context:
            task_id = str(context.get("task_id", "") or "").strip()
            if task_id:
                return task_id
        for tid, task_group in self._task_bg_map.items():
            if bg_task in task_group:
                return tid
        return None

    async def _notify_session_bg_failure(
        self,
        task_id: str,
        exc: BaseException,
        *,
        project_id: str | None = None,
    ) -> None:
        """Broadcast error message + idle status for a failed session background task."""
        try:
            channel_id = f"session:{task_id}"
            pid = self._normalize_project_id(project_id or self.engine.project_id)
            msg = await self.chat_store.insert_message(
                channel_id=channel_id,
                sender="system",
                sender_name=STORED_SPEAKER,
                content=f"Error: {exc}",
                project_id=pid,
            )
            await self.broadcast({"type": "session_message", "payload": msg})
            await self.broadcast({"type": "board_task_status_changed", "payload": {
                "project_id": pid, "task_id": task_id, "column_id": "in-progress", "status": "failed",
            }})
            idle_payload: dict[str, Any] = {
                "project_id": pid,
                "task_id": task_id, "status": "idle", "current_tool": None, "iteration": 0,
            }
            resolved_agent = self._resolve_agent_for_idle(task_id)
            if resolved_agent:
                idle_payload["agent_id"] = resolved_agent
            await self.broadcast({"type": "agent_runtime_update", "payload": idle_payload})
        except Exception as notify_exc:
            logger.debug(f"Failed to notify frontend of session bg failure: {notify_exc}")

    async def _send_ack(self, ws: Any, ok: bool = True, **extra: Any) -> None:
        payload: dict[str, Any] = {"ok": ok, **extra}
        await self._safe_send_json(ws, {"type": "ack", "payload": payload})

    async def _publish_service_result(self, result: ServiceResult) -> None:
        for event in result.events:
            await self.broadcast({"type": event.type, "payload": event.payload})

    async def _send_service_ack(self, ws: Any, result: ServiceResult, **extra: Any) -> None:
        payload = dict(result.payload or {})
        payload.update(extra)
        ok = bool(payload.pop("ok", True))
        await self._send_ack(ws, ok=ok, **payload)

    async def _send_service_error(self, ws: Any, exc: ServiceError, *, action: str | None = None) -> None:
        payload = exc.to_payload()
        payload.pop("ok", None)
        if action:
            payload["action"] = action
        await self._send_ack(ws, ok=False, **payload)

    async def _refresh_runtime_control_for_client(
        self,
        ws: Any,
        *,
        engine: Any,
        project_id: str,
    ) -> None:
        """Replace optimistic Continue state with a durable snapshot."""
        try:
            collab = await build_collab_sync(
                engine,
                self.agent_store,
                self.chat_store,
                self.event_adapter,
                exec_mode=self._exec_mode,
            )
            collab["project_id"] = self._normalize_project_id(project_id)
            await self._safe_send_json(ws, {"type": "collab_sync_push", "payload": collab})
            await self._send_owner_interaction_baseline_for_client(
                ws,
                engine=engine,
                project_id=self._normalize_project_id(project_id),
                after_sync=collab,
            )
        except Exception:
            logger.opt(exception=True).debug("failed to refresh runtime control after rejected Continue")

    # UI profile name → engine CompanyProfile name
    _PROFILE_TO_ENGINE: dict[str, str] = {"classic": "corporate"}

    def _normalize_session_exec_mode(self, value: Any) -> str:
        return SessionService.normalize_exec_mode(value)

    def _normalize_session_company_profile(self, value: Any) -> str:
        return self._ensure_office_services().session.normalize_company_profile(value)

    def _normalize_session_preferred_agent(self, value: Any, default: str = "native") -> str:
        return SessionService.normalize_preferred_agent(value, default=default)

    def _normalize_session_org_id(self, value: Any) -> str:
        return SessionService.normalize_org_id(value)

    def _resolve_task_session_config(self, task: Any | None) -> tuple[str, str]:
        return self._ensure_office_services().session.resolve_task_session_config(task)

    def _resolve_task_identity(self, task: Any | None, **defaults: Any) -> Any:
        return self._ensure_office_services().session.resolve_task_identity(task, **defaults)

    def _resolve_task_org_id(self, task: Any | None) -> str:
        return self._ensure_office_services().session.resolve_task_org_id(task)

    async def _resolve_session_runtime_config_task(
        self,
        task_id: str,
        task: Any | None,
        *,
        engine: Any,
    ) -> Any | None:
        """Resolve company-session config from the durable runtime identity."""
        if task is None:
            return None
        exec_mode, _ = self._resolve_task_session_config(task)
        runtime_bound = is_company_runtime_task(task)
        if not runtime_bound and not self._is_company_session_exec_mode(exec_mode):
            return task
        if is_runtime_auxiliary_task(task):
            # CEO assessments and meeting turns are runtime-internal rows
            # without a work-item identity; showing them must not error.
            return task
        try:
            target = await self._resolve_company_runtime_target(task_id, engine=engine)
        except ServiceError:
            if runtime_bound:
                raise
            logger.opt(exception=True).debug(
                "failed to resolve durable session config task"
            )
            return task
        except Exception as exc:
            if runtime_bound:
                raise ServiceError(
                    "company_runtime_identity_mismatch",
                    "Company runtime identity could not be resolved",
                    {"task_id": str(task_id or "").strip()},
                ) from exc
            logger.opt(exception=True).debug(
                "failed to resolve durable session config task"
            )
            return task
        if target is not None:
            return target.get("config_task") or task
        if runtime_bound:
            raise ServiceError(
                "company_runtime_identity_mismatch",
                "Company runtime identity could not be resolved",
                {"task_id": str(task_id or "").strip()},
            )
        return task

    @staticmethod
    def _is_company_session_exec_mode(exec_mode: Any) -> bool:
        return str(exec_mode or "").strip().lower() in {"company", "org", "custom"}

    def _resolve_task_preferred_agent(self, task: Any | None) -> str:
        return self._ensure_office_services().session.resolve_task_preferred_agent(task)

    def _resolve_task_selected_execution_agent(self, task: Any | None) -> str:
        return self._ensure_office_services().session.resolve_task_selected_execution_agent(task)

    async def _session_config_lock_reason(self, task: Any, project_id: str) -> str:
        """Return a reason when a session's execution config can no longer change."""
        return await self._ensure_office_services().session.session_config_lock_reason(task, project_id)

    async def _persist_session_config(
        self,
        task: Any,
        *,
        exec_mode: str,
        company_profile: str,
        preferred_agent: str,
        org_id: str = "",
        engine: Any | None = None,
    ) -> None:
        await self._ensure_office_services().session.persist_session_config(
            task,
            exec_mode=exec_mode,
            company_profile=company_profile,
            preferred_agent=preferred_agent,
            org_id=org_id,
            engine=engine,
        )
    def _resolve_engine_mode(self, mode: str | None = None, profile: str | None = None) -> tuple[str, str | None]:
        """Resolve UI execution mode into (engine_mode, company_profile).

        UI modes → engine API:
          "task"    → mode="project", company_profile=None
          "company" → mode="company", company_profile=profile
          "org"     → mode="org", company_profile="custom"
        UI profile "classic" maps to engine CompanyProfile "corporate".
        """
        mode = mode or self._exec_mode
        profile = profile or self._company_profile
        if mode == "company":
            engine_profile = self._PROFILE_TO_ENGINE.get(profile, profile) if profile else None
            return "company", engine_profile
        if mode in {"org", "custom"}:
            return "org", "custom"
        return "project", None

    async def _run_task(
        self,
        title: str,
        description: str,
        mode: str,
        profile: str,
        task_id: str | None = None,
        *,
        run_engine: Any | None = None,
        run_project_id: str | None = None,
        org_id: str | None = None,
    ) -> None:
        """Execute a task with the selected mode."""
        engine = run_engine or self.engine
        pid = self._normalize_project_id(run_project_id or getattr(engine, "project_id", None))
        error_channel = f"session:{task_id}" if task_id else f"activity:{pid}"

        # Look up session_id from task
        session_id: str | None = None
        task = None
        config_task = None
        preferred_agent = self._task_preferred_agent
        session_org_id = self._normalize_session_org_id(org_id)
        if task_id and getattr(engine, "store", None):
            task = await engine.store.get_task(task_id)
            if task:
                session_id = task.session_id

        company_runtime_target: dict[str, Any] | None = None
        try:
            if task is not None:
                config_task = await self._resolve_session_runtime_config_task(
                    task_id,
                    task,
                    engine=engine,
                )
                identity = self._resolve_task_identity(
                    config_task,
                    default_exec_mode=mode,
                    default_company_profile=profile,
                    default_preferred_agent=preferred_agent,
                    default_org_id=session_org_id,
                )
                mode = identity.exec_mode
                profile = identity.company_profile
                session_org_id = identity.org_id
                preferred_agent = identity.preferred_agent
                if identity.is_custom_org and not identity.org_id:
                    raise ServiceError(
                        "org_id_required",
                        "org_id_required",
                        {"project_id": pid, "task_id": task_id},
                    )
            content = f"{title}\n{description}".strip()
            engine_mode, company_profile = self._resolve_engine_mode(mode, profile)
            # The Company router uses this preference to seed staffing.  A
            # JiuwenSwarm Team choice must therefore cross the same ingress
            # boundary as a Task-mode external-agent choice.
            engine_preferred_agent = (
                preferred_agent
                if engine_mode == "project" or preferred_agent != "native"
                else None
            )
            permission_config = (
                self._ensure_office_services().session.resolve_task_native_permission_config(
                    config_task or task,
                    engine,
                )
            )
            if task_id:
                # Per-task lock: same session serialized, different sessions concurrent
                async with WSHandler._task_lock_context(self, task_id):
                    if self._is_company_session_exec_mode(mode) and task is not None and self._store_is_ready(engine.store):
                        from ampuly.core.models import TaskStatus
                        await apply_task_status_transition(
                            engine.store,
                            task,
                            target_status_or_phase=TaskStatus.RUNNING,
                            reason="run_task_started",
                        )
                    await self.broadcast({"type": "board_task_status_changed", "payload": {
                        "project_id": pid, "task_id": task_id, "column_id": "in-progress", "status": "running",
                    }})
                    if task is not None:
                        await self._persist_session_config(
                            task,
                            exec_mode=mode,
                            company_profile=profile,
                            preferred_agent=preferred_agent,
                            org_id=session_org_id,
                            engine=engine,
                        )
                    if self._is_company_session_exec_mode(mode):
                        try:
                            company_runtime_target = await self._resolve_company_runtime_target(task_id, engine=engine)
                            await self._set_company_runtime_control(company_runtime_target, state="running")
                        except Exception:
                            logger.opt(exception=True).debug("failed to mark run_task company runtime running")
                    await engine.process_message(
                        content,
                        project_id=pid,
                        session_id=session_id,
                        mode=engine_mode,
                        org_id=session_org_id or None,
                        company_profile=company_profile,
                        preferred_agent=engine_preferred_agent,
                        origin_task_id=task_id,
                        message_metadata=permission_config,
                    )
                await self._sync_task_transcript_messages(task_id, engine=engine)
            else:
                await engine.process_message(
                    content,
                    project_id=pid,
                    mode=engine_mode,
                    org_id=session_org_id or None,
                    company_profile=company_profile,
                    preferred_agent=engine_preferred_agent,
                    message_metadata=permission_config,
                )

            # Broadcast: task idle (agent responded, waiting for user)
            if task_id:
                await self.broadcast({"type": "board_task_status_changed", "payload": {
                    "project_id": pid, "task_id": task_id, "column_id": "in-progress", "status": "idle",
                }})
                if getattr(engine, "store", None):
                    from ampuly.core.models import TaskStatus as TS
                    t = await engine.store.get_task(task_id)
                    if t:
                        t.status = TS.IDLE
                        await engine.store.save_task(t)
                if self._is_company_session_exec_mode(mode):
                    try:
                        idle_target = await self._resolve_company_runtime_target(task_id, engine=engine)
                        await self._set_company_runtime_control(idle_target or company_runtime_target, state="idle")
                    except Exception:
                        logger.opt(exception=True).debug("failed to mark run_task company runtime idle")
        except Exception as e:
            logger.opt(exception=True).error(f"Task execution error: {e}")
            # Broadcast: task failed (stays in in-progress, user can retry)
            if task_id:
                await self.broadcast({"type": "board_task_status_changed", "payload": {
                    "project_id": pid, "task_id": task_id, "column_id": "in-progress", "status": "failed",
                }})
                if self._is_company_session_exec_mode(mode):
                    try:
                        failed_target = await self._resolve_company_runtime_target(task_id, engine=engine)
                        await self._set_company_runtime_control(failed_target or company_runtime_target, state="idle")
                    except Exception:
                        logger.opt(exception=True).debug("failed to clear run_task company runtime after error")
            err_meta: dict[str, Any] = {}
            if task_id:
                err_meta["task_id"] = task_id
            msg = await self.chat_store.insert_message(
                channel_id=error_channel,
                sender="system",
                sender_name=STORED_SPEAKER,
                content=f"Task error: {e}",
                metadata=err_meta or None,
                project_id=pid,
            )
            await self.broadcast({"type": "session_message", "payload": msg})
        finally:
            # Always refresh the frontend after a task run so new delegation
            # runs / work items are reflected on the kanban immediately.
            try:
                collab = await build_collab_sync(
                    engine, self.agent_store, self.chat_store,
                    self.event_adapter,
                    exec_mode=mode,
                )
                await self.broadcast({"type": "collab_sync_push", "payload": collab})
                await self._broadcast_owner_interaction_baseline(
                    engine=engine,
                    project_id=pid,
                    after_sync=collab,
                )
            except Exception:
                logger.opt(exception=True).warning("Post-run collab_sync broadcast failed (non-fatal)")

    async def _mirror_agent_message(
        self,
        event: Any,
        *,
        engine: Any | None = None,
        project_id: str | None = None,
    ) -> None:
        """Mirror agent_message_sent events into session channel or activity."""
        runtime_engine = engine or self.engine
        pid = self._normalize_project_id(project_id or getattr(runtime_engine, "project_id", None))
        p = event.payload or {}
        from_role = p.get("from", "")
        content = p.get("subject", "") or p.get("body", "") or "Message"
        task_id = p.get("task_id")

        # Resolve ampuly_role_id → agent_id for consistent sender identity
        from_agent = self.event_adapter._resolve_role_to_agent(from_role) if from_role else ""

        # Resolve human-readable name: agent store name → org role name → raw ID
        display_name = from_role or from_agent
        if from_agent:
            agents = await self.agent_store.get_all()
            match = next((a for a in agents if a["agent_id"] == from_agent), None)
            if match:
                display_name = match["name"]
        org_engine = getattr(runtime_engine, "org_engine", None)
        if display_name == from_role and org_engine:
            org_role = org_engine.get_agent(from_role)
            if org_role:
                display_name = org_role.name

        # Route to session channel if task_id is known, else activity
        target_channel = f"session:{task_id}" if task_id else f"activity:{pid}"
        mirror_meta: dict[str, Any] = {}
        if task_id:
            mirror_meta["task_id"] = task_id
        msg = await self.chat_store.insert_message(
            channel_id=target_channel,
            sender=from_agent,
            sender_name=display_name,
            content=content,
            metadata=mirror_meta or None,
            project_id=pid,
        )
        await self.broadcast({"type": "session_message", "payload": msg})

    async def _reconcile_execution_checkpoint_cards(
        self,
        channel_id: str,
        *,
        project_id: str,
        engine: Any,
    ) -> list[dict[str, Any]]:
        """Mark checkpoint cards terminal once the engine checkpoint is terminal."""
        getter = getattr(self.chat_store, "get_unresolved_checkpoint_messages", None)
        if not callable(getter):
            return []
        try:
            cards = await getter(channel_id, project_id=project_id)
        except Exception:
            logger.opt(exception=True).debug(
                f"Failed to load unresolved execution checkpoint cards for {channel_id}",
            )
            return []

        updated_cards: list[dict[str, Any]] = []
        for card in cards:
            metadata = dict(card.get("metadata", {}) or {})
            checkpoint_type = str(metadata.get("checkpoint_type", "") or "").strip()
            if not checkpoint_type:
                continue
            checkpoint_id = str(metadata.get("checkpoint_id", "") or "").strip()
            if not checkpoint_id:
                continue
            status = await self._execution_checkpoint_status(
                engine=engine,
                project_id=project_id,
                checkpoint_id=checkpoint_id,
                checkpoint_type=checkpoint_type,
            )
            if not status or status == "pending":
                continue
            try:
                updated = await self.chat_store.update_checkpoint_status(
                    checkpoint_id,
                    channel_id=channel_id,
                    checkpoint_type=checkpoint_type,
                    status=status,
                    status_metadata={
                        "checkpoint_resolution_source": "execution_checkpoint_lifecycle",
                    },
                    project_id=project_id,
                )
            except Exception:
                logger.opt(exception=True).debug(
                    f"Failed to reconcile execution checkpoint card {checkpoint_id}",
                )
                continue
            if updated is not None:
                updated_cards.append(updated)
                await self.broadcast({"type": "session_message", "payload": updated})
        return updated_cards

    # ── Session Handlers ──────────────────────────────────────────────

    async def _handle_create_session(self, ws: Any, data: dict) -> None:
        """Create a new Task (PENDING) + engine session. Broadcasts session_created."""
        try:
            run_engine, pid = await self._engine_for_request(data)
            result = await self.services.session.create(
                project_id=pid,
                title=data.get("title", "New Chat"),
                exec_mode=data.get("exec_mode", self._exec_mode),
                company_profile=data.get("company_profile"),
                preferred_agent=data.get("preferred_agent", self._task_preferred_agent),
                org_id=data.get("org_id") or data.get("organization_id"),
                native_approval_level=data.get("native_approval_level"),
                interface="office_ui",
            )
            self._session_to_task.update(self.services_context.session_to_task)
            await self._publish_service_result(result)
            await self._send_ack(ws, ok=True, action="create_session", **result.payload)
        except ServiceError as exc:
            await self._send_service_error(ws, exc, action="create_session")

    async def _handle_session_update_config(self, ws: Any, data: dict) -> None:
        """Update a session's persisted execution configuration."""
        try:
            _engine, project_id = await self._engine_for_request(data)
            result = await self.services.session.update_config(
                project_id=project_id,
                task_id=str(data.get("task_id", "") or ""),
                exec_mode=data.get("exec_mode"),
                company_profile=data.get("company_profile"),
                preferred_agent=data.get("preferred_agent"),
                org_id=data.get("org_id") or data.get("organization_id"),
                native_approval_level=data.get("native_approval_level"),
            )
            await self._publish_service_result(result)
            await self._send_ack(ws, ok=True, **result.payload)
        except ServiceError as exc:
            await self._send_service_error(ws, exc, action="session_update_config")

    async def _handle_native_permission_default_set(self, ws: Any, data: dict) -> None:
        """Persist the default used only when creating future native sessions."""
        from ampuly.core.native_permissions import parse_native_approval_level
        from ampuly.core.workspace_trust import save_explicit_workspace_authority_change

        raw = data.get("native_approval_level")
        try:
            normalized = parse_native_approval_level(raw)
        except ValueError:
            await self._send_ack(
                ws, ok=False, action="native_permission_default_set",
                error="invalid_native_approval_level",
            )
            return
        root = self._root_engine
        previous = root.config.autonomy.native_approval_level
        root.config.autonomy.native_approval_level = normalized
        try:
            save_explicit_workspace_authority_change(
                root.config,
                root.ampuly_home / "config",
            )
        except Exception as exc:
            root.config.autonomy.native_approval_level = previous
            await self._send_ack(
                ws,
                ok=False,
                action="native_permission_default_set",
                error="native_permission_default_persist_failed",
                detail=str(exc),
            )
            return
        if getattr(root, "approval_engine", None):
            root.approval_engine.native_policy.set_config(root.config.autonomy)
        # Existing session levels live in their scope registries and are not
        # rewritten. Every already-created project delegate receives only the
        # new creation default; future delegates copy it from the root config.
        delegates = list(
            dict(getattr(root, "_project_engine_delegates", {}) or {}).values()
        )
        for engine in [self.engine, *delegates]:
            if engine is root:
                continue
            engine.config.autonomy.native_approval_level = normalized
            if getattr(engine, "approval_engine", None):
                engine.approval_engine.native_policy.set_config(engine.config.autonomy)
        payload = {"native_approval_default": normalized}
        await self.broadcast({"type": "native_permission_default_updated", "payload": payload})
        await self._send_ack(ws, ok=True, action="native_permission_default_set", **payload)

    async def _handle_session_detail(self, ws: Any, data: dict) -> None:
        """Return a paginated persisted transcript/context for a single session.

        The session's cards, its runtime configuration and its runtime controls
        each needed the project's whole task list; they now share one read for
        the request (``request_reads``, AV ).
        """
        with request_read_scope():
            await self._handle_session_detail_in_scope(ws, data)

    async def _handle_session_detail_in_scope(self, ws: Any, data: dict) -> None:
        if self._shutting_down:
            return

        task_id = str(data.get("task_id", "") or "").strip()
        if not task_id:
            await self._send_ack(ws, ok=False, error="task_id required")
            return

        run_engine, request_project_id = await self._engine_for_request(data)
        view_generation = data.get("view_generation")
        store = run_engine.store
        if not self._store_is_ready(store):
            await self._send_ack(ws, ok=False, error="store_not_ready", project_id=request_project_id, view_generation=view_generation)
            return

        task = await store.get_task(task_id)
        if not task:
            await self._send_ack(ws, ok=False, error="task_not_found", project_id=request_project_id, task_id=task_id, view_generation=view_generation, action="session_detail")
            return

        channel_id = f"session:{task_id}"
        session_id = getattr(task, "session_id", None)
        project_id = getattr(task, "project_id", None) or run_engine.project_id or request_project_id
        request_limit = max(1, min(int(data.get("limit", 200) or 200), 500))
        detail_level = _normalize_transcript_detail_level(data.get("detail_level", "summary"))
        raw_include = data.get("include")
        if isinstance(raw_include, list):
            include_set = {str(item or "").strip() for item in raw_include if str(item or "").strip()}
        else:
            include_set = {"messages", "session_state"}
            if detail_level == "full":
                include_set.update({"progress", "work_items", "runtime_context"})
        before_timestamp = self._normalize_session_detail_timestamp(data.get("before_created_at"))
        before_message_id = str(data.get("before_message_id", "") or "").strip() or None

        try:
            await self.chat_store.create_session_channel(
                task_id,
                getattr(task, "title", "") or "Session",
                project_id=project_id,
            )
        except Exception as exc:
            if self._is_expected_shutdown_error(exc):
                logger.debug(f"session_detail: channel bootstrap skipped during shutdown for {task_id}")
                return
            raise
        try:
            transcript_page, transcript_total_count, transcript_has_more = await self._load_session_transcript_page(
                task,
                limit=request_limit,
                detail_level=detail_level,
                before_timestamp=before_timestamp,
                before_message_id=before_message_id,
                engine=run_engine,
            )
            if transcript_page:
                await self.chat_store.backfill_messages(
                    channel_id,
                    transcript_page,
                    project_id=project_id,
                )
        except Exception:
            logger.opt(exception=True).debug(f"session_detail: transcript page load failed for {task_id}")
            transcript_total_count = 0
            transcript_has_more = False

        await self._reconcile_execution_checkpoint_cards(
            channel_id,
            project_id=project_id,
            engine=run_engine,
        )

        try:
            cache_page = await self.chat_store.get_channel_messages_page_info(
                channel_id,
                limit=request_limit,
                before_timestamp=before_timestamp,
                before_message_id=before_message_id,
                detail_level=detail_level,
                project_id=project_id,
            )
            messages = list(cache_page.get("messages", []) or [])
            visible_cache_count = int(cache_page.get("total_count", len(messages)) or 0)
            cache_has_more = bool(cache_page.get("has_more", False))
            messages = self._filter_ui_messages_for_detail_level(messages, detail_level)
            messages = [_sanitize_ui_message_dict(message) for message in messages]
        except Exception as exc:
            if self._is_expected_shutdown_error(exc):
                logger.debug(f"session_detail: cache page skipped during shutdown for {task_id}")
                return
            messages = []
            visible_cache_count = len(messages)
            cache_has_more = False

        # ExecutionCheckpoint is the source of truth for actionable cards.
        # Rebuild active cards for every snapshot so an EventBus loss, server
        # restart, or stale ChatStore projection cannot hide/change a decision.
        interaction_cards = await self._visible_owner_interaction_cards(
            engine=run_engine,
            project_id=project_id,
            requester_task_id=task_id,
            requester_session_id=session_id,
        )
        interaction_cards = [
            card for card in interaction_cards
            if str(card.get("channel_id", "") or "").strip() == channel_id
        ]
        if interaction_cards:
            authoritative_ids = {
                str(card.get("metadata", {}).get("checkpoint_id", "") or "").strip()
                for card in interaction_cards
            }
            messages = [
                message for message in messages
                if str(dict(message.get("metadata", {}) or {}).get("checkpoint_id", "") or "").strip()
                not in authoritative_ids
            ]
            messages.extend(_sanitize_ui_message_dict(card) for card in interaction_cards)
            messages.sort(key=lambda item: (
                float(item.get("created_at", 0) or 0),
                str(item.get("message_id", "") or ""),
            ))
        total_message_count = max(transcript_total_count, visible_cache_count, len(messages))
        has_more = transcript_has_more or cache_has_more

        task_meta = task.metadata if isinstance(getattr(task, "metadata", None), dict) else {}
        handoff_context = _extract_markdown_text(task_meta.get("handoff_context"), max_chars=None)
        task_description_context = _extract_markdown_text(getattr(task, "description", ""), max_chars=None)
        parent_session_link = _task_parent_session_link(task, task_meta)
        if not handoff_context and parent_session_link:
            handoff_context = task_description_context or await _build_session_context_preview(
                run_engine,
                session_id,
                max_chars=None,
            )
        handoff_to = _extract_markdown_text(task_meta.get("handoff_to"), max_chars=None)
        status_val = task.status.value if hasattr(task.status, "value") else str(task.status)
        created_at = getattr(task, "created_at", None)
        created_ts = created_at.timestamp() if hasattr(created_at, "timestamp") else time.time()
        updated_at = getattr(task, "updated_at", None)
        updated_ts = updated_at.timestamp() if hasattr(updated_at, "timestamp") else created_ts
        assigned_to = str(getattr(task, "assigned_to", "") or "").strip()
        assignee_ids: list[str] = []
        if assigned_to:
            try:
                assignee_ids = [self.event_adapter._resolve_role_to_agent(assigned_to)] if self.event_adapter else [assigned_to]
            except Exception:
                assignee_ids = [assigned_to]
        identity = self._resolve_task_identity(task)
        exec_mode_val = identity.exec_mode
        company_profile_val = identity.company_profile
        org_id_val = identity.org_id
        config_task = await self._resolve_session_runtime_config_task(
            task_id,
            task,
            engine=run_engine,
        )
        permission_config = (
            self._ensure_office_services().session.resolve_task_native_permission_config(
                config_task or task,
                run_engine,
            )
        )
        project_tasks = [task]
        if self._is_company_session_exec_mode(exec_mode_val):
            try:
                project_tasks = await _request_project_tasks(store, project_id)
            except Exception:
                logger.opt(exception=True).debug("session_detail: failed to load project tasks for runtime control")
                project_tasks = [task]
        try:
            runtime_control_meta = (
                await _build_company_runtime_control_by_task(run_engine, project_tasks, project_id)
            ).get(task_id, {})
        except Exception:
            logger.opt(exception=True).debug("session_detail: failed to build runtime control payload")
            runtime_control_meta = {}
        runtime_meta = dict(task_meta.get("runtime_v2", {}) or {})
        member_session_meta = dict(task_meta.get("member_session_state", {}) or {})
        session_state: dict[str, Any] = {
            "project_id": project_id,
            "task_id": task_id,
            "runtime_task_id": task_id,
            "execution_turn_id": task_id,
            "session_id": session_id,
            "parent_session_id": parent_session_link or None,
            "mode": "child" if parent_session_link else "primary",
            "exec_mode": exec_mode_val,
            "company_profile": company_profile_val,
            "org_id": org_id_val,
            **permission_config,
            "channel_id": channel_id,
            "title": getattr(task, "title", "") or "Session",
            "status": status_val,
            "column_id": STATUS_TO_COLUMN.get(status_val, "todo"),
            "assignee_ids": assignee_ids,
            "priority": None,
            "tags": list(getattr(task, "tags", []) or []),
            "created_at": created_ts,
            "updated_at": updated_ts,
            "message_count": total_message_count,
            "handoff_context": handoff_context,
            "handoff_to": handoff_to,
            "origin_task_id": task_meta.get("origin_task_id") or task_id,
            "artifacts": task_meta.get("artifacts"),
            "runtime_session_id": runtime_meta.get("runtime_session_id"),
            "resume_cursor": runtime_meta.get("resume_cursor"),
            "active_subagents": list(runtime_meta.get("active_subagents", []) or []),
            "permission_requests": list(runtime_meta.get("permission_requests", []) or []),
            "worktree_path": runtime_meta.get("worktree_path"),
            "context_tokens": runtime_meta.get("context_tokens"),
            "context_window": runtime_meta.get("context_window"),
            "context_remaining_pct": runtime_meta.get("context_remaining_pct"),
            "input_tokens": runtime_meta.get("input_tokens"),
            "output_tokens": runtime_meta.get("output_tokens"),
            "total_tokens": runtime_meta.get("total_tokens"),
            "turn_cost_usd": runtime_meta.get("turn_cost_usd"),
            "session_cost_usd": runtime_meta.get("session_cost_usd"),
            "pending_permission_count": runtime_meta.get("pending_permission_count"),
            "drain_mode": runtime_meta.get("drain_mode"),
            "resident_status": normalize_role_runtime_status(
                member_session_meta.get("status") or member_session_meta.get("resident_status"),
                member_session_meta.get("focused_work_item_id"),
            ),
            "actionable_inbox_count": member_session_meta.get("actionable_inbox_count"),
            "protocol_backlog_count": member_session_meta.get("protocol_backlog_count"),
            "notification_backlog_count": member_session_meta.get("notification_backlog_count"),
            "latest_notification": member_session_meta.get("latest_notification"),
            "detail_loaded": True,
            "full_loaded": detail_level == "full" and not has_more,
            "has_more": has_more,
            "detail_loading": False,
            "view_generation": view_generation,
            **runtime_control_meta,
        }
        if "progress" in include_set or "work_items" in include_set or detail_level == "full":
            try:
                # Flush the in-memory progress buffer first: entries are
                # broadcast to clients before they reach the DB, so a snapshot
                # built from the DB alone would erase freshly streamed entries
                # from the client's live log (visible as flickering rows).
                await self._flush_progress(task_id, project_id=project_id)
                progress_log = await self.chat_store.get_progress(task_id, project_id=project_id)
            except Exception:
                progress_log = []
            session_state["progress_log"] = progress_log
        if "work_items" in include_set or detail_level == "full":
            session_state["work_item_log"] = list(task_meta.get("work_item_log", []) or [])
            if task_meta.get("role_work_items"):
                session_state["role_work_items"] = task_meta.get("role_work_items")
            if task_meta.get("executor_role_work_items"):
                session_state["executor_role_work_items"] = task_meta.get("executor_role_work_items")

        await self._send_ack(
            ws,
            ok=True,
            action="session_detail",
            project_id=project_id,
            view_generation=view_generation,
            task_id=task_id,
            channel_id=channel_id,
            session_id=session_id,
            detail_level=detail_level,
            include=sorted(include_set),
            message_count=total_message_count,
            loaded_count=len(messages),
            has_more=has_more,
            messages=messages,
            session_state=session_state,
            handoff_context=handoff_context,
            handoff_to=handoff_to,
        )

    async def _handle_external_team_activity_get(self, ws: Any, data: dict) -> None:
        try:
            _engine, project_id = await self._engine_for_request(data)
            result = await self._ensure_office_services().runtime.external_team_activity(
                project_id=project_id,
                task_id=str(data.get("task_id", "") or "").strip(),
                external_invocation_id=str(data.get("external_invocation_id", "") or "").strip(),
                limit=max(1, min(int(data.get("limit", 100) or 100), 500)),
                before_created_at=str(data.get("before_created_at", "") or "").strip(),
                before_event_id=str(data.get("before_event_id", "") or "").strip(),
            )
            payload = dict(result.payload or {})
            payload["view_generation"] = data.get("view_generation")
            await self._safe_send_json(ws, {
                "type": "external_team_activity_snapshot",
                "payload": payload,
            })
        except Exception as exc:
            if isinstance(exc, ServiceError):
                payload = exc.to_payload()
            else:
                logger.opt(exception=True).debug(
                    "Failed to read external team telemetry"
                )
                payload = {
                    "reason": "telemetry_unavailable",
                    "error": "telemetry_unavailable",
                }
            payload.update({
                "available": False,
                "project_id": str(data.get("project_id", "") or ""),
                "task_id": str(data.get("task_id", "") or ""),
                "external_invocation_id": str(data.get("external_invocation_id", "") or ""),
                "view_generation": data.get("view_generation"),
            })
            await self._safe_send_json(ws, {
                "type": "external_team_activity_snapshot",
                "payload": payload,
            })

    @staticmethod
    def _route_still_refuses(run_engine: Any, metadata: dict[str, Any]) -> str:
        """Whether this item's model call would still be refused before sending -- a dry run that sends nothing (review
        J5). The step's own model when it names one, otherwise the default and the quick-task route, each with the
        item's customer in scope. The refusal code, or "" when nothing refuses."""
        from ampuly.llm.budget import RouteRefused
        from ampuly.llm.provider import model_credential_scope

        llm = getattr(run_engine, "llm", None)
        if llm is None:
            return ""
        customer = str(metadata.get("customer_id", "") or "")
        environment = str(metadata.get("environment_id", "") or "")
        node = metadata.get("workflow_node")
        step_model = str(dict(node).get("model", "") or "").strip() if isinstance(node, dict) else ""
        try:
            with model_credential_scope(customer, environment):
                targets = [llm.for_model(step_model, customer_id=customer, environment_id=environment)] if step_model else [
                    llm._route(None), llm._route("quick_tasks")]
                for target in targets:
                    if not target._call_api_key():
                        return "key_not_set"
        except RouteRefused as exc:
            return str(getattr(exc, "code", "") or "route_refused")
        except Exception:  # noqa: BLE001 - a dry run that cannot tell says nothing
            return ""
        return ""

    async def _budget_card_refusal(self, run_engine: Any, store: Any, project_id: str, checkpoint_id: str, decision: dict,
                                   *, requester: dict[str, Any]) -> str:
        """Why "continue" on this card would only stop again, or "". Any trouble reading is "" -- the engine decides.

        Said only to somebody who may answer this card, and only while it is pending: otherwise the budget's state
        would be told to any socket that names a checkpoint id, ahead of the engine's own authorization.
        """
        from ampuly.layer2_organization.budget_stop_wait import refusal_before_continue

        try:
            checkpoint = await store.get_execution_checkpoint(checkpoint_id, project_id=project_id, checkpoint_type="task_user_input")
            payload = dict(getattr(checkpoint, "payload", {}) or {}) if checkpoint is not None else {}
            requested = payload.get("pause_request")
            if not isinstance(requested, dict) or not requested.get("budget_stop"):
                return ""
            if str(getattr(checkpoint, "status", "") or "") != "pending":
                return ""
            may_answer = getattr(run_engine, "can_answer_checkpoint", None)
            if not callable(may_answer) or not await may_answer(checkpoint, **{k: v for k, v in requester.items() if v is not None}):
                return ""
            task = await store.get_task(str(payload.get("task_id", "") or getattr(checkpoint, "task_id", "") or ""))
            reply = str(decision.get("text", "") or decision.get("option_id", "") or "")
            metadata = dict(getattr(task, "metadata", {}) or {})
            business = self._accounts().business

            def budget_of(budget_id: str) -> Any:
                # Why the allowance is held goes into the owner's refusal text: said in their words (P-c).
                return _budget_for_owner(business.run_budget(budget_id), nested=True)

            return refusal_before_continue(requested, reply, metadata, budget_of,
                                           route_check=lambda: WSHandler._route_still_refuses(run_engine, metadata))
        except Exception:
            logger.opt(exception=True).debug("budget card pre-check skipped")
            return ""

    async def _build_answer_refused(self, run_engine: Any, store: Any, project_id: str, checkpoint_id: str,
                                    checkpoint_type: str, *, requester: dict[str, Any]) -> bool:
        """Whether this answer is to a build job's question that no build turn here waits for (总控施工模式, B1).

        Such a question was left by a console that stopped, or by a turn that ended before it could close it. Taken in,
        the engine finds no live waiter and resumes the build's task on its general executor with its whole toolset --
        outside the build's fence (master_build.py). The build runner closes the question as stale and this answer goes
        no further. Said only to somebody who may answer the question: anybody else gets the engine's own answer.
        """
        from types import SimpleNamespace

        from ampuly.plugins.office_ui.master_build import build_job_of

        declared = SimpleNamespace(session_id=requester.get("requester_session_id") or "",
                                   task_id=requester.get("requester_task_id") or "")
        try:
            checkpoint = await store.get_execution_checkpoint(
                checkpoint_id, project_id=project_id, checkpoint_type=checkpoint_type,
            )
        except Exception:
            # Not readable here: an answer declaring a build as its asker is refused rather than let through blind.
            logger.opt(exception=True).debug("build answer check: checkpoint {} unreadable", checkpoint_id[:8])
            return bool(build_job_of(declared))
        # Only an answer to a question still open can be taken up: a repeat of an earlier answer, or one to a question
        # already closed, gets the engine's own answer (a duplicate or a refusal) and wakes nothing.
        if checkpoint is None or not build_job_of(checkpoint) or str(getattr(checkpoint, "status", "") or "") != "pending":
            return False
        may_answer = getattr(run_engine, "can_answer_checkpoint", None)
        if callable(may_answer):
            try:
                if not await may_answer(checkpoint, **{k: v for k, v in requester.items() if v is not None}):
                    return False
            except Exception:
                logger.opt(exception=True).debug("build answer check: authorization of {} unreadable", checkpoint_id[:8])
        try:
            return bool(await self._master_build_runner().refuse_left_answer(run_engine, checkpoint))
        except Exception:
            logger.opt(exception=True).warning("build answer check: the build runner could not look at {}; refused",
                                               checkpoint_id[:8])
            return True

    async def _handle_interaction_reply(self, ws: Any, data: dict, *, server_actor: dict[str, Any] | None = None) -> None:
        """Durably answer one explicit owner-facing ExecutionCheckpoint.

        This control message deliberately bypasses ``session_send`` and the
        per-task conversation lock.  The engine commits the decision with a
        checkpoint CAS before Office acknowledges it; chat rows emitted below
        are only a transcript projection of that durable receipt.
        """
        run_engine, project_id = await self._engine_for_request(data)
        checkpoint_id = str(data.get("checkpoint_id", "") or "").strip()
        checkpoint_type = str(data.get("checkpoint_type", "") or "").strip()
        client_request_id = str(data.get("client_request_id", "") or "").strip()
        requester_task_id = str(data.get("requester_task_id", "") or "").strip()
        declared_session_id = str(data.get("requester_session_id", "") or "").strip()
        decision = data.get("decision")

        missing = [
            name
            for name, value in (
                ("checkpoint_id", checkpoint_id),
                ("checkpoint_type", checkpoint_type),
                ("client_request_id", client_request_id),
            )
            if not value
        ]
        # ``server_actor`` is an internal adapter hand-off only (currently the
        # Feishu directory after open_id authorization).  Never read an actor
        # identity from the wire payload.
        requester_actor: dict[str, Any] | None = (
            dict(server_actor) if server_actor is not None else self._interaction_actor_for_ws(ws)
        )
        missing_identity = not (requester_task_id or declared_session_id)
        if missing or not isinstance(decision, dict):
            await self._send_ack(
                ws,
                ok=False,
                action="interaction_reply",
                error="invalid_request",
                reason=(
                    f"missing:{','.join(missing)}"
                    if missing
                    else (
                        "decision_must_be_object"
                    )
                ),
                checkpoint_id=checkpoint_id,
                checkpoint_type=checkpoint_type,
                client_request_id=client_request_id,
                project_id=project_id,
            )
            return

        if missing_identity:
            # The organization page can render a required-confirmation reorg
            # that has no task/session anchor. It still uses interaction_reply:
            # Office issues a process-local owner capability for this exact
            # checkpoint type and never accepts an actor token from the wire.
            issue_actor = getattr(run_engine, "issue_project_owner_actor", None)
            if checkpoint_type != "company_reorg_pending" or not callable(issue_actor):
                await self._send_ack(
                    ws,
                    ok=False,
                    action="interaction_reply",
                    error="invalid_request",
                    reason="requester_identity_required",
                    checkpoint_id=checkpoint_id,
                    checkpoint_type=checkpoint_type,
                    client_request_id=client_request_id,
                    project_id=project_id,
                )
                return
            try:
                requester_actor = issue_actor(interface="office_org")
            except Exception:
                await self._send_ack(
                    ws,
                    ok=False,
                    action="interaction_reply",
                    error="owner_actor_unavailable",
                    reason="requester_identity_required",
                    checkpoint_id=checkpoint_id,
                    checkpoint_type=checkpoint_type,
                    client_request_id=client_request_id,
                    project_id=project_id,
                )
                return

        store = getattr(run_engine, "store", None)
        if not self._store_is_ready(store):
            await self._send_ack(
                ws,
                ok=False,
                action="interaction_reply",
                error="store_not_ready",
                checkpoint_id=checkpoint_id,
                checkpoint_type=checkpoint_type,
                client_request_id=client_request_id,
                project_id=project_id,
            )
            return
        # Actor visibility and company-runtime identity resolution belong to
        # the engine.  Office forwards exactly the task/session identity the
        # client declared and does not maintain a second authorization model.
        requester_session_id = declared_session_id

        submit = getattr(run_engine, "submit_checkpoint_decision", None)
        if not callable(submit):
            # Fail closed.  Falling back to session_send would reintroduce the
            # task-lock cycle this protocol exists to remove.
            await self._send_ack(
                ws,
                ok=False,
                action="interaction_reply",
                error="interaction_reply_unsupported",
                checkpoint_id=checkpoint_id,
                checkpoint_type=checkpoint_type,
                client_request_id=client_request_id,
                project_id=project_id,
            )
            return

        # A question a build job asked (总控施工模式, B1) is answered only while the build's own turn waits for it.
        # After a restart, or once that turn has ended, the engine would take the answer up and run the build's task
        # outside the build's fence: the question is closed and the answer refused the way a stale card is.
        if await WSHandler._build_answer_refused(
            self, run_engine, store, project_id, checkpoint_id, checkpoint_type,
            requester={"requester_task_id": requester_task_id, "requester_session_id": requester_session_id or None,
                       "requester_actor": requester_actor},
        ):
            await self._send_ack(
                ws, ok=False, action="interaction_reply", accepted=False, deduplicated=False,
                error="invalid_state", reason="invalid_state", status="stale",
                checkpoint_id=checkpoint_id, checkpoint_type=checkpoint_type, client_request_id=client_request_id,
                project_id=project_id, requester_task_id=requester_task_id, requester_session_id=requester_session_id,
            )
            return

        if checkpoint_type == "task_user_input":
            # "Continue" on a budget card while the allowance still cannot be spent from would be accepted, refused
            # before dispatch, and answered with a new card. Say why now and leave this card where it is.
            still_stopped = await WSHandler._budget_card_refusal(
                self, run_engine, store, project_id, checkpoint_id, decision,
                requester={"requester_task_id": requester_task_id, "requester_session_id": requester_session_id or None,
                           "requester_actor": requester_actor},
            )
            if still_stopped:
                await self._send_ack(
                    ws, ok=False, action="interaction_reply", error=still_stopped, reason=still_stopped,
                    code="allowance_still_stopped", checkpoint_id=checkpoint_id, checkpoint_type=checkpoint_type,
                    client_request_id=client_request_id, project_id=project_id,
                )
                return

        submit_kwargs: dict[str, Any] = {
            "checkpoint_id": checkpoint_id,
            "checkpoint_type": checkpoint_type,
            "decision": dict(decision),
            "client_request_id": client_request_id,
            "requester_task_id": requester_task_id,
            "requester_session_id": requester_session_id or None,
        }
        if requester_actor is not None:
            submit_kwargs["requester_actor"] = requester_actor
        # The Feishu card of this checkpoint, when one was sent and nobody has claimed it: its spec is loaded before
        # the answer goes in, because once the runtime holds the answer the checkpoint is no longer pending and the
        # spec cannot be rebuilt.  A reply that came through GateService (a card click) finds its row claimed.
        gate_spec: Any = None
        if getattr(self, "_account_store", None) is not None:
            try:
                card_row = self._accounts().business.gate_card(checkpoint_id) or {}
                if card_row.get("message_id") and not card_row.get("decision"):
                    gate_spec = await self._gate_service().load_spec(checkpoint_id)
            except Exception:
                logger.opt(exception=True).debug("gate: could not look up the card of checkpoint {}", checkpoint_id[:8])
                gate_spec = None
        raw_receipt = await submit(
            **submit_kwargs,
        )
        receipt = (
            dict(raw_receipt)
            if isinstance(raw_receipt, dict)
            else {
                key: getattr(raw_receipt, key)
                for key in (
                    "accepted", "deduplicated", "duplicate", "status",
                    "outcome", "reason", "checkpoint_id", "checkpoint_type",
                )
                if hasattr(raw_receipt, key)
            }
        )
        outcome = str(receipt.get("outcome", "") or "").strip().lower()
        accepted = bool(receipt.get("accepted")) or outcome in {"accepted", "duplicate"}
        deduplicated = bool(
            receipt.get("deduplicated") or receipt.get("duplicate") or outcome == "duplicate"
        )
        reason = str(receipt.get("reason") or (outcome if not accepted else "") or "").strip()
        status = str(receipt.get("status") or ("answered" if accepted else "pending") or "").strip()

        # ACK is sent immediately after the durable store receipt.  Only then
        # may the frontend switch the card to its accepted/responded state.
        await self._send_ack(
            ws,
            ok=accepted,
            action="interaction_reply",
            accepted=accepted,
            deduplicated=deduplicated,
            error=(reason or "interaction_reply_rejected") if not accepted else None,
            reason=reason or None,
            status=status,
            checkpoint_id=checkpoint_id,
            checkpoint_type=checkpoint_type,
            client_request_id=client_request_id,
            project_id=project_id,
            requester_task_id=requester_task_id,
            requester_session_id=requester_session_id,
        )
        # A duplicate is the same decision arriving again -- after a refresh,
        # a reconnect, a double click. It was projected when it was first
        # accepted; projecting it again would show the approval twice (A10).
        if not accepted or deduplicated:
            return

        # Chat projection is not the receipt. Keep it out of this socket's
        # single control inbox so the next approval/Stop is not queued behind it.
        WSHandler._track_ui_projection(self,
            self._project_accepted_interaction_reply(
                engine=run_engine,
                project_id=project_id,
                requester_task_id=requester_task_id,
                requester_session_id=requester_session_id,
                checkpoint_id=checkpoint_id,
                checkpoint_type=checkpoint_type,
                client_request_id=client_request_id,
                decision=dict(decision),
            )
        )
        if gate_spec is not None:
            # A permission answered on the console's chat card left its Feishu card open, buttons and all
            # : close it the way the console's 放行 / 打回 closes a review card, through GateService.
            reply_kind = str(decision.get("checkpoint_reply_kind", "") or "").strip().lower()
            option_id = str(decision.get("option_id", "") or decision.get("interaction_option_id", "") or "").lower()
            refused = reply_kind == "deny" or (not reply_kind and "deny" in option_id)
            try:
                settled = await self._gate_service().settle_answered_elsewhere(
                    gate_spec, "deny" if refused else "approve", person=self._gate_person_for_ws(ws), channel="console",
                )
                logger.info("gate: card of checkpoint {} closed after a console answer: {}", checkpoint_id[:8], settled)
            except Exception:
                logger.opt(exception=True).warning("gate: could not close the card of checkpoint {} after a console answer", checkpoint_id[:8])

    async def _project_accepted_interaction_reply(
        self,
        *,
        engine: Any,
        project_id: str,
        requester_task_id: str,
        requester_session_id: str,
        checkpoint_id: str,
        checkpoint_type: str,
        client_request_id: str,
        decision: dict[str, Any],
    ) -> None:
        """Write the non-authoritative chat transcript after durable ACK."""
        checkpoint = await self._load_execution_checkpoint_for_reply(
            engine=engine,
            project_id=project_id,
            checkpoint_id=checkpoint_id,
            checkpoint_type=checkpoint_type,
        )
        presentation_task_id = await self._interaction_checkpoint_presentation_task_id(
            checkpoint,
            engine=engine,
        )
        channel_id = (
            f"session:{presentation_task_id}"
            if presentation_task_id
            else f"activity:{project_id}"
        )
        text = str(
            decision.get("text")
            or decision.get("option_label")
            or decision.get("option_id")
            or "Decision submitted."
        ).strip() or "Decision submitted."
        response_metadata: dict[str, Any] = {
            "response_to_checkpoint_id": checkpoint_id,
            "response_to_checkpoint_type": checkpoint_type,
            "ui_message_id": client_request_id,
        }
        # Preserve only the domain reply fields consumed by transcript/UI
        # renderers.  Tool arguments and approval policy data remain solely in
        # the ExecutionCheckpoint.
        for key in (
            "checkpoint_reply_kind",
            "option_id",
            "option_label",
            "self_evolution_trigger",
            "human_feedback_text",
            "recruitment_role_agents",
            "recruitment_agent",
            "staffing_action",
            "staffing_selections",
            "user_input_answers",
        ):
            if key in decision:
                response_metadata[key] = decision[key]

        message_id = f"interaction::{client_request_id}"
        existing_scope = await self.chat_store.message_scope(message_id)
        response_message: dict[str, Any] | None = None
        if existing_scope is None:
            response_message = await self.chat_store.insert_message(
                channel_id=channel_id,
                sender="user",
                sender_name="You",
                content=text,
                project_id=project_id,
                metadata=response_metadata,
                message_id=message_id,
            )
            await self.broadcast({"type": "session_message", "payload": response_message})
        elif existing_scope != (channel_id, project_id):
            logger.warning(
                "Interaction reply projection id collision: {} belongs to {}",
                message_id,
                existing_scope,
            )

        if checkpoint is not None:
            card = await self._interaction_checkpoint_ui_message(
                checkpoint,
                presentation_task_id=presentation_task_id,
                engine=engine,
                project_id=project_id,
            )
            if card is not None:
                await self._broadcast_owner_interaction_cards([card], project_id=project_id)

    async def _handle_session_send(self, ws: Any, data: dict) -> None:
        """Handle user message in a session. Auto-titles from first message."""
        task_id = data.get("task_id", "")
        content = data.get("content", "")
        if not content or not task_id:
            return
        run_engine, run_project_id = await self._engine_for_request(data)
        raw_metadata = data.get("metadata")
        if isinstance(raw_metadata, dict) and any(
            str(raw_metadata.get(key, "") or "").strip()
            for key in (
                "response_to_checkpoint_id",
                "response_to_checkpoint_type",
                "response_to_escalation_id",
            )
        ):
            await self._send_ack(
                ws,
                ok=False,
                action="session_send",
                error="checkpoint_reply_requires_interaction_reply",
                project_id=run_project_id,
                task_id=task_id,
            )
            return

        # Process file attachments via AttachmentStore (disk storage, lightweight refs)
        raw_attachments = data.get("attachments", [])
        attachment_refs: list[dict] = []
        attachment_errors: list[str] = []
        if raw_attachments:
            ensure_attachment_store = getattr(run_engine, "_ensure_attachment_store", None)
            if callable(ensure_attachment_store):
                try:
                    ensure_attachment_store()
                except Exception as exc:
                    logger.warning(f"Failed to refresh attachment store for project {run_project_id!r}: {exc}")
        att_store = getattr(run_engine, "attachment_store", None)
        if raw_attachments and att_store:
            for att in raw_attachments:
                filename = str(att.get("filename", "upload") or "upload").strip() or "upload"
                mime_type = str(att.get("mime_type", "") or "").strip() or None
                try:
                    ref = await att_store.save_from_base64(
                        filename,
                        att.get("data", ""),
                        mime_type=mime_type,
                    )
                    attachment_refs.append(ref.to_dict())
                except Exception as exc:
                    logger.warning(f"Attachment save failed: {exc}")
                    attachment_errors.append(f"{filename}: {exc}")
        elif raw_attachments and not att_store:
            attachment_errors.append("Attachment store is not available for the active project.")

        channel_id = f"session:{task_id}"
        pid = run_project_id

        # Look up session_id from task
        session_id: str | None = None
        task = None
        task_session_exec_mode = self._normalize_session_exec_mode(self._exec_mode)
        store = run_engine.store
        if self._store_is_ready(store):
            task = await store.get_task(task_id)
            if task:
                session_id = task.session_id
                task_session_exec_mode, _ = self._resolve_task_session_config(task)
            else:
                await self._send_ack(ws, ok=False, action="session_stop", error="task_not_found", project_id=run_project_id, task_id=task_id)
                return

        # Only cancelled/deleted sessions are terminal — their session data has
        # been torn down, so no further input can be accepted. A DONE session is
        # NOT terminal: task-mode reuses the same primary task across follow-up
        # turns (engine `_find_reusable_task_mode_task` reopens a DONE task in the
        # same session), and company sessions accept follow-up text after final
        # delivery. Blocking DONE here made task mode one-shot — the second user
        # message was rejected before it ever reached the engine.
        if task:
            from ampuly.core.models import TaskStatus
            if task.status == TaskStatus.CANCELLED:
                try:
                    cancelled_target = await self._resolve_company_runtime_target(
                        task_id,
                        engine=run_engine,
                    )
                except Exception:
                    logger.opt(exception=True).debug(
                        "failed to resolve cancelled company UI anchor"
                    )
                    cancelled_target = None
                identity = (cancelled_target or {}).get("identity")
                active_cancelled_anchor = bool(
                    identity is not None
                    and str(getattr(identity, "ui_anchor_task_id", "") or "") == task_id
                    and str(getattr(identity, "pending_checkpoint_id", "") or "").strip()
                    and str(getattr(identity, "pending_checkpoint_type", "") or "").strip()
                    in COMPANY_RUNTIME_CHECKPOINT_TYPES
                    and str(getattr(identity, "pending_checkpoint_status", "") or "").strip().lower()
                    in ACTIVE_COMPANY_RUNTIME_CHECKPOINT_STATUSES
                )
                if not active_cancelled_anchor:
                    await self._send_ack(ws, ok=False, error="session_ended")
                    return

        if attachment_errors:
            helper_lines = [
                "Some attachments could not be included, so they were not sent to the model:",
                *[f"- {item}" for item in attachment_errors],
            ]
            helper = await self.chat_store.insert_message(
                channel_id=channel_id,
                sender="assistant",
                sender_name=STORED_SPEAKER,
                content="\n".join(helper_lines),
                project_id=pid,
                metadata={"type": "system"},
            )
            await self.broadcast({"type": "session_message", "payload": helper})
            if raw_attachments and not attachment_refs and content.strip() == "Sent with attachments":
                return

        # Ordinary conversation metadata contains only its idempotency key.
        # Every structured checkpoint field belongs to interaction_reply.
        reply_metadata: dict[str, Any] = {}
        if isinstance(raw_metadata, dict):
            raw_ui_message_id = str(raw_metadata.get("ui_message_id", "") or "").strip()
            if raw_ui_message_id:
                reply_metadata["ui_message_id"] = raw_ui_message_id

        # Idempotency on the client-generated message id: the WS client queues
        # sends while disconnected and flushes the queue after a reconnect, so
        # one typed message can be delivered more than once. The first delivery
        # persisted a row under this id in this channel; later copies are
        # acknowledged and dropped instead of dispatching a duplicate turn.
        client_message_id = str(reply_metadata.get("ui_message_id", "") or "").strip()
        if client_message_id:
            existing_scope = await self.chat_store.message_scope(client_message_id)
            if existing_scope == (channel_id, pid):
                logger.info(
                    f"session_send deduplicated re-delivered client message {client_message_id} "
                    f"for task {task_id}"
                )
                await self._send_ack(
                    ws,
                    ok=True,
                    action="session_send",
                    task_id=task_id,
                    project_id=pid,
                    deduplicated=True,
                    message_id=client_message_id,
                )
                return
            if existing_scope is not None:
                # Same id already used in another channel/project: never reuse it
                # as a row id there (insert_message REPLACEs by primary key).
                client_message_id = ""

        msg_metadata: dict = dict(reply_metadata)
        if attachment_refs:
            msg_metadata["attachment_refs"] = attachment_refs
        msg = await self.chat_store.insert_message(
            channel_id=channel_id,
            sender="user",
            sender_name="You",
            content=content,
            project_id=pid,
            metadata=msg_metadata if msg_metadata else None,
            # Persist under the client-generated id so re-deliveries of the same
            # send are detectable and the optimistic bubble merges with the echo.
            message_id=client_message_id or None,
        )
        await self.broadcast({"type": "session_message", "payload": msg})

        # Auto-generate title from first message if task title is still default
        store = run_engine.store
        if self._store_is_ready(store) and task:
            if task.title in ("New Chat", ""):
                auto_title = _compact_session_title(content)
                task.title = auto_title
                await store.save_task(task)
                await self.chat_store.update_channel_name(channel_id, auto_title, project_id=pid)
                # Also update engine session title
                if run_engine.memory and session_id:
                    await run_engine.memory.update_session_title(session_id, auto_title)
                await self.broadcast({"type": "session_title_updated", "payload": {
                    "project_id": pid,
                    "task_id": task_id,
                    "title": auto_title,
                }})

        if await self._route_company_suspend_reply_if_pending(
            task_id=task_id,
            content=content,
            session_id=session_id,
            task=task,
            attachment_refs=attachment_refs or None,
            message_metadata=reply_metadata if reply_metadata else None,
            user_message_id=str(msg.get("message_id") or "").strip() or None,
            user_message_created_at=float(msg.get("created_at")) if msg.get("created_at") is not None else None,
            run_engine=run_engine,
            run_project_id=run_project_id,
        ):
            return

        if task and self._is_company_session_exec_mode(task_session_exec_mode):
            self._track_session(
                task_id,
                self._process_session_message(
                    task_id,
                    content,
                    session_id=session_id,
                    attachment_refs=attachment_refs or None,
                    message_metadata=reply_metadata if reply_metadata else None,
                    user_message_id=str(msg.get("message_id") or "").strip() or None,
                    user_message_created_at=float(msg.get("created_at")) if msg.get("created_at") is not None else None,
                    run_engine=run_engine,
                    run_project_id=run_project_id,
                ),
                project_id=run_project_id,
                engine=run_engine,
            )
            return

        # Route task-mode sessions through Dispatcher: classify intent, then either engine or direct reply.
        self._track_session(
            task_id,
            self._dispatch_session_message(
                task_id,
                content,
                session_id=session_id,
                attachment_refs=attachment_refs or None,
                message_metadata=reply_metadata if reply_metadata else None,
                user_message_id=str(msg.get("message_id") or "").strip() or None,
                user_message_created_at=float(msg.get("created_at")) if msg.get("created_at") is not None else None,
                run_engine=run_engine,
                run_project_id=run_project_id,
            ),
            project_id=run_project_id,
            engine=run_engine,
        )

    async def _cancel_task_tree(
        self,
        task_id: str,
        *,
        hard: bool = False,
        preserve_history: bool = False,
        store: Any | None = None,
    ) -> list[str]:
        """Cancel a task and its children, clean up engine store data.

        Args:
            hard: If True, hard-delete task rows and all lifecycle data
                  (used by session_delete).  If False, soft-cancel and
                  partial cleanup (used by session_stop).

        Returns all affected task_ids (parent + children).
        """
        all_task_ids: list[str] = [task_id]
        store = store or self.engine.store
        if not store:
            return all_task_ids
        from ampuly.core.models import TaskStatus
        task = await store.get_task(task_id)
        if not task:
            return all_task_ids

        # Collect child tasks first (before any deletion)
        child_tasks: list[tuple[str, str | None]] = []
        parent_sid = task.session_id or task_id
        project_id = task.project_id or getattr(store, "project_id", None) or self.engine.project_id or "default"
        try:
            siblings = await store.get_tasks(project_id=project_id)
            for sib in siblings:
                if sib.id == task_id:
                    continue
                if getattr(sib, "parent_session_id", None) == parent_sid:
                    child_tasks.append((sib.id, sib.session_id))
                    all_task_ids.append(sib.id)
        except Exception:
            logger.debug(f"Failed to find children of {task_id}")

        async def _cancel_child_via_phase(child_task: Any) -> None:
            """Cascade CANCELLED to the child's work_item.phase so the UI
            column + all projection layers update. Plain tasks keep legacy
            Task.status behavior through the shared transition fallback.
            """
            child_task.metadata = dict(getattr(child_task, "metadata", {}) or {})
            child_task.metadata["last_stop_reason"] = "user_stop"
            await apply_task_status_transition(
                store,
                child_task,
                target_status_or_phase=TaskStatus.CANCELLED,
                reason="user_stop",
                metadata_updates={"last_stop_reason": "user_stop"},
                release_claim=True,
            )

        if hard:
            # Hard-delete: children first, then parent (preserves session ref-count accuracy)
            for child_id, child_sid in child_tasks:
                try:
                    await store.hard_delete_task(child_id, child_sid)
                except Exception:
                    logger.debug(f"hard_delete_task failed for child {child_id}")
            try:
                await store.hard_delete_task(task_id, task.session_id)
            except Exception:
                logger.debug(f"hard_delete_task failed for {task_id}")
        elif preserve_history:
            # Parent stays IDLE (suspend-for-resume — user hit Stop, may resume
            # later). We do NOT transition parent's work_item here; resuming
            # should pick it back up in whatever phase it was parked in.
            task.metadata["last_stop_reason"] = "user_stop"
            task.status = TaskStatus.IDLE
            await store.save_task(task)
            for child_id, _child_sid in child_tasks:
                try:
                    child_task = await store.get_task(child_id)
                    if child_task:
                        await _cancel_child_via_phase(child_task)
                except Exception:
                    logger.debug(f"Failed to preserve stop state for child task {child_id}")
        else:
            # Soft-cancel: cascade CANCELLED phase to parent + children
            await apply_task_status_transition(
                store,
                task,
                target_status_or_phase=TaskStatus.CANCELLED,
                reason="user_cancel",
                release_claim=True,
            )
            try:
                await store.delete_session_data(task_id, task.session_id)
            except Exception:
                logger.debug(f"Failed to clean session data for {task_id}")
            for child_id, child_sid in child_tasks:
                try:
                    child_task = await store.get_task(child_id)
                    if child_task:
                        await _cancel_child_via_phase(child_task)
                    await store.delete_session_data(child_id, child_sid)
                except Exception:
                    pass

        # Clean progress buffers + cancel background tasks for all affected
        for tid in all_task_ids:
            self._progress_buffer.pop(tid, None)
            self._progress_project_ids.pop(tid, None)
            if hard:
                try:
                    await self.chat_store.delete_progress(tid, project_id=project_id)
                except Exception:
                    pass
            self._cancel_session_tasks(tid)

        return all_task_ids

    async def _resolve_company_runtime_target(
        self,
        task_id: str,
        *,
        engine: Any | None = None,
        runtime_session_id: str = "",
        checkpoint_id: str = "",
    ) -> dict[str, Any] | None:
        """Resolve a Task/UI channel to the canonical session-first scope."""
        runtime_engine = engine or self.engine
        store = runtime_engine.store
        if not task_id or not self._store_is_ready(store):
            return None
        task = await store.get_task(task_id)
        if task is None:
            return None
        project_id = self._normalize_project_id(
            getattr(task, "project_id", None) or getattr(runtime_engine, "project_id", None)
        )
        # Read once per request inside a read scope (session detail); loaded as
        # before everywhere else, including every action that resolves a target.
        identity_index = await _request_identity_index(store, project_id)
        identity = identity_index.resolve(
            task_id=task_id,
            runtime_session_id=runtime_session_id,
            checkpoint_id=checkpoint_id,
        )
        if identity is None:
            return None
        ui_anchor_task_id = identity.ui_anchor_task_id
        config_task = identity_index.task(identity.config_source_task_id) or task

        return {
            "task": task,
            "engine": runtime_engine,
            "identity": identity,
            "runtime_session_id": identity.runtime_session_id,
            "ui_channel_task_id": task_id,
            "ui_anchor_task_id": ui_anchor_task_id,
            "config_source_task_id": identity.config_source_task_id,
            "config_task": config_task,
            "checkpoint": identity.checkpoint,
            "origin_task_id": ui_anchor_task_id,
            "affected_task_ids": list(identity.runtime_task_ids),
        }

    async def _broadcast_company_runtime_control(
        self,
        target: dict[str, Any],
        *,
        state: str,
        checkpoint_id: str = "",
        stop_intent_id: str = "",
    ) -> None:
        affected_task_ids = [
            str(item).strip()
            for item in list(target.get("affected_task_ids", []) or [])
            if str(item).strip()
        ]
        runtime_engine = target.get("engine") or self.engine
        project_id = self._normalize_project_id(getattr(runtime_engine, "project_id", None))
        payload = {
            "project_id": project_id,
            "runtime_control_state": state,
            "can_stop": state == "running",
            "can_resume": state == "suspended",
            "resume_parent_session_id": str(target.get("runtime_session_id", "") or "").strip(),
            "pending_runtime_checkpoint_id": checkpoint_id,
            "stop_intent_id": stop_intent_id,
            "task_ids": affected_task_ids,
        }
        await self.broadcast({"type": "session_runtime_control", "payload": payload})

    async def _set_company_runtime_control(
        self,
        target: dict[str, Any] | None,
        *,
        state: str,
        checkpoint_id: str = "",
        stop_intent_id: str = "",
    ) -> None:
        if target is None:
            return
        await self._broadcast_company_runtime_control(
            target,
            state=state,
            checkpoint_id=checkpoint_id,
            stop_intent_id=stop_intent_id,
        )

    async def _notify_session_stop_registry(
        self, engine: Any, *, project_id: str, task_ids: list[str], actor: str,
    ) -> dict[str, Any]:
        """AE04a: request exact scoped turns to stop; never settle or close them."""
        from ampuly.plugins.office_ui.session_stop_registry import notify_session_stop_registry

        result = await notify_session_stop_registry(
            engine, project_id=project_id, task_ids=task_ids, actor=actor,
        )
        if result["errors"]:
            logger.warning(
                "session_stop registry notification incomplete ({})",
                ",".join(sorted({item["code"] for item in result["errors"]})),
            )
        return result

    async def _finalize_company_runtime_stop(self, target: dict[str, Any], *, stop_intent_id: str) -> None:
        runtime_engine = target.get("engine") or self.engine
        parent_session_id = str(target.get("runtime_session_id", "") or "").strip()
        origin_task_id = str(target.get("origin_task_id", "") or "").strip()
        affected_task_ids = [
            str(item).strip()
            for item in list(target.get("affected_task_ids", []) or [])
            if str(item).strip()
        ]
        suspended: dict[str, Any] | None = None
        stop_failure = ""
        try:
            suspended = await asyncio.wait_for(
                runtime_engine.suspend_company_runtime(
                    origin_task_id=origin_task_id,
                    session_id=parent_session_id or None,
                    reason="user_stop",
                    checkpoint_type="company_runtime_suspended",
                    stop_intent_id=stop_intent_id,
                ),
                timeout=30.0,
            )
            if suspended is None:
                stop_failure = "stop_not_applied"
        except asyncio.TimeoutError:
            stop_failure = "stop_timeout"
            logger.warning("suspend_company_runtime timed out for {} (30 s); the console stays honest and reports it", origin_task_id[:8])
        except Exception as exc:
            stop_failure = f"{type(exc).__name__}"
            logger.opt(exception=True).warning(f"suspend_company_runtime failed for {origin_task_id}")

        if suspended is not None:
            for candidate in list(suspended.get("task_ids", []) or []):
                candidate_id = str(candidate or "").strip()
                if candidate_id and candidate_id not in affected_task_ids:
                    affected_task_ids.append(candidate_id)
            target["affected_task_ids"] = affected_task_ids
            self._stop_requested_task_ids.update(affected_task_ids)
            # The durable WorkItem hold is already installed: interrupting
            # its turn must not turn a Stop into an order cancellation.
            target["registry_stop"] = await self._notify_session_stop_registry(
                runtime_engine,
                project_id=self._normalize_project_id(getattr(runtime_engine, "project_id", None)),
                task_ids=affected_task_ids, actor=target.get("stop_requested_by", "unknown"),
            )
            for tid in affected_task_ids:
                self._progress_buffer.pop(tid, None)
                self._progress_project_ids.pop(tid, None)
                self._cancel_session_tasks(tid)
            try:
                await self._set_company_runtime_control(
                    target,
                    state="suspended",
                    checkpoint_id=str(suspended.get("checkpoint_id", "") or ""),
                    stop_intent_id=stop_intent_id,
                )
            except Exception:
                logger.opt(exception=True).debug("failed to broadcast company runtime suspended state")
            channel_id = f"session:{target.get('ui_channel_task_id', '')}"
            pid = self._normalize_project_id(getattr(runtime_engine, "project_id", None))
            try:
                msg = await self.chat_store.insert_message(
                    channel_id=channel_id,
                    sender="system",
                    sender_name="System",
                    content="Company runtime suspended by user",
                    project_id=pid,
                    metadata={
                        "type": "system",
                        "stop_reason": "user_stop",
                        "checkpoint_type": suspended.get("checkpoint_type"),
                        "checkpoint_id": suspended.get("checkpoint_id"),
                        "stop_intent_id": stop_intent_id,
                        "registry_stop": target["registry_stop"],
                    },
                )
                await self.broadcast({"type": "session_message", "payload": msg})
            except Exception:
                logger.opt(exception=True).warning(f"Failed to insert suspend message for {origin_task_id}")
        else:
            try:
                await self._set_company_runtime_control(
                    target,
                    state="running" if affected_task_ids else "idle",
                    stop_intent_id=stop_intent_id,
                )
            except Exception:
                pass
            # A stop that did not take effect must be visible: before
            # 2026-09-06 the header simply flipped back and the operator had
            # no way to know the run was still live.
            channel_id = f"session:{target.get('ui_channel_task_id', '')}"
            pid = self._normalize_project_id(getattr(runtime_engine, "project_id", None))
            try:
                msg = await self.chat_store.insert_message(
                    channel_id=channel_id,
                    sender="system",
                    sender_name="System",
                    content=f"停止未生效（{stop_failure or 'stop_not_applied'}）：运行没有被挂起，请稍后重试或在流程图上处理具体工作项。",
                    project_id=pid,
                    metadata={"type": "system", "stop_reason": "user_stop", "stop_failure": stop_failure or "stop_not_applied", "stop_intent_id": stop_intent_id},
                )
                await self.broadcast({"type": "session_message", "payload": msg})
            except Exception:
                logger.opt(exception=True).debug("failed to report a stop that did not apply")
        self._company_stop_intents.pop(parent_session_id, None)
        self._company_stop_finalize_tasks.pop(parent_session_id, None)

    async def _handle_session_stop(self, ws: Any, data: dict) -> None:
        """Stop a running task: suspend company runtime, cancel legacy task mode."""
        task_id = data.get("task_id", "")
        if not task_id:
            return

        run_engine, run_project_id = await self._engine_for_request(data)
        store = run_engine.store
        task = None
        if self._store_is_ready(store):
            try:
                task = await store.get_task(task_id)
            except Exception:
                logger.opt(exception=True).debug(f"Failed to load task for stop: {task_id}")
            if task is None:
                await self._send_ack(ws, ok=False, action="session_stop", error="task_not_found", project_id=run_project_id, task_id=task_id)
                return

        target = None
        if task is not None:
            try:
                target = await self._resolve_company_runtime_target(task_id, engine=run_engine)
            except Exception:
                logger.opt(exception=True).warning(
                    f"failed to resolve company runtime stop target for {task_id}"
                )
            if target is not None:
                target["stop_requested_by"] = _ws_actor_login(self, ws)
                parent_session_id = str(target.get("runtime_session_id", "") or "").strip()
                existing_checkpoint = None
                try:
                    existing_checkpoint = await run_engine.get_pending_company_runtime_suspend_checkpoint(parent_session_id)
                except Exception:
                    logger.opt(exception=True).debug("failed to check existing company suspend checkpoint")
                existing_intent = self._company_stop_intents.get(parent_session_id)
                existing_finalizer = self._company_stop_finalize_tasks.get(parent_session_id)
                if existing_checkpoint is not None:
                    from ampuly.plugins.office_ui.session_stop_registry import MAX_STOP_TASKS, _identifier

                    checkpoint_payload = existing_checkpoint.payload
                    if checkpoint_payload is None:
                        checkpoint_payload = {}
                    stop_task_ids = list(target.get("affected_task_ids", []) or [task_id])
                    scope_invalid = type(checkpoint_payload) is not dict
                    if not scope_invalid and "task_ids" in checkpoint_payload:
                        durable_ids = checkpoint_payload["task_ids"]
                        scope_invalid = (
                            getattr(existing_checkpoint, "project_id", None) != run_project_id
                            or getattr(existing_checkpoint, "session_id", None) != parent_session_id
                            or checkpoint_payload.get("project_id", run_project_id) != run_project_id
                            or checkpoint_payload.get("parent_session_id", parent_session_id) != parent_session_id
                            or checkpoint_payload.get("session_id", parent_session_id) != parent_session_id
                            or type(durable_ids) is not list or len(durable_ids) > MAX_STOP_TASKS
                            or any(not _identifier(tid) for tid in durable_ids)
                        )
                        if not scope_invalid:
                            # Exactly the durable held scope, not newer tasks
                            # now grouped under the same runtime session.
                            stop_task_ids = list(durable_ids)
                    if scope_invalid:
                        await self._send_ack(ws, ok=False, action="session_stop", error="stop_registry_scope_invalid", project_id=run_project_id, task_id=task_id, runtime_session_id=parent_session_id)
                        return
                    await self._set_company_runtime_control(
                        target,
                        state="suspended",
                        checkpoint_id=existing_checkpoint.checkpoint_id,
                        stop_intent_id=str(checkpoint_payload.get("stop_intent_id", "") or ""),
                    )
                    registry_stop = await self._notify_session_stop_registry(
                        run_engine, project_id=run_project_id,
                        task_ids=stop_task_ids,
                        actor=target["stop_requested_by"],
                    )
                    await self._send_ack(ws, ok=True, action="session_stop", idempotent=True, project_id=run_project_id, task_id=task_id, runtime_session_id=parent_session_id, registry_stop=registry_stop)
                    return
                if existing_intent or (existing_finalizer is not None and not existing_finalizer.done()):
                    await self._set_company_runtime_control(
                        target,
                        state="suspending",
                        stop_intent_id=str((existing_intent or {}).get("stop_intent_id", "") or ""),
                    )
                    await self._send_ack(ws, ok=True, action="session_stop", idempotent=True, project_id=run_project_id, task_id=task_id, runtime_session_id=parent_session_id)
                    return

                stop_intent_id = str(uuid.uuid4())
                self._company_stop_intents[parent_session_id] = {
                    "stop_intent_id": stop_intent_id,
                    "requested_at": datetime.now().isoformat(),
                    "origin_task_id": target.get("origin_task_id", task_id),
                }
                await self._set_company_runtime_control(
                    target,
                    state="suspending",
                    stop_intent_id=stop_intent_id,
                )
                finalizer = self._track(
                    self._finalize_company_runtime_stop(target, stop_intent_id=stop_intent_id)
                )
                self._company_stop_finalize_tasks[parent_session_id] = finalizer
                await self._send_ack(ws, ok=True, action="session_stop", stop_intent_id=stop_intent_id, project_id=run_project_id, task_id=task_id, runtime_session_id=parent_session_id)
                return

            if is_company_runtime_task(task):
                await self._send_ack(
                    ws,
                    ok=False,
                    action="session_stop",
                    error="company_runtime_identity_mismatch",
                    project_id=run_project_id,
                    task_id=task_id,
                )
                return

        try:
            all_task_ids = await self._cancel_task_tree(task_id, preserve_history=True, store=store)
        except Exception:
            logger.opt(exception=True).warning(f"_cancel_task_tree failed for {task_id}")
            all_task_ids = [task_id]
        self._stop_requested_task_ids.update(all_task_ids)
        registry_stop = (
            await self._notify_session_stop_registry(
                run_engine, project_id=run_project_id, task_ids=all_task_ids,
                actor=_ws_actor_login(self, ws),
            ) if task is not None else {"status": "unsupported", "interrupts": [], "errors": []}
        )

        # Broadcast status updates for all affected tasks
        for tid in all_task_ids:
            is_primary_task = tid == task_id
            try:
                await self.broadcast({"type": "board_task_status_changed", "payload": {
                    "project_id": run_project_id,
                    "task_id": tid,
                    "column_id": "in-progress" if is_primary_task else "done",
                    "status": "idle" if is_primary_task else "cancelled",
                }})
                stop_payload: dict[str, Any] = {
                    "project_id": run_project_id,
                    "task_id": tid, "status": "idle", "current_tool": None, "iteration": 0,
                }
                # Resolve agent_id from event_adapter map or task.assigned_to
                stop_task = None
                if self._store_is_ready(store):
                    try:
                        stop_task = await store.get_task(tid)
                    except Exception:
                        pass
                resolved_agent = self._resolve_agent_for_idle(tid, stop_task)
                if resolved_agent:
                    stop_payload["agent_id"] = resolved_agent
                await self.broadcast({"type": "agent_runtime_update", "payload": stop_payload})
            except Exception:
                logger.opt(exception=True).warning(f"Failed to broadcast stop status for {tid}")

        # Insert system message (only for the primary task — children are internal)
        channel_id = f"session:{task_id}"
        pid = run_project_id
        try:
            msg = await self.chat_store.insert_message(
                channel_id=channel_id,
                sender="system",
                sender_name="System",
                content="Task stopped by user",
                project_id=pid,
                metadata={"type": "system", "stop_reason": "user_stop"},
            )
            await self.broadcast({"type": "session_message", "payload": msg})
        except Exception:
            logger.opt(exception=True).warning(f"Failed to insert stop message for {task_id}")
        await self._send_ack(ws, ok=True, action="session_stop", project_id=run_project_id, task_id=task_id, registry_stop=registry_stop)

    async def _handle_session_resume(self, ws: Any, data: dict) -> None:
        """Resume by durable runtime-session/checkpoint identity."""
        task_id = str(data.get("task_id", "") or "").strip()
        if not task_id:
            await self._send_ack(
                ws,
                ok=False,
                action="session_resume",
                project_id=str(data.get("project_id", "") or "").strip(),
                error="missing_task_id",
                task_id=task_id,
            )
            return
        run_engine, run_project_id = await self._engine_for_request(data)

        async def reject(error: str, **extra: Any) -> None:
            ack_extra = {
                "project_id": run_project_id,
                "task_id": task_id,
                **extra,
            }
            await self._send_ack(
                ws,
                ok=False,
                action="session_resume",
                error=error,
                **ack_extra,
            )
            await self._refresh_runtime_control_for_client(
                ws,
                engine=run_engine,
                project_id=run_project_id,
            )

        task = None
        session_id_override = str(data.get("session_id", "") or "").strip() or None
        if self._store_is_ready(run_engine.store):
            try:
                task = await run_engine.store.get_task(task_id)
            except Exception:
                logger.opt(exception=True).warning(f"session_resume: get_task failed for {task_id}")
            if task is None:
                await reject("task_not_found", project_id=run_project_id, task_id=task_id)
                return
        session_id = session_id_override
        if not session_id and task is not None:
            session_id = str(task.session_id or task.parent_session_id or "").strip() or None
        exec_mode, _company_profile = self._resolve_task_session_config(task)
        runtime_session_id = str(data.get("runtime_session_id", "") or "").strip()
        checkpoint_id = str(data.get("checkpoint_id", "") or "").strip()
        is_company_resume = bool(runtime_session_id or checkpoint_id) or exec_mode in {
            "company",
            "org",
            "custom",
        }
        if is_company_resume and task is not None:
            if not runtime_session_id:
                await reject("missing_runtime_session_id")
                return
            if not checkpoint_id:
                await reject("missing_checkpoint_id")
                return
            try:
                target = await self._resolve_company_runtime_target(
                    task_id,
                    engine=run_engine,
                    runtime_session_id=runtime_session_id,
                    checkpoint_id=checkpoint_id,
                )
            except Exception:
                logger.opt(exception=True).warning(f"session_resume: failed to resolve company runtime target for {task_id}")
                target = None
            if target is None:
                await reject(
                    "company_runtime_identity_mismatch",
                    project_id=run_project_id,
                    task_id=task_id,
                )
                return
            checkpoint = target.get("checkpoint")
            if checkpoint is None or str(getattr(checkpoint, "status", "") or "").strip().lower() != "pending":
                await reject("checkpoint_not_pending", checkpoint_id=checkpoint_id)
                return
            session_id = runtime_session_id
            finalizer = self._company_stop_finalize_tasks.get(runtime_session_id)
            if finalizer is not None and not finalizer.done():
                try:
                    await asyncio.wait_for(asyncio.shield(finalizer), timeout=10.0)
                except asyncio.TimeoutError:
                    await reject("stop_finalize_in_progress")
                    return
                except Exception:
                    logger.opt(exception=True).debug("session_resume: stop finalizer ended with error")
            self._company_stop_intents.pop(runtime_session_id, None)
            content = str(data.get("content", "") or "").strip() or "Resume the existing runtime."
            lock = self._company_suspend_reply_locks.get(runtime_session_id)
            if lock is not None:
                self._release_current_execution_handoff()
                await reject(
                    "checkpoint_handoff_in_progress",
                    checkpoint_id=checkpoint_id,
                )
                return
            lock = asyncio.Lock()
            self._company_suspend_reply_locks[runtime_session_id] = lock
            try:
                bg = self._track_session(
                    task_id,
                    self._process_company_suspend_reply(
                        ui_task_id=task_id,
                        runtime_session_id=runtime_session_id,
                        content=content,
                        attachment_refs=None,
                        message_metadata={
                            "ui_force_resume": True,
                            "response_to_checkpoint_id": checkpoint_id,
                            "response_to_checkpoint_type": str(getattr(checkpoint, "checkpoint_type", "") or ""),
                        },
                        user_message_id=None,
                        user_message_created_at=None,
                        run_engine=run_engine,
                        run_project_id=run_project_id,
                        target=target,
                        checkpoint=checkpoint,
                        lock=lock,
                    ),
                    project_id=run_project_id,
                    engine=run_engine,
                )
            except BaseException:
                self._company_suspend_reply_locks.pop(runtime_session_id, None)
                raise
            self._task_bg_context[bg]["company_suspend_reply"] = True
            await self._send_ack(
                ws,
                ok=True,
                action="session_resume",
                project_id=run_project_id,
                task_id=task_id,
                runtime_session_id=runtime_session_id,
                checkpoint_id=checkpoint_id,
            )
            return
        if not session_id:
            await reject("session_not_found")
            return

        content = str(data.get("content", "") or "").strip() or "Resume the existing runtime."

        self._track_session(
            task_id,
            self._process_session_message(
                task_id,
                content,
                session_id=session_id,
                message_metadata={"ui_force_resume": True},
                run_engine=run_engine,
                run_project_id=run_project_id,
            ),
            project_id=run_project_id,
            engine=run_engine,
        )
        await self._send_ack(ws, ok=True, action="session_resume", project_id=run_project_id, task_id=task_id, session_id=session_id)

    async def _load_execution_checkpoint_for_reply(
        self,
        *,
        engine: Any,
        project_id: str,
        checkpoint_id: str,
        checkpoint_type: str,
    ) -> Any | None:
        normalized_checkpoint_id = str(checkpoint_id or "").strip()
        normalized_checkpoint_type = str(checkpoint_type or "").strip()
        if not normalized_checkpoint_id:
            return None

        store = getattr(engine, "store", None)
        getter = getattr(store, "get_execution_checkpoints", None)
        if callable(getter):
            try:
                checkpoints = await getter(project_id=project_id)
            except TypeError:
                checkpoints = await getter(project_id)
            except Exception:
                logger.opt(exception=True).debug("failed to list checkpoints for explicit reply routing")
                checkpoints = []
            for checkpoint in list(checkpoints or []):
                if str(getattr(checkpoint, "checkpoint_id", "") or "").strip() != normalized_checkpoint_id:
                    continue
                if (
                    normalized_checkpoint_type
                    and str(getattr(checkpoint, "checkpoint_type", "") or "").strip() != normalized_checkpoint_type
                ):
                    return None
                return checkpoint

        direct_lookup = getattr(engine, "_load_execution_checkpoint_by_id", None)
        if callable(direct_lookup):
            try:
                maybe_checkpoint = direct_lookup(normalized_checkpoint_id)
                checkpoint = await maybe_checkpoint if inspect.isawaitable(maybe_checkpoint) else maybe_checkpoint
            except Exception:
                logger.opt(exception=True).debug("failed to load checkpoint by id for explicit reply routing")
                checkpoint = None
            if checkpoint is not None:
                if str(getattr(checkpoint, "checkpoint_id", "") or "").strip() != normalized_checkpoint_id:
                    return None
                if (
                    normalized_checkpoint_type
                    and str(getattr(checkpoint, "checkpoint_type", "") or "").strip() != normalized_checkpoint_type
                ):
                    return None
                return checkpoint
        return None

    @staticmethod
    def _checkpoint_created_timestamp(checkpoint: Any | None) -> float | None:
        raw_value = getattr(checkpoint, "created_at", None) if checkpoint is not None else None
        if raw_value is None:
            return None
        if isinstance(raw_value, (int, float)):
            return float(raw_value)
        if isinstance(raw_value, datetime):
            return raw_value.timestamp()
        if isinstance(raw_value, str):
            try:
                return datetime.fromisoformat(raw_value.replace("Z", "+00:00")).timestamp()
            except ValueError:
                return None
        return None

    async def _route_company_suspend_reply_if_pending(
        self,
        *,
        task_id: str,
        content: str,
        session_id: str | None,
        task: Any | None,
        attachment_refs: list[dict] | None,
        message_metadata: dict[str, Any] | None,
        user_message_id: str | None,
        user_message_created_at: float | None,
        run_engine: Any,
        run_project_id: str,
    ) -> bool:
        """Route text after company Stop without waiting on the parent task lock.

        A live company run can still hold the parent session lock while Stop is
        finalizing or already suspended. Plain text after Stop must reach the
        engine's company-runtime suspend checkpoint immediately so the
        CEO/final-decider can arbitrate with edit/delete/delegate tools. The
        Continue button uses ``session_resume`` and keeps the original forced
        resume path.
        """
        explicit_checkpoint_type = str((message_metadata or {}).get("response_to_checkpoint_type", "") or "").strip()
        explicit_runtime_handoff = (
            explicit_checkpoint_type in COMPANY_RUNTIME_CHECKPOINT_TYPES
        )
        if explicit_checkpoint_type and not explicit_runtime_handoff:
            return False
        if task is None:
            return False
        explicit_checkpoint_id = str(
            (message_metadata or {}).get("response_to_checkpoint_id", "") or ""
        ).strip()

        async def reject(reason: str, content: str) -> bool:
            if self._chat_store_is_ready(self.chat_store):
                try:
                    helper = await self.chat_store.insert_message(
                        channel_id=f"session:{task_id}",
                        sender="assistant",
                        sender_name=STORED_SPEAKER,
                        content=content,
                        project_id=run_project_id,
                        metadata={"type": "system", "reason": reason},
                    )
                    await self.broadcast({"type": "session_message", "payload": helper})
                except Exception:
                    logger.opt(exception=True).debug(
                        "failed to emit company runtime handoff rejection"
                    )
            return True

        if explicit_runtime_handoff and not explicit_checkpoint_id:
            return await reject(
                "missing_runtime_checkpoint_id",
                "This Continue request has no runtime checkpoint identity. Refresh the session and try again.",
            )

        try:
            base_target = await self._resolve_company_runtime_target(
                task_id,
                engine=run_engine,
            )
        except Exception:
            logger.opt(exception=True).debug("failed to resolve company suspend reply target")
            base_target = None
        if base_target is None:
            if explicit_runtime_handoff or is_company_runtime_task(task):
                return await reject(
                    "company_runtime_identity_mismatch",
                    "This message no longer matches an active company runtime. Refresh the session before retrying.",
                )
            return False

        target = base_target
        if explicit_checkpoint_id:
            try:
                target = await self._resolve_company_runtime_target(
                    task_id,
                    engine=run_engine,
                    checkpoint_id=explicit_checkpoint_id,
                )
            except Exception:
                logger.opt(exception=True).debug(
                    "failed to resolve explicit company runtime checkpoint"
                )
                target = None
            if target is None:
                if explicit_runtime_handoff or base_target.get("checkpoint") is not None:
                    return await reject(
                        "company_runtime_identity_mismatch",
                        "This runtime checkpoint does not match the current company session. Refresh before retrying.",
                    )
                return False

        runtime_session_id = str(target.get("runtime_session_id", "") or "").strip()
        if not runtime_session_id:
            return await reject(
                "company_runtime_identity_mismatch",
                "The active company runtime has no canonical session identity. Refresh before retrying.",
            )

        finalizer = self._company_stop_finalize_tasks.get(runtime_session_id)
        if finalizer is not None and not finalizer.done():
            try:
                await asyncio.wait_for(asyncio.shield(finalizer), timeout=10.0)
            except asyncio.TimeoutError:
                helper = await self.chat_store.insert_message(
                    channel_id=f"session:{task_id}",
                    sender="assistant",
                    sender_name=STORED_SPEAKER,
                    content="Stop is still finalizing. Send your update again after the runtime reaches Suspended.",
                    project_id=run_project_id,
                    metadata={"type": "system", "reason": "company_stop_finalize_in_progress"},
                )
                await self.broadcast({"type": "session_message", "payload": helper})
                return True
            except Exception:
                logger.opt(exception=True).debug("company stop finalizer failed before follow-up routing")

            # Stop finalization may have created the checkpoint after the first
            # index load.  Reload durable identity before deciding whether this
            # message is an ordinary turn.
            try:
                target = await self._resolve_company_runtime_target(
                    task_id,
                    engine=run_engine,
                    checkpoint_id=explicit_checkpoint_id,
                )
            except Exception:
                logger.opt(exception=True).debug(
                    "failed to reload company runtime identity after stop finalization"
                )
                target = None
            if target is None:
                return await reject(
                    "company_runtime_identity_mismatch",
                    "The stopped runtime could not be matched to this session. Refresh before retrying.",
                )

        checkpoint = target.get("checkpoint")
        if checkpoint is None:
            if explicit_runtime_handoff:
                return await reject(
                    "company_runtime_checkpoint_not_found",
                    "This company runtime checkpoint is no longer active. Refresh before retrying.",
                )
            return False
        checkpoint_type = str(
            getattr(checkpoint, "checkpoint_type", "") or ""
        ).strip()
        if checkpoint_type not in COMPANY_RUNTIME_CHECKPOINT_TYPES:
            # This router owns only Stop/Continue runtime handoffs.  A completed
            # delivery-feedback (or any other ordinary interaction) may remain
            # the latest durable checkpoint after the company run ends; it must
            # not capture and reject the next normal conversation turn.
            return False
        checkpoint_status = str(
            getattr(checkpoint, "status", "") or ""
        ).strip().lower()
        if checkpoint_status != "pending":
            return await reject(
                "company_runtime_checkpoint_not_pending",
                (
                    "This company runtime is already being resumed. Wait for the current handoff to finish."
                    if checkpoint_status == "resuming"
                    else "This company runtime checkpoint is no longer pending. Refresh before retrying."
                ),
            )

        lock = self._company_suspend_reply_locks.get(runtime_session_id)
        if lock is not None:
            self._release_current_execution_handoff()
            return await reject(
                "checkpoint_handoff_in_progress",
                "This company runtime is already being resumed by another request.",
            )
        lock = asyncio.Lock()
        self._company_suspend_reply_locks[runtime_session_id] = lock

        try:
            bg = self._track_session(
                task_id,
                self._process_company_suspend_reply(
                    ui_task_id=task_id,
                    runtime_session_id=runtime_session_id,
                    content=content,
                    attachment_refs=attachment_refs,
                    message_metadata=message_metadata,
                    user_message_id=user_message_id,
                    user_message_created_at=user_message_created_at,
                    run_engine=run_engine,
                    run_project_id=run_project_id,
                    target=target,
                    checkpoint=checkpoint,
                    lock=lock,
                ),
                project_id=run_project_id,
                engine=run_engine,
            )
        except BaseException:
            self._company_suspend_reply_locks.pop(runtime_session_id, None)
            raise
        self._task_bg_context[bg]["company_suspend_reply"] = True
        return True

    async def _process_company_suspend_reply(
        self,
        *,
        ui_task_id: str,
        runtime_session_id: str,
        content: str,
        attachment_refs: list[dict] | None,
        message_metadata: dict[str, Any] | None,
        user_message_id: str | None,
        user_message_created_at: float | None,
        run_engine: Any,
        run_project_id: str,
        target: dict[str, Any],
        checkpoint: Any,
        lock: asyncio.Lock,
    ) -> None:
        channel_id = f"session:{ui_task_id}"
        pid = self._normalize_project_id(run_project_id or getattr(run_engine, "project_id", None))
        async with lock:
            try:
                config_task = target.get("config_task")
                session_exec_mode = self._normalize_session_exec_mode(self._exec_mode)
                session_company_profile = self._normalize_session_company_profile(self._company_profile)
                session_org_id = ""
                if config_task is not None:
                    session_exec_mode, session_company_profile = self._resolve_task_session_config(config_task)
                    session_org_id = self._resolve_task_org_id(config_task)
                engine_mode, company_profile = self._resolve_engine_mode(
                    session_exec_mode,
                    session_company_profile,
                )
                if engine_mode == "org" and not session_org_id:
                    raise ServiceError(
                        "org_id_required",
                        "org_id_required",
                        {
                            "project_id": pid,
                            "task_id": str(target.get("config_source_task_id", "") or "").strip(),
                        },
                    )

                try:
                    await self._set_company_runtime_control(
                        target,
                        state="resuming",
                        checkpoint_id=str(
                            getattr(checkpoint, "checkpoint_id", "") or ""
                        ).strip(),
                    )
                except Exception:
                    logger.opt(exception=True).debug("failed to broadcast company suspend reply routing state")

                engine_message_metadata = dict(message_metadata or {})
                engine_message_metadata.update({
                    "response_to_checkpoint_id": str(getattr(checkpoint, "checkpoint_id", "") or ""),
                    "response_to_checkpoint_type": str(getattr(checkpoint, "checkpoint_type", "") or ""),
                })
                engine_message_metadata.update(_ui_message_identity_metadata(
                    message_id=user_message_id,
                    conversation_turn_id=_ui_conversation_turn_id(user_message_id),
                    created_at=user_message_created_at,
                ))
                execution_anchor_task_id = str(
                    target.get("ui_anchor_task_id", "") or ""
                ).strip()
                if execution_anchor_task_id:
                    self._active_runtime_children[execution_anchor_task_id] = execution_anchor_task_id
                self._session_to_task[runtime_session_id] = (
                    execution_anchor_task_id or ui_task_id
                )
                resolved_preferred_agent = (
                    self._resolve_task_preferred_agent(config_task)
                    if config_task is not None
                    else self._task_preferred_agent
                )
                await run_engine.process_message(
                    content,
                    project_id=pid,
                    session_id=runtime_session_id,
                    mode=engine_mode,
                    org_id=session_org_id or None,
                    company_profile=company_profile,
                    preferred_agent=(
                        resolved_preferred_agent
                        if resolved_preferred_agent != "native"
                        else None
                    ),
                    origin_task_id=execution_anchor_task_id or None,
                    attachment_refs=attachment_refs,
                    message_metadata=engine_message_metadata or None,
                )
                await self._sync_task_transcript_messages(
                    ui_task_id,
                    engine=run_engine,
                )
                for card in await self._visible_owner_interaction_cards(
                    engine=run_engine,
                    project_id=pid,
                    requester_task_id=ui_task_id,
                    requester_session_id=runtime_session_id,
                ):
                    await self.broadcast({"type": "session_message", "payload": card})
                # Replace the optimistic ``resuming`` projection with the
                # checkpoint state committed by the engine.  Successful and
                # already-consumed handoffs need the same durable refresh as
                # failed handoffs so every client converges on snapshot state.
                try:
                    await self.on_kanban_changed(engine=run_engine)
                except Exception:
                    logger.opt(exception=True).debug(
                        "failed to refresh company runtime control after handoff"
                    )
            except asyncio.CancelledError:
                raise
            except Exception as exc:
                if self._is_expected_shutdown_error(exc) or self._is_closed_database_error(exc):
                    logger.debug(
                        "Company suspend reply skipped during shutdown/closed store: {}: {}",
                        type(exc).__name__,
                        exc,
                    )
                else:
                    logger.exception("Company suspend reply processing error: {}", exc)
                    if self._chat_store_is_ready(self.chat_store):
                        try:
                            msg = await self.chat_store.insert_message(
                                channel_id=channel_id,
                                sender="system",
                                sender_name=STORED_SPEAKER,
                                content=f"Error: {exc}",
                                project_id=pid,
                            )
                            await self.broadcast({"type": "session_message", "payload": msg})
                        except Exception as chat_exc:
                            if self._is_expected_shutdown_error(chat_exc) or self._is_closed_database_error(chat_exc):
                                logger.debug(
                                    "Skipped company suspend reply error message during shutdown/closed store: {}: {}",
                                    type(chat_exc).__name__,
                                    chat_exc,
                                )
                            else:
                                logger.opt(exception=True).debug(
                                    "Failed to write company suspend reply error message",
                                )
                    # The engine restores a failed handoff checkpoint to
                    # pending.  Replace the optimistic ``resuming`` projection
                    # for every client with that durable state immediately.
                    await self.on_kanban_changed(engine=run_engine)
            finally:
                if self._chat_store_is_ready(self.chat_store):
                    await self._flush_progress(ui_task_id, project_id=pid)
                self._task_bg_context.pop(asyncio.current_task(), None)
                self._company_suspend_reply_locks.pop(runtime_session_id, None)

    def _resolve_task_comms_dir(self, task: Any) -> Path | None:
        """Resolve `<workspace>/.ampuly-comms/<project>/<session>` for a task.

        Returns None when the task lacks enough metadata to locate its
        on-disk comms tree (e.g. workspace never resolved, no session id).
        """
        md = task.metadata or {}
        workspace_root = (
            str(md.get("comms_workspace_root") or "").strip()
            or str(md.get("target_output_dir") or "").strip()
            or str(md.get("setup_workspace_prepared") or "").strip()
        )
        comms_root = str(md.get("comms_root") or "").strip()
        session_id = (
            str(getattr(task, "parent_session_id", "") or "").strip()
            or str(getattr(task, "session_id", "") or "").strip()
        )
        project_id = (
            str(getattr(task, "project_id", "") or "").strip()
            or self.engine.project_id
            or "default"
        )
        if not session_id:
            return None
        try:
            from ampuly.layer2_organization import comms as _comms
            if workspace_root:
                return _comms.resolve_layout(workspace_root, project_id, session_id).root
            if comms_root:
                # comms_root is `<ws>/.ampuly-comms`; its parent is workspace_root.
                inferred_ws = str(Path(comms_root).parent)
                return _comms.resolve_layout(inferred_ws, project_id, session_id).root
        except Exception:
            logger.opt(exception=True).debug(f"_resolve_task_comms_dir failed for task {getattr(task, 'id', '?')}")
        return None

    async def _handle_session_delete(self, ws: Any, data: dict) -> None:
        """Delete task/session data and notify frontend."""
        task_id = data.get("task_id", "")
        if not task_id:
            return
        try:
            _engine, project_id = await self._engine_for_request(data)
            result = await self._ensure_office_services().session.delete(project_id=project_id, task_id=task_id)
            self._session_to_task.update(self.services_context.session_to_task)
            await self._publish_service_result(result)
            await self._send_ack(ws, ok=True, project_id=project_id)
        except ServiceError as exc:
            await self._send_service_error(ws, exc, action="session_delete")

    async def _handle_session_complete(self, ws: Any, data: dict) -> None:
        """Mark a session's task as DONE (user explicitly completes it)."""
        task_id = data.get("task_id", "")
        if not task_id:
            return
        try:
            _engine, project_id = await self._engine_for_request(data)
            result = await self._ensure_office_services().session.complete(project_id=project_id, task_id=task_id)
            await self._publish_service_result(result)
            await self._send_ack(ws, ok=True, project_id=project_id)
        except ServiceError as exc:
            await self._send_service_error(ws, exc, action="session_complete")

    async def _handle_session_update_title(self, ws: Any, data: dict) -> None:
        """Update session/task title."""
        task_id = data.get("task_id", "")
        title = data.get("title", "")
        if not task_id or not title:
            return
        try:
            _engine, project_id = await self._engine_for_request(data)
            result = await self._ensure_office_services().session.rename(
                project_id=project_id,
                task_id=task_id,
                title=title,
            )
            await self._publish_service_result(result)
        except ServiceError as exc:
            await self._send_service_error(ws, exc, action="session_update_title")

    async def _dispatch_session_message(
        self, task_id: str, content: str, *, session_id: str | None = None,
        attachment_refs: list[dict] | None = None,
        message_metadata: dict[str, Any] | None = None,
        user_message_id: str | None = None,
        user_message_created_at: float | None = None,
        run_engine: Any | None = None,
        run_project_id: str | None = None,
    ) -> None:
        """Route through Dispatcher: classify → engine pipeline or direct reply."""
        captured_context = run_engine is not None or run_project_id is not None
        engine = run_engine or self.engine
        pid = self._normalize_project_id(run_project_id or getattr(engine, "project_id", None))
        channel_id = f"session:{task_id}"
        dispatcher = self.dispatcher if engine is self.engine else Dispatcher(engine, self.chat_store)
        try:
            result = await dispatcher.handle(
                task_id,
                content,
                session_id=session_id,
                has_attachments=bool(attachment_refs),
            )
            if result.route == "engine":
                process_kwargs: dict[str, Any] = {
                    "session_id": session_id,
                    "attachment_refs": attachment_refs,
                }
                if message_metadata:
                    process_kwargs["message_metadata"] = message_metadata
                if user_message_id:
                    process_kwargs["user_message_id"] = user_message_id
                if user_message_created_at is not None:
                    process_kwargs["user_message_created_at"] = user_message_created_at
                if captured_context:
                    process_kwargs["run_engine"] = engine
                    process_kwargs["run_project_id"] = pid
                await self._process_session_message(task_id, content, **process_kwargs)
            else:
                # Direct reply from Dispatcher (status query, conversation, session control)
                msg = await self.chat_store.insert_message(
                    channel_id=channel_id,
                    sender="assistant",
                    sender_name=STORED_SPEAKER,
                    content=result.response,
                    project_id=pid,
                )
                await self.broadcast({"type": "session_message", "payload": msg})
                # Record exchange in engine memory for context continuity
                if engine.memory and session_id:
                    user_turn_meta = _ui_message_identity_metadata(
                        kind="top_level_user_turn",
                        message_id=user_message_id,
                        conversation_turn_id=_ui_conversation_turn_id(user_message_id),
                        created_at=user_message_created_at,
                    )
                    await engine.memory.record_user_turn(
                        session_id, content,
                        project_id=pid,
                        metadata=user_turn_meta or None,
                    )
                    assistant_turn_meta = _ui_message_identity_metadata(
                        kind="top_level_reply",
                        message_id=str(msg.get("message_id") or "").strip() or None,
                        created_at=float(msg.get("created_at")) if msg.get("created_at") is not None else None,
                    )
                    await engine.memory.record_assistant_turn(
                        session_id, result.response,
                        project_id=pid,
                        metadata=assistant_turn_meta or None,
                    )
        except Exception as e:
            logger.opt(exception=True).error(f"Dispatcher error, falling back to engine: {e}")
            process_kwargs = {
                "session_id": session_id,
                "attachment_refs": attachment_refs,
            }
            if message_metadata:
                process_kwargs["message_metadata"] = message_metadata
            if user_message_id:
                process_kwargs["user_message_id"] = user_message_id
            if user_message_created_at is not None:
                process_kwargs["user_message_created_at"] = user_message_created_at
            if captured_context:
                process_kwargs["run_engine"] = engine
                process_kwargs["run_project_id"] = pid
            await self._process_session_message(task_id, content, **process_kwargs)

    async def _execution_checkpoint_status(
        self,
        *,
        engine: Any,
        project_id: str,
        checkpoint_id: str,
        checkpoint_type: str | None = None,
    ) -> str:
        normalized_checkpoint_id = str(checkpoint_id or "").strip()
        normalized_checkpoint_type = str(checkpoint_type or "").strip()
        if not normalized_checkpoint_id:
            return ""
        direct_lookup = getattr(engine, "_load_execution_checkpoint_by_id", None)
        checkpoint = None
        if callable(direct_lookup):
            try:
                checkpoint = await direct_lookup(normalized_checkpoint_id)
            except Exception:
                logger.opt(exception=True).debug("failed to load checkpoint by id from engine")
        if checkpoint is None:
            store = getattr(engine, "store", None)
            getter = getattr(store, "get_execution_checkpoints", None)
            if callable(getter):
                try:
                    checkpoints = await getter(project_id=project_id)
                except TypeError:
                    checkpoints = await getter(project_id)
                for item in checkpoints:
                    if str(getattr(item, "checkpoint_id", "") or "").strip() == normalized_checkpoint_id:
                        checkpoint = item
                        break
        if checkpoint is None:
            return ""
        if normalized_checkpoint_type and str(getattr(checkpoint, "checkpoint_type", "") or "").strip() != normalized_checkpoint_type:
            return ""
        return str(getattr(checkpoint, "status", "") or "").strip().lower()

    async def _process_session_message(
        self, task_id: str, content: str, *,
        session_id: str | None = None,
        attachment_refs: list[dict] | None = None,
        message_metadata: dict[str, Any] | None = None,
        user_message_id: str | None = None,
        user_message_created_at: float | None = None,
        run_engine: Any | None = None,
        run_project_id: str | None = None,
        creation_source_task_id: str | None = None,
        _first_owned_source_handoff_sink: object = None,
    ) -> None:
        """Process user message in session context via engine.

        Passes session_id to engine.process_message so the engine can:
        - Record user/assistant turns to session memory
        - Build session-aware context for agent execution

        Temporarily overrides engine.on_progress so that all progress
        during this call routes to session:{task_id}.
        """
        creation_source_kwargs = {}
        source_handoff_complete = False
        source_primary = None
        if creation_source_task_id is not None or _first_owned_source_handoff_sink is not None:
            from ampuly.layer0_interaction.message_bus import (
                _validate_creation_source_task_id, _validate_first_owned_source_handoff_sink,
            )
            from ampuly.core.models import Task, TaskStatus
            _validate_creation_source_task_id(creation_source_task_id)
            _validate_first_owned_source_handoff_sink(_first_owned_source_handoff_sink)
            from ampuly.database.source_project_scope import validate_source_project
            validate_source_project(run_project_id)
            if (
                type(task_id) is not str or task_id != creation_source_task_id
                or type(run_project_id) is not str
                or type(session_id) is not str or not session_id
            ):
                raise RuntimeError("source launch handoff unavailable") from None

            def notify_source_handoff(fact, observation) -> None:
                nonlocal source_handoff_complete
                if source_handoff_complete:
                    raise RuntimeError("source launch handoff unavailable") from None
                if _first_owned_source_handoff_sink(fact, observation) is not None:
                    raise RuntimeError("source launch handoff unavailable") from None
                source_handoff_complete = True
                # Presentation mapping only after the original durable source receiver accepts.
                self._session_to_task[session_id] = task_id

            creation_source_kwargs = {
                "creation_source_task_id": creation_source_task_id,
                "_first_owned_source_handoff_sink": notify_source_handoff,
            }
        engine = run_engine or self.engine
        pid = self._normalize_project_id(run_project_id or getattr(engine, "project_id", None))
        channel_id = f"session:{task_id}"
        if creation_source_task_id is not None and (
            pid != run_project_id or not self._store_is_ready(engine.store)
        ):
            raise RuntimeError("source launch handoff unavailable") from None

        # Register session→task mapping for company runtime child resolution
        if session_id and creation_source_task_id is None:
            self._session_to_task[session_id] = task_id

        session_exec_mode = self._normalize_session_exec_mode(self._exec_mode)
        session_company_profile = self._normalize_session_company_profile(self._company_profile)
        session_preferred_agent = self._task_preferred_agent
        session_org_id = ""
        task = None
        config_task = None
        store = engine.store
        if self._store_is_ready(store):
            from ampuly.core.models import TaskStatus
            task = await store.get_task(task_id)
            if creation_source_task_id is not None and (
                type(task) is not Task
                or any(type(value) is not str for value in (task.id, task.project_id, task.session_id))
                or task.id != task_id or task.project_id != pid
                or task.session_id != session_id or task.status is not TaskStatus.PENDING
            ):
                raise RuntimeError("source launch handoff unavailable") from None
            if task:
                # This coroutine usually runs as a fire-and-forget background
                # task (_track_session), where a raised ServiceError is only
                # logged and the user's message silently vanishes. Fail closed
                # with a visible chat error instead of raising.
                try:
                    config_task = await self._resolve_session_runtime_config_task(
                        task_id,
                        task,
                        engine=engine,
                    )
                    session_exec_mode, session_company_profile = self._resolve_task_session_config(
                        config_task
                    )
                    session_org_id = self._resolve_task_org_id(config_task)
                    session_preferred_agent = self._resolve_task_preferred_agent(config_task)
                    if (
                        session_exec_mode in {"org", "custom"}
                        and not session_org_id
                        and is_company_runtime_task(task)
                    ):
                        raise ServiceError(
                            "org_id_required",
                            "org_id_required",
                            {"project_id": pid, "task_id": task_id},
                        )
                except ServiceError as exc:
                    if creation_source_task_id is not None:
                        raise
                    logger.warning(
                        f"Session message for task {task_id} rejected during "
                        f"runtime identity resolution: {exc.code}"
                    )
                    try:
                        msg = await self.chat_store.insert_message(
                            channel_id=channel_id,
                            sender="system",
                            sender_name=STORED_SPEAKER,
                            content=f"Error: {exc.message}",
                            project_id=pid,
                        )
                        await self.broadcast({"type": "session_message", "payload": msg})
                    except Exception:
                        logger.opt(exception=True).debug(
                            "failed to surface session identity error"
                        )
                    return

        # Per-task lock: same session serialized, different sessions concurrent
        source_lock = WSHandler._source_task_lock_for(self, task_id)
        if creation_source_task_id is not None:
            source_lock = WSHandler._mark_source_task_lock(self, task_id)
        async with WSHandler._task_lock_context(self, task_id):
            current_task = asyncio.current_task()
            if current_task is not None:
                self._task_lock_holders[task_id] = current_task
            if self._store_is_ready(store):
                from ampuly.core.models import TaskStatus
                task = await store.get_task(task_id)
                if creation_source_task_id is not None and (
                    type(task) is not Task
                    or any(type(value) is not str for value in (task.id, task.project_id, task.session_id))
                    or task.id != task_id or task.project_id != pid
                    or task.session_id != session_id or task.status is not TaskStatus.PENDING
                ):
                    raise RuntimeError("source launch handoff unavailable") from None
                if task:
                    config_task = await self._resolve_session_runtime_config_task(
                        task_id,
                        task,
                        engine=engine,
                    )
                    session_exec_mode, session_company_profile = self._resolve_task_session_config(
                        config_task
                    )
                    session_org_id = self._resolve_task_org_id(config_task)
                    session_preferred_agent = self._resolve_task_preferred_agent(config_task)
                    if (
                        session_exec_mode in {"org", "custom"}
                        and not session_org_id
                        and is_company_runtime_task(task)
                    ):
                        raise ServiceError(
                            "org_id_required",
                            "org_id_required",
                            {"project_id": pid, "task_id": task_id},
                        )
                    if task.status == TaskStatus.DONE and self._is_company_session_exec_mode(session_exec_mode):
                        task.status = TaskStatus.IDLE
                        task.metadata = dict(getattr(task, "metadata", {}) or {})
                        task.metadata["company_session_reopened_at"] = datetime.now().isoformat()
                        await store.save_task(task)
                    await apply_task_status_transition(
                        store,
                        task,
                        target_status_or_phase=TaskStatus.RUNNING,
                        reason="session_message_started",
                    )
            # The order moves first: the page asks for its order list when it sees the run move.
            await self._follow_order_run(task_id, "running", project_id=pid)
            await self.broadcast({"type": "board_task_status_changed", "payload": {
                "project_id": pid, "task_id": task_id, "column_id": "in-progress", "status": "running",
            }})
            terminal_board_broadcast_sent = False
            # Register company runtime origin so child-task progress can dual-route
            company_runtime_target: dict[str, Any] | None = None
            if session_exec_mode in ("company", "org", "custom"):
                self._active_runtime_children[task_id] = task_id  # primary maps to self
                try:
                    company_runtime_target = await self._resolve_company_runtime_target(task_id, engine=engine)
                    await self._set_company_runtime_control(company_runtime_target, state="running")
                except Exception:
                    logger.opt(exception=True).debug("failed to mark company session runtime running")
            try:
                if creation_source_task_id is not None:
                    self._session_to_task[session_id] = task_id
                if config_task is not None and not str(
                    (getattr(config_task, "metadata", {}) or {}).get(
                        "native_approval_level", ""
                    )
                    or ""
                ).strip():
                    session_service = self._ensure_office_services().session
                    await session_service.persist_native_permission_config(
                        config_task,
                        level=session_service.resolve_task_native_approval_level(
                            config_task,
                            engine,
                        ),
                        engine=engine,
                    )
                config_task_id = str(getattr(config_task, "id", "") or "").strip()
                selected_task_id = str(getattr(task, "id", "") or "").strip()
                should_persist_selected_config = bool(
                    task is not None
                    and (
                        not config_task_id
                        or config_task_id == selected_task_id
                        or (session_exec_mode == "org" and not session_org_id)
                    )
                )
                if should_persist_selected_config:
                    await self._persist_session_config(
                        task,
                        exec_mode=session_exec_mode,
                        company_profile=session_company_profile,
                        preferred_agent=session_preferred_agent,
                        org_id=session_org_id,
                        engine=engine,
                    )
                    persisted_identity = self._resolve_task_identity(
                        task,
                        default_exec_mode=session_exec_mode,
                        default_company_profile=session_company_profile,
                        default_preferred_agent=session_preferred_agent,
                        default_org_id=session_org_id,
                    )
                    session_exec_mode = persisted_identity.exec_mode
                    session_company_profile = persisted_identity.company_profile
                    session_preferred_agent = persisted_identity.preferred_agent
                    session_org_id = persisted_identity.org_id
                engine_mode, company_profile = self._resolve_engine_mode(
                    session_exec_mode,
                    session_company_profile,
                )
                engine_preferred_agent = (
                    session_preferred_agent
                    if session_exec_mode == "task" or session_preferred_agent != "native"
                    else None
                )
                engine_message_metadata = dict(message_metadata or {})
                engine_message_metadata.update(_ui_message_identity_metadata(
                    message_id=user_message_id,
                    conversation_turn_id=_ui_conversation_turn_id(user_message_id),
                    created_at=user_message_created_at,
                ))
                # Permission state is server-owned and session-scoped.  Never
                # let an omitted or client-supplied value fall back to the
                # mutable system default for an existing session.
                engine_message_metadata.update(
                    self._ensure_office_services().session.resolve_task_native_permission_config(
                        config_task or task,
                        engine,
                    )
                )
                await engine.process_message(
                    content,
                    project_id=pid,
                    session_id=session_id,
                    mode=engine_mode,
                    org_id=session_org_id or None,
                    company_profile=company_profile,
                    preferred_agent=engine_preferred_agent,
                    origin_task_id=task_id,
                    attachment_refs=attachment_refs,
                    message_metadata=engine_message_metadata or None,
                    **creation_source_kwargs,
                )
                if creation_source_task_id is not None and not source_handoff_complete:
                    raise RuntimeError("source launch handoff outcome unknown") from None
                await self._sync_task_transcript_messages(
                    task_id,
                    engine=engine,
                )
                for card in await self._visible_owner_interaction_cards(
                    engine=engine,
                    project_id=pid,
                    requester_task_id=task_id,
                    requester_session_id=session_id,
                ):
                    await self.broadcast({"type": "session_message", "payload": card})
                await self._ensure_reply_projected(
                    channel_id=channel_id,
                    project_id=pid,
                    session_id=session_id or (str(getattr(task, "session_id", "") or "").strip() if task else None),
                    engine=engine,
                )

                # ── Status: idle only while the engine left the task active ──
                store = engine.store
                final_status = "idle"
                final_column_id = "in-progress"
                if self._store_is_ready(store):
                    from ampuly.core.models import TaskStatus as TS
                    t = await store.get_task(task_id)
                    if t:
                        try:
                            current_status = t.status if isinstance(t.status, TS) else TS(str(t.status))
                        except ValueError:
                            current_status = TS.IDLE
                        if current_status in {TS.PENDING, TS.RUNNING}:
                            t.status = TS.IDLE
                            await store.save_task(t)
                            current_status = TS.IDLE
                        final_status = current_status.value
                        if current_status in {TS.DONE, TS.CANCELLED}:
                            final_column_id = "done"
                await self._follow_order_run(task_id, final_status, project_id=pid)
                await self.broadcast({"type": "board_task_status_changed", "payload": {
                    "project_id": pid, "task_id": task_id, "column_id": final_column_id, "status": final_status,
                }})
                terminal_board_broadcast_sent = True
                if session_exec_mode in ("company", "org", "custom"):
                    try:
                        idle_target = await self._resolve_company_runtime_target(task_id, engine=engine)
                        await self._set_company_runtime_control(idle_target or company_runtime_target, state="idle")
                    except Exception:
                        logger.opt(exception=True).debug("failed to mark company session runtime idle")
            except asyncio.CancelledError as error:
                if creation_source_task_id is not None or source_lock is not None:
                    source_primary = error
                raise
            except Exception as e:
                if creation_source_task_id is not None and not source_handoff_complete:
                    source_primary = e
                    raise
                logger.exception(f"Session processing error: {e}")
                msg = await self.chat_store.insert_message(
                    channel_id=channel_id,
                    sender="system",
                    sender_name=STORED_SPEAKER,
                    content=f"Error: {e}",
                    project_id=pid,
                )
                await self.broadcast({"type": "session_message", "payload": msg})

                # ── Status: failed ─────────────────────────────────────
                store = engine.store
                if self._store_is_ready(store):
                    from ampuly.core.models import TaskStatus as TS
                    t = await store.get_task(task_id)
                    if t and (creation_source_task_id is None or t.status is not TS.DONE):
                        t.status = TS.FAILED
                        await store.save_task(t)
                await self.broadcast({"type": "board_task_status_changed", "payload": {
                    "project_id": pid, "task_id": task_id, "column_id": "in-progress", "status": "failed",
                }})
                terminal_board_broadcast_sent = True
                if session_exec_mode in ("company", "org", "custom"):
                    try:
                        failed_target = await self._resolve_company_runtime_target(task_id, engine=engine)
                        await self._set_company_runtime_control(failed_target or company_runtime_target, state="idle")
                    except Exception:
                        logger.opt(exception=True).debug("failed to clear company session runtime after error")
            except BaseException as error:
                if creation_source_task_id is not None or source_lock is not None:
                    source_primary = error
                raise
            finally:
                try:
                    # Flush progress buffers before clearing company runtime mappings
                    child_ids = [k for k, v in self._active_runtime_children.items() if v == task_id and k != task_id]
                    for cid in child_ids:
                        await self._flush_progress(cid, project_id=pid)
                    await self._flush_progress(task_id, project_id=pid)
                    # Clean up per-task state
                    self._active_runtime_children.pop(task_id, None)
                    for k in child_ids:
                        self._active_runtime_children.pop(k, None)
                        self._stop_requested_task_ids.discard(k)
                    retained_source_lock = WSHandler._source_task_lock_for(self, task_id)
                    if source_lock is None and retained_source_lock is None:
                        self._task_locks.pop(task_id, None)
                        self._task_lock_holders.pop(task_id, None)
                    elif self._task_lock_holders.get(task_id) is current_task:
                        self._task_lock_holders.pop(task_id, None)
                    self._stop_requested_task_ids.discard(task_id)
                    if session_id:
                        self._session_to_task.pop(session_id, None)
                    if not terminal_board_broadcast_sent:
                        # A cancelled run (or a failure inside the failure handler)
                        # never reaches the terminal broadcasts above, leaving the
                        # board stuck on "running" until a full refresh. Mirror the
                        # persisted status best-effort; never write engine state here.
                        try:
                            store = engine.store
                            if self._store_is_ready(store):
                                t = await store.get_task(task_id)
                                if t is not None:
                                    status_val = t.status.value if hasattr(t.status, "value") else str(t.status)
                                    await self.broadcast({"type": "board_task_status_changed", "payload": {
                                        "project_id": pid,
                                        "task_id": task_id,
                                        "column_id": "done" if status_val in ("done", "cancelled") else "in-progress",
                                        "status": status_val,
                                    }})
                        except Exception:
                            logger.opt(exception=True).debug("failed to mirror terminal board status")
                    # Clear agent runtime indicator — include agent_id so the
                    # frontend can also clear the swarm agent's reflecting/tool_active state.
                    idle_payload: dict[str, Any] = {
                        "project_id": pid,
                        "task_id": task_id, "status": "idle", "current_tool": None, "iteration": 0,
                    }
                    resolved_agent = self._resolve_agent_for_idle(task_id, task)
                    if resolved_agent:
                        idle_payload["agent_id"] = resolved_agent
                    await self.broadcast({"type": "agent_runtime_update", "payload": idle_payload})
                except BaseException:
                    if source_primary is None:
                        raise

    # ── Checkpoint metadata extraction ──────────────────────────────────

    async def _interaction_checkpoint_presentation_task_id(
        self,
        checkpoint: Any | None,
        *,
        engine: Any,
    ) -> str:
        """Choose a UI host without changing the checkpoint's owner actor."""

        actor_task_id, actor_session_id = (
            owner_interaction_actor_identity(checkpoint)
        )
        if actor_task_id:
            return actor_task_id
        if not actor_session_id:
            return ""
        store = getattr(engine, "store", None)
        if not self._store_is_ready(store):
            return ""
        try:
            # Read once per request inside a read scope; loaded as before outside one.
            identity_index = await _request_identity_index(
                store,
                str(getattr(checkpoint, "project_id", "") or "default").strip()
                or "default",
            )
            identity = identity_index.resolve(runtime_session_id=actor_session_id)
        except Exception:
            logger.opt(exception=True).debug(
                "failed to resolve owner interaction presentation task"
            )
            return ""
        if identity is None:
            return ""
        # Rootless company runtimes have no ui_anchor_task_id.  Their canonical
        # config Task is a presentation host only; the actor metadata below
        # deliberately remains taskless/root-session-owned.
        return str(
            identity.ui_anchor_task_id or identity.config_source_task_id or ""
        ).strip()

    async def _build_owner_interaction_meta(
        self,
        checkpoint: Any,
        *,
        engine: Any,
    ) -> dict[str, Any] | None:
        checkpoint_type = str(getattr(checkpoint, "checkpoint_type", "") or "").strip()
        if checkpoint_type not in OWNER_INTERACTION_CHECKPOINT_TYPES:
            return None
        payload = dict(getattr(checkpoint, "payload", {}) or {})
        if not self._owner_interaction_checkpoint_is_projectable(checkpoint):
            return None
        if checkpoint_type in {"tool_permission", "action_permission"}:
            interaction = dict(payload.get("interaction", {}) or {})
            approval = dict(payload.get("approval", {}) or {})
            tool_call = dict(payload.get("tool_call", {}) or {})
            effect = dict(payload.get("effect", {}) or {})
            effect_approval = dict(payload.get("effect_approval", {}) or {})
            raw_effect_result = dict(payload.get("effect_result", {}) or {})
            raw_receipt = dict(raw_effect_result.get("provider_receipt", {}) or {})
            safe_receipt_keys = {
                "provider_message_id", "message_id", "receipt_id", "request_id",
                "chat_id", "destination", "timestamp", "ts", "status", "provider",
                "effect_id", "delivery_status", "read_status", "feedback_status",
                "business_status",
            }
            safe_effect_result = {
                key: value
                for key, value in raw_effect_result.items()
                if key in {
                    "effect_id", "state", "status", "provider", "verification_status",
                    "last_error",
                }
                and isinstance(value, (str, int, float, bool))
            }
            safe_effect_result["provider_receipt"] = {
                key: value
                for key, value in raw_receipt.items()
                if key in safe_receipt_keys
                and isinstance(value, (str, int, float, bool))
            }
            options = [
                {
                    "id": str(option.get("id", "") or "").strip(),
                    "label": str(option.get("label") or option.get("id") or "").strip(),
                    "description": str(option.get("description", "") or "").strip(),
                }
                for option in list(interaction.get("options", []) or [])
                if isinstance(option, dict) and str(option.get("id", "") or "").strip()
            ]
            prompt = str(
                interaction.get("prompt")
                or approval.get("rationale")
                or (
                    f"Authorize tool {tool_call.get('name') or 'action'}?"
                    if checkpoint_type == "tool_permission"
                    else f"Authorize action {approval.get('action_name') or tool_call.get('name') or 'request'}?"
                )
            ).strip()
            return {
                "checkpoint_type": checkpoint_type,
                "checkpoint_id": str(getattr(checkpoint, "checkpoint_id", "") or "").strip(),
                "checkpoint_status": str(getattr(checkpoint, "status", "pending") or "pending").strip(),
                "escalation_type": checkpoint_type,
                "prompt": prompt,
                "summary": str(approval.get("rationale") or prompt).strip(),
                "options": options,
                "default_action": interaction.get("default_action"),
                "tool_call_id": str(tool_call.get("id", "") or "").strip(),
                "tool_name": str(tool_call.get("name", "") or "").strip(),
                # The one argument the chat card words the request by (blockers.py reads the same keys): the place
                # or the command, never the whole argument dict.
                "tool_argument": next(
                    (str(tool_call["arguments"][key])[:160] for key in ("url", "path", "command", "query")
                     if isinstance(tool_call.get("arguments"), dict) and tool_call["arguments"].get(key)),
                    "",
                ),
                "tool_risk_level": str(approval.get("risk_level", "") or "").strip(),
                "action_kind": str(approval.get("action_kind", "") or "").strip(),
                "action_name": str(approval.get("action_name", "") or "").strip(),
                "effect_approval_protocol": str(
                    effect_approval.get("protocol", "") or ""
                ).strip(),
                "effect_id": str(effect.get("effect_id", "") or "").strip(),
                "effect_kind": str(effect.get("kind", "") or "").strip(),
                "effect_provider": str(effect.get("provider", "") or "").strip(),
                "effect_environment": str(
                    effect.get("environment_id", "") or ""
                ).strip(),
                "effect_preview": dict(payload.get("effect_preview", {}) or {}),
                "effect_simulation": dict(
                    payload.get("effect_simulation", {}) or {}
                ),
                "effect_result": safe_effect_result,
                "approval_type": str(
                    approval.get("approval_type", "") or ""
                ).strip(),
            }
        if checkpoint_type == "task_user_input":
            return await self._build_task_user_input_meta(checkpoint, engine=engine)
        if checkpoint_type == "company_work_item_gate":
            return self._build_company_work_item_gate_meta(checkpoint)
        if checkpoint_type == "company_staffing_selection":
            return self._build_staffing_selection_meta(checkpoint, engine=engine)
        if checkpoint_type == "company_recruitment_confirmation":
            return self._build_recruitment_meta(checkpoint, engine=engine)
        if checkpoint_type == "company_reorg_pending":
            return await self._build_reorg_meta(checkpoint, engine=engine)
        if checkpoint_type == "company_delivery_feedback":
            return self._build_delivery_feedback_meta(checkpoint)

        # Routing/failure interactions share the structured-input renderer but
        # retain their real checkpoint_type for engine dispatch.
        interaction = dict(payload.get("interaction", {}) or {})
        prompt = str(
            interaction.get("prompt")
            or payload.get("prompt")
            or payload.get("reason")
            or "Additional input is required to continue."
        ).strip()
        options = [
            {
                "id": str(option.get("id", "") or "").strip(),
                "label": str(option.get("label") or option.get("id") or "").strip(),
                "description": str(option.get("description", "") or "").strip(),
            }
            for option in list(interaction.get("options", payload.get("options", [])) or [])
            if isinstance(option, dict) and str(option.get("id", "") or "").strip()
        ]
        return {
            "checkpoint_type": checkpoint_type,
            "checkpoint_id": str(getattr(checkpoint, "checkpoint_id", "") or "").strip(),
            "checkpoint_status": str(getattr(checkpoint, "status", "pending") or "pending").strip(),
            "work_item_projection_title": (
                {
                    "route_clarification": "需要澄清",
                    "company_runtime_selection": "运行时选择",
                    "company_run_failure_review": "运行失败复盘",
                }.get(checkpoint_type, "需要输入")
                if _ws_is_zh()
                else {
                    "route_clarification": "Clarification Needed",
                    "company_runtime_selection": "Runtime Selection",
                    "company_run_failure_review": "Run Failure Review",
                }.get(checkpoint_type, "Input Needed")
            ),
            "summary": str(payload.get("summary") or payload.get("reason") or prompt).strip(),
            "prompt": prompt,
            "questions": [],
            "input_questions": ([{
                "id": "decision",
                "header": "选择操作" if _ws_is_zh() else "Choose an action",
                "question": prompt,
                "options": options,
                "allow_freeform": True,
                "required": True,
            }] if options else []),
            "required_fields": [],
        }

    @staticmethod
    def _owner_interaction_checkpoint_is_projectable(checkpoint: Any) -> bool:
        """Keep internal manager reviews outside the owner interaction surface."""

        payload = dict(getattr(checkpoint, "payload", {}) or {})
        review_levels = {
            str(container.get("review_level", "") or "").strip().lower()
            for container in (
                payload,
                dict(payload.get("interaction", {}) or {}),
                dict(payload.get("gate", {}) or {}),
                dict(payload.get("approval", {}) or {}),
                dict(payload.get("pause_request", {}) or {}),
            )
        }
        return "manager" not in review_levels

    async def _interaction_checkpoint_ui_message(
        self,
        checkpoint: Any,
        *,
        presentation_task_id: str = "",
        engine: Any,
        project_id: str,
    ) -> dict[str, Any] | None:
        metadata = await self._build_owner_interaction_meta(checkpoint, engine=engine)
        if metadata is None:
            return None
        checkpoint_id = str(getattr(checkpoint, "checkpoint_id", "") or "").strip()
        if not checkpoint_id:
            return None
        status = str(getattr(checkpoint, "status", "pending") or "pending").strip().lower()
        metadata = {
            **metadata,
            "checkpoint_id": checkpoint_id,
            "checkpoint_status": status,
            "source": "execution_checkpoint",
        }
        actor_task_id, actor_session_id = owner_interaction_actor_identity(checkpoint)
        host_task_id = str(presentation_task_id or "").strip()
        if not host_task_id:
            host_task_id = await self._interaction_checkpoint_presentation_task_id(
                checkpoint,
                engine=engine,
            )
        metadata["interaction_requester_task_id"] = actor_task_id
        metadata["interaction_requester_session_id"] = actor_session_id
        channel_id = f"session:{host_task_id}" if host_task_id else f"activity:{project_id}"
        created_at = self._checkpoint_created_timestamp(checkpoint) or time.time()
        content = str(
            metadata.get("prompt")
            or metadata.get("summary")
            or "Action required."
        ).strip() or "Action required."
        return {
            "message_id": f"checkpoint::{checkpoint_id}",
            "channel_id": channel_id,
            "sender": "assistant",
            # Sent as is, never stored: shown as the owner reads it.
            "sender_name": display_speaker(str(
                metadata.get("work_item_projection_title")
                or metadata.get("requesting_role_id")
                or STORED_SPEAKER
            ).strip() or STORED_SPEAKER),
            "content": content,
            "created_at": created_at,
            "reply_to_id": None,
            "mentions": [],
            "metadata": metadata,
            "project_id": project_id,
        }

    async def _visible_owner_interaction_cards(
        self,
        *,
        engine: Any,
        project_id: str,
        requester_task_id: str,
        requester_session_id: str | None,
        checkpoints: list[Any] | None = None,
    ) -> list[dict[str, Any]]:
        if checkpoints is None:
            checkpoints = await self._active_owner_interaction_checkpoints(
                engine=engine,
                project_id=project_id,
            )

        requested_session_id = str(requester_session_id or "").strip()
        requested_task_id = str(requester_task_id or "").strip()
        visible: list[dict[str, Any]] = []
        visibility_check = getattr(engine, "can_answer_checkpoint", None)
        if not callable(visibility_check):
            return []
        # Inside a read request every card is checked against the request's one
        # identity index instead of a fresh project load per card (AV).
        engine_store = getattr(engine, "store", None)
        share_request_index = (
            engine_store is not None
            and current_request_reads() is not None
            and _accepts_keyword(visibility_check, "identity_index")
        )
        request_indexes: dict[str, Any] = {}
        for checkpoint in checkpoints:
            actor_task_id, actor_session_id = (
                owner_interaction_actor_identity(checkpoint)
            )
            if not actor_task_id and not actor_session_id:
                continue
            # The caller's Task can be a UI-only host for a root-session-owned
            # checkpoint.  It selects presentation scope but is never forwarded
            # to the engine as the actor.
            if actor_task_id:
                in_scope = bool(
                    requested_task_id == actor_task_id
                    or (
                        requested_session_id
                        and actor_session_id
                        and requested_session_id == actor_session_id
                    )
                )
            else:
                in_scope = bool(
                    requested_session_id
                    and requested_session_id == actor_session_id
                )
            if not in_scope:
                continue
            try:
                shared_index: dict[str, Any] = {}
                if share_request_index:
                    checkpoint_project_id = (
                        str(getattr(checkpoint, "project_id", "") or "default").strip() or "default"
                    )
                    if checkpoint_project_id not in request_indexes:
                        request_indexes[checkpoint_project_id] = await _request_identity_index(
                            engine_store,
                            checkpoint_project_id,
                        )
                    shared_index["identity_index"] = request_indexes[checkpoint_project_id]
                candidate = visibility_check(
                    checkpoint,
                    requester_task_id=actor_task_id,
                    requester_session_id=actor_session_id or None,
                    **shared_index,
                )
                allowed = bool(await candidate) if inspect.isawaitable(candidate) else bool(candidate)
            except Exception:
                logger.opt(exception=True).debug(
                    "failed owner interaction checkpoint visibility check"
                )
                allowed = False
            if not allowed:
                continue
            presentation_task_id = (
                await self._interaction_checkpoint_presentation_task_id(
                    checkpoint,
                    engine=engine,
                )
            )
            card = await self._interaction_checkpoint_ui_message(
                checkpoint,
                presentation_task_id=presentation_task_id,
                engine=engine,
                project_id=project_id,
            )
            if card is not None:
                visible.append(card)
        return sorted(
            visible,
            key=lambda card: (
                float(card.get("created_at", 0) or 0),
                str(card.get("message_id", "") or ""),
            ),
        )

    async def _active_owner_interaction_checkpoints(
        self,
        *,
        engine: Any,
        project_id: str,
    ) -> list[Any]:
        store = getattr(engine, "store", None)
        getter = getattr(store, "get_execution_checkpoints", None)
        if not callable(getter):
            return []
        try:
            checkpoints = await getter(
                project_id=project_id,
                statuses=sorted(OWNER_INTERACTION_ACTIVE_STATUSES),
            )
        except TypeError:
            checkpoints = await getter(project_id=project_id)
        except Exception:
            logger.opt(exception=True).debug("failed to load owner interaction checkpoints")
            return []

        active: list[Any] = []
        for checkpoint in list(checkpoints or []):
            checkpoint_type = str(getattr(checkpoint, "checkpoint_type", "") or "").strip()
            status = str(getattr(checkpoint, "status", "") or "").strip().lower()
            if checkpoint_type not in OWNER_INTERACTION_CHECKPOINT_TYPES:
                continue
            if status not in OWNER_INTERACTION_ACTIVE_STATUSES:
                continue
            if not self._owner_interaction_checkpoint_is_projectable(checkpoint):
                continue
            active.append(checkpoint)
        return active

    async def _owner_interaction_baseline_cards(
        self,
        *,
        engine: Any,
        project_id: str,
    ) -> list[dict[str, Any]]:
        """Rebuild every reconnect card from durable checkpoints, not events.

        Every card's visibility check reads the same project task list (one
        read scope for the whole replay, joined to the caller's when it has one).
        """

        checkpoints = await self._active_owner_interaction_checkpoints(
            engine=engine,
            project_id=project_id,
        )
        if not checkpoints:
            return []

        cards_by_id: dict[str, dict[str, Any]] = {}
        with request_read_scope():
            for checkpoint in checkpoints:
                actor_task_id, actor_session_id = (
                    owner_interaction_actor_identity(checkpoint)
                )
                if not actor_task_id and not actor_session_id:
                    continue
                for card in await self._visible_owner_interaction_cards(
                    engine=engine,
                    project_id=project_id,
                    requester_task_id=actor_task_id,
                    requester_session_id=actor_session_id,
                    checkpoints=[checkpoint],
                ):
                    card_id = str(card.get("message_id", "") or "").strip()
                    if card_id:
                        cards_by_id[card_id] = card
        return sorted(
            cards_by_id.values(),
            key=lambda card: (
                float(card.get("created_at", 0) or 0),
                str(card.get("message_id", "") or ""),
            ),
        )

    # ── Owner cards a page already shows (AV) ─────────────
    # Every sync used to resend every open owner card to the page, which took
    # each for news and re-read its session. Each connection now remembers what
    # it was last sent of each card (id + a digest of the whole card) and gets a
    # card again only when it is new or has changed. A new connection, a page
    # that moved to another project, the first sync after either, a sync for
    # another view of the page than the last one answered, and a sync that asks
    # for ``full_cards`` get every card.

    @staticmethod
    def _owner_card_socket(ws: Any) -> Any:
        """The page's own socket, also when a merged request is answered through a recorder."""
        if isinstance(ws, _AckRecorder) and ws.on_behalf_of is not None:
            return ws.on_behalf_of
        return ws

    def _owner_cards_remembered_for(self, page: Any) -> bool:
        """Whether what ``page`` was sent is remembered: only for a connected page.

        A bare recorder an internal call hands a handler (auto-resume,
        work-item retry) is no page, and a socket that has left is gone:
        nothing is remembered for either (every card goes, as before AV), so
        this record never keeps such an object alive.
        """
        if isinstance(page, _AckRecorder):
            return False
        clients = getattr(self, "_clients", None)
        return isinstance(clients, (set, frozenset)) and page in clients

    @staticmethod
    def _owner_cards_view_generation(data: dict[str, Any]) -> str:
        """Which view of the page a sync is for (the page's ``view_generation``; "" when it sends none)."""
        value = data.get("view_generation")
        return "" if value is None else str(value).strip()

    @staticmethod
    def _card_ids_a_sync_carried(sync_payload: Any) -> set[str]:
        """Ids of the messages a sync reply or push carried itself.

        A sync carries its own copy of each session's newest open card under
        the card's own id (``checkpoint::<id>``), and the page merges it over
        the card it shows, preferring the incoming copy. So a card a sync
        carried is not "already shown as it is" any more: the replay after it
        sends the authoritative card again (AV re-review).

        Rule for every sender: whatever sends a collab_sync payload that carries ``messages`` to a page
        replays the owner cards right after it with ``after_sync=<that payload>``.
        """
        messages = sync_payload.get("messages") if isinstance(sync_payload, dict) else None
        return {
            str(message.get("message_id", "") or "").strip()
            for message in (messages if isinstance(messages, list) else [])
            if isinstance(message, dict) and str(message.get("message_id", "") or "").strip()
        }

    @staticmethod
    def _owner_card_digest(card: dict[str, Any]) -> str:
        try:
            text = json.dumps(card, sort_keys=True, default=str)
        except (TypeError, ValueError):
            text = repr(card)
        return hashlib.blake2b(text.encode("utf-8", "replace"), digest_size=16).hexdigest()

    def _owner_cards_on_page(self, ws: Any, project_id: str) -> dict[str, Any]:
        """This page's record for ``project_id``: {"project_id", "cards": {card id: digest}, "synced", "view_generation"}.

        A page that was on another project starts again from nothing: its
        message list was replaced when it changed project. Records of pages
        that have closed or left are dropped here.
        """
        memory = getattr(self, "_owner_cards_sent", None)
        if not isinstance(memory, dict):
            memory = {}
            self._owner_cards_sent = memory
        clients = getattr(self, "_clients", None)
        for gone in [
            socket for socket in memory
            if socket is not ws and (
                not self._ws_is_open(socket)
                or (isinstance(clients, (set, frozenset)) and socket not in clients)
            )
        ]:
            memory.pop(gone, None)
        state = memory.get(ws)
        binding = WSHandler._owner_ui_binding(self, ws)
        if (state is None or state.get("project_id") != project_id
                or state.get("receipt_schema") != 1 or state.get("binding") is not binding):
            previous_epoch = int((state or {}).get("view_epoch", 0))
            state = {"project_id": project_id, "cards": {}, "synced": False,
                     "view_generation": None, "view_epoch": previous_epoch + 1,
                     "binding": binding, "receipt_schema": 1}
            memory[ws] = state
        return state

    def _owner_cards_page_state_for_sync(
        self,
        ws: Any,
        project_id: str,
        *,
        full: bool,
        view_generation: str = "",
    ) -> dict[str, Any] | None:
        """The record of the page a full sync is answering, when the page is on that project.

        ``full`` (the page asked for every card) marks it unsynced, so the
        replay that follows sends every open card again. So does a sync for
        another view of the page (``view_generation``) than the last sync
        answered: the page throws away an answer for a view it has left, and
        the answer it keeps may replace its whole message list -- the cards
        sent with the answer it threw away go with it.
        """
        if not isinstance(getattr(self, "_client_project_ids", None), dict):
            return None  # a handler without connection bookkeeping (test doubles)
        page = self._owner_card_socket(ws)
        if not self._owner_cards_remembered_for(page) or self._client_active_project_id(page) != project_id:
            return None
        state = self._owner_cards_on_page(page, project_id)
        if full or state.get("view_generation") != view_generation:
            # Replace, rather than clear in place: a send already awaiting IO
            # can only write its old page state, never the replacement view.
            state = {**state, "cards": {}, "synced": False,
                     "view_generation": view_generation,
                     "view_epoch": state["view_epoch"] + 1}
            self._owner_cards_sent[page] = state
        return state

    def _owner_card_receipt_scope_is_current(self, page: Any, state: Any, binding: Any, project_id: str, epoch: int) -> bool:
        return (isinstance(state, dict)
                and getattr(self, "_owner_cards_sent", {}).get(page) is state
                and state.get("project_id") == project_id
                and state.get("view_epoch") == epoch
                and state.get("binding") is binding
                and self._client_active_project_id(page) == project_id
                and WSHandler._owner_ui_binding(self, page) is binding
                and self._ws_is_open(page))

    async def _send_owner_interaction_baseline_for_client(
        self,
        ws: Any,
        *,
        engine: Any,
        project_id: str,
        full: bool = False,
        after_sync: Any = None,
        expected_binding: Any = _UI_READ_BINDING_UNSET,
    ) -> None:
        """Send this page the open owner cards it does not already show as they are.

        Every open card goes when ``full``, while the page has not had its
        first full sync on this project (its message list is about to be, or
        was just, replaced), and to anything that is no connected page.
        ``after_sync``: the sync this page was just sent -- the cards it
        carried its own copy of go again (see ``_card_ids_a_sync_carried``).
        """
        try:
            if expected_binding is _UI_READ_BINDING_UNSET:
                expected_binding = WSHandler._owner_ui_binding(self, ws)
        except Exception:
            return
        page = self._owner_card_socket(ws)
        if not WSHandler._owner_ui_is_current(self, ws, expected_binding, project_id):
            return
        cards = await self._owner_interaction_baseline_cards(
            engine=engine,
            project_id=project_id,
        )
        sent: dict[str, str] = {}  # not remembered: every card goes
        page_state = None
        receipt_epoch = 0
        if self._owner_cards_remembered_for(page):
            page_state = self._owner_cards_on_page(page, project_id)
            sent = page_state["cards"]
            receipt_epoch = page_state["view_epoch"]
            if full or not page_state.get("synced"):
                sent.clear()
            for carried in self._card_ids_a_sync_carried(after_sync):
                sent.pop(carried, None)
        open_card_ids: set[str] = set()
        for card in cards:
            if self._client_active_project_id(page) != project_id:
                return
            card_id = str(card.get("message_id", "") or "").strip()
            digest = self._owner_card_digest(card)
            if card_id:
                open_card_ids.add(card_id)
                if sent.get(card_id) == digest:
                    continue
            delivered = await self._send_envelope_to_client(
                ws,
                {"type": "session_message", "payload": card},
                expected_binding=expected_binding,
            )
            if not delivered:
                return
            if card_id and self._owner_card_receipt_scope_is_current(
                page, page_state, expected_binding, project_id, receipt_epoch,
            ):
                sent[card_id] = digest
        # A card that closed and later opens again is news again.
        for closed_id in [card_id for card_id in sent if card_id not in open_card_ids]:
            sent.pop(closed_id, None)

    async def _broadcast_owner_interaction_cards(
        self,
        cards: list[dict[str, Any]],
        *,
        project_id: str,
        all_open_cards: bool = False,
    ) -> None:
        """Push cards to every owner page, leaving out a page that already shows the very same card.

        ``all_open_cards``: ``cards`` is every open card of the project, so a
        page's record of any other card is dropped (that card has closed).
        A broadcaster that does not declare ``send_to`` (a stand-in) is called
        as before and every page gets every card.
        """
        broadcaster = self.broadcast
        real_broadcast = (getattr(broadcaster, "__self__", None) is self
                          and getattr(broadcaster, "__func__", None) is WSHandler.broadcast)
        filtered_broadcast = _accepts_keyword(broadcaster, "send_to")
        original_states = list((getattr(self, "_owner_cards_sent", {}) or {}).items())
        failed_pages: set[Any] = set()
        origin_task = asyncio.current_task()
        for card in cards:
            card_id = str(card.get("message_id", "") or "").strip()
            digest = self._owner_card_digest(card)

            def _page_needs_it(socket: Any, card_id: str = card_id, digest: str = digest) -> bool:
                # A predicate is not a delivery receipt. Compatibility senders
                # may call it and then fail, revoke or never perform wire IO.
                if not card_id:
                    return True
                sent = self._owner_cards_on_page(socket, project_id)["cards"]
                return sent.get(card_id) != digest

            if real_broadcast:
                async def deliver(page: Any) -> bool:
                    state = self._owner_cards_on_page(page, project_id)
                    if card_id and state["cards"].get(card_id) == digest:
                        return True
                    expected_binding, epoch = state["binding"], state["view_epoch"]
                    initial = getattr(self, "_client_initial_state_tasks", {}).get(_socket_behind(page))
                    ready = getattr(initial, "_ui_initial_snapshot_ready", None)
                    if (isinstance(initial, asyncio.Task) and initial is not origin_task
                            and not initial.done() and isinstance(ready, asyncio.Event)):
                        # Keep background cards out of the physical-send FIFO
                        # until this peer's complete sync has reached the wire.
                        # Do not drop terminal updates or precommit their digest.
                        peer_waiters = getattr(initial, "_ui_initial_card_waiters", 0)
                        total_waiters = getattr(self, "_ui_initial_card_waiters", 0)
                        if (type(peer_waiters) is not int or type(total_waiters) is not int
                                or peer_waiters < 0 or total_waiters < 0
                                or peer_waiters >= self._UI_SEND_LIMIT
                                or total_waiters >= self._UI_SEND_GLOBAL_LIMIT):
                            WSHandler._close_ui_peer(self, page)
                            return False
                        setattr(initial, "_ui_initial_card_waiters", peer_waiters + 1)
                        self._ui_initial_card_waiters = total_waiters + 1
                        try:
                            async with asyncio.timeout(self._UI_INITIAL_CARD_WAIT_SEC):
                                await ready.wait()
                        except TimeoutError:
                            WSHandler._close_ui_peer(self, page)
                            return False
                        finally:
                            initial._ui_initial_card_waiters -= 1
                            self._ui_initial_card_waiters -= 1
                        current = getattr(self, "_client_initial_state_tasks", {}).get(_socket_behind(page))
                        if (current is not None and current is not initial
                                or initial.cancelled()
                                or initial.done() and initial.exception() is not None):
                            return False
                        if not self._owner_card_receipt_scope_is_current(
                                page, state, expected_binding, project_id, epoch):
                            return False
                    delivery_digest = self._owner_card_digest(card)
                    if card_id and state["cards"].get(card_id) == delivery_digest:
                        return True
                    delivered = await self._send_envelope_to_client(
                        page, {"type": "session_message", "payload": card},
                        expected_binding=expected_binding,
                    )
                    if (delivered and card_id and self._owner_card_receipt_scope_is_current(
                            page, state, expected_binding, project_id, epoch)):
                        state["cards"][card_id] = delivery_digest
                    return bool(delivered)
                # Existing UI lifecycle, empty Context, independent peers. A
                # slow transport never serializes other pages' card delivery.
                pending = [(page, WSHandler._track_ui_transport(self, deliver(page))) for page in set(self._clients)]
                results = await asyncio.gather(*(task for _, task in pending), return_exceptions=True)
                failed_pages.update(page for (page, _), result in zip(pending, results) if result is not True)
            elif filtered_broadcast:
                await broadcaster({"type": "session_message", "payload": card}, send_to=_page_needs_it)
            else:
                # A stand-in has no per-peer wire result; preserve its calls,
                # but never infer confirmed delivery from a None return.
                await broadcaster({"type": "session_message", "payload": card})
        if all_open_cards:
            open_card_ids = {
                str(card.get("message_id", "") or "").strip() for card in cards
            }
            for page, state in original_states:
                if page in failed_pages or not real_broadcast:
                    continue
                if not self._owner_card_receipt_scope_is_current(
                    page, state, state.get("binding"), project_id, state.get("view_epoch"),
                ):
                    continue
                sent = state.get("cards") or {}
                for closed_id in [card_id for card_id in sent if card_id not in open_card_ids]:
                    sent.pop(closed_id, None)

    async def _broadcast_owner_interaction_baseline(
        self,
        *,
        engine: Any,
        project_id: str,
        after_sync: Any = None,
    ) -> None:
        carried = self._card_ids_a_sync_carried(after_sync)
        memory = getattr(self, "_owner_cards_sent", None)
        if carried and isinstance(memory, dict):
            for state in list(memory.values()):
                if state.get("project_id") != project_id:
                    continue
                sent = state.get("cards") or {}
                for card_id in carried:
                    sent.pop(card_id, None)
        await self._broadcast_owner_interaction_cards(
            await self._owner_interaction_baseline_cards(
                engine=engine,
                project_id=project_id,
            ),
            project_id=project_id,
            all_open_cards=True,
        )

    async def _build_task_user_input_meta(
        self,
        cp: Any,
        *,
        engine: Any | None = None,
    ) -> dict[str, Any] | None:
        payload = dict(cp.payload or {})
        pause_request = dict(payload.get("pause_request", {}) or {})
        task_id = str(payload.get("task_id", "")).strip()
        work_item_projection_id = ""
        work_item_projection_title = ""
        runtime_engine = engine or self.engine
        store = runtime_engine.store
        work_item_turn_type = ""
        if store and task_id:
            task = await store.get_task(task_id)
            if task:
                task_metadata = dict(getattr(task, "metadata", {}) or {})
                work_item_projection_id = str(task_metadata.get("work_item_projection_id", "") or "").strip()
                work_item_turn_type = str(task_metadata.get("work_item_turn_type", "") or "").strip()
                work_item_projection_title = str(task.title or "").strip()

        prompt = str(payload.get("prompt", "") or "").strip()
        summary = str(pause_request.get("reason", "") or prompt).strip()
        questions = [str(item).strip() for item in list(pause_request.get("questions", []) or []) if str(item).strip()]
        input_questions = [
            dict(item)
            for item in list(pause_request.get("input_questions", []) or [])
            if isinstance(item, dict) and str(item.get("question", "") or item.get("header", "") or "").strip()
        ]
        if not input_questions:
            input_questions = [
                {
                    "id": f"question_{index + 1}",
                    "header": "",
                    "question": question,
                    "options": [],
                    "allow_freeform": True,
                    "required": True,
                }
                for index, question in enumerate(questions)
            ]
        required_fields = [
            str(item).strip()
            for item in list(pause_request.get("required_fields", []) or [])
            if str(item).strip()
        ]
        resume_hint = str(pause_request.get("resume_hint", "") or "").strip()

        return {
            "checkpoint_type": "task_user_input",
            "checkpoint_id": cp.checkpoint_id,
            "task_id": task_id,
            **work_item_identity_payload(projection_id=work_item_projection_id, turn_type=work_item_turn_type),
            "work_item_projection_title": work_item_projection_title,
            "summary": summary,
            "prompt": prompt,
            "questions": questions,
            "input_questions": input_questions,
            "required_fields": required_fields,
            # An allowance's stop card says why in Chinese; the engine's note is kept beside it (P-c).
            **_budget_context_note(pause_request),
            "resume_hint": resume_hint,
            "requesting_role_id": str(
                payload.get("requesting_role_id") or pause_request.get("requesting_role_id") or ""
            ).strip(),
            "requesting_task_id": str(
                payload.get("requesting_task_id") or pause_request.get("requesting_task_id") or ""
            ).strip(),
            "requesting_work_item_id": str(
                payload.get("requesting_work_item_id") or pause_request.get("requesting_work_item_id") or ""
            ).strip(),
            "seat_id": str(payload.get("seat_id") or pause_request.get("seat_id") or "").strip(),
            "runtime_session_id": str(payload.get("runtime_session_id", "") or "").strip(),
            "resume_cursor": payload.get("resume_cursor"),
            "active_subagents": list(payload.get("active_subagents", []) or []),
            "permission_requests": list(payload.get("permission_requests", []) or []),
            "worktree_path": str(payload.get("worktree_path", "") or "").strip(),
        }

    def _build_company_work_item_gate_meta(self, cp: Any) -> dict[str, Any]:
        payload = dict(cp.payload or {})
        gate = dict(payload.get("gate", {}) or {})
        projection_id = str(payload.get("work_item_projection_id") or "").strip()
        turn_type = str(payload.get("work_item_turn_type") or "").strip()
        projection_title = str(
            payload.get("work_item_projection_title") or projection_id or "Work item gate"
        ).strip()
        gate_type = str(gate.get("type", "") or "review").strip()
        prompt_lines = [
            f"{projection_title} requires confirmation.",
            f"Gate type: {gate_type}",
        ]
        instructions = str(gate.get("instructions", "") or "").strip()
        if instructions:
            prompt_lines.append(f"Instructions: {instructions}")
        return {
            "checkpoint_type": "company_work_item_gate",
            "checkpoint_id": cp.checkpoint_id,
            **work_item_identity_payload(projection_id=projection_id, turn_type=turn_type),
            "work_item_projection_title": projection_title,
            "company_profile": payload.get("company_profile", ""),
            "summary": instructions or f"Pending {gate_type} confirmation",
            "prompt": "\n".join(prompt_lines),
            "options": [
                {"id": "approve", "label": "Approve"},
                {"id": "deny", "label": "Deny"},
            ],
            "default_action": "deny",
            "runtime_session_id": str(payload.get("runtime_session_id", "") or "").strip(),
            "resume_cursor": payload.get("resume_cursor"),
            "active_subagents": list(payload.get("active_subagents", []) or []),
            "permission_requests": list(payload.get("permission_requests", []) or []),
            "worktree_path": str(payload.get("worktree_path", "") or "").strip(),
        }

    def _build_recruitment_meta(self, cp: Any, *, engine: Any | None = None) -> dict[str, Any]:
        """Extract recruitment plan data into frontend-friendly metadata."""
        runtime_engine = engine or self.engine
        payload = cp.payload
        rp = payload.get("recruitment_plan", {})
        plan_metadata = dict(rp.get("metadata", {}) or {})
        recruitment_agent = self._normalize_session_preferred_agent(
            payload.get("recruitment_agent") or plan_metadata.get("recruitment_agent") or "native",
            default="native",
        )
        proposals_raw = rp.get("proposals", [])
        proposals = []
        payload_role_agents: dict[str, str] = {}
        raw_payload_role_agents = payload.get("recruitment_role_agents")
        if isinstance(raw_payload_role_agents, dict):
            payload_role_agents = {
                str(raw_role_id or "").strip(): self._normalize_session_preferred_agent(raw_agent, default="codex")
                for raw_role_id, raw_agent in raw_payload_role_agents.items()
                if str(raw_role_id or "").strip()
            }
        recruitment_role_agents: dict[str, str] = {}
        employee_payloads: list[dict[str, Any]] = []
        template_payloads: list[dict[str, Any]] = []
        org_engine = getattr(runtime_engine, "org_engine", None)
        reports_to_by_role = {
            str(getattr(agent, "role_id", "") or "").strip(): str(
                getattr(agent, "reports_to", "") or ""
            ).strip()
            for agent in (org_engine.list_agents() if org_engine else [])
            if str(getattr(agent, "role_id", "") or "").strip()
        }
        talent_market = getattr(runtime_engine, "talent_market", None)
        is_placeholder = getattr(runtime_engine, "_is_placeholder_staffing_employee", lambda _employee: False)
        employee_payload = getattr(runtime_engine, "_staffing_employee_payload", None)
        template_payload = getattr(runtime_engine, "_staffing_template_payload", None)
        if org_engine and callable(employee_payload):
            try:
                employee_payloads = [
                    employee_payload(employee)
                    for employee in org_engine.list_employees()
                    if not is_placeholder(employee)
                ]
            except Exception:
                employee_payloads = []
        if talent_market and callable(template_payload):
            try:
                template_payloads = [
                    template_payload(template)
                    for template in talent_market.list_available_templates()
                    if str(getattr(template, "id", "") or "").strip()
                ]
            except Exception:
                template_payloads = []
        employees_by_id = {
            str(item.get("employee_id", "") or "").strip(): item
            for item in employee_payloads
            if str(item.get("employee_id", "") or "").strip()
        }
        templates_by_id = {
            str(item.get("template_id", "") or "").strip(): item
            for item in template_payloads
            if str(item.get("template_id", "") or "").strip()
        }
        employees_by_role: dict[str, list[dict[str, Any]]] = {}
        for item in employee_payloads:
            role_id = str(item.get("role_id", "") or "").strip()
            if role_id:
                employees_by_role.setdefault(role_id, []).append(item)
        staffing_roles: list[dict[str, Any]] = []
        staffing_selections: dict[str, dict[str, str]] = {}
        recruitment_rationales: list[dict[str, Any]] = []
        for p in proposals_raw:
            role_id = str(p.get("role_id", "") or "").strip()
            proposal_metadata = dict(p.get("metadata", {}) or {})
            entry: dict[str, Any] = {
                "role_id": role_id,
                "status": p.get("status", ""),
                "rationale": p.get("rationale", ""),
                "role_labels": p.get("role_labels", []),
            }
            cand = p.get("candidate")
            if cand:
                entry["candidate"] = {
                    "template_id": cand.get("template_id", ""),
                    "template_name": cand.get("template_name", ""),
                    "category": cand.get("category", ""),
                    "domains": cand.get("domains", []),
                    "proposed_name": cand.get("proposed_employee_name", ""),
                    "rationale": cand.get("rationale", ""),
                }
                template_id = str(cand.get("template_id", "") or "").strip()
                if template_id and template_id not in templates_by_id:
                    templates_by_id[template_id] = {
                        "kind": "template",
                        "template_id": template_id,
                        "template_name": cand.get("template_name", "") or template_id,
                        "category": cand.get("category", ""),
                        "domains": cand.get("domains", []),
                        "tags": [],
                        "description": "",
                        "preferred_external_agent": cand.get("preferred_external_agent"),
                        "source_path": cand.get("source_path", ""),
                    }
            emp = p.get("existing_employee")
            if emp:
                entry["existing_employee"] = {
                    "employee_id": emp.get("employee_id", ""),
                    "employee_name": emp.get("employee_name", ""),
                    "role_id": emp.get("role_id", ""),
                    "domains": emp.get("domains", []),
                    "experience_score": emp.get("experience_score", 0),
                    "rationale": emp.get("rationale", ""),
                }
                employee_id = str(emp.get("employee_id", "") or "").strip()
                if employee_id and employee_id not in employees_by_id:
                    employee_payload_item = {
                        "kind": "employee",
                        "employee_id": employee_id,
                        "employee_name": emp.get("employee_name", "") or employee_id,
                        "role_id": emp.get("role_id", "") or role_id,
                        "category": emp.get("category", ""),
                        "domains": emp.get("domains", []),
                        "tags": [],
                        "description": "",
                        "preferred_external_agent": None,
                        "experience_score": emp.get("experience_score", 0),
                    }
                    employees_by_id[employee_id] = employee_payload_item
                    if role_id:
                        employees_by_role.setdefault(role_id, []).append(employee_payload_item)
            default_agent = self._normalize_session_preferred_agent("codex", default="codex")
            entry["default_agent"] = default_agent
            entry["selected_agent"] = self._normalize_session_preferred_agent(
                payload_role_agents.get(role_id) or proposal_metadata.get("selected_execution_agent"),
                default=default_agent,
            )
            if role_id:
                recruitment_role_agents[role_id] = entry["selected_agent"]
            proposals.append(entry)
            role_label = str((p.get("role_labels", []) or [role_id])[0] or role_id)
            default_selection: dict[str, str] = {"kind": "fallback", "id": ""}
            selection_label = "Fallback role-only"
            cand = p.get("candidate")
            emp = p.get("existing_employee")
            if emp and str(emp.get("employee_id", "") or "").strip():
                employee_id = str(emp.get("employee_id", "") or "").strip()
                default_selection = {"kind": "employee", "id": employee_id, "employee_id": employee_id}
                selection_label = str(emp.get("employee_name", "") or employee_id)
            elif cand and str(cand.get("template_id", "") or "").strip():
                template_id = str(cand.get("template_id", "") or "").strip()
                default_selection = {"kind": "template", "id": template_id, "template_id": template_id}
                selection_label = str(cand.get("proposed_employee_name") or cand.get("template_name") or template_id)
            if role_id:
                staffing_selections[role_id] = dict(default_selection)
                same_role_ids = {
                    str(item.get("employee_id", "") or "").strip()
                    for item in employees_by_role.get(role_id, [])
                    if str(item.get("employee_id", "") or "").strip()
                }
                same_role_ids.update(
                    str(item or "").strip()
                    for item in list(p.get("existing_employee_ids", []) or [])
                    if str(item or "").strip()
                )
                staffing_roles.append(
                    {
                        "role_id": role_id,
                        "role_label": role_label,
                        "role_responsibility": "",
                        "reports_to": reports_to_by_role.get(role_id, ""),
                        "default_selection": default_selection,
                        "same_role_employee_ids": sorted(same_role_ids),
                        "fallback_available": True,
                        "default_agent": default_agent,
                        "selected_agent": entry["selected_agent"],
                        "default_source": "recruitment",
                    }
                )
                reason_parts = [
                    str((cand or {}).get("rationale", "") or "").strip(),
                    str((emp or {}).get("rationale", "") or "").strip(),
                    str(p.get("rationale", "") or "").strip(),
                ]
                rationale = next((item for item in reason_parts if item), "")
                recruitment_rationales.append(
                    {
                        "role_id": role_id,
                        "role_label": role_label,
                        "status": p.get("status", ""),
                        "selection_label": selection_label,
                        "rationale": rationale,
                    }
                )
        employee_payloads = list(employees_by_id.values())
        template_payloads = list(templates_by_id.values())
        return {
            "checkpoint_type": "company_recruitment_confirmation",
            "checkpoint_id": cp.checkpoint_id,
            "company_profile": rp.get("company_profile", "corporate"),
            "previous_checkpoint_id": payload.get("previous_checkpoint_id", ""),
            "recruitment_revision": payload.get("recruitment_revision") or dict(rp.get("metadata", {}) or {}).get("recruitment_revision"),
            "recruiter_feedback": list(rp.get("recruiter_feedback", []) or []),
            "recruitment_agent": recruitment_agent,
            "recruitment_role_agents": recruitment_role_agents,
            "proposals": proposals,
            "summary": rp.get("summary", ""),
            "recruitment_rationales": recruitment_rationales,
            "staffing_roles": staffing_roles,
            "staffing_pool": {
                "employees": employee_payloads,
                "templates": template_payloads,
            },
            "staffing_selections": staffing_selections,
        }

    def _build_staffing_selection_meta(
        self,
        cp: Any,
        *,
        engine: Any | None = None,
    ) -> dict[str, Any]:
        """Extract manual staffing data into frontend-friendly metadata."""
        payload = dict(cp.payload or {})
        runtime_engine = engine or self.engine
        org_engine = getattr(runtime_engine, "org_engine", None)
        reports_to_by_role = {
            str(getattr(agent, "role_id", "") or "").strip(): str(
                getattr(agent, "reports_to", "") or ""
            ).strip()
            for agent in (org_engine.list_agents() if org_engine else [])
            if str(getattr(agent, "role_id", "") or "").strip()
        }
        raw_role_agents = payload.get("recruitment_role_agents")
        payload_role_agents = raw_role_agents if isinstance(raw_role_agents, dict) else {}
        recruitment_agent = self._normalize_session_preferred_agent(
            payload.get("recruitment_agent") or "native",
            default="native",
        )
        staffing_roles: list[dict[str, Any]] = []
        recruitment_role_agents: dict[str, str] = {}
        for raw_role in list(payload.get("staffing_roles", []) or []):
            if not isinstance(raw_role, dict):
                continue
            role = dict(raw_role)
            role_id = str(role.get("role_id", "") or "").strip()
            selected_agent = self._normalize_session_preferred_agent(
                payload_role_agents.get(role_id) or role.get("selected_agent") or role.get("default_agent") or "codex",
                default="codex",
            )
            if role_id:
                role["selected_agent"] = selected_agent
                role["reports_to"] = str(
                    role.get("reports_to") or reports_to_by_role.get(role_id, "")
                ).strip()
                recruitment_role_agents[role_id] = selected_agent
            staffing_roles.append(role)
        return {
            "checkpoint_type": "company_staffing_selection",
            "checkpoint_id": cp.checkpoint_id,
            "company_profile": payload.get("company_profile", "corporate"),
            "summary": payload.get("summary") or "Select staff manually, or run automatic recruitment.",
            "staffing_strategy": payload.get("staffing_strategy", ""),
            "recommended_action": payload.get("recommended_action", ""),
            "staffing_defaults": dict(payload.get("staffing_defaults", {}) or {}),
            "staffing_roles": staffing_roles,
            "recruitment_agent": recruitment_agent,
            "recruitment_role_agents": recruitment_role_agents,
            "staffing_pool": dict(payload.get("staffing_pool", {}) or {}),
        }

    async def _build_reorg_meta(
        self,
        cp: Any,
        *,
        engine: Any | None = None,
    ) -> dict[str, Any] | None:
        """Extract reorg proposal data into frontend-friendly metadata."""
        runtime_engine = engine or self.engine
        store = runtime_engine.store
        if not store:
            return None
        proposal_id = cp.payload.get("proposal_id", "")
        if not proposal_id:
            return None
        proposal = await store.get_reorg_proposal(proposal_id)
        if not proposal:
            return None
        changeset = proposal.changeset
        role_changes = []
        if hasattr(changeset, "role_changes"):
            for rc in changeset.role_changes:
                role_changes.append({
                    "action": rc.action,
                    "role_id": rc.role_id,
                    "replacement_role_id": rc.replacement_role_id,
                    "reason": rc.reason,
                })
        return {
            "checkpoint_type": "company_reorg_pending",
            "checkpoint_id": cp.checkpoint_id,
            "proposal_id": proposal.proposal_id,
            "scope": proposal.scope.value,
            "risk_level": proposal.risk_level.value,
            "status": proposal.status.value,
            "title": proposal.title,
            "summary": proposal.summary,
            "rationale": proposal.rationale,
            "role_changes": role_changes,
            "impact_summary": proposal.impact_summary,
            "user_confirmation_required": proposal.user_confirmation_required,
        }

    def _build_delivery_feedback_meta(self, cp: Any) -> dict[str, Any]:
        payload = dict(cp.payload or {})
        prompt = str(payload.get("prompt", "") or "").strip()
        projection_title = str(payload.get("work_item_projection_title", "") or "").strip()
        feedback_scope = str(payload.get("feedback_scope", "work_item") or "work_item").strip()
        delivery_package = payload.get("delivery_package")
        if not isinstance(delivery_package, dict):
            delivery_package = {}
        result_content = str(payload.get("result_content", "") or "").strip()
        summary = str(
            delivery_package.get("executive_summary")
            or delivery_package.get("summary")
            or payload.get("work_item_summary")
            or payload.get("work_item_summary_for_downstream")
            or result_content
            or projection_title
            or ("Final delivery review" if feedback_scope == "final" else "Work item review")
        ).strip()
        waiting_task_id = str(
            payload.get("waiting_task_id")
            or payload.get("task_id")
            or getattr(cp, "task_id", "")
            or ""
        ).strip()
        return {
            "checkpoint_type": "company_delivery_feedback",
            "checkpoint_id": cp.checkpoint_id,
            "waiting_task_id": waiting_task_id,
            "task_id": waiting_task_id,
            **work_item_identity_payload(
                projection_id=str(payload.get("work_item_projection_id", "") or "").strip(),
                turn_type=str(payload.get("work_item_turn_type", "") or "").strip(),
            ),
            "work_item_projection_title": projection_title,
            "company_profile": payload.get("company_profile", ""),
            "feedback_scope": feedback_scope,
            "summary": summary,
            "prompt": prompt,
            "options": [
                {"id": "approve", "label": "完全同意"},
                {"id": "ignore", "label": "忽略"},
                {"id": "feedback", "label": "写一句反馈"},
            ],
            "delivery_package": delivery_package,
            "result_content": result_content,
            "delivery_revision": payload.get("delivery_revision", ""),
            "owner_directive_revision": payload.get("owner_directive_revision", ""),
            "latest_user_directive": str(payload.get("latest_user_directive", "") or "").strip(),
            "waiting_work_item_id": str(payload.get("waiting_work_item_id", "") or "").strip(),
            "runtime_session_id": str(payload.get("runtime_session_id", "") or "").strip(),
            "resume_cursor": payload.get("resume_cursor"),
            "active_subagents": list(payload.get("active_subagents", []) or []),
            "permission_requests": list(payload.get("permission_requests", []) or []),
            "worktree_path": str(payload.get("worktree_path", "") or "").strip(),
        }

    # ── Secretary ──────────────────────────────────────────────────────

    async def _handle_secretary_send(self, ws: Any, data: dict) -> None:
        """Handle user message in the secretary channel (no kanban task linkage)."""
        content = data.get("content", "")
        if not content:
            return

        run_engine, pid = await self._engine_for_request(data)

        # Ensure secretary channel exists
        await self.chat_store.ensure_secretary_channel(project_id=pid)
        secretary_channel = f"secretary:{pid}"

        # Lazily resolve or create a persistent secretary session
        secretary_session_id = self._secretary_session_ids.get(pid)
        if secretary_session_id is None:
            if getattr(run_engine, "secretary", None):
                sessions = await run_engine.secretary.list_sessions(
                    pid, limit=1,
                )
                if sessions:
                    secretary_session_id = sessions[0].session_id
            if secretary_session_id is None:
                import uuid as _uuid
                secretary_session_id = str(_uuid.uuid4())
            self._secretary_session_ids[pid] = secretary_session_id
            if self._active_engine_project_id() == pid:
                self._secretary_session_id = secretary_session_id

        # Insert user message to chat_store for UI rendering
        msg = await self.chat_store.insert_message(
            channel_id=secretary_channel,
            sender="user",
            sender_name="You",
            content=content,
            project_id=pid,
        )
        await self.broadcast({"type": "session_message", "payload": msg})

        # Process via SecretaryService (shared with CLI `ampuly secretary`)
        self._track(self._process_secretary_message(content, engine=run_engine, project_id=pid, session_id=secretary_session_id))

    async def _process_secretary_message(
        self,
        content: str,
        *,
        engine: Any,
        project_id: str,
        session_id: str,
    ) -> None:
        """Call engine.process_secretary_message and write reply to secretary channel."""
        pid = project_id
        secretary_channel = f"secretary:{pid}"
        try:
            result = await engine.process_secretary_message(
                content,
                project_id=pid,
                session_id=session_id,
            )
            reply_text = result.get("response", "") if isinstance(result, dict) else str(result)

            # Show applied updates if any
            applied = result.get("applied_updates", []) if isinstance(result, dict) else []
            if applied:
                reply_text += "\n\n**Applied updates:**\n" + "\n".join(f"- {u}" for u in applied)

            msg = await self.chat_store.insert_message(
                channel_id=secretary_channel,
                sender="assistant",
                sender_name="Secretary",
                content=(reply_text or "No response."),
                project_id=pid,
            )
            await self.broadcast({"type": "session_message", "payload": msg})
        except Exception as e:
            logger.opt(exception=True).error(f"Secretary processing error: {e}")
            msg = await self.chat_store.insert_message(
                channel_id=secretary_channel,
                sender="system",
                sender_name="Secretary",
                content=f"Error: {e}",
                project_id=pid,
            )
            await self.broadcast({"type": "session_message", "payload": msg})

    # ── Master Control (总控) ───────────────────────────────────────────

    # Client message ids already seen, per project, newest last. Bounded so a
    # long-lived console cannot grow it; per process because it guards
    # against one click landing twice, not against history.
    _MASTER_SEEN_LIMIT = 300

    @staticmethod
    def _master_seen_bucket(project_id: str, thread_id: str = "") -> str:
        """Whose remembered ids a send is checked against: one conversation's (总控对话栏). The project's first
        conversation keeps the project's own bucket, as before conversations were split."""
        pid = str(project_id or "default")
        thread = str(thread_id or "").strip()
        return f"{pid}\x1f{thread}" if thread else pid

    def _master_send_forget(self, project_id: str, client_message_id: str, thread_id: str = "") -> None:
        """Forget an id remembered for a send that was then refused, so its corrected resend is not a duplicate."""
        bucket = (getattr(self, "_master_seen_client_ids", None) or {}).get(
            WSHandler._master_seen_bucket(project_id, thread_id))
        clean = str(client_message_id or "").strip()
        if bucket and clean in bucket:
            bucket.remove(clean)

    def _master_send_is_duplicate(self, project_id: str, client_message_id: str, thread_id: str = "") -> bool:
        """Remember this id; True when it was already remembered -- in the same conversation (``thread_id``; "" is
        the project's first conversation)."""
        clean = str(client_message_id or "").strip()
        if not clean or len(clean) > 128:
            return False
        seen = getattr(self, "_master_seen_client_ids", None)
        if seen is None:
            seen = self._master_seen_client_ids = {}
        bucket = seen.setdefault(WSHandler._master_seen_bucket(project_id, thread_id), [])
        if clean in bucket:
            return True
        bucket.append(clean)
        if len(bucket) > self._MASTER_SEEN_LIMIT:
            del bucket[: len(bucket) - self._MASTER_SEEN_LIMIT]
        return False

    async def _handle_master_send(self, ws: Any, data: dict) -> None:
        """Handle user message in the master-control channel (system-level chat).

        总控对话栏 (policy, 第七节): ``thread_id`` names the conversation -- one of this project's, not
        archived, else refused (``thread_not_found`` / ``thread_archived``) before anything is stored or remembered.
        Without it the message is for the project's first conversation (``master:{pid}``), so today's client keeps
        working unchanged. The message, the dedup of its client id, the turn's memory and its answer all belong to that
        one conversation. (The builder-side 安安 panel names the conversation it shows: the project's most recently
        active one, ``master_threads.latest_thread_id``, which ``master_thread_list`` answers as ``latest_thread_id``.)
        """
        from ampuly.plugins.office_ui.master_control import master_channel_id

        content = str(data.get("content", "") or "").strip()
        if not content and not data.get("attachments"):
            return

        run_engine, pid = await self._engine_for_request(data)
        client_message_id = str(data.get("client_message_id", "") or "").strip()
        requested_thread = str(data.get("thread_id", "") or "").strip()
        thread_id = ""                   # the conversation, when the request named one
        later_thread = ""                # a later conversation's id; "" = the project's first conversation
        channel = master_channel_id(pid)
        # Acks name the conversation back only when the request named one: an older client's acks are as they were.
        thread_ack: dict[str, Any] = {"thread_id": requested_thread} if requested_thread else {}
        thread: dict[str, Any] | None = None
        if requested_thread:
            thread = await _master_thread_row(self.chat_store, pid, requested_thread)
            refusal = ("thread_not_found" if thread is None
                       else "thread_archived" if float(thread.get("archived_at", 0) or 0) else "")
            if refusal:
                await self._send_ack(
                    ws, ok=False, action="master_send", project_id=pid, client_message_id=client_message_id,
                    error=refusal, **thread_ack,
                )
                return
            thread_id = str(thread["thread_id"])
            if not thread.get("legacy"):
                later_thread = thread_id
                channel = str(thread["channel_id"])
        # 安安 · 引用: what the owner pointed at on the canvas, checked before anything is stored (4.7 Q04) -- and
        # before the id is remembered, so a send refused here can be corrected and sent again under the same id.
        references: list[dict[str, Any]] = []
        if data.get("references"):
            from ampuly.plugins.office_ui.master_references import ReferenceRefused, resolve_references

            def artifact_reader(item: dict[str, Any]) -> dict[str, Any]:
                from ampuly.plugins.office_ui.master_artifact_references import resolve_artifact_reference

                denied, _ = artifact_customer_denied(self, ws, pid, str(item.get("path", "") or ""))
                if denied:
                    raise ValueError("artifact_reference_unavailable")
                return resolve_artifact_reference(run_engine, pid, item)

            try:
                references = resolve_references(
                    data.get("references"),
                    self._workflow_registry(),
                    Path(__file__).resolve().parents[3] / "distribution" / "skills",
                    project_id=pid,
                    artifact_reader=artifact_reader,
                )
            except ReferenceRefused as exc:
                await self._send_ack(
                    ws, ok=False, action="master_send", project_id=pid, client_message_id=client_message_id,
                    error="reference_invalid", problems=exc.problems, **thread_ack,
                )
                return
        # A10: the same send arriving twice -- double-click, retry, reconnect
        # replay -- is acknowledged and not run again. Nothing is inserted,
        # so the chat shows one message and one answer. Per conversation.
        if self._master_send_is_duplicate(pid, client_message_id, later_thread):
            await self._send_ack(
                ws, ok=True, action="master_send", project_id=pid,
                client_message_id=client_message_id, duplicate=True, **thread_ack,
            )
            return
        # 安安 · 附件: stored and read by the order chat's own attachment store (4.7 Q04-A). Files that cannot be
        # stored are named back; a message left with neither words nor files is refused, and its id forgotten so
        # the corrected send is not taken for a duplicate.
        attachment_refs: list[dict[str, Any]] = []
        attachments_read: list[dict[str, Any]] = []
        if data.get("attachments"):
            from ampuly.plugins.office_ui.master_attachments import save_and_read

            ensure_store = getattr(run_engine, "_ensure_attachment_store", None)
            if callable(ensure_store):
                try:
                    ensure_store()
                except Exception as exc:
                    logger.warning(f"master control: attachment store for {pid!r} unavailable: {exc}")
            attachment_refs, attachments_read, attachment_problems = await save_and_read(
                getattr(run_engine, "attachment_store", None), data.get("attachments"),
            )
            # 安安 · 看图 (4.7 A13): with the vision switch on, pictures and scans are stored as 排队, not 未读.
            from ampuly.plugins.office_ui.master_vision import mark_queued

            mark_queued(attachments_read)
            if attachment_problems:
                if not content and not attachment_refs:
                    self._master_send_forget(pid, client_message_id, later_thread)
                    await self._send_ack(
                        ws, ok=False, action="master_send", project_id=pid, client_message_id=client_message_id,
                        error="attachment_invalid", problems=attachment_problems, **thread_ack,
                    )
                    return
                await self._send_ack(
                    ws, ok=True, action="master_send", project_id=pid, client_message_id=client_message_id,
                    attachment_problems=attachment_problems, **thread_ack,
                )
            if not content:
                from ampuly.i18n_runtime import is_zh

                content = "（只发了附件）" if is_zh() else "(files only)"
        if later_thread:
            await self.chat_store.ensure_master_channel(project_id=pid, channel_id=channel)
        else:
            await self.chat_store.ensure_master_channel(project_id=pid)

        metadata: dict[str, Any] | None = None
        if references:
            from ampuly.plugins.office_ui.master_references import reference_summary

            metadata = {"references": reference_summary(references)}
        if attachment_refs:
            from ampuly.plugins.office_ui.master_attachments import attachment_summary

            # attachment_refs is the key the chat already shows files from; attachments_read says what was read.
            metadata = {**(metadata or {}), "attachment_refs": attachment_refs, "attachments_read": attachment_summary(attachments_read)}
        msg = await self.chat_store.insert_message(
            channel_id=channel,
            sender="user",
            sender_name="You",
            content=content,
            metadata=metadata,
            project_id=pid,
        )
        await self.broadcast({"type": "session_message", "payload": msg})
        if thread_id:
            await _master_thread_touch(self.chat_store, pid, thread_id, at=msg.get("created_at"), first_words=content)
            if not str((thread or {}).get("title", "") or "").strip():
                # Its title was just taken from this message: the column is sent again to the socket that sent it.
                await WSHandler._master_send_thread_list(self, ws, pid)
        self._track(self._process_master_message(
            content,
            ws=ws,
            engine=run_engine,
            project_id=pid,
            message_id=str(msg.get("message_id", "") or ""),
            references=references,
            attachments=attachments_read,
            attachment_refs=attachment_refs,
            user_message=msg,
            # The first conversation, named or not, is resolved by the turn as the first conversation.
            thread_id=later_thread,
            channel_id=channel,
        ))

    async def _master_console_session_id(self, engine: Any, project_id: str, thread_id: str = "") -> str:
        """The durable id of a master conversation of this project.

        The conversation is a SessionRecord, found again after a restart by its
        interface marker -- the shape the Secretary page already uses. The
        in-memory map is a cache and is consulted first; a miss looks in the
        store before creating anything, because a lookup that skips straight to
        create is how one conversation silently becomes two.

        总控对话栏 (policy, 第七节): a project may have many conversations. ``thread_id`` names one (its id is
        its session's, :meth:`_master_thread_session_id`); without it this is the project's FIRST conversation -- the
        one every project had before conversations were split. Since there can be several master sessions now, the
        first one is never "whichever the store's get-or-create answers" (that is the most recently touched): it is
        the one the column registered, else the oldest master session not made as a later conversation
        (``master_threads.first_thread_record``); the store's atomic get-or-create is used only while the project has
        no master session at all, so two consoles still make one, not two.

        Returns "" when there is no store to hold one. The caller keeps working
        without a binding rather than inventing an id nothing can resolve.
        """
        from ampuly.application.execution_binding import (
            INTERFACE_KEY,
            MASTER_CONTROL_INTERFACE,
            is_master_control_record,
        )
        from ampuly.core.models import SessionRecord
        from ampuly.i18n_runtime import is_zh
        from ampuly.plugins.office_ui import master_threads as threads

        self._master_session_store_fault = False
        if str(thread_id or "").strip():
            return await WSHandler._master_thread_session_id(self, engine, project_id, thread_id)
        pid = str(project_id or "default")
        cached = self._master_session_ids.get(pid)

        store = getattr(engine, "store", None)
        if store is None:
            self._master_session_store_fault = True
            return ""
        title = "总控" if is_zh() else "Master Control"
        try:
            if cached:
                record = await store.get_session(cached)
                if (record is not None and record.project_id == pid
                        and is_master_control_record(record) and not threads.is_later_thread_record(record)):
                    return cached
                self._master_session_ids.pop(pid, None)
            found: Any = None
            legacy_of = getattr(getattr(self, "chat_store", None), "legacy_master_thread", None)
            registered = await legacy_of(pid) if callable(legacy_of) else None
            if registered:
                # The column names the first conversation: that session, made again under the same id if the
                # project's runtime store no longer has it (a store put back from an older copy).
                found = await store.get_session(str(registered["thread_id"]))
                if found is None:
                    found = SessionRecord(session_id=str(registered["thread_id"]), project_id=pid, title=title,
                                          metadata={INTERFACE_KEY: MASTER_CONTROL_INTERFACE})
                    await store.save_session(found)
                if found.project_id != pid or not is_master_control_record(found):
                    found = None
            if found is None:
                rows = await store.list_sessions(project_id=pid, interface=MASTER_CONTROL_INTERFACE,
                                                 limit=threads.SESSIONS_LOOKED_AT)
                found = threads.first_thread_record(rows)
                if found is None and not rows:
                    found = await store.get_or_create_interface_session(
                        project_id=pid,
                        interface=MASTER_CONTROL_INTERFACE,
                        title=title,
                    )
                    if threads.is_later_thread_record(found):
                        found = None  # a later conversation was made in between; the first one is made below
                if found is None:
                    # Only later conversations so far (the project's first message named none of them): its first
                    # conversation begins now.
                    found = SessionRecord(project_id=pid, title=title,
                                          metadata={INTERFACE_KEY: MASTER_CONTROL_INTERFACE})
                    await store.save_session(found)
        except Exception:
            logger.warning("master control: sessions unreadable; this turn cannot start")
            self._master_session_store_fault = True
            return ""

        session_id = str(getattr(found, "session_id", "") or "")
        self._master_session_store_fault = not bool(session_id)
        if session_id:
            self._master_session_ids[pid] = session_id
        return session_id

    async def _master_thread_session_id(self, engine: Any, project_id: str, thread_id: str) -> str:
        """The session of one named 总控 conversation (总控对话栏): its id is the thread id. A session that belongs to
        another project or to another surface is never borrowed ("" -- the turn cannot start); one the
        project's runtime store no longer has (put back from an older copy) is made again under the same id, so the
        conversation keeps its identity. "" when there is no store to hold one."""
        from ampuly.application.execution_binding import is_master_control_record
        from ampuly.plugins.office_ui import master_threads as threads

        self._master_session_store_fault = False
        pid = str(project_id or "default")
        clean = str(thread_id or "").strip()
        store = getattr(engine, "store", None)
        if store is None or not threads.valid_thread_id(clean):
            self._master_session_store_fault = True
            return ""
        try:
            record = await store.get_session(clean)
            if record is None:
                await store.save_session(threads.new_thread_record(pid, session_id=clean))
                return clean
        except Exception:
            logger.warning("master control: sessions unreadable; this turn cannot start")
            self._master_session_store_fault = True
            return ""
        if record.project_id != pid or not is_master_control_record(record):
            logger.warning("master control: a conversation id named a session that is not this project's 总控")
            self._master_session_store_fault = True
            return ""
        return clean

    # ── 总控对话栏 (policy, 第七节): the conversations of a project, as the column lists them ──
    #
    # master_threads.py says what a conversation is (a master-control session; its words in one channel; its entry in
    # the ``master_threads`` index of ui_state.db). These are the console's side of it: the project's first
    # conversation registered lazily, the four owner-only actions, and the column sent again after any change.
    #
    # The builder-side 安安 panel has no column to pick a conversation from; it works on the project's most recently
    # active conversation that is not archived (``master_threads.latest_thread_id``), which every per-project
    # ``master_thread_list`` reply names as ``latest_thread_id`` for it to send with -- the same answer every time for
    # the same column, never a conversation of another project. A send that names no conversation at all (today's
    # client) is the project's first conversation, archived or not, so an older page keeps working unchanged.

    # A project found to have no old conversation is not looked at again for this long (a listing opens its store file).
    _MASTER_NO_FIRST_RECHECK_SEC = 60.0

    async def _master_register_first_thread(self, project_id: str, session_id: str) -> dict[str, Any] | None:
        """Register the project's first conversation -- its channel ``master:{pid}`` and its session, 「以前的对话」 --
        with the time of its first and last words (now, when it has none yet). Nothing of it is moved or copied."""
        from ampuly.plugins.office_ui.master_control import master_channel_id
        from ampuly.plugins.office_ui.master_threads import LEGACY_TITLE_ZH

        chat_store = self.chat_store
        pid = str(project_id or "default")
        channel = master_channel_id(pid)
        _count, first_at, last_at = await chat_store.master_channel_span(channel, pid)
        return await chat_store.add_master_thread(
            pid, str(session_id), channel_id=channel, title=LEGACY_TITLE_ZH, legacy=True,
            created_at=first_at, last_activity_at=last_at,
        )

    async def _master_first_thread(
        self, engine: Any, project_id: str, *, session_id: str = "", ws: Any = None,
    ) -> dict[str, Any] | None:
        """The project's first conversation in the column; registered here the first time it is used (a turn whose
        message named no conversation, or named the first one) under the session that turn runs on. When it was
        registered just now and ``ws`` is given, the column is sent again to that socket. None when the column cannot
        be kept (a stand-in store) or read now -- the turn still runs."""
        from ampuly.plugins.office_ui import master_threads as threads

        chat_store = getattr(self, "chat_store", None)
        legacy_of = getattr(chat_store, "legacy_master_thread", None)
        if not callable(legacy_of) or not callable(getattr(chat_store, "add_master_thread", None)):
            return None
        pid = str(project_id or "default")
        try:
            found = await legacy_of(pid)
            if found is not None:
                return found
            sid = str(session_id or "").strip()
            store = getattr(engine, "store", None)
            if not sid and store is not None:
                sid = await threads.first_thread_session(store, pid)
            if not sid:
                return None
            row = await WSHandler._master_register_first_thread(self, pid, sid)
        except Exception:  # noqa: BLE001 - the column is display; the turn and its words stand
            logger.opt(exception=True).warning("master control: the first conversation could not be registered")
            return None
        if row is not None and ws is not None:
            await WSHandler._master_send_thread_list(self, ws, pid)
        return row

    async def _master_listed_first_thread(self, project_id: str) -> None:
        """Before a project's conversations are listed: its first conversation takes its place in the column when there
        is an old conversation to show -- a master session in its runtime store (read without loading the project: the
        engine this process already runs, else its store file read-only), or words in ``master:{pid}`` with no session
        left (the session is then made again under the id registered here the next time the conversation is used).
        A project with neither gets no empty 「以前的对话」."""
        from ampuly.plugins.office_ui import master_threads as threads
        from ampuly.plugins.office_ui.master_control import master_channel_id

        chat_store = self.chat_store
        pid = str(project_id or "default")
        if await chat_store.legacy_master_thread(pid) is not None:
            return
        checked = self.__dict__.setdefault("_master_no_first_thread", {})
        if time.monotonic() - float(checked.get(pid, -1e18)) < WSHandler._MASTER_NO_FIRST_RECHECK_SEC:
            return
        sid: str | None = ""
        engines = getattr(self, "_project_engines", None)
        engine = None
        if callable(engines):
            try:
                engine = engines().loaded(pid)
            except Exception:  # noqa: BLE001 - not loaded is read from the file below
                engine = None
        store = getattr(engine, "store", None)
        if store is not None and WSHandler._store_is_ready(store):
            sid = await threads.first_thread_session(store, pid)
        else:
            db_path = WSHandler._gate_retire_unloaded_db(self, pid)
            if db_path is not None:
                sid = await asyncio.to_thread(threads.first_thread_session_readonly, db_path, pid)
        if sid is None:
            return  # the store file could not be read now: not known, looked at again next time
        if not sid:
            count, _first, _last = await chat_store.master_channel_span(master_channel_id(pid), pid)
            if count:
                sid = str(uuid.uuid4())
        if not sid:
            checked[pid] = time.monotonic()
            return
        checked.pop(pid, None)
        await WSHandler._master_register_first_thread(self, pid, sid)

    async def _master_thread_flags(self, project_id: str, first_thread_id: str) -> dict[str, dict[str, bool]]:
        """Per conversation: a build of it working now / waiting on the owner (build mode's job records). {} when build
        mode or its records cannot be read -- no dot is better than a wrong one."""
        from ampuly.plugins.office_ui import master_threads as threads
        from ampuly.plugins.office_ui.master_build import list_jobs

        getter = getattr(self, "_master_build_runner", None)
        if not callable(getter):
            return {}
        try:
            runner = getter()
            jobs = await asyncio.to_thread(list_jobs, runner.host.ampuly_home(), str(project_id or "default"))
        except Exception:  # noqa: BLE001 - display only
            logger.opt(exception=True).debug("master control: build jobs unreadable for the conversation column")
            return {}
        return threads.build_flags(jobs, first_thread_id=first_thread_id, holds=runner.holds)

    async def _master_thread_listing(self, project_id: str, *, limit: int) -> dict[str, Any]:
        """One project's conversations as the column shows them: ``threads`` (contract objects, most recently active
        first, archived ones included and flagged) and ``latest_thread_id`` (the builder-side panel's)."""
        from ampuly.plugins.office_ui import master_threads as threads

        pid = str(project_id or "default")
        try:
            await WSHandler._master_listed_first_thread(self, pid)
        except Exception:  # noqa: BLE001 - listed without it this time; looked for again next time
            logger.opt(exception=True).warning("master control: the first conversation could not be looked for")
        rows = await self.chat_store.list_master_threads(pid, limit=limit)
        legacy = next((row for row in rows if row.get("legacy")), None) or await self.chat_store.legacy_master_thread(pid)
        flags = await WSHandler._master_thread_flags(self, pid, str((legacy or {}).get("thread_id", "") or ""))
        return {
            "threads": [threads.thread_payload(row, flags) for row in rows],
            "latest_thread_id": threads.latest_thread_id(rows),
        }

    async def _master_thread_reply_row(self, project_id: str, row: dict[str, Any]) -> dict[str, Any]:
        """One conversation as a reply carries it, with its build dots."""
        from ampuly.plugins.office_ui import master_threads as threads

        pid = str(project_id or "default")
        legacy = row if row.get("legacy") else await self.chat_store.legacy_master_thread(pid)
        flags = await WSHandler._master_thread_flags(self, pid, str((legacy or {}).get("thread_id", "") or ""))
        return threads.thread_payload(row, flags)

    async def _master_send_thread_list(self, ws: Any, project_id: str) -> None:
        """The project's column, sent again to one socket after a change it caused (a conversation made, renamed,
        archived or brought back, its title taken from its first message, a build's state). Display only."""
        from ampuly.plugins.office_ui import master_threads as threads

        pid = str(project_id or "default")
        if not callable(getattr(getattr(self, "chat_store", None), "list_master_threads", None)):
            return
        try:
            listing = await WSHandler._master_thread_listing(self, pid, limit=threads.LIST_ONE_PROJECT)
        except Exception:  # noqa: BLE001 - the page asks again when it next lists
            logger.opt(exception=True).warning("master control: the conversation column could not be sent")
            return
        await self._send_ack(ws, ok=True, action="master_thread_list", project_id=pid, **listing)

    def _master_thread_project(self, data: dict[str, Any] | None) -> tuple[str, bool]:
        """(project id, whether one was asked for) of a ``master_thread_*`` request; "" when missing or not a project
        id (a later channel's colon never is)."""
        from ampuly.project_id import is_valid_project_id

        raw = str((data or {}).get("project_id") or (data or {}).get("projectId") or "").strip()
        return (raw if is_valid_project_id(raw) else ""), bool(raw)

    async def _master_thread_refusal(self, ws: Any, action: str, data: dict[str, Any]) -> str | None:
        """The project of an owner's ``master_thread_*`` request, or None when it was refused (owner_required /
        project_required, in the style of the other owner actions)."""
        pid, _asked = WSHandler._master_thread_project(self, data)
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action=action, project_id=pid, error="owner_required")
            return None
        if not pid:
            await self._send_ack(ws, ok=False, action=action, project_id=pid, error="project_required")
            return None
        return pid

    async def _handle_master_thread_list(self, ws: Any, data: dict) -> None:
        """总控对话栏: the conversations of one project (``project_id``), or of every project this owner sees (none
        named): the newest 50 of each, archived ones flagged and never dropped. Owner only. Registers a project's first
        conversation the first time it is listed (when it has an old one); changes nothing else."""
        from ampuly.plugins.office_ui import master_threads as threads

        action = "master_thread_list"
        pid, asked = WSHandler._master_thread_project(self, data)
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action=action, project_id=pid, error="owner_required")
            return
        if asked and not pid:
            await self._send_ack(ws, ok=False, action=action, project_id=pid, error="project_required")
            return
        if pid:
            listing = await WSHandler._master_thread_listing(self, pid, limit=threads.LIST_ONE_PROJECT)
            await self._send_ack(ws, ok=True, action=action, project_id=pid, **listing)
            return
        every: list[dict[str, Any]] = []
        latest: dict[str, str] = {}
        for project in await WSHandler._master_thread_projects(self, ws):
            try:
                listing = await WSHandler._master_thread_listing(self, project, limit=threads.LIST_PER_PROJECT)
            except Exception:  # noqa: BLE001 - one unreadable project does not empty the column
                logger.opt(exception=True).warning(f"master control: the conversations of {project!r} could not be listed")
                continue
            every.extend(listing["threads"])
            latest[project] = listing["latest_thread_id"]
        await self._send_ack(ws, ok=True, action=action, project_id="", threads=every, latest_thread_ids=latest)

    async def _master_thread_projects(self, ws: Any) -> list[str]:
        """The projects the column lists when none is named: every project this owner sees (the project list, narrowed
        to the socket's customers); the projects the column already knows when the list cannot be read."""
        from ampuly.project_id import is_valid_project_id

        try:
            listed = await self._ensure_office_services().project.list(active_project_id=None)
            entries = visible_projects_for_scope(self, ws, list(dict(listed.payload or {}).get("projects") or []))
            found = [str(entry.get("id", "") or entry.get("project_id", "") or "") for entry in entries]
        except Exception:  # noqa: BLE001 - the column's own index stands in
            logger.opt(exception=True).warning("master control: the project list could not be read for the column")
            found = list(await self.chat_store.master_thread_projects())
        return [pid for pid in dict.fromkeys(found) if is_valid_project_id(pid)]

    async def _handle_master_thread_create(self, ws: Any, data: dict) -> None:
        """总控对话栏 「新对话」: a new, empty conversation in this project -- a master-control session of its own (marked
        as a later conversation, so it is never taken for the first one) and its own channel. Owner only."""
        from ampuly.i18n_runtime import is_zh
        from ampuly.plugins.office_ui import master_threads as threads
        from ampuly.plugins.office_ui.master_control import master_channel_id

        action = "master_thread_create"
        pid = await WSHandler._master_thread_refusal(self, ws, action, data)
        if pid is None:
            return
        try:
            engine = await self._engine_for_project(pid)
        except Exception:  # noqa: BLE001 - a project that cannot be opened (deleted) gets no conversation
            logger.opt(exception=True).warning(f"master control: no conversation made in {pid!r}; the project cannot be opened")
            await self._send_ack(ws, ok=False, action=action, project_id=pid, error="project_required")
            return
        # The column first knows the project's old conversation, so the new one never hides it.
        try:
            await WSHandler._master_listed_first_thread(self, pid)
        except Exception:  # noqa: BLE001 - looked for again at the next listing
            logger.opt(exception=True).warning("master control: the first conversation could not be looked for")
        record = threads.new_thread_record(pid, title="总控" if is_zh() else "Master Control")
        store = getattr(engine, "store", None)
        if store is not None:
            try:
                await store.save_session(record)
            except Exception:  # noqa: BLE001 - made under the same id the first time the conversation is used
                logger.opt(exception=True).warning("master control: the new conversation's session was not saved yet")
        thread_id = str(record.session_id)
        row = await self.chat_store.add_master_thread(pid, thread_id, channel_id=master_channel_id(pid, thread_id))
        if row is None:
            await self._send_ack(ws, ok=False, action=action, project_id=pid, error="thread_not_found")
            return
        await self._send_ack(ws, ok=True, action=action, project_id=pid,
                             thread=await WSHandler._master_thread_reply_row(self, pid, row))
        await WSHandler._master_send_thread_list(self, ws, pid)

    async def _master_thread_named(self, ws: Any, action: str, data: dict[str, Any]) -> tuple[str, dict[str, Any]] | None:
        """(project, conversation) of a rename / archive: one of this project's conversations, else refused as
        ``thread_not_found`` (another project's, an unknown or malformed id)."""
        pid = await WSHandler._master_thread_refusal(self, ws, action, data)
        if pid is None:
            return None
        thread_id = str(data.get("thread_id", "") or "").strip()
        row = await _master_thread_row(self.chat_store, pid, thread_id)
        if row is None:
            await self._send_ack(ws, ok=False, action=action, project_id=pid, thread_id=thread_id, error="thread_not_found")
            return None
        return pid, row

    async def _handle_master_thread_rename(self, ws: Any, data: dict) -> None:
        """总控对话栏: the owner names a conversation -- plain text, 1 to 60 characters once tidied (``title_invalid``
        otherwise). The first conversation can be renamed too. Owner only."""
        from ampuly.plugins.office_ui.master_threads import ThreadRefused, clean_title

        action = "master_thread_rename"
        named = await WSHandler._master_thread_named(self, ws, action, data)
        if named is None:
            return
        pid, row = named
        try:
            title = clean_title(data.get("title"))
        except ThreadRefused as refused:
            await self._send_ack(ws, ok=False, action=action, project_id=pid, thread_id=row["thread_id"], error=refused.code)
            return
        renamed = await self.chat_store.rename_master_thread(pid, str(row["thread_id"]), title) or row
        await self._send_ack(ws, ok=True, action=action, project_id=pid,
                             thread=await WSHandler._master_thread_reply_row(self, pid, renamed))
        await WSHandler._master_send_thread_list(self, ws, pid)

    async def _handle_master_thread_archive(self, ws: Any, data: dict) -> None:
        """总控对话栏: put a conversation away under 「已归档」 (``archived: true``) or bring it back (``false``). Nothing
        of it is deleted; an archived conversation takes no new message until it is brought back. Owner only."""
        action = "master_thread_archive"
        named = await WSHandler._master_thread_named(self, ws, action, data)
        if named is None:
            return
        pid, row = named
        raw = data.get("archived", True)
        archived = raw if isinstance(raw, bool) else str(raw).strip().lower() not in {"", "0", "false", "no", "off"}
        changed = await self.chat_store.archive_master_thread(pid, str(row["thread_id"]), archived) or row
        await self._send_ack(ws, ok=True, action=action, project_id=pid,
                             thread=await WSHandler._master_thread_reply_row(self, pid, changed))
        await WSHandler._master_send_thread_list(self, ws, pid)

    async def _master_bind_execution(
        self,
        engine: Any,
        console_session_id: str,
        binding: Any,
    ) -> None:
        """Record which execution session this conversation is now driving.

        Written into the conversation's own SessionRecord -- the store that
        already owns it -- rather than a second table, and everything else in
        that record is carried through untouched. A failure here is logged and
        does not take the turn down: the turn still ran, and a binding that
        could not be written is a lost pointer, not a lost answer.
        """
        from ampuly.application.execution_binding import with_binding

        store = getattr(engine, "store", None)
        if store is None or not console_session_id:
            return
        try:
            record = await store.get_session(console_session_id)
            if record is None:
                logger.warning("master control: the conversation row is gone; execution binding not recorded")
                return
            record.metadata = with_binding(dict(getattr(record, "metadata", {}) or {}), binding)
            await store.save_session(record)
        except Exception:
            logger.opt(exception=True).warning("master control: could not record the execution binding")

    async def _master_harness_session(
        self,
        engine: Any,
        provider: Any,
        scope: Any,
        task: Any,
        console_session_id: str,
        budget_id: str = "",
    ) -> str:
        from ampuly.plugins.office_ui.master_harness_session import open_master_harness_session

        return await open_master_harness_session(
            self, engine, provider, scope, task, console_session_id, budget_id,
        )

    async def _master_loop_turn(
        self,
        content: str,
        *,
        ws: Any,
        engine: Any,
        project_id: str,
        console_session_id: str,
        message_id: str = "",
        history: list[dict[str, str]] | None = None,
        thread_id: str = "",
        preprocess: Any = None,
    ) -> tuple[Any, Any]:
        """One master-control turn: existing runtime loop, provider claim and console writes.

        Returns the turn and the delegate that performed its writes (a TaskResult
        carries no receipts).
        """
        from ampuly.layer3_agent.harness import HarnessScope
        from ampuly.plugins.office_ui.master_loop import (
            MasterConsoleActions,
            MasterLoopFailed,
            loop_system_prompt,
        )
        from ampuly.plugins.office_ui.master_runtime import (
            MasterTurn,
            MasterSafetyStop,
            build_agent,
            build_tool_registry,
            conversation_so_far,
            instruct,
            master_task,
            workspace_for,
            customer_for,
        )

        pid = str(project_id or "default")
        llm = getattr(engine, "llm", None)
        if llm is None:
            raise RuntimeError("engine has no llm")
        # Never the process's working directory, which for a console server is
        # the product's own source tree.
        business = self._accounts().business
        customer_id = await customer_for(business, pid)
        workspace = workspace_for(engine, project_id=pid, customer_id=customer_id)

        task = self._master_loop_tasks.get(pid)
        if task is None or str(getattr(task, "session_id", "") or "") != console_session_id:
            task = master_task(
                project_id=pid,
                console_session_id=console_session_id,
                workspace_root=workspace,
                customer_id=customer_id,
            )
            task.metadata["ampuly_home"] = str(engine.ampuly_home)
            self._master_loop_tasks[pid] = task
        elif str((task.metadata or {}).get("customer_id", "") or "") != customer_id:
            raise MasterSafetyStop("Master conversation customer changed; refusing to reuse its memory")

        # The managed route allocates its own attempt budget under admission;
        # pre-binding would look like a changed task contract.
        managed_factory = getattr(engine, "_managed_master_attempt_factory", None)
        task.metadata["execution_source"] = "direct_task"
        budget_id = ""
        if managed_factory is None:
            from ampuly.plugins.office_ui.direct_task_scope import apply_direct_source, bind_direct_task_budget

            actor = str((_ws_owner_actor(self, ws) or {}).get("login", "") or "")
            budget_id = bind_direct_task_budget(
                engine=engine,
                project_id=pid,
                actor=actor,
                customer_id=str((task.metadata or {}).get("customer_id", "") or ""),
                environment_id=str((task.metadata or {}).get("environment_id", "") or ""),
            )
            task.metadata.update(apply_direct_source(
                task, project_id=pid, workspace_root=workspace, budget_id=budget_id))

        actions = MasterConsoleActions(
            self,
            ws=ws,
            engine=engine,
            project_id=pid,
            message_id=message_id,
            business=self._accounts().business,
            console_session_id=console_session_id,
            thread_id=thread_id,
        )
        # From here on a failure carries the delegate with it: what the loop
        # already wrote decides whether falling back is safe.
        try:
            # The tracker is what makes the spend visible; the task row is what
            # keeps its cost rows inside the project total that master control
            # reports. Neither works without the other.
            from ampuly.plugins.office_ui.master_runtime import ensure_master_task_row

            if not await ensure_master_task_row(getattr(engine, "store", None), task):
                raise MasterSafetyStop("Master control accounting unavailable; model call not started")
            if managed_factory is not None:
                from ampuly.plugins.office_ui.master_managed_entry import run_managed_master_turn
                managed_turn = await run_managed_master_turn(
                    factory=managed_factory, engine=engine, business=business, task=task,
                    scope=HarnessScope(project_id=pid, workspace_path=workspace, customer_id=customer_id),
                    actions=actions, content=content, history=history, preprocess=preprocess,
                )
                return managed_turn, actions
            if preprocess is not None:
                content = await preprocess(task, content)
            agent = build_agent(
                llm, build_tool_registry(actions), loop_system_prompt(),
                cost_tracker=getattr(engine, "cost_tracker", None),
                event_store=getattr(engine, "store", None),
                # policy (B0): the turn used to see only this message. What was said before comes from the
                # console's stored rows, bounded; the runtime keeps no transcript for this loop (conversation_so_far).
                conversation=conversation_so_far(history, content),
            )
            provider = engine._native_harness_provider(agent)
            if provider is None:
                raise RuntimeError("no harness registry; a looped turn would leave no record")

            from ampuly.i18n_runtime import is_zh
            from ampuly.plugins.office_ui.master_harness_session import (
                MasterHarnessResumeBlocked,
                claim_master_flight,
                release_master_flight,
                steer_live_master_turn,
                steer_open_flight,
            )

            flight_key = f"{pid}\x1f{console_session_id}"
            owner, flight = await claim_master_flight(self, flight_key)
            owned_flight = flight if owner else None

            def _steered_turn(bound_session: str, steered: bool) -> tuple[Any, Any]:
                if steered:
                    notice = (
                        "这条消息已排入正在进行的回合，会在下一步处理；沿用当前会话和预算。"
                        if is_zh() else
                        "Queued for the open turn's next step, within its current session and budget."
                    )
                else:
                    notice = (
                        "当前回合已无法接收这条消息；请等回合结束后重发。没有另开会话。"
                        if is_zh() else
                        "The current turn could not accept this message. Please resend after it ends; no new session was opened."
                    )
                return MasterTurn(reply=notice, harness_session_id=bound_session), actions

            scope = HarnessScope(project_id=pid, workspace_path=workspace, customer_id=customer_id)
            session_id = ""
            try:
                if not owner:
                    await flight.ready.wait()
                    if flight.session_id and not flight.finished.is_set():
                        return _steered_turn(
                            flight.session_id, await steer_open_flight(flight, content),
                        )
                    if flight.blocked_reason:
                        raise MasterSafetyStop(
                            f"master harness resume {flight.blocked_reason}; binding kept, no replacement session"
                        )
                    owner, flight = await claim_master_flight(self, flight_key)
                    if not owner:
                        await flight.ready.wait()
                        if flight.session_id and not flight.finished.is_set():
                            return _steered_turn(
                                flight.session_id, await steer_open_flight(flight, content),
                            )
                        raise MasterSafetyStop(
                            "master turn is already in flight; no replacement session"
                        )
                    owned_flight = flight
                try:
                    session_id = await self._master_harness_session(
                        engine, provider, scope, task, console_session_id, budget_id=budget_id,
                    )
                except MasterHarnessResumeBlocked as blocked:
                    flight.blocked_reason = blocked.reason
                    flight.session_id = blocked.harness_session_id
                    if blocked.reason == "busy" and await steer_live_master_turn(
                        engine, blocked.harness_session_id, content,
                    ):
                        return _steered_turn(blocked.harness_session_id, True)
                    raise MasterSafetyStop(
                        f"master harness resume {blocked.reason}; binding kept, no replacement session"
                    ) from blocked
                flight.session_id = session_id
                flight.provider = provider
                provider.adopt_task(session_id, task)
                # An adopted task keeps its own description: the provider stamps
                # the session on and sets nothing else. Without this the turn
                # answers the previous question and looks entirely healthy.
                instruct(task, content)
                from types import SimpleNamespace

                active_turn_id = ""

                async def on_master_event(event: Any) -> None:
                    nonlocal active_turn_id
                    if event.event_type == "turn_started" and event.session_id == session_id:
                        active_turn_id = str(event.turn_id or "")
                        flight.turn_id = active_turn_id
                        flight.provider = provider
                        flight.ready.set()
                        await actions.notify_turn_state(session_id, "starting", turn_id=active_turn_id)

                # policy (B0): 插话 on this turn. engine.harness_steer_turn finds the turn's provider here, and
                # harness_turn_is_live tells the console the turn runs in this process (so it is interrupted, never
                # settled) -- the same two markers a worker turn and the managed master set. Held for exactly the life of
                # the turn: removed however it ends, finished, failed or cancelled.
                live_turns = engine.__dict__.setdefault("_harness_live_turns", set())
                live_providers = engine.__dict__.setdefault("_harness_live_providers", {})
                live_turns.add(session_id)
                live_providers[session_id] = provider
                try:
                    result = await provider.start_turn(
                        session_id,
                        str(getattr(task, "description", "") or ""),
                        inputs={"task_id": str(getattr(task, "id", "") or ""), "budget_id": budget_id},
                        callbacks=SimpleNamespace(on_event=on_master_event),
                    )
                finally:
                    live_turns.discard(session_id)
                    if live_providers.get(session_id) is provider:
                        live_providers.pop(session_id, None)
                    await actions.notify_turn_state(session_id, "returned", turn_id=active_turn_id)
            finally:
                if owned_flight is not None:
                    await release_master_flight(self, flight_key, owned_flight)
            raw_status = getattr(result, "status", "")
            status = str(getattr(raw_status, "value", raw_status) or "")
            if status == "cancelled":
                raise MasterSafetyStop("Master turn was cancelled; no fallback model call will be made")
            if status and status != "done":
                # The iteration bound is what this usually is: a whole bound
                # of paid calls (DEFAULT_MAX_ITERATIONS) and no answer. The
                # runtime says so in the content, which is a sentence for a
                # log and not for the owner -- so it becomes a failure, and
                # the caller decides what the owner is told.
                raise RuntimeError(
                    str(getattr(result, "content", "") or "").strip()
                    or f"the looped turn ended {status}"
                )
        except MasterLoopFailed:
            raise
        except Exception as loop_error:
            raise MasterLoopFailed(
                str(loop_error) or type(loop_error).__name__, actions,
            ) from loop_error

        return (
            MasterTurn(
                reply=str(getattr(result, "content", "") or ""),
                tool_calls=[dict(call) for call in actions.calls],
                # The runtime does not report how many iterations it took, so
                # this stays zero rather than carrying a number we invented.
                iterations=0,
                harness_session_id=session_id,
            ),
            actions,
        )

    async def _restate_master_attachments(
        self, user_message: dict[str, Any] | None, attachments: list[dict[str, Any]], *, project_id: str,
    ) -> None:
        """The owner's message, restated with what the vision model read: its status line changes in place."""
        from ampuly.plugins.office_ui.master_attachments import attachment_summary

        if not user_message or not user_message.get("message_id"):
            return
        metadata = {**dict(user_message.get("metadata") or {}), "attachments_read": attachment_summary(attachments)}
        try:
            if await self.chat_store.update_message_metadata(str(user_message["message_id"]), metadata, project_id=project_id):
                await self.broadcast({"type": "session_message", "payload": {**user_message, "metadata": metadata}})
        except Exception as exc:  # the turn still has the reading; only the status line under the message is stale
            logger.warning(f"master control: attachment status not restated ({type(exc).__name__})")

    async def _settle_left_master_attachments(self, project_id: str) -> None:
        """P-f : files a stopped console left 排队 / 解析中 under an owner's message are settled, once per
        project and start, when its conversation is first read (``_handle_collab_sync``).

        The status of a file being read lived only in this process; after a restart it said 排队 or 解析中 forever, with
        a 取消 button. A file of a message stored before this process started, that no turn here holds
        (``master_vision.working_on``), is settled as interrupted -- a queued one never sent and not billed, one being
        read of unknown outcome and possibly billed (``master_vision.settle_stored``) -- and the message is restated in
        place. A conversation that cannot be read is looked at again at the next read. Nothing is sent anywhere.
        """
        from ampuly.plugins.office_ui import master_vision

        pid = str(project_id or "default").strip() or "default"
        chat_store = getattr(self, "chat_store", None)
        done = getattr(self, "_master_attachments_settled", None)
        if done is None:
            done = self._master_attachments_settled = set()
        if pid in done or chat_store is None:
            return
        done.add(pid)
        try:
            messages = await _master_messages_left_reading(chat_store, pid)
        except Exception as exc:
            done.discard(pid)
            logger.debug(f"master control: files left reading could not be looked for in {pid!r} ({type(exc).__name__})")
            return
        for message in messages:
            try:
                stored_at = float(message.get("created_at") or 0)
            except (TypeError, ValueError):
                continue
            if stored_at >= master_vision.PROCESS_STARTED_AT:
                continue  # stored by this process: its own turn restates it
            message_id = str(message.get("message_id", "") or "")
            stored = [dict(item) for item in list((message.get("metadata") or {}).get("attachments_read") or [])
                      if isinstance(item, dict)]
            if master_vision.settle_stored(stored, None, interrupted=True,
                                           still_live=lambda attachment_id: master_vision.working_on(pid, message_id, attachment_id)):
                logger.info(f"master control: files left reading under message {message_id[:8]} settled as interrupted")
                await WSHandler._restate_master_attachments(self, message, stored, project_id=pid)

    async def _handle_master_attachment_cancel(self, ws: Any, data: dict) -> None:
        """安安 · 看图 (4.7 A13): stop reading one file sent to 总控; nothing it read is given to the model.

        A queued file is never sent (no charge); one whose request is out is said to be possibly billed. A file whose
        stored status still says queued / reading while nothing here works on it (a restart mid-turn) is settled as
        cancelled. The status line under the message is what the owner sees; the ack is for scripts. The message is
        found by its id however far back it is (P-f: only the newest 200 rows were looked at).
        """
        from ampuly.plugins.office_ui import master_vision

        pid = self._request_project_id(data)
        message_id = str(data.get("message_id", "") or "").strip()
        attachment_id = str(data.get("attachment_id", "") or "").strip()
        if not message_id or not attachment_id:
            await self._send_ack(ws, ok=False, action="master_attachment_cancel", project_id=pid,
                                 error="message_id_and_attachment_id_required")
            return
        state = await master_vision.cancel(pid, message_id, attachment_id)
        # A file a turn here still holds (its answer just came back) is restated by that turn; settling the stored
        # copy now would say 已取消 and be overwritten with 完成 a moment later.
        if not state and not master_vision.working_on(pid, message_id, attachment_id):
            try:
                message = await _master_message_by_id(self.chat_store, pid, message_id)
            except Exception as exc:
                logger.warning(f"master control: attachment cancel could not read the message ({type(exc).__name__})")
                message = None
            stored = [dict(item) for item in list(((message or {}).get("metadata") or {}).get("attachments_read") or [])
                      if isinstance(item, dict)]
            if message is not None and master_vision.settle_stored(stored, attachment_id):
                state = "settled"
                await self._restate_master_attachments(message, stored, project_id=pid)
        await self._send_ack(
            ws, ok=bool(state), action="master_attachment_cancel", project_id=pid, message_id=message_id,
            attachment_id=attachment_id, cancelled=state, **({} if state else {"error": "not_running"}),
        )

    async def _handle_master_attachment_page(self, ws: Any, data: dict) -> None:
        """来源定位 (4.7 A13): one page of a file sent to 总控, for the side panel a reply's 「来自：…」 opens.

        Only a file some message of one of this project's 总控 conversations carried can be shown (found by its id,
        newest message first, whichever conversation it was sent in -- 总控对话栏); it is read from the project's
        attachment store, off the event loop, and nothing is sent anywhere else.
        """
        from ampuly.plugins.office_ui.master_attachments import page_preview
        from ampuly.core.attachment_store import AttachmentRef

        run_engine, pid = await self._engine_for_request(data)
        attachment_id = str(data.get("attachment_id", "") or "").strip()
        try:
            page = max(0, int(data.get("page", 0) or 0))
        except (TypeError, ValueError):
            page = 0
        reply = {"action": "master_attachment_page", "project_id": pid, "attachment_id": attachment_id, "page": page}
        if not attachment_id:
            await self._send_ack(ws, ok=False, error="attachment_id_required", **reply)
            return
        try:
            # Any of the project's 总控 conversations (总控对话栏): the file is found by its own id, newest message first.
            rows = await _master_messages_with_attachment(self.chat_store, pid, attachment_id)
        except Exception as exc:
            logger.warning(f"master control: attachment page could not read the conversation ({type(exc).__name__})")
            rows = []
        ref = next((
            item for row in rows
            for item in list(((row.get("metadata") or {}) if isinstance(row, dict) else {}).get("attachment_refs") or [])
            if isinstance(item, dict) and str(item.get("attachment_id", "") or "") == attachment_id
        ), None)
        ensure_store = getattr(run_engine, "_ensure_attachment_store", None)
        if callable(ensure_store):
            try:
                ensure_store()
            except Exception as exc:
                logger.warning(f"master control: attachment store for {pid!r} unavailable: {exc}")
        store = getattr(run_engine, "attachment_store", None)
        if ref is None or store is None:
            await self._send_ack(ws, ok=False, error="not_found", **reply)
            return
        try:
            raw = await asyncio.to_thread(store.read_bytes, AttachmentRef.from_dict(ref))
            preview = await asyncio.to_thread(
                page_preview, raw, filename=str(ref.get("filename", "") or ""),
                mime_type=str(ref.get("mime_type", "") or ""), page=page,
            )
        except Exception as exc:
            logger.warning(f"master control: attachment page not read ({type(exc).__name__})")
            await self._send_ack(ws, ok=False, error="unreadable", **reply)
            return
        await self._send_ack(ws, ok=True, preview=preview, **reply)

    async def _process_master_message(
        self,
        content: str,
        *,
        ws: Any,
        engine: Any,
        project_id: str,
        message_id: str = "",
        references: list[dict[str, Any]] | None = None,
        attachments: list[dict[str, Any]] | None = None,
        attachment_refs: list[dict[str, Any]] | None = None,
        user_message: dict[str, Any] | None = None,
        thread_id: str = "",
        channel_id: str = "",
    ) -> None:
        """Run one master-control turn: LLM reply + optional order dispatch.

        总控对话栏 (policy, 第七节): the turn belongs to one conversation -- ``thread_id`` (a later one, its
        rows in ``channel_id``) or, without it, the project's first conversation (``master:{pid}``, registered in the
        column here the first time it is used). It reads that conversation's rows as its memory, runs on that
        conversation's session (so its execution binding and build jobs are that conversation's), answers into it, and
        moves its last activity on.
        """
        from ampuly.i18n_runtime import is_zh
        from ampuly.plugins.office_ui.master_attachments import attachments_context
        from ampuly.plugins.office_ui.master_control import master_channel_id, process_master_message
        from ampuly.plugins.office_ui.master_loop import loop_enabled as master_loop_enabled
        # Q2-WS-A readiness refusal imports remember_unfinished_master_goal
        # inside the admission branch below (not at module top).
        from ampuly.plugins.office_ui.master_references import references_context

        # The model reads the owner's words plus what they pointed at and sent; the bare-decision check below reads
        # only the words, so a reference or a file never turns "批准" into something else.
        blocks = [
            block for block in (
                references_context(list(references or []), zh=is_zh()),
                attachments_context(list(attachments or []), zh=is_zh()),
            ) if block
        ]
        turn_content = "\n\n".join([content, *blocks]) if blocks else content
        pid = project_id
        thread_id = str(thread_id or "").strip()
        channel = str(channel_id or "").strip() or master_channel_id(pid, thread_id)
        # The conversation's entry in the column, once known: the named one, or the first one once registered below.
        index_thread = thread_id
        sender_name = "总控" if is_zh() else "Master Control"

        async def _reply(text: str, sender: str = "assistant", metadata: dict | None = None) -> None:
            from .flow_draft_resume import stamp_flow_metadata
            reply_id = str(uuid.uuid4())
            metadata = stamp_flow_metadata(metadata, project_id=pid, message_id=reply_id)
            if attachments:
                # 安安 · 看图 (4.7 A13): a file still shown as waiting when the turn answers was never read (the turn
                # stopped first); and a reply that cites a file it read carries the file and page to open (来自：…).
                from ampuly.plugins.office_ui import master_vision
                from ampuly.plugins.office_ui.master_attachments import cited_sources

                if master_vision.settle_unfinished(attachments):
                    await self._restate_master_attachments(user_message, attachments, project_id=pid)
                sources = cited_sources(text, attachments, attachment_refs, zh=is_zh()) if sender == "assistant" else []
                if sources:
                    metadata = {**(metadata or {}), "attachment_sources": sources}
                # 4.9-A02: every reply to a message with files names the files it did not (fully) read, by the
                # product and not by the model's say-so.
                from ampuly.plugins.office_ui.master_attachments import unread_attachments, with_unread_disclosure

                unread_rows = unread_attachments(attachments, zh=is_zh())
                if unread_rows:
                    text = with_unread_disclosure(text, attachments, zh=is_zh())
                    metadata = {**(metadata or {}), "attachment_unread": unread_rows}
            reply_msg = await self.chat_store.insert_message(
                message_id=reply_id,
                channel_id=channel,
                sender=sender,
                sender_name=sender_name,
                content=text,
                metadata=metadata,
                project_id=pid,
            )
            if index_thread:
                await _master_thread_touch(self.chat_store, pid, index_thread, at=reply_msg.get("created_at"))
            await self.broadcast({"type": "session_message", "payload": reply_msg})

        try:
            bare_decision = content.strip().lower().strip("。.!！?？ \t\r\n")
            if bare_decision in {"approve", "deny", "批准", "拒绝", "放行", "打回", "同意", "确认"}:
                from ampuly.plugins.office_ui.master_control import build_system_context
                decision_context = await build_system_context(
                    engine, pid, business=self._accounts().business,
                )
                pending_ids = {
                    str(item.get("checkpoint_id", "") or "")
                    for item in decision_context.get("pending_checkpoints", [])
                    if item.get("checkpoint_id")
                }
                if len(pending_ids) > 1:
                    await _reply(
                        "当前有多个待处理事项，请在审批中心选择具体目标，或明确提供目标编号；本次未执行任何审批。"
                        if is_zh() else
                        "Several decisions are pending. Select a target in Approvals or specify its ID; no approval was performed."
                    )
                    return
            raw_history = await self.chat_store.get_channel_messages(channel, limit=24, project_id=pid)
            history = master_history_rows(raw_history)
            llm = getattr(engine, "llm", None)
            if llm is None:
                await _reply("引擎尚未就绪（无 LLM），请稍后再试。" if is_zh() else "Engine LLM is not ready yet.", sender="system")
                return
            # The conversation this turn belongs to. Resolved before the turn
            # so a binding has somewhere to live, and so the context can say
            # whether the conversation is durable instead of implying it.
            if thread_id:
                console_session_id = await self._master_console_session_id(engine, pid, thread_id=thread_id)
            else:
                console_session_id = await self._master_console_session_id(engine, pid)
                if console_session_id:
                    # 总控对话栏: the project's first conversation takes its place in the column the first time it
                    # is used (「以前的对话」), with the time of what was just said as its last activity.
                    first = await WSHandler._master_first_thread(self, engine, pid, session_id=console_session_id, ws=ws)
                    if first:
                        index_thread = str(first.get("thread_id", "") or "")
                        await _master_thread_touch(self.chat_store, pid, index_thread,
                                                   at=(user_message or {}).get("created_at"))
            # File recognition runs only after the consuming path has bound
            # its actual task and budget (native, managed, or single-turn).
            async def _prepare_attachments(task: Any, current_content: str) -> str:
                if not attachments or not attachment_refs:
                    return current_content
                from ampuly.plugins.office_ui import master_vision

                async def _vision_progress() -> None:
                    await self._restate_master_attachments(user_message, attachments, project_id=pid)

                if await master_vision.apply(
                    engine, project_id=pid, session_id=console_session_id, business=self._accounts().business,
                    attachments=attachments, attachment_refs=attachment_refs, budget_task=task,
                    message_id=message_id, on_progress=_vision_progress,
                ):
                    blocks = [block for block in (
                        references_context(list(references or []), zh=is_zh()),
                        attachments_context(list(attachments or []), zh=is_zh()),
                    ) if block]
                    await self._restate_master_attachments(user_message, attachments, project_id=pid)
                    return "\n\n".join([content, *blocks]) if blocks else content
                return current_content

            # The multi-step turn, unless the owner has switched it off, and
            # only when this installation can actually record one. On by
            # default (owner's decision): the loop has the
            # tools A02 needs, a ten-iteration cap, and every call is shown.
            # A failure of that turn does not start the single-call path.
            if (
                master_loop_enabled()
                and console_session_id
                and getattr(engine, "harness_registry", None) is not None
            ):
                # Q2-WS-B + unlabeled expand: explicit marker OR high-precision
                # delivery-shaped heuristic routes to run_no_flow_direct_chain
                # before the model loop. Chat questions / vague asks fall through.
                # Only reached when multi-step is ready; WS-A not-ready unchanged.
                from ampuly.plugins.office_ui.no_flow_direct_chain import (
                    parse_no_flow_master_candidate,
                    route_no_flow_master_directive_if_eligible,
                )

                if parse_no_flow_master_candidate(content) is not None:
                    from ampuly.plugins.office_ui.artifacts_service import (
                        workspace_root_for_project,
                    )
                    from ampuly.plugins.office_ui.master_runtime import (
                        MasterSafetyStop,
                        customer_for,
                    )

                    owner = _ws_owner_actor(self, ws) or {}
                    actor = str(owner.get("login", "") or "")
                    routed: dict[str, Any] | None
                    try:
                        workspace = workspace_root_for_project(engine, pid)
                    except Exception:
                        workspace = None
                    try:
                        business = self._accounts().business
                    except Exception:
                        business = None
                    try:
                        customer_id = (
                            await customer_for(business, pid)
                            if workspace is not None
                            else ""
                        )
                    except MasterSafetyStop:
                        routed = {
                            "ok": False,
                            "eligible": True,
                            "refused": True,
                            "code": "no_flow_customer_unavailable",
                            "consult_started": False,
                        }
                    else:
                        if workspace is None:
                            routed = {
                                "ok": False,
                                "eligible": True,
                                "refused": True,
                                "code": "no_flow_workspace_missing",
                                "consult_started": False,
                            }
                        else:
                            routed = await route_no_flow_master_directive_if_eligible(
                                content=content,
                                ampuly_home=getattr(engine, "ampuly_home", "") or "",
                                store=getattr(engine, "store", None),
                                project_id=pid,
                                actor=actor,
                                workspace_root=workspace,
                                customer_id=customer_id,
                                session_id=console_session_id,
                                message_id=message_id,
                                attachments=list(attachments or []),
                            )
                    if routed is not None:
                        code = str(routed.get("code", "") or "")
                        path_text = str(routed.get("workspace_file", "") or "")
                        task_id = str(routed.get("task_id", "") or "")
                        if routed.get("ok"):
                            if is_zh():
                                notice = (
                                    "无 flow 直接交付已记录。"
                                    + (f" 文件：{path_text}" if path_text else "")
                                    + (f" 任务：{task_id}" if task_id else "")
                                    + " 未发起模型咨询。"
                                )
                            else:
                                notice = (
                                    "No-flow direct delivery recorded."
                                    + (f" File: {path_text}" if path_text else "")
                                    + (f" Task: {task_id}" if task_id else "")
                                    + " No model consult was started."
                                )
                        else:
                            if is_zh():
                                notice = (
                                    f"无 flow 直接交付未完成（{code or 'refused'}）。"
                                    "未发起模型咨询，也未退回多步环。"
                                )
                            else:
                                notice = (
                                    f"No-flow direct delivery did not complete ({code or 'refused'}). "
                                    "No model consult was started and the multi-step loop was not used."
                                )
                        await _reply(
                            notice,
                            metadata={
                                "type": "no_flow_direct_delivery",
                                "ok": bool(routed.get("ok")),
                                "code": code,
                                "task_id": task_id,
                                "workspace_file": path_text,
                                "consult_started": bool(routed.get("consult_started")),
                            },
                        )
                        return

                try:
                    turn, loop_actions = await self._master_loop_turn(
                        turn_content,
                        ws=ws,
                        engine=engine,
                        project_id=pid,
                        console_session_id=console_session_id,
                        message_id=message_id,
                        history=history,
                        thread_id=thread_id,
                        preprocess=_prepare_attachments,
                    )
                except Exception as loop_error:
                    from ampuly.plugins.office_ui.master_runtime import fallback_forbidden
                    if fallback_forbidden(loop_error):
                        await _reply(
                            "执行已停止：预算、凭据、权限或会话范围校验未通过。不会切换执行路径重试。"
                            if is_zh() else
                            "Execution stopped: budget, credentials, permissions or session scope "
                            "could not be verified. No fallback or retry was started."
                        )
                        return
                    # The owner is told the turn stopped. A second model call
                    # would be a different executor spending the same ask.
                    logger.opt(exception=True).warning(f"Master control loop failed; no single-call consult: {loop_error}")
                    performed = getattr(loop_error, "actions", None)
                    receipts = list(getattr(performed, "receipts", []) or [])
                    # "May a write have happened", not "did one finish". A
                    # write cancelled between entering the handler and
                    # returning leaves the effect done and no receipt, and
                    # order creation carries no idempotency key to catch the
                    # duplicate a retry would make.
                    may_have_written = bool(
                        performed is not None
                        and getattr(performed, "may_have_written", lambda: bool(receipts))()
                    )
                    if may_have_written:
                        # Something already ran, or may have. Re-asking the
                        # single-call path with the same message could
                        # dispatch the same order twice, so it does not run:
                        # the owner gets whatever receipts exist and is told
                        # the turn stopped early.
                        stopped = (
                            f"⚠️ 多步执行中断了（{loop_error}）。下面这些动作已经执行，本次不再重跑，也没有改走单次问答。"
                            if is_zh() else
                            f"⚠️ The multi-step turn stopped early ({loop_error}). What it already did is "
                            "below; it is not being retried and no single-call consult was started."
                        )
                        # policy (M1): a work order the turn drafted before it broke is linked from here as on
                        # a finished reply -- the order in 业务工单, not a session.
                        stopped_metadata: dict[str, Any] = (
                            {"type": "master_order_drafted",
                             "order_id": getattr(performed, "drafted_order_id", "")}
                            if getattr(performed, "drafted_order_id", "")
                            else {}
                        )
                        if getattr(performed, "connector_candidates", None):
                            # A candidate drafted before the turn broke is named here too, as on a finished reply,
                            # so the flow-draft card that asked for it shows it drafted (lib/flowDraft.ts).
                            stopped_metadata["master_connector_candidates"] = list(performed.connector_candidates)
                        await _reply(
                            (stopped + ("\n\n" + "\n".join(receipts) if receipts else "")).strip(),
                            metadata=stopped_metadata or None,
                        )
                        return
                    from ampuly.plugins.office_ui.master_runtime import remember_unfinished_master_goal

                    stored = await remember_unfinished_master_goal(
                        getattr(engine, "store", None),
                        self._master_loop_tasks.get(pid),
                        goal=content,
                        reason=str(loop_error),
                    )
                    notice = (
                        f"⚠️ 多步执行没能完成（{loop_error}）。原目标已保留，没有改走单次问答，也没有再发起模型请求。"
                        if is_zh() else
                        f"⚠️ The multi-step turn did not complete ({loop_error}). The original goal was kept. "
                        "No single-call consult was started and no further model request was made."
                    )
                    if not stored:
                        notice += (
                            "\n\n原目标这次没能写入恢复记录。"
                            if is_zh() else
                            "\n\nThe original goal could not be stored for recovery."
                        )
                    await _reply(notice)
                    return
                else:
                    looped_text = str(turn.reply or "").strip()
                    from ampuly.plugins.office_ui.master_control import unbacked_claims

                    corrections = unbacked_claims(looped_text, list(getattr(loop_actions, "_attempted", []) or []), zh=is_zh())
                    if loop_actions.receipts:
                        looped_text = (looped_text + "\n\n" + "\n".join(loop_actions.receipts)).strip()
                    if corrections:
                        looped_text = (looped_text + "\n\n" + "\n".join(corrections)).strip()
                    # The durable record of what this reply looked at and did:
                    # names and read/write only. The live strip is ephemeral
                    # by design; this is what survives a reload.
                    reply_metadata: dict[str, Any] = {}
                    if getattr(loop_actions, "drafted_order_id", ""):
                        # The drafted work order, by id only here (its receipt names it by title): 总控 links the order
                        # in 业务工单 from this (MasterControlPage draftedOrderId).
                        reply_metadata.update({"type": "master_order_drafted", "order_id": loop_actions.drafted_order_id})
                    if getattr(loop_actions, "node_proposal", None):
                        # Previewed on the builder canvas from this reply; the owner applies and saves it there.
                        reply_metadata["master_node_proposal"] = loop_actions.node_proposal
                    if getattr(loop_actions, "flow_draft", None):
                        # 需求 → 流程草案: shown as a card; "在搭建台打开" recompiles it from this stored spec.
                        reply_metadata["master_flow_draft"] = loop_actions.flow_draft
                    if getattr(loop_actions, "connector_candidates", None):
                        # The candidate this reply drafted, by id: the receipt says it in words only, and the flow-draft
                        # card links its placeholder to the candidate from here (lib/flowDraft.ts componentAskStates).
                        reply_metadata["master_connector_candidates"] = list(loop_actions.connector_candidates)
                    if getattr(loop_actions, "component_candidates", None):
                        reply_metadata["master_component_candidates"] = list(loop_actions.component_candidates)
                    if getattr(loop_actions, "flow_draft_resume", None):
                        reply_metadata["master_flow_draft_resume"] = loop_actions.flow_draft_resume
                    if getattr(loop_actions, "build_jobs", None):
                        # 总控施工模式 (B1): the build this reply started or continued, by id only; its own card is a
                        # message of its own (master_build.py), which this reply's page can find by the id.
                        reply_metadata["master_build_jobs"] = list(loop_actions.build_jobs)
                    recorded_calls = [
                        {"name": str(call.get("name", "") or ""), "writes": bool(call.get("writes"))}
                        for call in list(loop_actions.calls or [])
                        if str(call.get("name", "") or "")
                    ]
                    if recorded_calls:
                        reply_metadata["master_tool_calls"] = recorded_calls
                    if corrections:
                        reply_metadata["master_unbacked_claims"] = len(corrections)
                    await _reply(
                        looped_text or ("（无回复）" if is_zh() else "(no response)"),
                        metadata=reply_metadata or None,
                    )
                    return

            # Q2-WS-A (Codex 1218): multi-step is on but this installation
            # cannot record one (no durable console session and/or no harness
            # registry). Stop with a bounded "not ready" result. Do not fall
            # through to the single-call consult -- that path is only for the
            # owner explicitly turning multi-step off.
            if master_loop_enabled():
                missing: list[str] = []
                if not console_session_id:
                    missing.append("console session" if not is_zh() else "console session")
                if getattr(engine, "harness_registry", None) is None:
                    missing.append("harness registry" if not is_zh() else "harness registry")
                missing_text = ", ".join(missing) if missing else "runtime"
                from ampuly.plugins.office_ui.master_runtime import remember_unfinished_master_goal

                # Only keep the goal on a Task that belongs to THIS console
                # session. A cached Task from another conversation must not be
                # treated as this turn's recovery target.
                task = self._master_loop_tasks.get(pid)
                same_session = (
                    task is not None
                    and bool(console_session_id)
                    and str(getattr(task, "session_id", "") or "") == str(console_session_id)
                )
                stored = False
                if same_session:
                    stored = await remember_unfinished_master_goal(
                        getattr(engine, "store", None),
                        task,
                        goal=content,
                        reason=f"master_runtime_not_ready:{missing_text}",
                    )
                if is_zh():
                    notice = (
                        f"执行条件未就绪：多步执行已开启，但缺少 {missing_text}。"
                        "本次未发起模型请求，也未退回单次问答。"
                    )
                else:
                    notice = (
                        f"Execution conditions are not ready: multi-step mode is on, "
                        f"but {missing_text} is missing. No model call was started "
                        "and the single-call path was not used."
                    )
                if not stored:
                    notice += (
                        "\n\n原目标这次没能写入恢复记录。"
                        if is_zh() else
                        "\n\nThe original goal could not be stored for recovery."
                    )
                await _reply(notice)
                return

            # AUD49-R01 / 4.9-A01-WS-01: the single-call consult is only for an
            # owner-explicit AMPULY_MASTER_SINGLE_SHOT (env or settings). If the
            # multi-step switch could not be read, refuse rather than silently
            # paying for one consult.
            from ampuly.plugins.office_ui.master_loop import single_shot_explicitly_enabled

            if not single_shot_explicitly_enabled():
                if is_zh():
                    notice = (
                        "执行条件未就绪：无法确认是否已开启单次模式。"
                        "本次未发起模型请求，也未退回单次问答。"
                    )
                else:
                    notice = (
                        "Execution conditions are not ready: could not confirm "
                        "single-shot mode. No model call was started and the "
                        "single-call path was not used."
                    )
                await _reply(notice)
                return

            from ampuly.plugins.office_ui.direct_task_scope import bind_direct_task_budget
            from ampuly.plugins.office_ui.master_runtime import MasterSafetyStop, customer_for

            if not console_session_id or getattr(self, "_master_session_store_fault", False):
                # The session store failed open. A healthy budget ledger is
                # not a task identity, and this path must not spend anyway.
                await _reply(
                    "执行已停止：会话无法持久化，没有发起模型请求。" if is_zh() else
                    "Execution stopped: the conversation could not be stored, so no model request was started."
                )
                return

            business = self._accounts().business
            actor = str((_ws_owner_actor(self, ws) or {}).get("login", "") or "")
            try:
                single_budget_id = bind_direct_task_budget(
                    engine=engine, project_id=pid, actor=actor,
                    customer_id=await customer_for(business, pid),
                )
            except MasterSafetyStop:
                # A budget refusal must not become an unbudgeted model call.
                await _reply(
                    "执行已停止：直接任务预算无法核实，没有切换执行路径重试。" if is_zh() else
                    "Execution stopped: the direct-task budget could not be verified; no fallback was started."
                )
                return
            result = await process_master_message(
                llm,
                engine=engine,
                project_id=pid,
                content=turn_content,
                console_session_id=console_session_id,
                history=history,
                business=business,
                budget_id=single_budget_id,
                preprocess=_prepare_attachments,
                # policy (M1): the single call cannot look the flows up, so it is told them.
                order_flows=await asyncio.to_thread(_master_order_flows, self, pid),
            )
            reply_text = str(result.get("response", "") or "").strip()

            dispatch_notes: list[str] = []
            drafted_order_id = ""
            for action in result.get("actions", []):
                kind = action.get("kind")
                if kind == "create_order":
                    note, order_id = await self._master_draft_order(action, engine=engine, project_id=pid, ws=ws)
                    if note:
                        dispatch_notes.append(note)
                    if order_id and not drafted_order_id:
                        drafted_order_id = order_id
                elif kind in {"reply_checkpoint", "stop_order", "interrupt_turn", "steer_turn"}:
                    note = await self._master_control_verb(
                        action, ws=ws, project_id=pid, message_id=message_id,
                    )
                    if note:
                        dispatch_notes.append(note)
            from ampuly.plugins.office_ui.master_control import unbacked_claims

            corrections = unbacked_claims(reply_text, [str(a.get("kind", "")) for a in result.get("actions", [])], zh=is_zh())
            if dispatch_notes:
                reply_text = (reply_text + "\n\n" + "\n".join(dispatch_notes)).strip()
            if corrections:
                reply_text = (reply_text + "\n\n" + "\n".join(corrections)).strip()
            await _reply(
                reply_text or ("（无回复）" if is_zh() else "(no response)"),
                metadata=(
                    {"type": "master_order_drafted", "order_id": drafted_order_id}
                    if drafted_order_id
                    else None
                ),
            )
        except Exception as e:
            logger.opt(exception=True).error(f"Master control processing error: {e}")
            await _reply(
                (f"总控处理出错：{e}" if is_zh() else f"Master control error: {e}"),
                sender="system",
            )

    async def _master_control_verb(
        self,
        action: dict[str, Any],
        *,
        ws: Any,
        project_id: str,
        message_id: str,
    ) -> str:
        """Run one validated control verb through the same durable handlers
        the workspace buttons use, and phrase the engine's answer for the
        owner.

        The handlers answer over the socket, so the call goes through a
        recorder that keeps the acknowledgement instead of a client; the
        receipt is built from that answer, never from the request. The
        idempotency key is the chat line that asked plus the target, so a
        redelivered or re-run message cannot answer a checkpoint twice; the
        engine's own checkpoint CAS still has the final say.
        """
        from ampuly.i18n_runtime import is_zh
        from ampuly.plugins.office_ui.master_control import decision_for, verb_receipt

        recorder = _AckRecorder(on_behalf_of=ws)
        kind = str(action.get("kind", "") or "")
        if kind == "reply_checkpoint":
            checkpoint_id = str(action.get("checkpoint_id", "") or "")
            decision_payload = decision_for(action)
            await self._handle_interaction_reply(recorder, {
                "project_id": project_id,
                "checkpoint_id": checkpoint_id,
                "checkpoint_type": str(action.get("checkpoint_type", "") or ""),
                "client_request_id": f"master:{message_id or 'anon'}:{checkpoint_id}",
                "requester_task_id": str(action.get("task_id", "") or ""),
                "requester_session_id": str(action.get("session_id", "") or ""),
                "decision": decision_payload,
            })
        elif kind == "stop_order":
            await self._handle_session_stop(recorder, {
                "project_id": project_id,
                "task_id": str(action.get("task_id", "") or ""),
            })
        elif kind == "interrupt_turn":
            session_id = await self._master_turn_session_id(
                str(action.get("task_id", "") or "")
            )
            if not session_id:
                # Nothing is running. Saying so is the answer; falling through
                # to a stop would turn "never mind, do this instead" into
                # "abandon the order", which is what this verb exists to
                # stop being the only option.
                await recorder.send_json({
                    "type": "ack",
                    "payload": {
                        "ok": False,
                        "action": "harness_turn_interrupt",
                        "error": "nothing_running",
                    },
                })
            else:
                await self._handle_harness_turn_interrupt(recorder, {
                    "project_id": project_id,
                    "session_id": session_id,
                })
        elif kind == "steer_turn":
            session_id = await self._master_turn_session_id(
                str(action.get("task_id", "") or "")
            )
            if not session_id:
                await recorder.send_json({
                    "type": "ack",
                    "payload": {
                        "ok": False,
                        "action": "harness_turn_steer",
                        "error": "nothing_running",
                    },
                })
            else:
                registry = self.engine.harness_registry
                expected_turn_id = await asyncio.to_thread(registry.pending_turn_id, session_id)
                # Same user message retried against the same turn keeps its id;
                # different text under that id is rejected by the registry.
                steer_request_id = str(uuid.uuid5(
                    uuid.NAMESPACE_URL, f"steer:{project_id}:{session_id}:{message_id}",
                )) if message_id else str(uuid.uuid4())
                await self._handle_harness_turn_steer(recorder, {
                    "project_id": project_id,
                    "session_id": session_id,
                    "expected_turn_id": expected_turn_id,
                    "request_id": steer_request_id,
                    "text": str(action.get("text", "") or ""),
                })
        else:
            return ""
        if is_zh():
            # The owner reads this under 安安's reply: names and reasons in words; codes and ids go to ``detail``.
            return _owner_verb_receipt(action, recorder.last_ack)
        return verb_receipt(action, recorder.last_ack, zh=False)

    async def _master_turn_session_id(self, task_id: str) -> str:
        """The harness session running this task's turn, if one is.

        Returns "" when the registry is absent, the task has no session, or no
        session has a turn in flight. Each of those means the same thing to
        the caller -- there is no turn to interrupt -- and none of them is an
        error worth raising into a chat reply.
        """
        clean = str(task_id or "").strip()
        registry = getattr(getattr(self, "engine", None), "harness_registry", None)
        if registry is None or not clean:
            return ""
        try:
            records = await asyncio.to_thread(registry.sessions_for_task, clean)
        except Exception:
            logger.opt(exception=True).debug(f"failed to resolve sessions for task {clean}")
            return ""
        for record in records:
            session_id = str(getattr(record, "session_id", "") or "")
            if not session_id:
                continue
            try:
                pending = await asyncio.to_thread(registry.pending_turn_id, session_id)
            except Exception:
                continue
            if pending:
                return session_id
        return ""

    async def _master_snooze_blocker(
        self,
        action: dict[str, Any],
        *,
        ws: Any,
        project_id: str,
        message_id: str = "",
    ) -> tuple[bool, str]:
        """Hold one blocker's reminder; the blocker itself is untouched (A19)."""
        from ampuly.plugins.office_ui.business_store import OrderTransitionError

        if not _ws_is_owner(self, ws):
            return _master_note(False, "只有负责人能暂缓提醒，这次没有暂缓。", "owner_required")
        checkpoint_id = str(action.get("checkpoint_id", "") or "").strip()
        until_at = str(action.get("until_at", "") or "").strip()
        try:
            row = await asyncio.to_thread(
                self._accounts().business.snooze_blocker,
                checkpoint_id, project_id=str(project_id or "default"), until_at=until_at,
                actor=_ws_actor_login(self, ws), note=str(action.get("note", "") or ""),
            )
        except OrderTransitionError as exc:
            return _master_note(
                False,
                "没能暂缓提醒：" + (_owner_words(exc) or "时间没写对，或者没说是哪一条待办。") + " 这条待办照旧在等你处理。",
                f"not held: {exc}", checkpoint_id=checkpoint_id,
            )
        return _master_note(
            True,
            f"🔕 已暂缓这条待办的提醒，到 {_owner_clock(row['until_at'])} 再提醒你；它还在等你处理，没有替你做任何决定。",
            f"reminder for {checkpoint_id} held until {row['until_at']}; it is still pending and nothing was decided",
            checkpoint_id=checkpoint_id, until_at=row["until_at"],
        )

    async def _master_run_trial(
        self,
        action: dict[str, Any],
        *,
        ws: Any,
        project_id: str,
        message_id: str = "",
    ) -> tuple[bool, str]:
        """The master write for A02's third step, through the console's own trial.

        Same admission, claim, timeout, settle and immutable round record as
        the button. Returns (ok, note); ok means the trial ran and settled,
        whatever it established -- a failed step is a settled trial, and the
        note says which step and why so the model can go fix it.
        """
        from ampuly.plugins.office_ui.builder_loop import BuilderError
        from ampuly.plugins.office_ui.builder_trial import run_saved_trial
        from ampuly.plugins.office_ui.business_store import OrderTransitionError
        from ampuly.plugins.office_ui.process_spec import from_payload

        if not _ws_is_owner(self, ws):
            return _master_note(False, "只有负责人能发起离线试跑，这次没有跑。", "owner_required")
        spec_id = str(action.get("spec_id", "") or "").strip()
        version = str(action.get("version", "") or "").strip()
        if not spec_id:
            return _master_note(False, "没说要试跑哪一条流程，这次没有跑。", "a trial needs a spec_id")
        try:
            business = self._accounts().business
            stored = await asyncio.to_thread(business.process_spec, spec_id, version)
        except Exception as exc:  # noqa: BLE001
            return _master_note(False, "没能开始试跑：读不到这条流程的说明。",
                                f"trial not started: {str(exc) or type(exc).__name__}", spec_id=spec_id, version=version)
        if stored is None:
            return _master_note(
                False, "没能开始试跑：找不到这条流程的说明（也可能是版本写错了）。",
                f"trial not started: no process description {spec_id!r}{(' v' + version) if version else ''}",
                spec_id=spec_id, version=version,
            )
        try:
            spec = from_payload(stored["spec"])
        except Exception as exc:  # noqa: BLE001
            return _master_note(False, "没能开始试跑：这条流程的说明读不出来，先在搭建台打开看看。",
                                f"trial not started: {exc}", spec_id=spec_id, version=version)
        actor = _ws_actor_login(self, ws)
        try:
            receipt = await run_saved_trial(
                business, spec, actor=actor, runner_factory=self._offline_trial_runner,
            )
        except (OrderTransitionError, BuilderError) as exc:
            return _master_note(
                False,
                "试跑没有开始：" + (_owner_words(exc) or "这条流程现在不能试跑（可能上一轮还没收尾）。"),
                f"trial not admitted: {exc}", spec_id=spec.spec_id, version=spec.version,
            )
        trial = dict(receipt.get("trial", {}) or {})
        outcome = str(trial.get("outcome", "") or "unknown")
        note = f"offline trial of {spec.spec_id} v{spec.version}: {outcome} (round {trial.get('round', '?')})"
        failed_step = str(trial.get("failed_step", "") or "")
        if failed_step:
            note += f"; failed at step {failed_step}"
        reason = str(trial.get("reason", "") or "").strip()
        if reason:
            note += f": {reason[:300]}"
        proposal = dict(receipt.get("proposal", {}) or {})
        if proposal.get("change"):
            note += f" | proposed change to step {proposal.get('step_id', '?')}: {str(proposal.get('change'))[:200]}"
        # The owner's sentence: the flow and the round by name, the verdict in words, and the step named as the
        # description names it. The trial's own reason and proposed change are already said in Chinese.
        verdict = {
            "passed": "通过了", "failed": "没通过", "unrun": "没跑起来，这一轮说明不了流程对不对",
            "validated": "只做了结构检查，流程还没真正执行",
        }.get(outcome, "结果不明")
        round_number = trial.get("round")
        flow_name = str(getattr(spec, "name", "") or "").strip() or "这条流程"
        said = f"🧪 离线试跑「{flow_name}」" + (f"（第 {round_number} 轮）" if round_number else "") + f"{verdict}。"
        why = _owner_words(reason[:300]).rstrip("。")
        if why and outcome != "passed":
            said += f"{why}。"
        elif failed_step and outcome != "passed":
            # The reason is not in the owner's words: still say where it stopped, by the step's name (never its id).
            failed_name = next((str(getattr(step, "name", "") or "") for step in list(getattr(spec, "steps", []) or [])
                                if str(getattr(step, "id", "") or "") == failed_step), "").strip()
            if failed_name:
                said += f"卡在「{failed_name}」这一步。"
        change = _owner_words(str(proposal.get("change", "") or "")[:200]).rstrip("。")
        if change:
            step_name = next((str(getattr(step, "name", "") or "") for step in list(getattr(spec, "steps", []) or [])
                              if str(getattr(step, "id", "") or "") == str(proposal.get("step_id", "") or "")), "")
            said += (f"建议改「{step_name}」：" if step_name else "建议：") + f"{change}。"
        said += "这一轮的记录已留下。"
        return _master_note(
            True, said, note, spec_id=spec.spec_id, version=spec.version, round=round_number,
            outcome=outcome, failed_step=failed_step,
        )

    # ── 总控施工模式 (policy, B1): the owner's own console only ──

    def _master_build_runner(self) -> Any:
        """This console's build runner (master_build.py), made on first use and kept for the life of the console."""
        from ampuly.plugins.office_ui.master_build import MasterBuildRunner

        runner = self.__dict__.get("_master_build_runner_instance")
        if runner is None:
            runner = MasterBuildRunner(_MasterBuildHost(self))
            self.__dict__["_master_build_runner_instance"] = runner
        return runner

    def _master_build_refusal(self, ws: Any) -> MasterAnswer | None:
        """Build mode is the owner's, from the owner's console: never a server adapter standing in for nobody."""
        if not _ws_is_owner(self, ws):
            return _master_note(False, "只有老板能让总控施工，这次没有开工。", "owner_required")
        if isinstance(ws, _AckRecorder) and ws.on_behalf_of is None:
            return _master_note(False, "施工只能从老板的控制台总控里开。", "build mode is reachable from the owner's console only")
        return None

    async def _master_start_build(
        self,
        action: dict[str, Any],
        *,
        ws: Any,
        project_id: str,
        message_id: str = "",
    ) -> tuple[bool, str]:
        """Open one build job in a draft of this project (master_start_build); the job runs in the background.

        总控对话栏 (policy, 第七节): the job belongs to the conversation this turn runs in -- the one the owner's
        message was said in, whose id is the turn's console session id -- and every message of the job goes there.
        """
        refused = self._master_build_refusal(ws)
        if refused is not None:
            return refused
        pid = str(project_id or "default")
        answer = await self._master_build_runner().start_build(
            project_id=pid,
            goal=str(action.get("goal", "") or ""),
            line_id=str(action.get("line_id", "") or ""),
            name=str(action.get("name", "") or ""),
            team=str(action.get("team", "") or ""),
            actor=_ws_actor_login(self, ws) or "owner",
            ws=ws,
            thread_id=await _master_thread_of_message(getattr(self, "chat_store", None), pid, message_id),
        )
        job = dict(answer.job or {})
        return _master_note(answer.ok, answer.zh, answer.en, job_id=job.get("job_id"), draft_id=job.get("draft_id"),
                            code=answer.code)

    async def _master_continue_build(
        self,
        action: dict[str, Any],
        *,
        ws: Any,
        project_id: str,
        message_id: str = "",
    ) -> tuple[bool, str]:
        """Let a stopped or handed-over build job go on with the owner's instruction (master_continue_build)."""
        refused = self._master_build_refusal(ws)
        if refused is not None:
            return refused
        answer = await self._master_build_runner().continue_build(
            project_id=str(project_id or "default"),
            job_id=str(action.get("job_id", "") or ""),
            instruction=str(action.get("instruction", "") or ""),
            actor=_ws_actor_login(self, ws) or "owner",
            ws=ws,
        )
        job = dict(answer.job or {})
        said, said_en = answer.zh, answer.en
        if answer.ok and "thread_id" in job:
            # 总控对话栏: a build goes on in the conversation it was started from, whichever conversation continued it;
            # when that is another one, the owner is told where its progress will be.
            where = await WSHandler._master_build_conversation_words(
                self, str(project_id or "default"), str(job.get("thread_id", "") or ""), message_id=message_id,
            )
            if where and not where.get("in_this_conversation"):
                said = f"{said}（它是在{where['conversation']}里开的，进展和交付写在那段对话里。）"
                said_en = f"{said_en} (it was started in another conversation; its progress is posted there)"
        return _master_note(answer.ok, said, said_en, job_id=job.get("job_id"), draft_id=job.get("draft_id"),
                            code=answer.code)

    async def _master_build_conversations(
        self, project_id: str, *, message_id: str = "", console_session_id: str = "",
    ) -> Any:
        """A reader of which 总控 conversation a build job belongs to, in words (``master_threads.conversation_in_words``):
        this one (the turn's -- its console session id, or found by the owner's message) or another one by its title.
        None when the conversation column cannot be read (a stand-in store): nothing is then said about it."""
        from ampuly.plugins.office_ui import master_threads as threads

        chat_store = getattr(self, "chat_store", None)
        lister = getattr(chat_store, "list_master_threads", None)
        if not callable(lister):
            return None
        pid = str(project_id or "default")
        try:
            rows = await lister(pid, limit=threads.LIST_ONE_PROJECT)
        except Exception:  # noqa: BLE001 - said about nothing rather than guessed
            logger.opt(exception=True).warning("master control: the conversation column could not be read")
            return None
        current = str(console_session_id or "") or await _master_thread_of_message(chat_store, pid, message_id)
        first = next((str(row["thread_id"]) for row in rows if row.get("legacy")), "")
        titles = {str(row["thread_id"]): str(row.get("title", "") or "") for row in rows}
        return lambda job_thread: threads.conversation_in_words(
            job_thread, current=current, first_thread_id=first, titles=titles,
        )

    async def _master_build_conversation_words(
        self, project_id: str, job_thread: str, *, message_id: str = "",
    ) -> dict[str, Any] | None:
        """One build job's conversation in words (:meth:`_master_build_conversations`); None when it cannot be said."""
        words = await WSHandler._master_build_conversations(self, project_id, message_id=message_id)
        return words(job_thread) if words is not None else None

    async def _master_builds_in_words(self, project_id: str, console_session_id: str, described: dict[str, Any]) -> dict[str, Any]:
        """master_list_builds (总控对话栏): every build of the project is listed, whichever conversation started it, and
        each says which conversation it belongs to -- 「这段对话」 or 「另一段对话「标题」」 -- in place of the raw id,
        which is never the model's to read out."""
        words = await WSHandler._master_build_conversations(self, project_id, console_session_id=console_session_id)
        builds = [dict(row) for row in list(dict(described or {}).get("builds") or []) if isinstance(row, dict)]
        for row in builds:
            job_thread = str(row.pop("thread_id", "") or "")
            if words is not None:
                row.update(words(job_thread))
        return {**dict(described or {}), "builds": builds}

    async def _duty_recover_master_builds(self) -> None:
        """Once per console start: builds a stopped console left marked running are said to be interrupted (B1).

        The first pass runs as the duty watch starts, before its first half-minute sleep (``_duty_watch_loop``). A pass
        that could not run at all (the engine not ready so soon after a start) is tried again next round, two rounds at
        most. A pass that ran but could not close every question a stopped build left open (that project's engine not
        up yet) goes on next round, ten rounds at most; an answer to such a question is refused meanwhile
        (``_build_answer_refused``). After that what is left is settled when the owner next starts or continues a build.
        """
        if (os.environ.get("AMPULY_LOCAL_DEMO_PROJECT_ONLY") or "").strip():
            return
        if getattr(self, "_master_builds_recovered", False):
            return
        attempts = int(getattr(self, "_master_builds_recovery_attempts", 0) or 0) + 1
        self._master_builds_recovery_attempts = attempts
        self._master_builds_recovered = attempts >= (10 if getattr(self, "_master_build_questions_left", False) else 2)
        try:
            runner = self._master_build_runner()
            settled = await runner.recover()
        except Exception:
            logger.opt(exception=True).warning(
                "duty watch: the build jobs a restart left could not be looked at (round {})", attempts,
            )
            return
        count_left = getattr(runner, "questions_left", None)
        left = int(count_left() or 0) if callable(count_left) else 0
        self._master_build_questions_left = bool(left)
        self._master_builds_recovered = not left or attempts >= 10
        if settled:
            logger.info("duty watch: {} build job(s) left running by a restart marked interrupted", len(settled))
        if left:
            logger.warning("duty watch: the open questions of {} build job(s) could not be closed yet (round {})",
                           left, attempts)

    async def _master_delegate_browser(
        self,
        action: dict[str, Any],
        *,
        ws: Any,
        project_id: str,
        message_id: str = "",
    ) -> tuple[bool, str]:
        """X08 / C01: the master console gives one open order a browser scope.

        The scope -- allowed domains, screenshots, downloads, lease term -- is
        written into the order's own metadata, where the browser tools already
        read it on every call and refuse anything outside it. Returns
        (ok, note); a refusal is a note the loop can act on.
        """
        from datetime import datetime, timezone

        if not _ws_is_owner(self, ws):
            return _master_note(False, "只有负责人能把浏览器交给订单用，这次没有委派。", "owner_required")
        task_id = str(action.get("task_id", "") or "").strip()
        domains = [str(d) for d in list(action.get("domains") or []) if str(d or "").strip()]
        if not task_id or not domains:
            return _master_note(
                False, "要委派浏览器，得说清是哪一单、能去哪些网站；这次没有委派。",
                "a browser delegation needs an open order and at least one domain; nothing was delegated",
            )
        store = getattr(getattr(self, "engine", None), "store", None)
        getter = getattr(store, "get_task", None)
        saver = getattr(store, "save_task", None)
        if not callable(getter) or not callable(saver):
            return _master_note(False, "现在读不到订单记录，这次没有委派浏览器。",
                                "the task store is not available; nothing was delegated", task_id=task_id)
        task = await getter(task_id)
        if task is None or str(getattr(task, "project_id", "") or "") != str(project_id or ""):
            return _master_note(False, "这个项目里找不到这一单，这次没有委派浏览器。",
                                f"no order {task_id[:8]} in this project; nothing was delegated", task_id=task_id)
        vision = bool(action.get("vision", False))
        downloads = bool(action.get("downloads", False))
        visible = bool(action.get("visible", False))
        lease = int(action.get("lease_minutes", 60) or 60)
        metadata = dict(getattr(task, "metadata", {}) or {})
        metadata.update({
            "browser_allowed_domains": domains,
            "browser_allow_vision": vision,
            # Q05: PULY (JEV) may pick a connector step's low-risk browser steps unless the owner says no (policy).
            "browser_allow_decider": bool(action.get("decider", True)),
            "browser_allow_downloads": downloads,
            "browser_visible": visible,
            "browser_lease_minutes": lease,
            "browser_delegated_by": _ws_actor_login(self, ws),
            "browser_delegated_at": datetime.now(timezone.utc).isoformat(),
        })
        # X11: what the real-browser ledger says about this machine's executor is
        # part of the delegation record and of what the owner reads back -- and,
        # for a customer's order, the gate: a browser this machine has not proven
        # safe (egress, hand-off, revocation) is not handed a real customer's
        # site. The owner lifts it by running the probe here, not by an argument.
        evidence = _browser_combination_evidence(getattr(self, "engine", None))
        customer = str(metadata.get("customer_id", "") or "").strip()
        if customer and not evidence.get("admitted"):
            if not evidence.get("available"):
                return _master_note(
                    False,
                    "读不到这台电脑的浏览器安全检查记录；没有这份记录，客户的订单不交给浏览器。这次没有委派。",
                    "the real-browser evidence ledger for this machine cannot be read; a customer's order is not "
                    "delegated a browser without it; nothing was delegated",
                    task_id=task_id,
                )
            gap = ", ".join(evidence.get("missing", []) or []) or ", ".join(evidence.get("failed", []) or [])
            short = len(list(evidence.get("missing", []) or [])) or len(list(evidence.get("failed", []) or []))
            return _master_note(
                False,
                f"这台电脑的浏览器安全检查还差 {short} 项没做完；做完之前，客户的订单不交给浏览器。"
                "先在这台电脑上把检查做完（浏览器会话面板里能看到还差哪几项），再来委派。这次没有委派。",
                f"this machine has no real-browser evidence for {gap} (executor {evidence.get('executor', '')}); "
                f"a customer's order is not delegated a browser until the owner runs the probe here "
                f"({evidence.get('advice', '')}); nothing was delegated",
                task_id=task_id,
            )
        if evidence.get("available"):
            metadata["browser_combination_executor"] = str(evidence.get("executor", ""))
            metadata["browser_combination_missing"] = list(evidence.get("missing", []))
        task.metadata = metadata
        await saver(task)
        # X08: a turn already running keeps the Task it was loaded with; the bridge holds the newer
        # scope so the very next browser tool call is judged by it, and the registry's own list follows.
        try:
            from ampuly.computer_use import browser_bridge as _bridge
            from ampuly.layer4_tools.browser_sessions import BrowserBinding as _Binding

            live_binding = _Binding.for_task(task)
            _bridge.note_delegation(live_binding, metadata)
            registry = self._browser_session_registry()
            if registry.binding_for_key(live_binding.key()) is not None:
                registry.bind_domains(live_binding, domains)
                registry.bind_lease_term(live_binding, lease * 60)
        except Exception:  # noqa: BLE001 - the delegation is written; a live session that cannot be told is told at its next reload
            pass
        # X08 / C01 in company mode: the work items already running this order take the same scope now;
        # the ones created later inherit it from the order when the engine creates them.
        children_scoped = 0
        lister = getattr(store, "get_tasks", None)
        if callable(lister):
            try:
                from ampuly.computer_use import browser_bridge as _bridge
                from ampuly.computer_use.browser_scope import inherit_browser_scope
                from ampuly.layer4_tools.browser_sessions import BrowserBinding as _Binding

                registry = self._browser_session_registry()
                everything = [item for item in await lister(project_id=project_id) if str(getattr(item, "id", "") or "") != task.id]
                # The root work item names the order's task as its origin; the tasks made under it do not -- they share
                # the root's delegation run, and they are the ones that open the pages.
                roots = [item for item in everything if str(dict(getattr(item, "metadata", {}) or {}).get("origin_task_id", "") or "") == task.id]
                runs = {str(dict(getattr(item, "metadata", {}) or {}).get("delegation_run_id", "") or "").strip() for item in roots} - {""}
                root_ids = {id(item) for item in roots}
                under_them = [item for item in everything if id(item) not in root_ids
                              and str(dict(getattr(item, "metadata", {}) or {}).get("delegation_run_id", "") or "").strip() in runs]
                for child in [*roots, *under_them]:
                    child_metadata = dict(getattr(child, "metadata", {}) or {})
                    child.metadata = inherit_browser_scope(child_metadata, metadata)
                    await saver(child)
                    child_binding = _Binding.for_task(child)
                    _bridge.note_delegation(child_binding, child.metadata)
                    if registry.binding_for_key(child_binding.key()) is not None:
                        registry.bind_domains(child_binding, domains)
                        registry.bind_lease_term(child_binding, lease * 60)
                    children_scoped += 1
            except Exception:  # noqa: BLE001 - the order is delegated; its running work items take it at their next reload
                logger.opt(exception=True).warning("browser delegation: the order's running work items could not be updated")
        title = str(action.get("title", "") or "") or str(getattr(task, "title", "") or "")
        sites = ", ".join(domains)
        # The owner's sentence names the order by its title, the sites and the limits; the evidence rows (C02 …),
        # the executor digest and the probe's command line are the model's, in ``detail``.
        if not evidence.get("available"):
            proof_zh = "读不到这台电脑的浏览器安全检查记录。"
        elif evidence.get("admitted"):
            proof_zh = "这台电脑的浏览器安全检查都通过了。"
        else:
            failed_count = len(list(evidence.get("failed", []) or []))
            proof_zh = (f"这台电脑的浏览器安全检查还差 {len(list(evidence.get('missing', []) or []))} 项"
                        + (f"（其中 {failed_count} 项没通过）" if failed_count else "")
                        + "，接真实客户的单之前先做完。")
        said = (f"🖥 已把浏览器交给「{title or '这一单'}」用：能去的网站 {sites}；截图{'允许' if vision else '不允许'}；"
                f"下载{'允许' if downloads else '不允许'}；AI 最多操作 {lease} 分钟。范围以外的网站、截图和下载都会被拦下；"
                f"这一单正在做的部分，下次查看订单时就按这个范围来。{proof_zh}"
                + (f"已同步到这单正在跑的 {children_scoped} 个工单。" if children_scoped else ""))
        if not evidence.get("available"):
            proof = "Real-browser evidence for this machine: ledger unreadable."
        elif evidence.get("admitted"):
            proof = f"Real-browser evidence for this machine: verified {', '.join(evidence['verified'])}."
        else:
            proof = (f"Real-browser evidence for this machine is missing {', '.join(evidence['missing'])}"
                     + (f", failed {', '.join(evidence['failed'])}" if evidence.get("failed") else "")
                     + " -- run browser_handoff_probe --ledger here before a real customer.")
        children_note = f" Also applied to {children_scoped} running work item(s) of this order." if children_scoped else ""
        return _master_note(
            True, said,
            (f"🖥 Browser delegated to \"{title or task_id[:8]}\": sites {sites}; screenshots {'allowed' if vision else 'off'}; "
             f"downloads {'allowed' if downloads else 'off'}; agent control {lease} min. Anything outside is refused "
             f"by the tools; a running turn picks it up when it next reads the order. {proof}{children_note}"),
            task_id=task_id, domains=domains, lease_minutes=lease,
        )

    async def _master_generate_connector_candidate(
        self,
        action: dict[str, Any],
        *,
        ws: Any,
        project_id: str,
        message_id: str = "",
    ) -> tuple[bool, str]:
        """Persist one inert W07-X candidate through the master-control funnel."""
        from ampuly.plugins.office_ui.connector_candidate import (
            ConnectorCandidateError,
            create_candidate,
            project_candidate_root,
        )
        from ampuly.plugins.office_ui.connector_contract import ContractError

        if not _ws_is_owner(self, ws):
            return _master_note(False, "只有负责人能起草连接器候选，这次没有起草。", "owner_required")
        contract = action.get("contract")
        if not isinstance(contract, dict):
            return _master_note(False, "没能起草连接器候选：还缺接口说明（调哪个地址、怎么登录、有哪些操作）。",
                                "a connector candidate needs a contract object")
        proposal: dict[str, Any] = {"contract": dict(contract)}
        catalog_id = str(action.get("catalog_id", "") or "").strip()
        if catalog_id:
            from ampuly.plugins.office_ui.component_catalog import (
                connector_admission_plan,
                load_catalog,
                resolve_connector_admission,
            )

            catalog = load_catalog(Path(__file__).resolve().parents[3])
            entry = next((item for item in catalog.connectors if str(item.get("id") or "") == catalog_id), None)
            if entry is None:
                return _master_note(False, "没能起草：组件库里找不到这个连接器了，刷新组件库后再试。",
                                    "catalog connector not found; reload the component library", catalog_id=catalog_id)
            plan = connector_admission_plan(entry)
            expected = str(action.get("catalog_fingerprint", "") or "").strip()
            if not expected or expected != str(plan.get("catalog_fingerprint") or ""):
                return _master_note(False, "没能起草：组件库里这个连接器的资料刚变过，刷新组件库后再试。",
                                    "catalog fingerprint changed; reload the component library", catalog_id=catalog_id)
            raw_confirmed = action.get("confirmed_inferred_fields")
            resolved = resolve_connector_admission(
                entry,
                contract_source=str(contract.get("source", "") or ""),
                confirmed_inferred_fields=(
                    [str(item) for item in raw_confirmed]
                    if isinstance(raw_confirmed, list) else []
                ),
            )
            if resolved["route"] != "generate_declarative_candidate":
                return _master_note(False, "没能起草：这个连接器不走自动起草，要按组件库里写的接入方式来。",
                                    f"catalog route {resolved['route']} does not use the FastMCP generator",
                                    catalog_id=catalog_id)
            if resolved["state"] != "ready_for_candidate":
                return _master_note(
                    False, f"没能起草：这个连接器的资料还缺 {len(list(resolved['blockers'] or []))} 项，先在组件库里补齐再试。",
                    "catalog evidence is incomplete: " + ", ".join(resolved["blockers"]), catalog_id=catalog_id,
                )
            proposal["catalog_admission"] = {
                "catalog_id": catalog_id,
                "catalog_fingerprint": expected,
                "route": resolved["route"],
            }
        home = getattr(self.engine, "ampuly_home", None)
        if home is None:
            return _master_note(False, "没能起草：现在没有地方存放连接器候选，稍后再试。", "connector candidate store is unavailable")
        try:
            candidate = await asyncio.to_thread(
                create_candidate,
                project_candidate_root(Path(home), str(project_id or "default")),
                proposal,
                actor=_ws_actor_login(self, ws),
                # 总控对话栏: the conversation the owner's message was said in (its channel), not only the first one.
                conversation_id=await _master_channel_of_message(
                    getattr(self, "chat_store", None), str(project_id or "default"), message_id),
                turn_id=str(message_id or "unknown-turn"),
            )
        except (ConnectorCandidateError, ContractError, OSError) as exc:
            return _master_note(
                False, "没能起草连接器候选：" + (_owner_words(exc) or "接口说明没通过检查（原因已告诉安安）。"),
                f"connector candidate not generated: {exc}",
            )
        # The id and fingerprint are the model's (and the flow-draft card's, through the reply's metadata); the
        # owner is told where the candidate is, which is where it is tested, reviewed and registered.
        return _master_note(
            True,
            "✅ 已起草一个连接器候选（草稿）：还没测试、没批准、没注册，也没启用。"
            "在「配置 · 服务与连接」的「连接器候选」里能看到它，测试和审查都在那里做。",
            f"connector candidate {candidate.candidate_id} created as draft; fingerprint "
            f"{candidate.fingerprint}. It is not tested, approved, registered, or enabled.",
            candidate_id=candidate.candidate_id, fingerprint=candidate.fingerprint, status="draft",
        )

    async def _master_create_improvement_proposal(
        self,
        action: dict[str, Any],
        *,
        ws: Any,
        project_id: str,
        message_id: str = "",
    ) -> tuple[bool, str]:
        """Persist one inert RSI draft through the same ConsoleAPI as the UI.

        4.7-A11: the owner's one sentence is enough. A proposal that carries only ``target`` (kind + id) and
        ``request`` goes the way 提一个改进 goes on the page: the server drafts the candidate from the asset as it is
        now and materializes it, inert.
        """
        from ampuly.plugins.office_ui.business_store import OrderTransitionError

        if not _ws_is_owner(self, ws):
            return _master_note(False, "只有负责人能提改进，这次没有记下。", "owner_required")
        payload = action.get("proposal")
        if not isinstance(payload, dict):
            return _master_note(False, "没能记下改进：没说清要改进什么。",
                                "an improvement proposal needs one complete proposal object")
        if "request" in payload and "candidate" not in payload:
            target = payload.get("target") if isinstance(payload.get("target"), dict) else {}
            try:
                started = await asyncio.to_thread(
                    self._console_api().start_improvement,
                    str(target.get("kind", "") or ""),
                    str(target.get("id", "") or ""),
                    str(payload.get("request", "") or ""),
                    actor=_ws_actor_login(self, ws),
                    project_id=str(project_id or "default"),
                    # 总控对话栏: the conversation the owner's message was said in (its channel), not only the first one.
                    conversation_id=await _master_channel_of_message(
                        getattr(self, "chat_store", None), str(project_id or "default"), message_id),
                    turn_id=str(message_id or "unknown-turn"),
                )
            except (OrderTransitionError, TypeError, ValueError, OSError) as exc:
                return _master_note(
                    False, "没能起草改进：" + (_owner_words(exc) or "这个对象现在不能提改进，刷新后再试。"),
                    f"improvement not started: {exc}",
                )
            editor = dict(started.get("editor", {}) or {})
            where = {
                "process": "a draft flow on the builder",
                "skill": "a candidate version in the component workbench (Test tab)",
                "connector": "a draft connector candidate",
            }.get(str(editor.get("kind", "")), "a candidate")
            carried = list(started.get("not_carried", []) or [])
            # Where the owner finds it, in the page's own words (lib/improvementProposal.ts editorWords).
            where_zh = {
                "process": f"起草了一份流程草稿「{str(editor.get('name', '') or '').strip() or '改进草稿'}」，在搭建台里能看到",
                "skill": "起草了这个技能的候选新版本，在组件库里打开这个技能，到「测试」里能看到改了什么",
                "connector": "起草了一个连接器候选，在「配置 · 服务与连接」的「连接器候选」里能看到",
            }.get(str(editor.get("kind", "")), "起草了一个候选")
            proposal_row = dict(started.get("proposal", {}) or {})
            return _master_note(
                True,
                f"📝 已按你的一句话{where_zh}。它现在只是草稿：没测试、没批准、没启用，也没发布；"
                "你在那里改好后，批准前会先按真实订单评估一次收益。"
                + ("这些步骤设置没有带进草稿：" + "；".join(carried) + "。" if carried else ""),
                f"improvement proposal {started['proposal']['proposal_id']} materialized as {where}. It is inert: not "
                "tested, approved, staged, activated or published. The owner edits it there, then asks for the "
                "real-order benefit check before approving."
                + (" Step settings not carried into the draft: " + "; ".join(carried) + "." if carried else ""),
                proposal_id=proposal_row.get("proposal_id"), editor=editor,
            )
        try:
            proposal = await asyncio.to_thread(
                self._console_api().create_improvement,
                dict(payload),
                actor=_ws_actor_login(self, ws),
                project_id=str(project_id or "default"),
                # 总控对话栏: the conversation the owner's message was said in (its channel), not only the first one.
                conversation_id=await _master_channel_of_message(
                    getattr(self, "chat_store", None), str(project_id or "default"), message_id),
                turn_id=str(message_id or "unknown-turn"),
            )
        except (OrderTransitionError, TypeError, ValueError, OSError) as exc:
            return _master_note(
                False, "没能记下改进提案：" + (_owner_words(exc) or "内容没通过检查（原因已告诉安安）。"),
                f"improvement proposal not recorded: {exc}",
            )
        return _master_note(
            True,
            f"📝 已记下一条改进提案（{_PROPOSAL_STATUS_ZH.get(str(proposal['status']), '已记下')}）："
            "还没生成候选、没测试、没批准、没启用，也不会分享出去。在组件库的「改进提案」里能看到。",
            f"improvement proposal {proposal['proposal_id']} recorded as {proposal['status']}; fingerprint "
            f"{proposal['proposal_fingerprint']}. It is not materialized, tested, approved, staged, "
            "activated, published, or shareable.",
            proposal_id=proposal["proposal_id"], fingerprint=proposal["proposal_fingerprint"], status=proposal["status"],
        )

    async def _master_create_improvement_from_acceptance(
        self,
        action: dict[str, Any],
        *,
        ws: Any,
        project_id: str,
        message_id: str = "",
    ) -> tuple[bool, str]:
        """Draft one improvement from an order's durable customer rejection, through the same ConsoleAPI as the UI."""
        from ampuly.plugins.office_ui.business_store import OrderTransitionError

        if not _ws_is_owner(self, ws):
            return _master_note(False, "只有负责人能提改进，这次没有记下。", "owner_required")
        candidate = action.get("candidate")
        order_id = str(action.get("order_id", "") or "").strip()
        if not isinstance(candidate, dict) or not order_id:
            return _master_note(
                False, "没能记下改进：要说清是哪一单被客户打回，以及想怎么改。",
                "an acceptance-derived improvement needs an order_id and one complete candidate object",
            )
        try:
            proposal = await asyncio.to_thread(
                self._console_api().create_improvement_from_acceptance,
                order_id,
                title=str(action.get("title", "") or ""),
                rationale=str(action.get("rationale", "") or ""),
                candidate=dict(candidate),
                actor=_ws_actor_login(self, ws),
                project_id=str(project_id or "default"),
                # 总控对话栏: the conversation the owner's message was said in (its channel), not only the first one.
                conversation_id=await _master_channel_of_message(
                    getattr(self, "chat_store", None), str(project_id or "default"), message_id),
                turn_id=str(message_id or "unknown-turn"),
            )
        except (OrderTransitionError, TypeError, ValueError, OSError) as exc:
            return _master_note(
                False, "没能记下改进提案：" + (_owner_words(exc) or "这一单的打回记录对不上，或者内容没通过检查（原因已告诉安安）。"),
                f"improvement proposal not recorded: {exc}", order_id=order_id,
            )
        return _master_note(
            True,
            f"📝 已按客户打回的那一单记下一条流程改进提案（{_PROPOSAL_STATUS_ZH.get(str(proposal['status']), '已记下')}）："
            "还没生成候选、没测试、没批准、没启用，也不会分享出去。在组件库的「改进提案」里能看到。",
            f"improvement proposal {proposal['proposal_id']} recorded as {proposal['status']} from order {order_id}'s "
            f"customer rejection; fingerprint {proposal['proposal_fingerprint']}. It is not materialized, tested, "
            "approved, staged, activated, published, or shareable.",
            proposal_id=proposal["proposal_id"], fingerprint=proposal["proposal_fingerprint"],
            status=proposal["status"], order_id=order_id,
        )

    async def _master_draft_order(
        self,
        action: dict,
        *,
        engine: Any,
        project_id: str,
        ws: Any = None,
    ) -> MasterAnswer:
        """安安起草工单 (policy, M1, option B). Returns (note, order_id) with ``detail`` for the model.

        Work starts from a work order, so master control only drafts one: on a flow this project takes orders on, its
        start fields filled from the owner's words, through the console's own entry (ConsoleAPI.create_order: flow
        ownership, adoption and version, the project's customer binding), in 「待接单」. It never starts a run, never
        creates a session and never spends -- the owner releases the order in 业务工单 like any other. A draft that
        cannot be placed is refused in plain words and nothing is created; there is no fallback to a free session.
        The note names the order by its title; the order id is the model's (``detail``) and the reply's metadata.
        """
        from ampuly.i18n_runtime import is_zh
        from ampuly.plugins.office_ui import master_order_draft as drafting
        from ampuly.plugins.office_ui.business_store import OrderTransitionError

        zh = is_zh()
        pid = str(project_id or "default")
        workflow_id = str(action.get("workflow_id", "") or "").strip()

        def refused(zh_reason: str, en_reason: str, **facts: Any) -> MasterAnswer:
            detail = {"refused": True, "message": en_reason, "workflow_id": workflow_id, **facts}
            if zh:
                return MasterAnswer((f"⚠️ 没有起草工单：{zh_reason.rstrip('。. ')}。", ""), detail)
            return MasterAnswer((f"⚠️ No work order was drafted: {en_reason.rstrip('. ')}.", ""), detail)

        try:
            console = self._console_api()
            # The same flows the console's own entry resolves (its ``package()`` reads this registry), read off the
            # event loop: they are loaded from disk, and the adoption from the business store.
            package, fields = await asyncio.to_thread(
                lambda: drafting.check_draft(
                    list(self._workflow_registry()), pid, workflow_id, action.get("fields"),
                    lambda project, flow: console.business.workflow_adoption(project, flow),
                )
            )
        except drafting.DraftRefused as exc:
            # Nothing fits: say so, and the model may offer a new flow (master_propose_flow_draft).
            return refused(exc.zh, exc.en, code=exc.code, next="offer master_propose_flow_draft when no flow fits")
        except Exception as exc:  # noqa: BLE001 - the flows or the adoption could not be read; nothing was created
            logger.opt(exception=True).warning("master draft: flows unreadable")
            return refused("读不到这个项目的业务流（原因已记进日志）", f"flows unreadable: {type(exc).__name__}: {exc}")
        # The owner reads the title in the receipt: the flow's name, never its id.
        title = str(action.get("title", "") or "").strip()[:80] or str(getattr(package, "name", "") or "").strip() or "新工单"
        try:
            order = await asyncio.to_thread(
                console.create_order,
                workflow_id=package.id,
                fields=fields,
                project_id=pid,
                source=drafting.ORDER_SOURCE,
                actor=_ws_actor_login(self, ws) or "owner",
                status="pending_review",
            )
        except (OrderTransitionError, ValueError) as exc:
            return refused(_owner_words(exc) or "工单没能建出来（原因已告诉安安）", f"the console refused the order: {exc}")
        except Exception as exc:  # noqa: BLE001 - an order may or may not exist; the owner is told where to look
            logger.opt(exception=True).warning(f"Master control failed to draft an order: {exc}")
            return refused(
                "系统出错，原因已记进日志。先到业务工单看看这张单有没有建出来，再决定要不要重新起草",
                f"order draft failed: {exc}",
            )
        detail = {
            "order_id": order.order_id,
            "workflow_id": package.id,
            "status": order.status,
            "fields": sorted(fields),
            "note": "drafted only: it waits in 业务工单「待接单」 until the owner releases it; nothing runs, no session was "
            "created, nothing was spent",
        }
        if zh:
            return MasterAnswer((f"已起草工单《{title}》，在业务工单「待接单」里等你放行。", order.order_id), detail)
        return MasterAnswer(
            (f"Drafted work order \"{title}\"; it waits in Orders under \"waiting to be taken\" for you to release it.",
             order.order_id),
            detail,
        )

    # ── Blockers (阻塞/待审批) ───────────────────────────────────────────

    async def _handle_employee_task_center_read(self, ws: Any, data: dict) -> None:
        """Default-off read of derived task-center health (live/interrupted/idle)."""
        from ampuly.plugins.office_ui.employee_task_center_ws import dispatch_task_center_read

        reply = await dispatch_task_center_read(self, ws, data if type(data) is dict else {})
        await self._send_ack(ws, **{k: v for k, v in reply.items()})

    async def _handle_pending_approval_badge_read(self, ws: Any, data: dict) -> None:
        """Default-off pending-approval badge read; WS push reuses blockers channel."""
        from ampuly.plugins.office_ui.pending_approval_badge_ws import dispatch_pending_approval_badge_read

        reply = await dispatch_pending_approval_badge_read(self, ws, data if type(data) is dict else {})
        await self._send_ack(ws, **{k: v for k, v in reply.items()})

    async def _handle_blockers_list(self, ws: Any, data: dict) -> None:
        """List everything currently waiting on a human decision.

        A run that pauses for a tool-permission checkpoint produces no logs
        and no runtime activity, so from the outside it is indistinguishable
        from a hang (observed twice Previously,: a web_fetch approval and a
        list_dir approval each stalled a station for tens of minutes while the
        console reported zero blockers). Surfacing the pending checkpoints
        directly is what makes that state legible.
        """
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="blockers_list", project_id=str(data.get("project_id") or ""), error="owner_required")
            return
        read_actor = _ws_actor_login(self, ws)
        run_engine, pid = await self._engine_for_request(data)
        store = getattr(run_engine, "store", None)
        items: list[dict[str, Any]] = []
        # What each item was built from, for the owner's card: the checkpoint (its pause request's facts) and the
        # waiting task (its runtime title, put in the owner's words there and nowhere in the item's text).
        sources: dict[str, tuple[Any, Any]] = {}
        if store is not None and self._store_is_ready(store):
            try:
                checkpoints = await store.get_pending_checkpoints(project_id=pid)
            except Exception as exc:
                logger.opt(exception=True).warning("blockers: failed to load pending checkpoints")
                await self._send_ack(
                    ws,
                    ok=False,
                    action="blockers_list",
                    project_id=pid,
                    error=str(exc) or "blockers_unavailable",
                )
                return
            # One reading of a pending checkpoint, shared with the
            # master-control context so the two can never disagree. The row
            # names the step as the owner knows it: the waiting task is read
            # here so its runtime title ("Report #1: X") is put in the
            # owner's words where the subject quotes it.
            get_task = getattr(store, "get_task", None)
            items = []
            for checkpoint in checkpoints:
                item = blocker_from_checkpoint(checkpoint)
                waiting_id = str(item.get("waiting_task_id", "") or "")
                waiting_task = None
                if waiting_id and callable(get_task):
                    try:
                        waiting_task = await get_task(waiting_id)
                    except Exception:
                        waiting_task = None
                if waiting_task is not None:
                    item = blocker_from_checkpoint(checkpoint, waiting_task=waiting_task)
                items.append(item)
                sources[str(item.get("checkpoint_id", "") or "")] = (checkpoint, waiting_task)
            business = self._accounts().business
            link = self._feishu_chat_link() if self._gate_configured() else ""
            for item in items:
                checkpoint_id = str(item.get("checkpoint_id", "") or "")
                try:
                    spec = await self._gate_spec_for_blocker(run_engine, item)
                except Exception:
                    spec = None
                if spec is not None and getattr(spec, "is_permission", False):
                    # A permission request is not a business gate: no ``gate`` (the page ignored it anyway), but the
                    # request in the owner's words as the card's spec resolved it -- describe_path knows the order
                    # folder, the page does not, so a "C:\\Users\\..." path is told apart from one inside the order.
                    details = dict(getattr(spec, "permission", {}) or {})
                    item["permission"] = {"summary": str(details.get("summary", "") or ""), "outside": bool(details.get("outside"))}
                elif spec is not None:
                    item["gate"] = {"node_id": spec.node_id, "node_name": spec.node_name, "version": spec.version, "assignee": spec.assignee}
                card = business.gate_card(checkpoint_id)
                if card and card.get("message_id"):
                    item["feishu"] = {"sent_at": str(card.get("sent_at", "") or ""), "link": link, "decision": str(card.get("decision", "") or "")}
        from ampuly.plugins.office_ui.blockers import hide_pauses_of_suspended_runs

        # A closed order's run is never resumed: its park (the cancel's suspend, or a restart's re-park) is not
        # listed as 运行已停放. Unreadable orders hide nothing rather than fail the list.
        closed_task_ids: set[str] = set()
        closed_orders_exact = True
        try:
            closed_task_ids = {
                str(getattr(order, "launched_task_id", "") or "").strip()
                for order in await asyncio.to_thread(self._accounts().business.list_orders, project_id=pid, status="closed")
            } - {""}
        except Exception:
            closed_orders_exact = False
            logger.warning("blockers: closed orders unreadable; listing every park")
        items, suspended_hidden = hide_pauses_of_suspended_runs(items, closed_task_ids=closed_task_ids)
        # A19: a held reminder stays in the list -- holding decides nothing --
        # and says so, so the panel and the master read the same snoozes and
        # a pause is never mistaken for handled because its reminder is off.
        if items:
            try:
                snoozed = await asyncio.to_thread(self._accounts().business.active_snoozes, project_id=pid)
            except Exception:
                logger.warning("blockers: snoozes unreadable; listing every blocker as due")
                snoozed = {}
            for item in items:
                held = (snoozed or {}).get(str(item.get("checkpoint_id", "") or ""))
                if held:
                    item["snoozed_until"] = str(held.get("until_at", "") or "")
                    item["snooze_note"] = str(held.get("note", "") or "")
        # S1-A : every item carries the owner's card -- one wording for every card, projected on the
        # server and nowhere else (owner_card.project; the frontend's word table is only its test sample). The
        # order is found the way the pages match a pause to one (the run's task, else the order's own id); an order
        # or an employee's name that cannot be read leaves the card without it, never the pause unlisted.
        if items:
            from ampuly.plugins.office_ui.owner_card import assignee_of, project as owner_card_of

            business = self._accounts().business
            org_engine = getattr(run_engine, "org_engine", None)

            def _order_of(item: dict[str, Any]) -> Any:
                for key in ("task_id", "waiting_task_id"):
                    run_task_id = str(item.get(key, "") or "").strip()
                    if run_task_id:
                        found = business.order_for_launched_task(run_task_id, project_id=pid)
                        if found is not None:
                            return found
                for key in ("task_id", "session_id"):
                    order_key = str(item.get(key, "") or "").strip()
                    if order_key:
                        found = business.get_order(order_key, project_id=pid)
                        if found is not None:
                            return found
                return None

            def _employee_name(employee_id: str) -> str:
                getter = getattr(org_engine, "get_employee", None)
                if callable(getter):
                    try:
                        name = str(getattr(getter(employee_id), "name", "") or "").strip()
                    except Exception:
                        name = ""
                    if name:
                        return name
                list_accounts = getattr(self._accounts(), "list_accounts", None)
                if callable(list_accounts):
                    try:
                        for account in list_accounts():
                            if str(getattr(account, "employee_id", "") or "").strip() == employee_id:
                                return str(getattr(account, "display_name", "") or "").strip()
                    except Exception:
                        pass
                return ""

            orders_seen: dict[tuple[str, str, str], Any] = {}
            names: dict[str, str] = {}
            for item in items:
                checkpoint, waiting_task = sources.get(str(item.get("checkpoint_id", "") or ""), (None, None))
                anchor = tuple(str(item.get(key, "") or "").strip() for key in ("task_id", "waiting_task_id", "session_id"))
                if anchor not in orders_seen:
                    try:
                        orders_seen[anchor] = await asyncio.to_thread(_order_of, item)
                    except Exception:
                        logger.warning("blockers: the order of a pause could not be read; its card names no order")
                        orders_seen[anchor] = None
                employee_id = assignee_of(item, checkpoint=checkpoint)
                if employee_id and employee_id not in names:
                    names[employee_id] = await asyncio.to_thread(_employee_name, employee_id)
                item["owner_card"] = owner_card_of(
                    item, order=orders_seen[anchor], zh=_ws_is_zh(), checkpoint=checkpoint, waiting_task=waiting_task, employee_names=names,
                )
        if (not _ws_is_owner(self, ws) or _ws_actor_login(self, ws) != read_actor
                or str(getattr(run_engine, "project_id", "") or "") != str(pid)):
            await self._send_ack(ws, ok=False, action="blockers_list", project_id=pid, error="scope_changed")
            return
        # Top5 item5: optional pending-approval badge on blockers channel (env-gated; default off).
        badge_payload = None
        try:
            from ampuly.plugins.office_ui.pending_approval_badge_ws import badge_from_blocker_items
            badge_payload = badge_from_blocker_items(items, project_id=pid, actor_login=_ws_actor_login(self, ws))
            if badge_payload is not None and not closed_orders_exact:
                badge_payload.update(count_exact=False, limited=True)
        except Exception:
            logger.opt(exception=True).warning("blockers: pending approval badge attach failed")
            badge_payload = None
        ack_kwargs = dict(ok=True, action="blockers_list", project_id=pid, blockers=items, suspended_hidden=suspended_hidden)
        if badge_payload is not None:
            ack_kwargs["pending_approval_badge"] = badge_payload
        await self._send_ack(ws, **ack_kwargs)

    async def _handle_blocker_snooze(self, ws: Any, data: dict) -> None:
        """Hold one blocker's reminder from the panel (A19).

        Same funnel as the master's `master_snooze_blocker`: owner only, the
        time must be a timestamp, and the blocker itself is untouched -- the
        ack says so in words. The panel offers it only on a listed pause; the
        store does not check pendingness (the master's validator does that
        for the conversation path).
        """
        checkpoint_id = str(data.get("checkpoint_id", "") or "").strip()
        try:
            pid = self._request_project_id(data)
        except ProjectScopeError:
            await self._send_ack(ws, ok=False, action="blocker_snooze", project_id="",
                                 checkpoint_id=checkpoint_id, error="project_id_required")
            return
        ok, note = await self._master_snooze_blocker(
            {"checkpoint_id": checkpoint_id, "until_at": data.get("until_at", ""), "note": data.get("note", "")},
            ws=ws, project_id=pid,
        )
        if not ok:
            await self._send_ack(ws, ok=False, action="blocker_snooze", project_id=pid,
                                 checkpoint_id=checkpoint_id, error=note)
            return
        try:
            held = await asyncio.to_thread(self._accounts().business.active_snoozes, project_id=pid)
        except Exception:
            held = {}
        until_at = str((held or {}).get(checkpoint_id, {}).get("until_at", "") or "")
        await self._send_ack(ws, ok=True, action="blocker_snooze", project_id=pid,
                             checkpoint_id=checkpoint_id, until_at=until_at, note=note)

    async def _handle_blocker_unsnooze(self, ws: Any, data: dict) -> None:
        """Bring one blocker's reminder back (A19). Owner only; idempotent."""
        checkpoint_id = str(data.get("checkpoint_id", "") or "").strip()
        try:
            pid = self._request_project_id(data)
        except ProjectScopeError:
            await self._send_ack(ws, ok=False, action="blocker_unsnooze", project_id="",
                                 checkpoint_id=checkpoint_id, error="project_id_required")
            return
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="blocker_unsnooze", project_id=pid,
                                 checkpoint_id=checkpoint_id, error="owner_required")
            return
        if not checkpoint_id:
            await self._send_ack(ws, ok=False, action="blocker_unsnooze", project_id=pid,
                                 checkpoint_id="", error="checkpoint_id_required")
            return
        removed = await asyncio.to_thread(
            self._accounts().business.unsnooze_blocker, checkpoint_id, project_id=pid,
        )
        await self._send_ack(ws, ok=True, action="blocker_unsnooze", project_id=pid,
                             checkpoint_id=checkpoint_id, removed=bool(removed))

