    # ── 资料 (data phase 2): read-only views of one project's own files ──

    @property
    def _data_usage_waiters(self) -> dict[str, set]:
        """Which sockets are waiting for which project's walk. Built on first use, as the cache is."""
        waiting = getattr(self, "_data_usage_waiting", None)
        if waiting is None:
            waiting = {}
            self._data_usage_waiting = waiting
        return waiting

    def _data_usage_cache(self) -> Any:
        """The server's usage walks, built on first use so a handler fake needs to know nothing about them."""
        cache = getattr(self, "_data_usage_walks", None)
        if cache is None:
            from ampuly.plugins.office_ui.data_actions import UsageCache

            cache = UsageCache()
            self._data_usage_walks = cache
        return cache

    def _data_request(self, ws: Any, data: dict) -> Any:
        """What the seven 资料 reads share: the project, who is asking, and where that project's files are.

        No engine is built and no folder is created. ``_engine_for_request`` would do both -- for a destroyed
        project it re-creates the directory and an empty store, which is what a destroyed project must not get
        back. Reading files needs neither.
        """
        from ampuly.plugins.office_ui import data_actions
        from ampuly.plugins.office_ui.data_scope import Viewer
        from ampuly.project_id import is_valid_project_id

        project_id = self._request_project_id(data)
        context = self.services_context
        if not is_valid_project_id(project_id) or not context.project_exists(project_id):
            raise data_actions.DataDenied("project_not_found", project_id)
        accounts = self._accounts()
        viewer = Viewer(owner=_ws_is_owner(self, ws), customers=ws_customer_scope(self, ws))
        home = Path(context.ampuly_home)
        # Only what is free is done here. The lifecycle record, the project's customer binding and the order map are
        # SQLite reads; they happen in ``Request.open()``, which runs in a thread.
        return data_actions.Request(
            project_id=project_id,
            viewer=viewer,
            roots=data_actions.Roots(
                project=Path(get_project_workplace(project_id)),
                attachments=home / "projects" / project_id / "attachments",
                workplace=Path(get_default_workplace_root()),
                home=home,
            ),
            data=dict(data or {}),
            business=accounts.business,
            is_destroyed=lambda: context.project_is_destroyed(project_id),
            read_binding=lambda: str(accounts.business.project_customer(project_id) or "").strip() or None,
        )

    def _record_data_read(self, ws: Any, project_id: str, action: str, object_type: str, *, object_id: str = "*",
                          customer_id: str = "", outcome: str = "success",
                          metadata: dict[str, Any] | None = None) -> None:
        """One row per 资料 call. A read that was refused is recorded too, with what it asked for."""
        try:
            self._console_api().record_observation(
                project_id=project_id or "default", actor=_ws_actor_login(self, ws), action=action,
                object_type=object_type, object_id=object_id, customer_id=customer_id,
                reason=f"console_{action}", outcome=outcome, metadata=metadata or {},
            )
        except Exception as exc:  # noqa: BLE001 - an audit row must never break the read itself
            logger.warning(f"data read observation failed: {type(exc).__name__}")

    async def _handle_data_action(self, ws: Any, data: dict, action: str, object_type: str, work: Any,
                                  *, context: dict[str, Any] | None = None, audit: bool = True) -> None:
        """One 资料 read: the shared checks, the work in a thread, one observation, one ack.

        ``work(request)`` runs off the event loop and returns ``(payload, object_id, customer_id)``. Every failure
        is answered as one fixed code -- never ``str(exc)``, which today's artifact handlers send and which carries
        absolute paths and OS text to whoever is looking.
        """
        from ampuly.plugins.office_ui import data_actions
        from ampuly.plugins.office_ui.data_browser import DataRefused
        from ampuly.plugins.office_ui.dir_browser import DirRefused
        from ampuly.plugins.office_ui.folder_move import MoveRefused

        project_id = ""
        try:
            request = self._data_request(ws, data)
            project_id = request.project_id

            def prepared_work(one: Any = request) -> tuple[dict, str, str]:
                one.open()
                return work(one)

            payload, object_id, customer_id = await asyncio.to_thread(prepared_work)
        except ProjectScopeError:
            await self._send_ack(ws, ok=False, action=action, error="project_not_found")
            return
        except data_actions.DataDenied as denied:
            project_id = denied.project_id or project_id
            self._record_data_read(ws, project_id, action, object_type, outcome="denied",
                                   metadata={"error": denied.code})
            await self._send_ack(ws, ok=False, action=action, project_id=project_id, error=denied.code,
                                 **(context or {}))
            return
        except (DataRefused, DirRefused, MoveRefused) as refused:
            # Every reader in this entry refuses the same way: a code the console can say in words.
            outcome = "not_found" if refused.code == "not_found" else "error"
            self._record_data_read(ws, project_id, action, object_type, outcome=outcome,
                                   metadata={"error": refused.code})
            await self._send_ack(ws, ok=False, action=action, project_id=project_id, error=refused.code,
                                 **(context or {}))
            return
        except Exception as exc:  # noqa: BLE001 - the reply says "error"; the type goes to the log and the row
            logger.warning(f"{action} failed: {type(exc).__name__}")
            self._record_data_read(ws, project_id, action, object_type, outcome="error",
                                   metadata={"error_type": type(exc).__name__})
            await self._send_ack(ws, ok=False, action=action, project_id=project_id, error="error",
                                 **(context or {}))
            return
        if audit:
            self._record_data_read(ws, project_id, action, object_type, object_id=object_id,
                                   customer_id=customer_id)
        await self._send_ack(ws, ok=True, action=action, project_id=project_id, **payload)

    async def _handle_data_project_index(self, ws: Any, data: dict) -> None:
        from ampuly.plugins.office_ui import data_actions

