    async def _handle_forget_backup_task(self, ws: Any, data: dict) -> None:
        """清掉一个备份计划任务（policy：旧任务保留，但用户要能自己清）。

        只清产品自己装的那几个——`scheduled_task.forget` 先问一遍清单，名字不在里面就拒绝。控制台上的一个
        按钮不该能删掉这台机器上任意一个计划任务。
        """
        from ampuly.core import scheduled_task

        name = str(data.get("name", "") or "").strip()
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="forget_backup_task", name=name, error="owner_required")
            return
        try:
            code, said = await asyncio.to_thread(
                scheduled_task.forget, name=name, this_home=self.services.context.ampuly_home)
        except scheduled_task.NotWindows:
            await self._send_ack(ws, ok=False, action="forget_backup_task", name=name,
                                 error="计划任务只在 Windows 上")
            return
        await self._send_ack(ws, ok=code == 0, action="forget_backup_task", name=name,
                             error="" if code == 0 else "；".join(said), said=said)

