    async def _handle_notify_test(self, ws: Any, data: dict) -> None:
        """Send one test line through every configured pager channel."""
        from ampuly.plugins.office_ui.notifier import compose_test, notifier_from_env

        _ = data
        notifier = notifier_from_env(outbound_allowed=self._connector_refusal)
        if not notifier.configured:
            await self._send_ack(ws, ok=False, action="notify_test", error="not_configured")
            return
        results = await notifier.send(compose_test(base_url=self._public_base_url()))
        await self._send_ack(
            ws,
            ok=all(result.ok for result in results),
            action="notify_test",
            results=[{"channel": r.channel, "ok": r.ok, "detail": r.detail} for r in results],
            recent=list(self._duty_log[-10:]),
        )

    def _workflow_registry(self) -> list[Any]:
        from ampuly.plugins.office_ui.workflow_packages import discover_packages

        repo_root = Path(__file__).resolve().parents[3]
        ampuly_home = Path(getattr(self.engine, "ampuly_home", None) or Path.cwd() / ".ampuly")
        return discover_packages(repo_root, ampuly_home)

    async def _handle_workflow_list(self, ws: Any, data: dict) -> None:
        """Published (and, for the owner, testing) workflow packages.

        A package is a tested business line stored as one directory; the
        card shows what an order needs to know - gates, stations, the last
        recorded run's duration and cost - and nothing that has to be
        configured, because nothing does.
        """
        from ampuly.plugins.office_ui.workflow_packages import visible_packages

        try:
            project_id = self._request_project_id(data)
        except ProjectScopeError as exc:
            await self._send_ack(
                ws,
                ok=False,
                action="workflow_list",
                project_id=str(data.get("project_id", "") or "").strip(),
                error=str(exc),
            )
            return
        include_testing = bool(data.get("include_testing", True))
        # The owner's builder also lists drafts (＋ 新建业务流, 安安's flow drafts): they are built there and never
        # orderable. Anyone else sees what is released or being tested, as before. A flow derived for another project
        # is not listed at all: one project is one customer, and that flow is theirs.
        packages = visible_packages(
            self._workflow_registry(), include_testing=include_testing, include_drafts=_ws_is_owner(self, ws),
            project_id=project_id,
        )
        await self._send_ack(
            ws,
            ok=True,
            action="workflow_list",
            project_id=project_id,
            workflows=[p.to_payload() for p in packages],
        )

