    async def _handle_workflow_release_evidence(self, ws: Any, data: dict) -> None:
        """The signed publish-time pack plus what the version did afterwards."""
        from ampuly.plugins.office_ui.release_runtime_evidence import build_runtime_evidence
        from ampuly.plugins.office_ui.workflow_asset import project_workflow_asset_from_evidence

        project_id = self._request_project_id(data)
        workflow_id = str(data.get("workflow_id", "") or "").strip()
        if await _ws_refuse_other_projects_flow(self, ws, action="workflow_release_evidence", project_id=project_id, workflow_id=workflow_id, doing="查看"):
            return
        package = self._console_api().package(workflow_id)
        if package is None:
            await self._send_ack(ws, ok=False, action="workflow_release_evidence", project_id=project_id, workflow_id=workflow_id, error="workflow_not_found")
            return
        try:
            evidence = build_runtime_evidence(package, self._accounts().business)
        except (OSError, TypeError, ValueError) as exc:
            await self._send_ack(ws, ok=False, action="workflow_release_evidence", project_id=project_id, workflow_id=workflow_id, error=str(exc))
            return
        allowed = ws_customer_scope(self, ws)
        if allowed:
            # A bound account sees only its own customers' verdicts.
            acceptance = evidence.get("runtime_evidence", {}).get("acceptance", {})
            orders = [o for o in list(acceptance.get("orders") or []) if str(o.get("customer_id", "")) in allowed]
            counts: dict[str, int] = {}
            for order in orders:
                counts[str(order.get("status", ""))] = counts.get(str(order.get("status", "")), 0) + 1
            acceptance["orders"] = orders
            acceptance["counts"] = counts
            acceptance["narrowed_to_scope"] = True
        evidence["workflow_asset"] = project_workflow_asset_from_evidence(evidence).to_payload()
        await self._send_ack(ws, ok=True, action="workflow_release_evidence", project_id=project_id, workflow_id=workflow_id, evidence=evidence)

