    async def _handle_improvement_proposal_bind_evaluation(self, ws: Any, data: dict) -> None:
        """Freeze the exact candidate identity and metrics before accepting results.

        4.7-A11: the console sends a ``standard`` (what should get better, by how much, how many run sessions per
        side); what is measured -- the proposal's own materialized candidate -- is filled in here, never typed.
        """
        from ampuly.plugins.office_ui.business_store import OrderTransitionError

        project_id = self._request_project_id(data)
        proposal_id = str(data.get("proposal_id", "") or "").strip()
        if not _ws_is_owner(self, ws):
            await self._send_ack(
                ws, ok=False, action="improvement_proposal_bind_evaluation",
                project_id=project_id, proposal_id=proposal_id, error="owner_required",
            )
            return
        spec_payload = data.get("spec")
        standard = data.get("standard")
        if not isinstance(spec_payload, dict) and not isinstance(standard, dict):
            await self._send_ack(
                ws, ok=False, action="improvement_proposal_bind_evaluation",
                project_id=project_id, proposal_id=proposal_id,
                error="evaluation_spec_required",
            )
            return
        try:
            if isinstance(standard, dict):
                proposal = await asyncio.to_thread(
                    self._console_api().bind_improvement_session_standard,
                    proposal_id,
                    actor=_ws_actor_login(self, ws),
                    project_id=project_id,
                    expected_fingerprint=str(data.get("expected_fingerprint", "") or "").strip(),
                    hypothesis=str(standard.get("hypothesis", "") or ""),
                    metrics=list(standard.get("metrics") or []) if isinstance(standard.get("metrics"), list) else [],
                    min_samples=standard.get("min_samples"),
                )
            else:
                proposal = self._console_api().bind_improvement_evaluation(
                    proposal_id,
                    actor=_ws_actor_login(self, ws),
                    project_id=project_id,
                    expected_fingerprint=str(data.get("expected_fingerprint", "") or "").strip(),
                    spec_payload=spec_payload,
                )
        except (OrderTransitionError, TypeError, ValueError) as exc:
            await self._send_ack(
                ws, ok=False, action="improvement_proposal_bind_evaluation",
                project_id=project_id, proposal_id=proposal_id, error=str(exc),
            )
            return
        await self._send_ack(
            ws, ok=True, action="improvement_proposal_bind_evaluation",
            project_id=project_id, proposal_id=proposal_id, proposal=proposal,
        )

    async def _handle_improvement_proposal_record_evaluation(self, ws: Any, data: dict) -> None:
        """Record what the change did on real orders; nothing publishes and nothing typed is accepted.

        4.7-A11: the evaluation is no longer a pair of numbers from the page. It is the last N finished real orders
        (``sample_size``, default 5) before and after, measured from the business store's order events and the usage
        ledger's model spend. Numbers sent with the request are ignored, never recorded.
        """
        from ampuly.plugins.office_ui.business_store import OrderTransitionError
        from ampuly.plugins.office_ui.improvement_proposal import DEFAULT_BENEFIT_SAMPLE

        project_id = self._request_project_id(data)
        proposal_id = str(data.get("proposal_id", "") or "").strip()
        if not _ws_is_owner(self, ws):
            await self._send_ack(
                ws, ok=False, action="improvement_proposal_record_evaluation",
                project_id=project_id, proposal_id=proposal_id, error="owner_required",
            )
            return
        spend = await WSHandler._improvement_order_spend(self, data, project_id)
        try:
            proposal = await asyncio.to_thread(
                self._console_api().evaluate_improvement_benefit,
                proposal_id,
                actor=_ws_actor_login(self, ws),
                project_id=project_id,
                expected_fingerprint=str(data.get("expected_fingerprint", "") or "").strip(),
                sample_size=data.get("sample_size", DEFAULT_BENEFIT_SAMPLE),
                spend=spend,
            )
        except (OrderTransitionError, TypeError, ValueError) as exc:
            await self._send_ack(
                ws, ok=False, action="improvement_proposal_record_evaluation",
                project_id=project_id, proposal_id=proposal_id, error=str(exc),
            )
            return
        await self._send_ack(
            ws, ok=True, action="improvement_proposal_record_evaluation",
            project_id=project_id, proposal_id=proposal_id, proposal=proposal,
        )

    async def _improvement_order_spend(self, data: dict, project_id: str) -> dict[str, float] | None:
        """Model spend per order from the usage ledger, for the real-order benefit check; None when unreadable."""
        from ampuly.plugins.office_ui.improvement_proposal import spend_by_order

        try:
            engine, _pid = await self._engine_for_request(data)
            store = getattr(engine, "store", None)
            cost_by_task = await store.get_cost_by_task(project_id)
            tasks = await store.get_tasks(project_id=project_id)
        except Exception:
            logger.opt(exception=True).debug("improvement benefit: the usage ledger could not be read for project {}", project_id)
            return None
        return spend_by_order(cost_by_task or {}, tasks or [])

    async def _handle_improvement_proposal_start(self, ws: Any, data: dict) -> None:
        """4.7-A11 提一个改进: one sentence on a published flow, a library skill or a registered connector.

        The server drafts and materializes an inert candidate and answers which editor it opens in; nothing is
        tested, approved, activated or published. Owner only.
        """
        from ampuly.plugins.office_ui.business_store import OrderTransitionError

        project_id = self._request_project_id(data)
        target_kind = str(data.get("target_kind", "") or "").strip()
        target_id = str(data.get("target_id", "") or "").strip()
        if not _ws_is_owner(self, ws):
            await self._send_ack(
                ws, ok=False, action="improvement_proposal_start", project_id=project_id,
                target_kind=target_kind, target_id=target_id, error="owner_required",
            )
            return
        try:
            started = await asyncio.to_thread(
                self._console_api().start_improvement,
                target_kind,
                target_id,
                str(data.get("request", "") or ""),
                actor=_ws_actor_login(self, ws),
                project_id=project_id,
                conversation_id=f"console:{project_id}",
                turn_id=f"improve-{uuid.uuid4().hex[:12]}",
            )
        except (OrderTransitionError, TypeError, ValueError, OSError) as exc:
            await self._send_ack(
                ws, ok=False, action="improvement_proposal_start", project_id=project_id,
                target_kind=target_kind, target_id=target_id, error=str(exc),
            )
            return
        await self._send_ack(
            ws, ok=True, action="improvement_proposal_start", project_id=project_id,
            target_kind=target_kind, target_id=target_id, **started,
        )

    async def _handle_improvement_proposal_approve(self, ws: Any, data: dict) -> None:
        """Approve an improvement on the real orders as they are now: worse refuses, too few orders decides nothing."""
        from ampuly.plugins.office_ui.business_store import OrderTransitionError
        from ampuly.plugins.office_ui.improvement_proposal import DEFAULT_BENEFIT_SAMPLE

        project_id = self._request_project_id(data)
        proposal_id = str(data.get("proposal_id", "") or "").strip()
        if not _ws_is_owner(self, ws):
            await self._send_ack(
                ws, ok=False, action="improvement_proposal_approve",
                project_id=project_id, proposal_id=proposal_id, error="owner_required",
            )
            return
        spend = await WSHandler._improvement_order_spend(self, data, project_id)
        try:
            decided = await asyncio.to_thread(
                self._console_api().approve_improvement,
                proposal_id,
                actor=_ws_actor_login(self, ws),
                project_id=project_id,
                expected_fingerprint=str(data.get("expected_fingerprint", "") or "").strip(),
                note=str(data.get("note", "") or "").strip(),
                sample_size=data.get("sample_size", DEFAULT_BENEFIT_SAMPLE),
                spend=spend,
            )
        except (OrderTransitionError, TypeError, ValueError) as exc:
            await self._send_ack(
                ws, ok=False, action="improvement_proposal_approve",
                project_id=project_id, proposal_id=proposal_id, error=str(exc),
            )
            return
        # A negative benefit is a refusal the owner reads (the proposal is recorded as rejected with its reason).
        await self._send_ack(
            ws, ok=bool(decided["approved"]), action="improvement_proposal_approve",
            project_id=project_id, proposal_id=proposal_id, proposal=decided["proposal"],
            approved=bool(decided["approved"]), reason=decided["reason"],
            **({} if decided["approved"] else {"error": decided["reason"]}),
        )

