    async def _handle_flow_component_candidate_action(self, ws: Any, data: dict) -> None:
        from .flow_component_adoption import (ComponentAdoptionError, retained_candidate,
            inspect_component_candidate, adopt_component_candidate)
        project_id = self._request_project_id(data)
        action = data.get("type")
        request_id = data.get("request_id")
        if action not in {"workflow_component_candidate_target", "workflow_adopt_component_draft"}:
            return
        try:
            if not _ws_is_owner(self, ws):
                raise ComponentAdoptionError("owner_required")
            mid, cid = data.get("candidate_message_id"), data.get("candidate_id")
            if (type(mid) is not str or not mid or len(mid) > 128 or type(cid) is not str
                    or not cid.startswith("component-") or len(cid) != 34):
                raise ComponentAdoptionError("invalid_request")
            stored_candidate = await _master_message_by_id(self.chat_store, project_id, mid)
            candidate = retained_candidate(stored_candidate, project_id=project_id, message_id=mid, candidate_id=cid)
            if data.get("source_reference") != candidate.get("source"):
                raise ComponentAdoptionError("source_reference_changed")
            stored_source = await _master_message_by_id(self.chat_store, project_id, candidate["source"]["message_id"])
            api = self._console_api()
            common = dict(stored_candidate=stored_candidate, stored_source=stored_source, project_id=project_id,
                candidate_message_id=mid, candidate_id=cid, actor=_ws_actor_login(self, ws),
                authorize_owner=lambda: _ws_is_owner(self, ws))
            if action == "workflow_component_candidate_target":
                result = await asyncio.to_thread(inspect_component_candidate, **common,
                    source_reference=data.get("source_reference"), packages=self._workflow_registry())
            else:
                expected = data.get("expected_materialized")
                if type(expected) is not dict or type(expected.get("package_id")) is not str:
                    raise ComponentAdoptionError("invalid_request")
                target = api.package(expected["package_id"])
                if target is None:
                    raise ComponentAdoptionError("invalid_package")
                result = await asyncio.to_thread(adopt_component_candidate, **common, package=target,
                    expected_materialized=expected, new_version=data.get("new_version"), request_id=request_id,
                    ampuly_home=api.ampuly_home, check_only=data.get("check_only", False))
        except (TypeError, ValueError, OSError) as error:
            await self._send_ack(ws, ok=False, action=action, project_id=project_id, request_id=request_id,
                error=getattr(error, "code", "component_draft_unavailable"),
                effects_produced=False if action == "workflow_component_candidate_target" else getattr(error, "effects_produced", None),
                external_effects_produced=False)
            return
        await self._send_ack(ws, action=action, project_id=project_id, request_id=request_id, **result)

    async def _handle_workflow_create_from_flow_draft(self, ws: Any, data: dict) -> None:
        """在搭建台打开 a 安安 flow draft (4.7 Q04-B): a new draft package, and the draft's steps for the canvas.

        The steps are not taken from the page: the requirement spec stored on 安安's reply is compiled again here,
        against the team the owner chose and the library as it is now. The new package is an empty draft; the steps
        go to the builder as an unsaved draft and are saved through the ordinary save. Owner only.
        """
        from ampuly.plugins.office_ui.business_store import OrderTransitionError
        from ampuly.plugins.office_ui.flow_compiler import (
            IntentRefused,
            compile_intent,
            flow_draft_library,
            flow_draft_team,
            normalize_intent,
        )

        project_id = self._request_project_id(data)
        message_id = str(data.get("message_id", "") or "").strip()
        draft_id = str(data.get("draft_id", "") or "").strip()
        action = "workflow_create_from_flow_draft"

        async def refuse(error: str, **extra: Any) -> None:
            await self._send_ack(ws, ok=False, action=action, project_id=project_id, message_id=message_id, error=error, **extra)

        if not _ws_is_owner(self, ws):
            await refuse("owner_required")
            return
        # The reply that carried the draft, by its id, in whichever of the project's 总控 conversations it was said
        # (总控对话栏) and however old it is; it used to be looked for among the first conversation's newest 300 rows.
        found = await _master_message_by_id(self.chat_store, project_id, message_id) if message_id else None
        stored = found if found is not None and found.get("sender") != "user" else None
        draft = dict((stored or {}).get("metadata") or {}).get("master_flow_draft")
        if data.get("source_reference") is not None:
            from .flow_draft_resume import DraftReferenceError, resolve_exact_draft
            try:
                draft = resolve_exact_draft(stored, data["source_reference"], project_id=project_id)
            except DraftReferenceError as error:
                await refuse(error.code)
                return
        if not isinstance(draft, dict) or not isinstance(draft.get("intent"), dict):
            await refuse("flow_draft_not_found")
            return
        try:
            intent = normalize_intent(draft["intent"])
        except IntentRefused as exc:
            await refuse("flow_draft_invalid", message=str(exc))
            return
        team, roles = flow_draft_team(str(data.get("team", "") or "").strip() or intent["team"])
        if not team:
            await refuse("team_required")
            return
        intent["team"] = team
        registry = self._workflow_registry()
        if data.get("source_reference") is not None and data.get("expected_materialized") is not None:
            from .flow_draft_resume import DraftReferenceError, resolve_materialized_draft
            try:
                resolve_materialized_draft(registry, data["source_reference"], project_id=project_id,
                    expected=data["expected_materialized"])
            except DraftReferenceError as error:
                await refuse(error.code)
                return
        # The project's own registered connectors count as library entries: a step that has a real API for it
        # should get that API, not the browser.
        _roots = getattr(self, "_connector_candidate_roots", None)
        _registry_root = None
        if callable(_roots):
            try:
                _candidate_root, _registry_root = _roots(project_id)
            except Exception:  # noqa: BLE001 - no registry means no API entries, not a failed draft
                _registry_root = None
        compiled = compile_intent(
            intent, roles=roles,
            library=flow_draft_library(Path(__file__).resolve().parents[3], registry, registry_root=_registry_root),
        )
        # One card, one flow: a card opened again -- a second click, another window, a retry -- finds the draft it
        # made instead of making another (4.7 Q04-B: repeated generation is idempotent).
        origin = f"flow_draft:{project_id}:{message_id}"
        package = next((item for item in registry if str(item.manifest.get("created_from", "") or "") == origin), None)
        existing = package is not None
        if package is None:
            try:
                package = self._console_api().create_blank_workflow_draft(
                    draft_id=draft_id, actor=_ws_actor_login(self, ws), org_source=_saved_org_path(team, strict=False),
                    name=intent["name"], summary=intent["summary"], intake_fields=intent["intake"] or None,
                    created_from=origin,
                )
            except (OrderTransitionError, TypeError, ValueError) as exc:
                await refuse(str(exc))
                return
        await self._send_ack(
            ws, ok=True, action=action, project_id=project_id, message_id=message_id, draft_id=package.id,
            existing=existing, workflow=package.to_payload(), nodes=compiled["nodes"],
            missing_components=compiled["missing_components"], unassigned_steps=compiled["unassigned_steps"],
            incomplete_steps=compiled["incomplete_steps"], library_revision=compiled["library_revision"],
        )

    async def _handle_workflow_derive_for_project(self, ws: Any, data: dict) -> None:
        """派生为本项目草稿 (policy): this project's own draft of a global flow; the template is untouched.

        The project is the request's own. Asking again for the same project answers with the draft already made
        (``existing``). Nothing is adopted, run or published. Owner only.
        """
        from ampuly.plugins.office_ui.business_store import OrderTransitionError

        project_id = self._request_project_id(data)
        workflow_id = str(data.get("workflow_id", "") or "").strip()
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="workflow_derive_for_project", project_id=project_id, workflow_id=workflow_id, error="owner_required")
            return
        if not workflow_id:
            await self._send_ack(ws, ok=False, action="workflow_derive_for_project", project_id=project_id, workflow_id=workflow_id, error="workflow_id is required")
            return
        try:
            derived, existing = await asyncio.to_thread(
                self._console_api().derive_workflow_for_project, workflow_id, project_id=project_id, actor=_ws_actor_login(self, ws),
            )
        except OrderTransitionError as exc:
            await self._send_ack(ws, ok=False, action="workflow_derive_for_project", project_id=project_id, workflow_id=workflow_id, error=str(exc))
            return
        await self._send_ack(ws, ok=True, action="workflow_derive_for_project", project_id=project_id, workflow_id=workflow_id,
                             workflow=derived.to_payload(), existing=existing)

    async def _handle_workflow_versions(self, ws: Any, data: dict) -> None:
        """流程版本面板: the flow's published versions and which project runs which, across projects. Read-only; owner only.

        Every project's adoption is shown to the owner, whose console this is; upgrading stays the project's own step.
        """
        from ampuly.plugins.office_ui.business_store import OrderTransitionError

        project_id = self._request_project_id(data)
        workflow_id = str(data.get("workflow_id", "") or "").strip()
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="workflow_versions", project_id=project_id, workflow_id=workflow_id, error="owner_required")
            return
        if not workflow_id:
            await self._send_ack(ws, ok=False, action="workflow_versions", project_id=project_id, workflow_id=workflow_id, error="workflow_id is required")
            return
        if await _ws_refuse_other_projects_flow(self, ws, action="workflow_versions", project_id=project_id, workflow_id=workflow_id, doing="查看"):
            return
        try:
            record = await asyncio.to_thread(self._console_api().workflow_versions, workflow_id)
        except (OrderTransitionError, OSError, ValueError) as exc:
            await self._send_ack(ws, ok=False, action="workflow_versions", project_id=project_id, workflow_id=workflow_id, error=str(exc))
            return
        await self._send_ack(ws, ok=True, action="workflow_versions", project_id=project_id, workflow_id=workflow_id, versions=record)

    async def _handle_workflow_create_blank(self, ws: Any, data: dict) -> None:
        """＋ 新建业务流: an empty local draft run by one saved team (4.7 Q01, A01). Owner only; nothing runs."""
        from ampuly.plugins.office_ui.business_store import OrderTransitionError

        project_id = self._request_project_id(data)
        draft_id = str(data.get("draft_id", "") or "").strip()
        org = str(data.get("org", "") or "").strip()
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="workflow_create_blank", project_id=project_id, draft_id=draft_id, error="owner_required")
            return
        try:
            org_source = _saved_org_path(org, strict=False)
        except ValueError:
            org_source = None
        if org_source is None or not org_source.is_file():
            await self._send_ack(ws, ok=False, action="workflow_create_blank", project_id=project_id, draft_id=draft_id,
                                 error="org_not_found", org=org)
            return
        try:
            package = self._console_api().create_blank_workflow_draft(
                draft_id=draft_id,
                actor=_ws_actor_login(self, ws),
                org_source=org_source,
                name=str(data.get("name", "") or "").strip(),
                summary=str(data.get("summary", "") or "").strip(),
            )
        except (OrderTransitionError, TypeError, ValueError) as exc:
            await self._send_ack(ws, ok=False, action="workflow_create_blank", project_id=project_id, draft_id=draft_id, error=str(exc))
            return
        await self._send_ack(ws, ok=True, action="workflow_create_blank", project_id=project_id, draft_id=package.id,
                             workflow=package.to_payload())

    async def _handle_workflow_create_draft(self, ws: Any, data: dict) -> None:
        """Create a local Builder candidate from an existing workflow template."""
        from ampuly.plugins.office_ui.business_store import OrderTransitionError

        project_id = self._request_project_id(data)
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="workflow_create_draft", project_id=project_id, error="owner_required")
            return
        workflow_id = str(data.get("workflow_id", "") or "").strip()
        draft_id = str(data.get("draft_id", "") or "").strip()
        raw_nodes = data.get("nodes")
        raw_fields = data.get("intake_fields")
        raw_acceptance = data.get("acceptance")
        if raw_nodes is not None and (not isinstance(raw_nodes, list) or any(not isinstance(item, dict) for item in raw_nodes)):
            await self._send_ack(ws, ok=False, action="workflow_create_draft", project_id=project_id, workflow_id=workflow_id, error="nodes must be a list of objects")
            return
        if raw_fields is not None and (not isinstance(raw_fields, list) or any(not isinstance(item, dict) for item in raw_fields)):
            await self._send_ack(ws, ok=False, action="workflow_create_draft", project_id=project_id, workflow_id=workflow_id, error="intake_fields must be a list of objects")
            return
        if raw_acceptance is not None and not isinstance(raw_acceptance, list):
            await self._send_ack(ws, ok=False, action="workflow_create_draft", project_id=project_id, workflow_id=workflow_id, error="acceptance must be a list")
            return
        try:
            package = self._console_api().create_workflow_draft(
                workflow_id,
                draft_id=draft_id,
                actor=_ws_actor_login(self, ws),
                name=str(data.get("name", "") or "").strip(),
                summary=str(data.get("summary", "") or "").strip(),
                nodes=[dict(item) for item in raw_nodes] if raw_nodes is not None else None,
                intake_fields=[dict(item) for item in raw_fields] if raw_fields is not None else None,
                acceptance=[str(item) for item in raw_acceptance] if raw_acceptance is not None else None,
                change_note=str(data.get("change_note", "") or "").strip(),
                # Another project's own flow is not copied from this one (usable_by_project).
                project_id=project_id,
            )
        except (OrderTransitionError, TypeError, ValueError) as exc:
            await self._send_ack(ws, ok=False, action="workflow_create_draft", project_id=project_id, workflow_id=workflow_id, draft_id=draft_id, error=str(exc))
            return
        await self._send_ack(
            ws,
            ok=True,
            action="workflow_create_draft",
            project_id=project_id,
            workflow_id=workflow_id,
            draft_id=package.id,
            workflow=package.to_payload(),
        )

