    async def _handle_workflow_update_nodes(self, ws: Any, data: dict) -> None:
        """Save a validated node-table draft without mutating a published package."""
        from ampuly.plugins.office_ui.business_store import OrderTransitionError

        project_id = self._request_project_id(data)
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="workflow_update_nodes", project_id=project_id, error="owner_required")
            return
        workflow_id = str(data.get("workflow_id", "") or "").strip()
        raw_nodes = data.get("nodes")
        if not isinstance(raw_nodes, list):
            await self._send_ack(
                ws,
                ok=False,
                action="workflow_update_nodes",
                project_id=project_id,
                workflow_id=workflow_id,
                error="nodes must be a list of objects",
            )
            return
        nodes = list(raw_nodes)
        actor = _ws_actor_login(self, ws)
        if await _ws_refuse_other_projects_flow(self, ws, action="workflow_update_nodes", project_id=project_id, workflow_id=workflow_id, doing="改"):
            return
        try:
            package = self._console_api().update_workflow_nodes(
                workflow_id,
                nodes,
                actor=actor,
                expected_version=str(data.get("expected_version", "") or "").strip(),
                new_version=str(data.get("new_version", "") or "").strip(),
                change_note=str(data.get("change_note", "") or "").strip(),
                expected_revision=str(data.get("expected_revision", "") or "").strip(),
            )
        except OrderTransitionError as exc:
            # A refused save says which step and which field, not only a sentence: the canvas points at it.
            node_blockers: list[dict] = []
            plain = ""
            current = self._workflow_package(workflow_id)
            if current is not None:
                from ampuly.plugins.office_ui.workflow_packages import node_findings_for, refused_save_text

                try:
                    node_blockers = node_findings_for(current, nodes)
                except Exception:
                    node_blockers = []
                # The owner reads the refusal in Chinese, by step and by field; the English sentence stays in
                # `detail`. Only when the save was refused for those findings: a version conflict is not worded as them.
                if node_blockers and str(exc).startswith("workflow node update is invalid"):
                    try:
                        plain = refused_save_text(current, nodes, node_blockers)
                    except Exception:
                        plain = ""
            await self._send_ack(
                ws,
                ok=False,
                action="workflow_update_nodes",
                project_id=project_id,
                workflow_id=workflow_id,
                error=plain or str(exc),
                detail=str(exc),
                node_blockers=node_blockers,
            )
            return
        await self._send_ack(
            ws,
            ok=True,
            action="workflow_update_nodes",
            project_id=project_id,
            workflow_id=workflow_id,
            workflow=package.to_payload(),
        )

    async def _handle_workflow_preflight(self, ws: Any, data: dict) -> None:
        """Run a Builder candidate preflight without installing or launching it."""
        from ampuly.plugins.office_ui.business_store import OrderTransitionError

        project_id = self._request_project_id(data)
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="workflow_preflight", project_id=project_id, error="owner_required")
            return
        workflow_id = str(data.get("workflow_id", "") or "").strip()
        focus_node_id = str(data.get("node_id", "") or "").strip()
        fields = data.get("fields", {})
        if not isinstance(fields, dict):
            await self._send_ack(
                ws,
                ok=False,
                action="workflow_preflight",
                project_id=project_id,
                workflow_id=workflow_id,
                error="fields must be an object",
            )
            return
        # One project is one customer: another project's own flow is not planned from here, whose answer would lay out
        # that customer's steps and fields (usable_by_project, as the list, adoption, orders and trials do).
        from ampuly.plugins.office_ui.workflow_packages import usable_by_project

        find_package = getattr(self, "_workflow_package", None)
        found = find_package(workflow_id) if callable(find_package) else None
        if found is not None and not usable_by_project(found, project_id):
            await self._send_ack(
                ws,
                ok=False,
                action="workflow_preflight",
                project_id=project_id,
                workflow_id=workflow_id,
                error="这条业务流是另一个项目专用的，不能在本项目预检",
            )
            return
        try:
            preflight_kwargs = {"project_id": project_id}
            if focus_node_id:
                preflight_kwargs["focus_node_id"] = focus_node_id
            # A step on the current default runs whatever the catalogue says of new choices (review R4).
            default_model = str(
                getattr(getattr(getattr(getattr(self, "engine", None), "config", None), "llm", None), "default_model", "") or "")
            if default_model:
                preflight_kwargs["default_model"] = default_model
            result = self._console_api().preflight_workflow(
                workflow_id,
                dict(fields),
                **preflight_kwargs,
            )
        except OrderTransitionError as exc:
            await self._send_ack(
                ws,
                ok=False,
                action="workflow_preflight",
                project_id=project_id,
                workflow_id=workflow_id,
                error=str(exc),
            )
            return
        await self._send_ack(
            ws,
            ok=True,
            action="workflow_preflight",
            project_id=project_id,
            workflow_id=workflow_id,
            node_id=focus_node_id,
            preflight=result,
        )

    async def _handle_workflow_provider_preflight(self, ws: Any, data: dict) -> None:
        """Join workflow and Provider fences without starting a trial."""
        from ampuly.plugins.office_ui.business_store import OrderTransitionError

        project_id = self._request_project_id(data)
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="workflow_provider_preflight", project_id=project_id, error="owner_required")
            return
        workflow_id = str(data.get("workflow_id", "") or "").strip()
        provider = str(data.get("provider", "") or "").strip()
        fields = data.get("fields", {})
        if not isinstance(fields, dict):
            await self._send_ack(ws, ok=False, action="workflow_provider_preflight", project_id=project_id, workflow_id=workflow_id, error="fields must be an object")
            return
        if not provider:
            await self._send_ack(ws, ok=False, action="workflow_provider_preflight", project_id=project_id, workflow_id=workflow_id, error="provider is required")
            return
        # Another project's own flow is not checked against a provider from here either (usable_by_project).
        from ampuly.plugins.office_ui.workflow_packages import usable_by_project

        find_package = getattr(self, "_workflow_package", None)
        found = find_package(workflow_id) if callable(find_package) else None
        if found is not None and not usable_by_project(found, project_id):
            await self._send_ack(ws, ok=False, action="workflow_provider_preflight", project_id=project_id, workflow_id=workflow_id, provider=provider,
                                 error="这条业务流是另一个项目专用的，不能在本项目预检")
            return
        try:
            result = self._console_api().provider_trial_preflight(
                workflow_id,
                dict(fields),
                project_id=project_id,
                provider=provider,
            )
        except (OrderTransitionError, TypeError, ValueError) as exc:
            await self._send_ack(ws, ok=False, action="workflow_provider_preflight", project_id=project_id, workflow_id=workflow_id, provider=provider, error=str(exc))
            return
        await self._send_ack(
            ws,
            ok=True,
            action="workflow_provider_preflight",
            project_id=project_id,
            workflow_id=workflow_id,
            provider=provider,
            trial=result,
        )

    def _workflow_package(self, workflow_id: str) -> Any | None:
        wanted = str(workflow_id or "").strip()
        return next((package for package in self._workflow_registry() if package.id == wanted), None)

    async def _handle_workflow_node_trial_list(self, ws: Any, data: dict) -> None:
        """Return durable real-node trial receipts for this project only."""
        from ampuly.plugins.office_ui.workflow_node_trial import list_node_trials, public_trial

        project_id = self._request_project_id(data)
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="workflow_node_trial_list", project_id=project_id, error="owner_required")
            return
        ampuly_home = Path(getattr(self.engine, "ampuly_home", None) or Path.cwd() / ".ampuly")
        workflow_id = str(data.get("workflow_id", "") or "").strip()
        node_id = str(data.get("node_id", "") or "").strip()
        package = self._workflow_package(workflow_id) if workflow_id else None
        trials = list_node_trials(
            self._accounts().business,
            ampuly_home,
            project_id=project_id,
            workflow_id=workflow_id,
            node_id=node_id,
            package=package,
        )
        # For one node of a saved package: which upstream steps a trial has to be pinned to, and what can be pinned.
        # A plan that cannot be made is an answer too: the page must not wait for one that will never come.
        pinning = None
        pinning_error = ""
        if node_id:
            from ampuly.plugins.office_ui.business_store import OrderTransitionError
            from ampuly.plugins.office_ui.workflow_node_trial import pin_candidates

            if package is None:
                pinning_error = "workflow_not_found"
            else:
                try:
                    pinning = pin_candidates(self._accounts().business, ampuly_home, package, node_id, project_id=project_id)
                except OrderTransitionError as exc:
                    pinning_error = str(exc)
        await self._send_ack(
            ws, ok=True, action="workflow_node_trial_list", project_id=project_id,
            trials=[public_trial(item) for item in trials],
            workflow_id=workflow_id, node_id=node_id, pinning=pinning, pinning_error=pinning_error,
        )

    async def _handle_workflow_node_trial_answer(self, ws: Any, data: dict) -> None:
        """A person's answer to the question a step asked inside a node trial: claim, then continue in the background."""
        from ampuly.plugins.office_ui.business_store import OrderTransitionError
        from ampuly.plugins.office_ui.workflow_node_trial import answer_node_trial, continue_node_trial, public_trial

        project_id = self._request_project_id(data)
        spec_id = str(data.get("spec_id", "") or "").strip()
        workflow_id = str(data.get("workflow_id", "") or "").strip()
        reply = {"ok": False, "action": "workflow_node_trial_answer", "project_id": project_id, "spec_id": spec_id}
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, **reply, error="owner_required")
            return
        package = self._workflow_package(workflow_id)
        if package is None:
            await self._send_ack(ws, **reply, error="workflow_not_found")
            return
        llm = getattr(self.engine, "llm", None)
        if llm is None:
            await self._send_ack(ws, **reply, error="model_runtime_unavailable")
            return
        actor = _ws_actor_login(self, ws)
        ampuly_home = Path(getattr(self.engine, "ampuly_home", None) or Path.cwd() / ".ampuly")
        try:
            trial, spec, claim = await answer_node_trial(
                self._accounts().business, package, ampuly_home=ampuly_home, project_id=project_id, spec_id=spec_id,
                reply=str(data.get("reply", "") or ""), actor=actor,
            )
        except (OrderTransitionError, TypeError, ValueError, OSError) as exc:  # BuilderError is a ValueError
            await self._send_ack(ws, **reply, error=str(exc))
            return
        self._track(continue_node_trial(
            self._accounts().business, spec, claim, descriptor=trial, ampuly_home=ampuly_home, llm=llm, actor=actor,
        ))
        await self._send_ack(ws, **{**reply, "ok": True}, trial=public_trial(trial))

    async def _handle_workflow_node_trial_abandon(self, ws: Any, data: dict) -> None:
        """Stop waiting for an answer: the trial's allowance closes and the trial says it was abandoned."""
        from ampuly.plugins.office_ui.business_store import OrderTransitionError
        from ampuly.plugins.office_ui.workflow_node_trial import abandon_node_trial, public_trial

        project_id = self._request_project_id(data)
        spec_id = str(data.get("spec_id", "") or "").strip()
        reply = {"ok": False, "action": "workflow_node_trial_abandon", "project_id": project_id, "spec_id": spec_id}
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, **reply, error="owner_required")
            return
        ampuly_home = Path(getattr(self.engine, "ampuly_home", None) or Path.cwd() / ".ampuly")
        try:
            trial = abandon_node_trial(self._accounts().business, ampuly_home=ampuly_home, project_id=project_id,
                                       spec_id=spec_id, actor=_ws_actor_login(self, ws))
        except (OrderTransitionError, OSError) as exc:
            await self._send_ack(ws, **reply, error=str(exc))
            return
        await self._send_ack(ws, **{**reply, "ok": True}, trial=public_trial(trial))

    async def _handle_workflow_node_trial_artifact(self, ws: Any, data: dict) -> None:
        """Open one file a node trial left, in place. Owner only; only files the trial itself recorded."""
        from ampuly.plugins.office_ui.workflow_node_trial import read_trial_artifact

        project_id = self._request_project_id(data)
        spec_id = str(data.get("spec_id", "") or "").strip()
        path = str(data.get("path", "") or "")
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="workflow_node_trial_artifact", project_id=project_id, spec_id=spec_id, path=path, error="owner_required")
            return
        ampuly_home = Path(getattr(self.engine, "ampuly_home", None) or Path.cwd() / ".ampuly")
        try:
            payload = read_trial_artifact(ampuly_home, project_id=project_id, spec_id=spec_id, relative_path=path)
        except (ValueError, FileNotFoundError, OSError) as exc:
            await self._send_ack(ws, ok=False, action="workflow_node_trial_artifact", project_id=project_id, spec_id=spec_id, path=path, error=str(exc))
            return
        await self._send_ack(ws, ok=True, action="workflow_node_trial_artifact", project_id=project_id, **payload)

    async def _handle_workflow_node_trial_start(self, ws: Any, data: dict) -> None:
        """Durably claim one saved root AI node, then execute it in the background."""
        from ampuly.plugins.office_ui.business_store import OrderTransitionError
        from ampuly.plugins.office_ui.workflow_node_trial import execute_node_trial, public_trial, start_node_trial

        project_id = self._request_project_id(data)
        workflow_id = str(data.get("workflow_id", "") or "").strip()
        node_id = str(data.get("node_id", "") or "").strip()
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="workflow_node_trial_start", project_id=project_id, workflow_id=workflow_id, node_id=node_id, error="owner_required")
            return
        package = self._workflow_package(workflow_id)
        if package is None:
            await self._send_ack(ws, ok=False, action="workflow_node_trial_start", project_id=project_id, workflow_id=workflow_id, node_id=node_id, error="workflow_not_found")
            return
        # One project is one customer: a trial spends this project's allowance and records into it, so another
        # project's own flow is refused before anything else is looked at (start_node_trial refuses it again).
        from ampuly.plugins.office_ui.workflow_packages import usable_by_project

        if not usable_by_project(package, project_id):
            await self._send_ack(ws, ok=False, action="workflow_node_trial_start", project_id=project_id, workflow_id=workflow_id, node_id=node_id, error="这条业务流是另一个项目专用的，不能在本项目试跑")
            return
        requested_version = str(data.get("workflow_version", "") or "").strip()
        current_version = str(package.manifest.get("version", "") or "").strip()
        if not requested_version or requested_version != current_version:
            await self._send_ack(ws, ok=False, action="workflow_node_trial_start", project_id=project_id, workflow_id=workflow_id, node_id=node_id, error="saved_workflow_version_mismatch")
            return
        llm = getattr(self.engine, "llm", None)
        if llm is None:
            await self._send_ack(ws, ok=False, action="workflow_node_trial_start", project_id=project_id, workflow_id=workflow_id, node_id=node_id, error="model_runtime_unavailable")
            return
        # A step that names its own model runs on that provider's key: a key that is not set is refused here, before an
        # allowance is opened, not after a call went out (LLMProvider.for_model).
        from ampuly.llm.budget import RouteRefused
        from ampuly.plugins.office_ui.step_models import bind_step_model_resolver, step_model

        bind_step_model_resolver(llm)
        nodes = list(getattr(package, "nodes", []) or [])
        requested_model = step_model(next((node for node in nodes if isinstance(node, dict) and str(node.get("id", "") or "") == node_id), None))
        if requested_model:
            try:
                llm.for_model(requested_model)
            except RouteRefused as exc:  # a missing key, and any other refusal before sending (the catalogue's too)
                await self._send_ack(ws, ok=False, action="workflow_node_trial_start", project_id=project_id, workflow_id=workflow_id, node_id=node_id, error=str(exc))
                return
        actor = _ws_actor_login(self, ws)
        ampuly_home = Path(getattr(self.engine, "ampuly_home", None) or Path.cwd() / ".ampuly")
        try:
            trial, spec, claim = await start_node_trial(
                self._accounts().business,
                package,
                node_id,
                ampuly_home=ampuly_home,
                project_id=project_id,
                actor=actor,
                request_id=str(data.get("request_id", "") or "").strip(),
                model_call_limit=data.get("model_call_limit", 12),
                pins=data.get("pins"),
                **({"image_limit": data["image_limit"]} if "image_limit" in data else {}),
            )
        except (OrderTransitionError, TypeError, ValueError, OSError) as exc:
            await self._send_ack(ws, ok=False, action="workflow_node_trial_start", project_id=project_id, workflow_id=workflow_id, node_id=node_id, error=str(exc))
            return
        if claim:
            self._track(execute_node_trial(
                self._accounts().business,
                spec,
                claim,
                descriptor=trial,
                ampuly_home=ampuly_home,
                llm=llm,
                actor=actor,
            ))
        await self._send_ack(
            ws,
            ok=True,
            action="workflow_node_trial_start",
            project_id=project_id,
            workflow_id=workflow_id,
            node_id=node_id,
            trial=public_trial(trial),
            accepted=bool(claim),
        )

    async def _handle_workflow_flow_trial_start(self, ws: Any, data: dict) -> None:
        """Whole-flow formal trial of the saved canvas version: every AI step in dependency order, each on what its
        upstream left in this same run (workflow_flow_trial). Checked and recorded here; run in the background."""
        from ampuly.plugins.office_ui.business_store import OrderTransitionError
        from ampuly.plugins.office_ui.workflow_flow_trial import execute_flow_trial, mark_flow_launch, prepare_flow_trial

        action = "workflow_flow_trial_start"
        project_id = self._request_project_id(data)
        workflow_id = str(data.get("workflow_id", "") or "").strip()
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action=action, project_id=project_id, workflow_id=workflow_id, error="owner_required")
            return
        freeze = None
        if "employee_package_id" in data or "employee_package_fingerprint" in data:
            # A formal run reads only the enterprise-published pin, never the mutable draft.
            from ampuly.plugins.office_ui.ai_employee_contract import AIEmployeeContractError
            from ampuly.plugins.office_ui.employee_workflow_template import pinned_workflow_package

            try:
                package, freeze = pinned_workflow_package(
                    Path(getattr(self.engine, "ampuly_home", None) or Path.cwd() / ".ampuly"),
                    data.get("employee_package_id"), data.get("employee_package_fingerprint"), require_new_adoption=True)
            except AIEmployeeContractError as exc:
                await self._send_ack(ws, ok=False, action=action, project_id=project_id, workflow_id=workflow_id, error=exc.code)
                return
            if not workflow_id or workflow_id != package.id:
                await self._send_ack(ws, ok=False, action=action, project_id=project_id, workflow_id=workflow_id, error="pinned_workflow_mismatch")
                return
            workflow_id = package.id
        else:
            package = self._workflow_package(workflow_id)
        if package is None:
            await self._send_ack(ws, ok=False, action=action, project_id=project_id, workflow_id=workflow_id, error="workflow_not_found")
            return
        from ampuly.plugins.office_ui.workflow_packages import usable_by_project

        if not usable_by_project(package, project_id):
            await self._send_ack(ws, ok=False, action=action, project_id=project_id, workflow_id=workflow_id, error="这条业务流是另一个项目专用的，不能在本项目试跑")
            return
        requested_version = str(data.get("workflow_version", "") or "").strip()
        current_version = str(package.manifest.get("version", "") or "").strip()
        if not requested_version or requested_version != current_version:
            await self._send_ack(ws, ok=False, action=action, project_id=project_id, workflow_id=workflow_id, error="saved_workflow_version_mismatch")
            return
        llm = getattr(self.engine, "llm", None)
        if llm is None:
            await self._send_ack(ws, ok=False, action=action, project_id=project_id, workflow_id=workflow_id, error="model_runtime_unavailable")
            return
        from ampuly.llm.budget import RouteRefused
        from ampuly.plugins.office_ui.step_models import bind_step_model_resolver, step_model

        bind_step_model_resolver(llm)
        # Every step that names its own model must have its key before anything is spent, not half-way through the run.
        for node in list(getattr(package, "nodes", []) or []):
            requested_model = step_model(node) if isinstance(node, dict) else ""
            if requested_model:
                try:
                    llm.for_model(requested_model)
                except RouteRefused as exc:
                    await self._send_ack(ws, ok=False, action=action, project_id=project_id, workflow_id=workflow_id, error=str(exc))
                    return
        actor = _ws_actor_login(self, ws)
        ampuly_home = Path(getattr(self.engine, "ampuly_home", None) or Path.cwd() / ".ampuly")
        business = self._accounts().business
        try:
            new_round = data.get("new_round", False)
            record = prepare_flow_trial(
                business, package, ampuly_home=ampuly_home, project_id=project_id, actor=actor,
                request_id=str(data.get("request_id", "") or "").strip(),
                model_call_limit_per_node=data.get("model_call_limit_per_node", 12),
                total_model_call_limit=data.get("total_model_call_limit"),
                new_round=new_round is True, freeze=freeze,
            )
        except (OrderTransitionError, TypeError, ValueError, OSError) as exc:
            await self._send_ack(ws, ok=False, action=action, project_id=project_id, workflow_id=workflow_id, error=str(exc))
            return
        accepted = False
        if record.get("phase") == "accepted" and not record.get("started") and not record.get("launch_claimed") and not record.get("reused"):
            accepted = mark_flow_launch(ampuly_home, str(record["flow_id"]))
        if accepted:
            self._track(execute_flow_trial(business, package, record, ampuly_home=ampuly_home, actor=actor, llm=llm))
        await self._send_ack(ws, ok=True, action=action, project_id=project_id, workflow_id=workflow_id,
                             flow_trial=record, accepted=accepted, request_id=record.get("request_id"))

    async def _handle_workflow_flow_trial_list(self, ws: Any, data: dict) -> None:
        from ampuly.plugins.office_ui.workflow_flow_trial import list_flow_trials

        action = "workflow_flow_trial_list"
        project_id = self._request_project_id(data)
        workflow_id = str(data.get("workflow_id", "") or "").strip()
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action=action, project_id=project_id, workflow_id=workflow_id, error="owner_required")
            return
        ampuly_home = Path(getattr(self.engine, "ampuly_home", None) or Path.cwd() / ".ampuly")
        rows = list_flow_trials(self._accounts().business, ampuly_home, project_id=project_id, workflow_id=workflow_id)
        from ampuly.plugins.office_ui.ai_employee_contract import AIEmployeeContractError
        from ampuly.plugins.office_ui.employee_workflow_template import published_workflow_trial_candidates

        candidates, candidate_error = [], None
        try:
            if workflow_id:
                candidates = published_workflow_trial_candidates(ampuly_home, project_id=project_id, workflow_id=workflow_id)
        except AIEmployeeContractError as exc:
            candidate_error = exc.code
        except (OSError, TypeError, ValueError):
            candidate_error = "published_workflow_catalog_unavailable"
        await self._send_ack(ws, ok=True, action=action, project_id=project_id, workflow_id=workflow_id, flow_trials=rows,
                             published_candidates=candidates, published_candidates_error=candidate_error)

    async def _handle_workflow_flow_trial_continue(self, ws: Any, data: dict) -> None:
        from ampuly.plugins.office_ui.business_store import OrderTransitionError
        from ampuly.plugins.office_ui.workflow_flow_trial import continue_flow_trial, read_flow_trial

        action = "workflow_flow_trial_continue"
        project_id = self._request_project_id(data)
        workflow_id = str(data.get("workflow_id", "") or "").strip()
        flow_id = str(data.get("flow_id", "") or "").strip()
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action=action, project_id=project_id, workflow_id=workflow_id, error="owner_required")
            return
        actor = _ws_actor_login(self, ws)
        ampuly_home = Path(getattr(self.engine, "ampuly_home", None) or Path.cwd() / ".ampuly")
        business = self._accounts().business
        try:
            record = read_flow_trial(business, ampuly_home, project_id=project_id, flow_id=flow_id)
            if str(record.get("workflow_id", "")) != workflow_id:
                raise OrderTransitionError("flow trial not found in this workflow")
            if record.get("phase") == "unknown":
                raise OrderTransitionError("这一步的结果还不能确定，先核验原试跑，不能接着跑或另开一轮")
        except (OrderTransitionError, TypeError, ValueError, OSError) as exc:
            await self._send_ack(ws, ok=False, action=action, project_id=project_id, workflow_id=workflow_id, flow_id=flow_id, error=str(exc))
            return
        # Resume belongs to the persisted run. A mutable draft may have changed
        # or been removed since a published run started; it is not its source.
        pin = record.get("freeze")
        if pin is not None:
            from ampuly.plugins.office_ui.ai_employee_contract import AIEmployeeContractError
            from ampuly.plugins.office_ui.employee_workflow_template import pinned_workflow_package

            try:
                if not isinstance(pin, dict) or pin.get("freeze_source") != "employee_packages_published" or pin.get("draft_digest"):
                    raise OrderTransitionError("published flow trial freeze cannot be verified")
                package, current_pin = pinned_workflow_package(ampuly_home, str(pin.get("package_id", "")), str(pin.get("package_fingerprint", "")))
                # The index can change, but the selected immutable identity and
                # graph must still be precisely the ones this run recorded.
                keys = ("freeze_source", "package_id", "package_version", "package_fingerprint", "index_relative",
                        "version_relative", "workflow_id", "workflow_version", "workflow_tree_sha256")
                if any(not pin.get(key) or pin.get(key) != current_pin.get(key) for key in keys):
                    raise OrderTransitionError("published flow trial freeze changed; verify the original run")
            except AIEmployeeContractError as exc:
                await self._send_ack(ws, ok=False, action=action, project_id=project_id, workflow_id=workflow_id, flow_id=flow_id, error=exc.code)
                return
            except (OrderTransitionError, TypeError, ValueError, OSError) as exc:
                await self._send_ack(ws, ok=False, action=action, project_id=project_id, workflow_id=workflow_id, flow_id=flow_id, error=str(exc))
                return
        else:
            package = self._workflow_package(workflow_id)
        if package is None:
            await self._send_ack(ws, ok=False, action=action, project_id=project_id, workflow_id=workflow_id, flow_id=flow_id, error="workflow_not_found")
            return
        from ampuly.plugins.office_ui.workflow_packages import usable_by_project

        if not usable_by_project(package, project_id):
            await self._send_ack(ws, ok=False, action=action, project_id=project_id, workflow_id=workflow_id, flow_id=flow_id, error="workflow_project_mismatch")
            return
        if package.id != workflow_id or str(package.manifest.get("version", "")) != str(record.get("workflow_version", "")):
            await self._send_ack(ws, ok=False, action=action, project_id=project_id, workflow_id=workflow_id, flow_id=flow_id, error="saved_workflow_version_mismatch")
            return
        llm = getattr(self.engine, "llm", None)
        if llm is None:
            await self._send_ack(ws, ok=False, action=action, project_id=project_id, workflow_id=workflow_id, error="model_runtime_unavailable")
            return
        continued = record.get("phase") in {"accepted", "running", "waiting"}
        if continued:
            self._track(continue_flow_trial(
                business, package, ampuly_home=ampuly_home, project_id=project_id, flow_id=flow_id, actor=actor, llm=llm,
            ))
        await self._send_ack(ws, ok=True, action=action, project_id=project_id, workflow_id=workflow_id, flow_id=flow_id, flow_trial=record, continued=continued)

    async def _handle_workflow_flow_trial_stop(self, ws: Any, data: dict) -> None:
        from ampuly.plugins.office_ui.business_store import OrderTransitionError
        from ampuly.plugins.office_ui.workflow_flow_trial import request_flow_stop

        action = "workflow_flow_trial_stop"
