    def _console_api(self) -> Any:
        """The console's internal API (work orders + launch), built once per handler."""
        if self._console_api_cache is None:
            from ampuly.plugins.office_ui.api import ConsoleAPI
            from ampuly.plugins.office_ui.runtime_projection_launch import RuntimeProjectionLaunchHost

            ampuly_home = Path(getattr(self.engine, "ampuly_home", None) or Path.cwd() / ".ampuly")
            self._console_api_cache = ConsoleAPI(
                ampuly_home=ampuly_home,
                packages=self._workflow_registry,
                launch=self._launch_workflow_package,
                runtime_publication_host=RuntimeProjectionLaunchHost(ampuly_home),
                business=self._accounts().business,
                provider_resolver=lambda name: (
                    self.engine.adapter_registry.get(name)
                    if getattr(self.engine, "adapter_registry", None) is not None
                    else None
                ),
                model_plan_source=lambda: self.engine.config.llm,
                employee_runtime_host=getattr(self.engine, "employee_runtime_host", None),
                acceptance_rework=self._restart_acceptance_rework_command,
                harness_registry=getattr(self.engine, "harness_registry", None),
            )
        return self._console_api_cache

    async def _restart_acceptance_rework_command(
        self,
        *,
        project_id: str,
        launched_task_id: str,
        target_node: str,
        feedback: str,
        request_id: str,
        command_id: str,
    ) -> dict[str, str]:
        """Reset and resume the pinned runtime behind one business command."""

        del command_id  # The business outbox owns idempotency and publication.
        engine = await self._engine_for_project(project_id)
        target = await self._resolve_company_runtime_target(
            launched_task_id,
            engine=engine,
        )
        if target is None:
            raise RuntimeError(
                "acceptance rework could not resolve the launched runtime"
            )
        runtime_session_id = str(
            target.get("runtime_session_id", "") or ""
        ).strip()
        config_task = target.get("config_task") or target.get("task")
        run_id = str(
            (getattr(config_task, "metadata", {}) or {}).get(
                "delegation_run_id", ""
            )
            or ""
        ).strip()
        if not runtime_session_id or not run_id:
            raise RuntimeError(
                "acceptance rework runtime identity is incomplete"
            )
        snapshot = await engine._load_company_runtime_snapshot(
            runtime_session_id,
            delegation_run_id=run_id,
        )
        if snapshot is None:
            raise RuntimeError(
                "acceptance rework runtime snapshot is unavailable"
            )
        plan, tasks = snapshot
        executor = getattr(engine, "company_executor", None)
        if executor is None:
            raise RuntimeError("acceptance rework executor is unavailable")
        await executor.restart_contractual_acceptance_rework(
            plan,
            tasks,
            target_projection_id=target_node,
            feedback=feedback,
            request_id=request_id,
            schedule_execution=self._track,
        )
        return {
            "run_id": run_id,
            "runtime_session_id": runtime_session_id,
            "runtime_task_id": str(launched_task_id or "").strip(),
        }

    async def _launch_workflow_package(
        self,
        project_id: str,
        package: Any,
        fields: dict[str, Any],
        order_id: str = "",
        command_id: str = "",
        model_plan: dict[str, Any] | None = None,
        launch_source: Any | None = None,
        *,
        record_creation_origin: bool = False,
    ) -> Any:
        """Zero-config launch of a package: install, prepare, switch org, create session, send intake.

        Every order gets its own workspace (``<workplace>/orders/<order_id>``):
        with one shared folder, yesterday's six drafts satisfied today's
        "6/6 files present" precheck (Regression case).
        """
        if type(record_creation_origin) is not bool:
            raise ValueError("record_creation_origin must be a bool")
        from .employee_launch_source import EmployeeOrderLaunchSource, validate_employee_launch_source, employee_task_origin
        employee_source = launch_source if type(launch_source) is EmployeeOrderLaunchSource else None
        employee_host = getattr(self.engine, "employee_runtime_host", None)
        if employee_source is not None:
            if employee_host is None:
                raise RuntimeError("employee runtime is unavailable")
            validate_employee_launch_source(employee_source, project_id=project_id, order_id=order_id,
                outbox_id=command_id, workflow_id=package.id, workflow_version=package.manifest["version"],
                fields=fields, model_plan=model_plan)
            reread = self._console_api().business.read_employee_order_claim_snapshot(project_id=project_id,
                order_id=order_id, outbox_id=command_id, workflow_id=package.id,
                expected_payload=employee_source.payload, include_launch_source=True)
            if (type(reread) is not EmployeeOrderLaunchSource
                    or reread.launch_payload_bytes != employee_source.launch_payload_bytes
                    or reread.restored.snapshot.fingerprint != employee_source.restored.snapshot.fingerprint):
                raise RuntimeError("employee original claim changed")
            employee_source = launch_source = reread
            employee_host.validate_launch(project_id, package, employee_source)
            record_creation_origin = True
        if record_creation_origin:
            from ampuly.database.source_project_scope import validate_source_project
            validate_source_project(project_id)
            if launch_source is None:
                raise RuntimeError("order Task origin is unavailable")
        if launch_source is not None and employee_source is None:
            source_import_failed = False
            try:
                from .order_launch_claim_source import validate_order_launch_claim
            except Exception:
                source_import_failed = True
            if source_import_failed:
                raise RuntimeError("order launch source unavailable") from None

            # Server-only original bytes, never fields/metadata/ACK. Validate
            # before prepare or launch effects; this is not runtime permission.
            validate_order_launch_claim(
                launch_source, project_id=project_id, order_id=order_id,
                outbox_id=command_id, workflow_id=package.id,
                workflow_version=package.manifest.get("version", ""),
                fields=fields, model_plan=model_plan,
            )
        origin_kwargs = {}
        if record_creation_origin:
            conversion_import_failed = False
            try:
                from .order_task_claim_conversion import order_task_origin_from_claim
            except Exception:
                conversion_import_failed = True
            if conversion_import_failed:
                raise RuntimeError("order Task origin conversion unavailable") from None
            # Explicit private rollout only: source presence never activates
            # the pilot, authorizes execution or backfills an existing Task.
            creation_origin = (employee_task_origin if employee_source is not None else order_task_origin_from_claim)(
                launch_source, project_id=project_id, order_id=order_id,
                outbox_id=command_id, workflow_id=package.id,
                workflow_version=package.manifest.get("version", ""),
                fields=fields, model_plan=model_plan,
            )
            if creation_origin is None:
                raise RuntimeError("order Task origin is required")
            origin_kwargs["creation_origin"] = creation_origin
        from ampuly.plugins.office_ui.api import LaunchReceipt
        from ampuly.plugins.office_ui.workflow_packages import prepare_invocation

        ampuly_home = Path(getattr(self.engine, "ampuly_home", None) or Path.cwd() / ".ampuly")
        publication_host = getattr(self._console_api(), 'runtime_publication_host', None)
        if publication_host is None:
            # Compatibility embedding only; the built-in console always owns
            # the formal publication host. No client flag selects this path.
            prepared = prepare_invocation(ampuly_home, project_id, package, fields,
                employee_launch_source=employee_source, employee_runtime_host=employee_host,
                existing_grants_only=employee_source is not None and "_employee_workflow_trial" in fields,
                legacy_mutable_install=True)
        else:
            if launch_source is None or not command_id:
                raise RuntimeError('runtime original launch claim required')
            def assert_original_claim():
                raw_source = employee_source.restored.source if employee_source is not None else launch_source
                original_payload = json.loads(raw_source.launch_payload_bytes)
                current = self._console_api().business.read_employee_order_claim_snapshot(
                    project_id=project_id, order_id=order_id, outbox_id=command_id,
                    workflow_id=package.id, expected_payload=original_payload, include_launch_source=True,
                    expected_chain_ancestor=raw_source.event_chain_head_sha256)
                current_source = current.restored.source if type(current) is EmployeeOrderLaunchSource else current
                if (type(current_source) is not type(raw_source)
                        or current_source.launch_payload_bytes != raw_source.launch_payload_bytes
                        or current_source.claim_event_id != raw_source.claim_event_id):
                    raise RuntimeError('runtime original launch claim changed')
                if employee_source is not None:
                    employee_host.validate_launch(project_id, package, current)
            prepared = publication_host.prepare(package,fields,project_id=project_id,
                request_id=command_id,assert_original_claim=assert_original_claim,
                employee_launch_source=employee_source,employee_runtime_host=employee_host,
                existing_grants_only=employee_source is not None and "_employee_workflow_trial" in fields)
        clean_order_id = str(order_id or "").strip()
        clean_command_id = str(command_id or "").strip()
        identity_seed = clean_command_id or clean_order_id
        runtime_task_id = (
            str(
                uuid.uuid5(
                    uuid.NAMESPACE_URL,
                    f"superones://{project_id}/business-commands/{identity_seed}/task",
                )
            )
            if identity_seed
            else ""
        )
        runtime_session_id = (
            str(
                uuid.uuid5(
                    uuid.NAMESPACE_URL,
                    f"superones://{project_id}/business-commands/{identity_seed}/session",
                )
            )
            if identity_seed
            else ""
        )
        exec_cfg = dict(prepared.get("exec", {}) or {})
        preferred_agent = str(exec_cfg.get("preferred_agent", "") or getattr(self, "_task_preferred_agent", "native") or "native")
        frozen_inputs = prepared.get('runtime_inputs')
        if frozen_inputs is None:
            switched = await self._apply_mode_switch(
                str(exec_cfg.get("mode", "org") or "org"),
                str(exec_cfg.get("company_profile", "custom") or "custom"),
                preferred_agent,
                org_id=str(prepared.get("org_id", "") or ""),
            )
            if not switched:
                raise RuntimeError("org_switch_failed")
        runtime_engine = await self.services_context.engine_for_project(project_id)
        self._apply_model_credential_or_refuse(runtime_engine, project_id)
        existing_task = None
        if runtime_task_id and self._store_is_ready(getattr(runtime_engine, "store", None)):
            existing_task = await runtime_engine.store.get_task(runtime_task_id)
            if existing_task is not None:
                if record_creation_origin:
                    # Creation is never inferred from a matching old identity.
                    # Earlier prepare/mode effects may already have occurred.
                    raise RuntimeError("order Task origin requires a new Task")
                existing_session_id = str(
                    getattr(existing_task, "session_id", "") or ""
                ).strip()
                if existing_session_id != runtime_session_id:
                    raise RuntimeError("order runtime identity conflicts with existing task")
                existing_status = str(
                    getattr(getattr(existing_task, "status", ""), "value", getattr(existing_task, "status", ""))
                    or ""
                ).strip()
                if existing_status == "cancelled":
                    raise RuntimeError("order runtime was cancelled and cannot be relaunched")
        if existing_task is None:
            result = await self.services.session.create(
                project_id=project_id,
                title=str(prepared.get("title", "") or package.name),
                exec_mode=str(exec_cfg.get("mode", "org") or "org"),
                company_profile=str(exec_cfg.get("company_profile", "custom") or "custom"),
                preferred_agent=preferred_agent,
                org_id=str(prepared.get("org_id", "") or ""),
                task_id=runtime_task_id or None,
                session_id=runtime_session_id or None,
                interface="office_ui",
                task_insert_only=True,
                **({'runtime_inputs': frozen_inputs, 'runtime_contract': prepared['workflow_contract']}
                   if frozen_inputs is not None else {}),
                **origin_kwargs,
            )
            self._session_to_task.update(self.services_context.session_to_task)
            await self._publish_service_result(result)
            task_id = str(result.payload.get("task_id", "") or "")
        else:
            task_id = runtime_task_id
            self.services_context.session_to_task[runtime_session_id] = runtime_task_id
            self._session_to_task.update(self.services_context.session_to_task)
        if order_id:
            await self._pin_order_workspace(
                project_id,
                task_id,
                clean_order_id,
                command_id=clean_command_id,
                engine=runtime_engine,
                steps=list(getattr(package, "nodes", None) or []),
                workflow_id=str(getattr(package, "id", "") or ""),
                workflow_version=str(dict(getattr(package, "manifest", {}) or {}).get("version", "") or ""),
                model_plan=dict(model_plan or {}),
            )
        await self._apply_workflow_parent_contract(
            task_id,
            dict(fields.get("_workflow_parent", {}) or {}),
            project_id=project_id,
            engine=runtime_engine,
        )
        if order_id:
            await self._hold_order_run(project_id, task_id, clean_order_id, engine=runtime_engine)
        workflow_contract = dict(prepared.get("workflow_contract", {}) or {})
        await self._apply_workflow_contract(
            task_id,
            workflow_contract,
            engine=runtime_engine,
        )
        if employee_source is not None:
            # Installed only on this newly created Task, before any message can
            # start the original Company runtime. Never backfill an old Task.
            import hashlib
            from .ai_employee_contract import canonical_json
            bound_task = await runtime_engine.store.get_task(task_id)
            if bound_task is None or "employee_launch" in bound_task.metadata:
                raise RuntimeError("employee launch Task source conflicts")
            original_fields = employee_source.payload["fields"]
            bound_task.metadata["employee_launch"] = {
                "order_id": order_id, "command_id": command_id,
                "source_headers": {name: getattr(employee_source.restored.source, name) for name in (
                    "project_id", "order_id", "outbox_id", "workflow_id", "workflow_version",
                    "launch_payload_sha256", "claim_event_id", "event_chain_head_sha256")},
                "pins_fingerprint": employee_source.restored.snapshot.fingerprint,
                "parent_order_id": str(dict(original_fields.get("_workflow_parent", {}) or {}).get("parent_order_id", "")),
                "input_refs": [{"artifact_id": "order-input-" + order_id,
                    "version": employee_source.restored.source.launch_payload_sha256,
                    "content_hash": hashlib.sha256(canonical_json(original_fields)).hexdigest(),
                    "project_id": project_id, "kind": "order_input"}],
            }
            await runtime_engine.store.save_task(bound_task)
        if workflow_contract:
            # The session-created event necessarily precedes contract pinning;
            # publish a scoped update so the live console sees the same
            # immutable release snapshot that a later full sync will restore.
            await self.broadcast({
                "type": "session_updated",
                "payload": {
                    "project_id": project_id,
                    "task_id": task_id,
                    "workflow_contract": workflow_contract,
                },
            })
        await self._apply_exec_overrides(task_id, exec_cfg, engine=runtime_engine)
        message = str(prepared.get("message", "") or "")
        await self._process_session_message_from_console(
            project_id,
            task_id,
            message,
            client_message_id=(
                f"business-command:{clean_command_id}"
                if clean_command_id
                else (f"order-launch:{clean_order_id}" if clean_order_id else "")
            ),
            **({"creation_source_task_id": task_id} if record_creation_origin else {}),
        )
        if identity_seed and not record_creation_origin and self._store_is_ready(getattr(runtime_engine, "store", None)):
            admitted = False
            for _ in range(200):
                current = await runtime_engine.store.get_task(task_id)
                current_status = str(
                    getattr(getattr(current, "status", ""), "value", getattr(current, "status", ""))
                    or ""
                ).strip()
                if current_status and current_status != "pending":
                    admitted = True
                    break
                await asyncio.sleep(0.01)
            if not admitted:
                raise RuntimeError("order runtime did not durably leave pending state")
        return LaunchReceipt(task_id=task_id, message=message, org_id=str(prepared.get("org_id", "") or ""))

    async def _apply_workflow_parent_contract(
        self,
        task_id: str,
        parent: dict[str, Any],
        *,
        project_id: str,
        engine: Any | None = None,
    ) -> None:
        """Pin validated workflow lineage and a shared parent budget on a child.

        The method is deliberately strict.  Losing this context would let a
        child run outside the customer's budget or make a restart look like a
        new piece of work, so a conflicting or foreign contract aborts launch.
        """
        if not parent:
            return
        required = ("parent_task_id", "node_id", "target_workflow_id", "correlation_id", "causation_id")
        if any(not str(parent.get(name, "") or "").strip() for name in required):
            raise RuntimeError("child workflow parent contract is incomplete")
        target_engine = engine if engine is not None else self.engine
        store = getattr(target_engine, "store", None)
        if store is None or not task_id:
            raise RuntimeError("child workflow runtime store is unavailable")
        task = await store.get_task(task_id)
        if task is None:
            raise RuntimeError("child workflow runtime task is unavailable")
        metadata = dict(getattr(task, "metadata", {}) or {})
        customer_id = str(parent.get("customer_id", "") or "").strip()
        environment_id = str(parent.get("environment_id", "") or "").strip()
        if customer_id and str(metadata.get("customer_id", "") or "").strip() not in {"", customer_id}:
            raise RuntimeError("child workflow customer scope conflicts with parent")
        if environment_id and str(metadata.get("environment_id", "") or "").strip() not in {"", environment_id}:
            raise RuntimeError("child workflow environment scope conflicts with parent")
        from ampuly.layer4_tools.spend_guard import budget_order_id, is_order_allowance, stamp_shared_allowance

        # The task that invoked this child, as it is now. An order's allowance is never in the contract (it changes
        # under a running order); the child takes whatever that task spends from at the moment the child starts --
        # the allowance, a newer one granted since, or none if the owner lifted it.
        parent_task = await store.get_task(str(parent.get("parent_task_id", "") or "").strip())
        if parent_task is None:
            # Whether the child is to be held is only known from that task. Starting it unheld because the task
            # could not be read would be the quiet version of the hole this method exists to close.
            raise RuntimeError("child workflow invoking task is unavailable")
        parent_metadata = dict(getattr(parent_task, "metadata", {}) or {})
        budget_id = str(parent.get("budget_id", "") or "").strip()
        if not budget_id and is_order_allowance(parent_metadata):
            budget_id = str(parent_metadata.get("budget_id", "") or "").strip()
        answers_to = ""
        if budget_id:
            budget = self._console_api().business.run_budget(budget_id)
            if budget is None:
                raise RuntimeError("child workflow parent budget not found")
            expected = {
                "project_id": str(project_id or "default").strip() or "default",
                "customer_id": customer_id,
                "environment_id": environment_id,
            }
            for name, wanted in expected.items():
                actual = str(budget.get(name, "") or "").strip()
                if name == "project_id" and actual != wanted:
                    raise RuntimeError("child workflow parent budget project scope conflicts")
                if wanted and actual != wanted:
                    raise RuntimeError(f"child workflow parent budget {name} scope conflicts")
            if str(budget.get("lifecycle", "") or "") != "open":
                # a parent order that has ended leaves its closed allowance on its tasks: its children start no more
                raise RuntimeError("child workflow parent budget is closed")
            # A budget is handed down only by a task that really spends from it, and only as the budget of the order
            # its own record names. Both are read here, from the store and the budget -- a contract is a claim.
            answers_to = str(budget.get("order_id", "") or "").strip()
            if str(parent_metadata.get("budget_id", "") or "").strip() != budget_id:
                raise RuntimeError("child workflow parent task does not spend from the budget it hands down")
            if answers_to != budget_order_id(parent_metadata):
                raise RuntimeError("child workflow parent budget belongs to another order")
        existing = metadata.get("workflow_parent")
        if existing is not None and json.dumps(existing, ensure_ascii=False, sort_keys=True) != json.dumps(
            parent, ensure_ascii=False, sort_keys=True
        ):
            raise RuntimeError("child workflow parent contract conflicts with existing runtime task")
        metadata["workflow_parent"] = dict(parent)
        metadata["workflow_correlation_id"] = str(parent.get("correlation_id", "") or "")
        metadata["workflow_causation_id"] = str(parent.get("causation_id", "") or "")
        metadata["upstream_artifact_refs"] = list(parent.get("artifact_refs", []) or [])
        if customer_id:
            metadata["customer_id"] = customer_id
        if environment_id:
            metadata["environment_id"] = environment_id
        if budget_id:
            # The child keeps its own order (cancelling, resuming and the business tools find it by that) and says
            # separately whose allowance it spends from; its work items inherit both. A child order that already
            # holds an allowance of its own keeps it.
            business = self._console_api().business
            business_path = getattr(business, "path", None)
            earlier = getattr(business, "closed_budget_ids_for_order", None)
            metadata, _changed = stamp_shared_allowance(
                metadata, budget_id=budget_id, ampuly_home=str(Path(business_path).parent) if business_path else "",
                answers_to=answers_to, order_allowance=is_order_allowance(parent_metadata),
                # a run started again after the allowance above it was replaced must not stay on the closed one
                replace=tuple(earlier(answers_to)) if callable(earlier) and answers_to else (),
                # the budget's own scope, where the child names none: see stamp_shared_allowance
                customer_id=str(budget.get("customer_id", "") or "").strip(),
                environment_id=str(budget.get("environment_id", "") or "").strip(),
            )
        task.metadata = metadata
        await store.save_task(task)

    async def _apply_workflow_contract(
        self,
        task_id: str,
        contract: dict[str, Any],
        *,
        engine: Any | None = None,
    ) -> None:
        """Persist the exact workflow/skill release snapshot on the runtime task.

        A task must not silently change package versions after launch.  The
        contract is deliberately stored as task metadata so the runtime and
        acceptance/audit layers can refer to the same immutable invocation
        snapshot without creating another source-of-truth table.
        """
        target_engine = engine if engine is not None else self.engine
        store = getattr(target_engine, "store", None)
        if store is None or not task_id or not contract:
            return
        task = await store.get_task(task_id)
        if task is None:
            return
        metadata = dict(task.metadata or {})
        existing = metadata.get("workflow_contract")
        if existing is not None:
            if json.dumps(existing, ensure_ascii=False, sort_keys=True) != json.dumps(
                contract, ensure_ascii=False, sort_keys=True
            ):
                raise RuntimeError("workflow contract conflicts with existing runtime task")
            return
        metadata["workflow_contract"] = contract
        task.metadata = metadata
        await store.save_task(task)
        logger.info("workflow contract pinned for task {}", task_id[:8])

    async def _apply_exec_overrides(
        self,
        task_id: str,
        exec_cfg: dict[str, Any],
        *,
        engine: Any | None = None,
    ) -> None:
        """Runtime knobs a package sets on its own runs (e.g. the pre-delivery rework cap)."""
        target_engine = engine if engine is not None else self.engine
        store = getattr(target_engine, "store", None)
        if store is None or not task_id:
            return
        overrides = {k: exec_cfg[k] for k in ("max_pre_delivery_reworks",) if k in exec_cfg}
        if not overrides:
            return
        try:
            task = await store.get_task(task_id)
            if task is None:
                return
            task.metadata = {**dict(task.metadata or {}), **overrides}
            await store.save_task(task)
            logger.info("order runtime overrides for task {}: {}", task_id[:8], overrides)
        except Exception:
            logger.opt(exception=True).warning("could not apply exec overrides on {}", task_id[:8])

    async def _pin_order_workspace(
        self,
        project_id: str,
        task_id: str,
        order_id: str,
        *,
        command_id: str = "",
        engine: Any | None = None,
        steps: list[dict[str, Any]] | None = None,
        workflow_id: str = "",
        workflow_version: str = "",
        model_plan: dict[str, Any] | None = None,
    ) -> None:
        """Make the order's session work in its own folder before the first message runs."""
        target_engine = engine if engine is not None else self.engine
        await WSHandler._pin_order_folder(
            self, project_id, task_id, order_id, command_id=command_id, engine=target_engine,
            steps=steps, workflow_id=workflow_id, workflow_version=workflow_version,
        )
        # Not best-effort: an order whose model plan cannot be pinned does not start. Its steps would otherwise
        # read the live settings, which is precisely what freezing the plan exists to stop.
        await WSHandler._pin_order_policy(self, project_id, task_id, order_id, plan=dict(model_plan or {}),
                                          engine=target_engine)
        # Not best-effort, and not skipped by anything above: an order that was given an allowance does not start
        # without it.
        await WSHandler._pin_order_allowance(self, project_id, task_id, order_id, engine=target_engine)
        # B5 : a flow that wrote no acceptance criteria launched an order with no acceptance record, and
        # once delivering it could only be cancelled -- nothing to submit, pass, freeze or export. Generated once here,
        # from the deliverables, and only where the flow wrote none.
        WSHandler._ensure_order_acceptance(self, project_id, order_id, steps=steps, workflow_version=workflow_version)

    _GENERATED_ACCEPTANCE_ACTOR = "系统：按交付物生成"

    @staticmethod
    def _deliverables_of_last_step(steps: list[dict[str, Any]] | None) -> tuple[str, list[str]]:
        """``(step name, deliverables)`` of the last step that names deliverables.

        A flow's last step is often a person's review that names none: what is handed over is then the deliverables
        of the last step that names some. When no step names any, the last step's name and no deliverables. The rule
        lives with the order folder's (``order_folder.last_deliverables``, C5-1).
        """
        from ampuly.plugins.office_ui.order_folder import last_deliverables

        return last_deliverables(steps)

    @staticmethod
    def _generated_acceptance_criterion(steps: list[dict[str, Any]] | None) -> str:
        """The one criterion an order gets when its flow wrote none: 「<最后一步的交付物> 已交付并经 owner 接受」."""
        name, deliverables = WSHandler._deliverables_of_last_step(steps)
        subject = "、".join(deliverables) if deliverables else (f"「{name}」的交付物" if name else "本单的交付物")
        return f"{subject} 已交付并经 owner 接受"

    def _ensure_order_acceptance(
        self, project_id: str, order_id: str, *, steps: list[dict[str, Any]] | None = None, workflow_version: str = "",
    ) -> bool:
        """Give the order an acceptance record when its flow wrote no criteria; say whether one was generated now.

        A flow that wrote criteria had them frozen on the order when it was placed (api.create_order); they are kept.
        A relaunch finds the generated record and writes nothing. Not best-effort: an order whose record cannot be
        written is one that could later only be cancelled, so the launch fails and is retried, as every other pin.
        """
        api = self._console_api()
        business = api.business
        clean_order_id = str(order_id or "").strip()
        if business.get_order(clean_order_id, project_id=project_id) is None:
            raise RuntimeError(f"order {clean_order_id!r}: its order was not found, so its acceptance cannot be generated")
        if business.acceptance(clean_order_id, project_id=project_id) is not None:
            return False
        criterion = WSHandler._generated_acceptance_criterion(steps)
        api.define_acceptance(
            clean_order_id, criteria=[criterion], actor=WSHandler._GENERATED_ACCEPTANCE_ACTOR,
            workflow_version=str(workflow_version or ""), project_id=project_id,
        )
        logger.info("order {} had no acceptance criteria; one generated from its deliverables: {}", clean_order_id, criterion)
        return True

    async def _pin_order_policy(self, project_id: str, task_id: str, order_id: str, *,
                                plan: dict[str, Any] | None = None, engine: Any | None = None) -> bool:
        """Write the order's frozen model plan onto its run task. Raises rather than start an unplanned run.

        The plan is handed down from the dispatch, which froze it at the claim. Nothing reads it back out of the
        outbox: a value that travels is one thing that can be wrong, where a value re-read is two.
        """
        del project_id  # the plan travels with the command, not with the project

        from ampuly.layer4_tools.spend_guard import PolicyConflict, stamp_order_policy
        from ampuly.plugins.office_ui.order_model_plan import plan_from_task

        found = dict(plan or {})
        if not found:
            # An order launched before this shipped, replayed from its outbox row, has no plan on its payload.
            # It runs as it always did; E7 is where a *new* order without a plan is refused.
            logger.info("order {} has no model plan on its launch command (pre-phase-1 row); running unpinned",
                        order_id)
            return False
        target_engine = engine if engine is not None else self.engine
        store = getattr(target_engine, "store", None)
        if store is None:
            raise RuntimeError(f"order {order_id}'s model plan could not be pinned to the run; not starting it "
                               "unplanned")
        task = await store.get_task(task_id)
        if task is None:
            raise RuntimeError(f"order {order_id}'s run task could not be read; not starting it unplanned")
        try:
            metadata, changed = stamp_order_policy(dict(getattr(task, "metadata", {}) or {}), plan=found)
        except PolicyConflict as clash:
            raise RuntimeError(f"order {order_id}: {clash}") from clash
        if not changed:
            return bool(plan_from_task(getattr(task, "metadata", {}) or {}))
        task.metadata = metadata
        await store.save_task(task)
        logger.info("order {} runs under model plan {}", order_id, str(found.get("plan_digest", ""))[:8])
        return True

    @staticmethod
    def _write_order_brief(
        root: Path, order_id: str, order: Any, *, workflow_id: str = "", workflow_version: str = "", package: Any = None,
    ) -> bool:
        """Write the order's intake once at the order root: ``订单资料.md`` for people and models, and
        ``.order-inputs.json`` with the fields as they were taken. Returns whether this call wrote either.

        Regression case (B5): the form's fields reached only the manager's one-line message, so the first step's
        employee searched the empty folder for "the original input" and stopped to ask. Like ``.order-steps.json``,
        a relaunch keeps what the order started with; a file cut short or of another order is replaced. Not
        best-effort: a failure here stops the launch, as every other failure of the pin does. The kernel side that
        points delegated work at the file is collaboration.ORDER_BRIEF_FILE.
        """
        from ampuly.core.config import replace_with_retry

        brief_name, inputs_name = "订单资料.md", ".order-inputs.json"
        fields = getattr(order, "fields", None)
        fields = dict(fields) if isinstance(fields, dict) else {}
        flow_id = str(workflow_id or getattr(order, "workflow_id", "") or "").strip()
        flow_name = str(getattr(package, "name", "") or "").strip() or flow_id
        version = str(workflow_version or "").strip()
        created = str(getattr(order, "created_at", "") or "").strip()
        try:
            created_text = datetime.fromisoformat(created).strftime("%Y-%m-%d %H:%M") if created else ""
        except ValueError:
            created_text = created
        customer = str(getattr(order, "customer_name", "") or getattr(order, "customer_id", "") or "").strip()
        environment = str(getattr(order, "environment_id", "") or "").strip()
        labels: dict[str, str] = {}
        for spec in list(getattr(package, "intake_fields", []) or []):
            if isinstance(spec, dict) and str(spec.get("id", "") or "").strip():
                labels[str(spec["id"])] = str(spec.get("label", "") or "").strip() or str(spec["id"])
        # The flow's own fields first, in its order, then whatever else the form sent. The runtime's own keys (the
        # project and customer scope, control-plane records, anything underscored) are not intake and stay in the
        # JSON only -- unless the flow's intake names one of them, which then reads by its label.
        runtime_keys = ("project_id", "customer_id", "environment_id", "fde_control_plane")
        shown: list[tuple[str, Any]] = [(labels[key], fields.get(key, "")) for key in labels]
        shown += [(key, value) for key, value in fields.items()
                  if key not in labels and not key.startswith("_") and key not in runtime_keys]
        lines = ["# 订单资料", "", f"- 订单号：{order_id}",
                 f"- 业务流：{flow_name}" + (f"（版本 {version}）" if version else "")]
        if created_text:
            lines.append(f"- 下单时间：{created_text}")
        if customer:
            lines.append(f"- 客户：{customer}")
        if environment:
            lines.append(f"- 环境：{environment}")
        lines += ["", "## 接单字段", ""]
        for name, value in shown:
            text = value if isinstance(value, str) else json.dumps(value, ensure_ascii=False, default=str)
            text = text.replace("\r\n", "\n").strip()
            if "\n" in text:
                lines.append(f"- {name}：")
                lines.extend(f"  {line}" for line in text.split("\n"))
            else:
                lines.append(f"- {name}：{text or '（未填）'}")
        if not shown:
            lines.append("本单没有填写接单字段。")
        lines += ["", f"同一份资料的机器可读版本在 {inputs_name}。", ""]
        brief = "\n".join(lines)
        inputs = json.dumps(
            {"schema": 1, "order_id": order_id, "workflow_id": flow_id, "workflow_version": version, "created_at": created,
             "customer_id": str(getattr(order, "customer_id", "") or ""), "fields": fields},
            ensure_ascii=False, indent=2, default=str,
        )

        def brief_is_valid(path: Path) -> bool:
            try:
                return f"- 订单号：{order_id}\n" in path.read_text(encoding="utf-8")
            except (OSError, ValueError):
                return False

        def inputs_are_valid(path: Path) -> bool:
            try:
                table = json.loads(path.read_text(encoding="utf-8"))
            except (OSError, ValueError):
                return False
            return isinstance(table, dict) and table.get("schema") == 1 and table.get("order_id") == order_id

        wrote = False
        for name, payload, valid in ((brief_name, brief, brief_is_valid), (inputs_name, inputs, inputs_are_valid)):
            path = root / name
            if path.exists() and valid(path):
                continue
            # Staged, flushed and published only where nothing is (as the step table is), so a crash never leaves
            # half a file; the runtime-internal prefix keeps the staging file out of every model's listing.
            staged = root / f".ampuly-write-order-brief-{uuid.uuid4().hex}.tmp"
            try:
                with open(staged, "x", encoding="utf-8") as handle:
                    handle.write(payload)
                    handle.flush()
                    os.fsync(handle.fileno())
                try:
                    os.link(staged, path)
                    wrote = True
                    continue
                except FileExistsError:
                    pass
                except OSError:
                    if not path.exists():
                        replace_with_retry(staged, path)  # a volume without hard links
                        wrote = True
                        continue
                if not valid(path):
                    replace_with_retry(staged, path)
                    wrote = True
            finally:
                staged.unlink(missing_ok=True)
        return wrote

    async def _pin_order_folder(
        self,
        project_id: str,
        task_id: str,
        order_id: str,
        *,
        command_id: str = "",
        engine: Any | None = None,
        steps: list[dict[str, Any]] | None = None,
        workflow_id: str = "",
        workflow_version: str = "",
    ) -> None:
        """Pin the order's run to its own folder ``<workplace>/orders/<order_id>`` (and its ``output/``).

        Not best-effort (data phase 1, C2): a run that is not pinned falls back to the whole project folder, where it
        reads and writes every other order's files, so anything that stops the pin stops the launch -- the same way
        an allowance that cannot be pinned does. ``steps`` (the package's nodes) is frozen once as
        ``.order-steps.json``: a relaunch keeps the first table. Each step's ``steps/<step>/work`` and
        ``steps/<step>/downloads`` are made from that table, and the order's intake is written once beside it
        (``_write_order_brief``): the same not-best-effort rule, a run without it asks a person where the input is.
        """
        from ampuly.core.order_layout import DOWNLOADS, OUTPUT, STEP_TABLE, STEPS, UNASSIGNED, WORK, order_segment_ok

        def refusal(why: str) -> str:
            return f"order {order_id!r}: {why}; not starting it in the whole project folder"

        if not order_segment_ok(order_id):
            raise ValueError(refusal("not a valid order folder name"))
        target_engine = engine if engine is not None else self.engine
        store = getattr(target_engine, "store", None)
        if store is None or not task_id:
            raise RuntimeError(refusal("no task store or no run task to pin"))
        try:
            task = await store.get_task(task_id)
            session = await store.get_session(str(getattr(task, "session_id", "") or "")) if task else None
            if session is None:
                raise RuntimeError(refusal("its run task or session could not be read"))
            # ensure_project_workplace, not get_project_workplace: `mkdir(parents=True)` below would
            # otherwise recreate a pinned project root whose disk is unplugged, and the order would write
            # its deliverables into an empty folder on whatever volume took that drive letter.
            root = ensure_project_workplace(project_id or "default") / "orders" / str(order_id)
            # The session is pinned first: whatever fails after this (the
            # folders, the step table, the task) leaves the session pointing
            # at the order's folder, never at the whole project, should a
            # message reach it before a relaunch (data phase 1 review).
            metadata = dict(session.metadata or {})
            defaults = dict(metadata.get("execution_defaults", {}) or {})
            defaults["workspace_root"] = str(root.resolve())
            defaults["target_output_dir"] = str((root / OUTPUT).resolve())
            metadata["execution_defaults"] = defaults
            metadata["order_id"] = str(order_id)
            if command_id:
                metadata["business_command_id"] = str(command_id)
            session.metadata = metadata
            await store.save_session(session)
            (root / OUTPUT).mkdir(parents=True, exist_ok=True)
            # The scratch folder of the run's tasks that belong to no step (the master control's own work): the
            # fence resolves their ``../steps/_unassigned/work`` here, so it exists before the run starts too.
            (root / STEPS / UNASSIGNED / WORK).mkdir(parents=True, exist_ok=True)
            if steps is not None:
                _freeze_order_steps(root, str(order_id), steps, workflow_id=workflow_id, workflow_version=workflow_version)
                # Every step's own folders exist before the run starts, by the frozen table's segments (:
                # a step told of a ``steps/<step>/work`` that was not there resolved it outside the order and
                # tripped a permission card each time).
                table = json.loads((root / STEP_TABLE).read_text(encoding="utf-8"))
                for row in list(table.get("steps", []) or []):
                    segment = str(row.get("segment", "") or "").strip() if isinstance(row, dict) else ""
                    for area in (WORK, DOWNLOADS) if segment else ():
                        (root / STEPS / segment / area).mkdir(parents=True, exist_ok=True)
            # The order is read once: its intake becomes the folder's 订单资料 (not best-effort: without it the
            # first step asks a person where the input is), and its customer scope goes onto the run task below.
            try:
                business = self._console_api().business
                order = business.get_order(str(order_id), project_id=project_id)
            except Exception as exc:
                raise RuntimeError(refusal("its order could not be read, so its intake cannot be written")) from exc
            if order is None:
                raise RuntimeError(refusal("its order was not found, so its intake cannot be written"))
            try:
                package = self._console_api().package(workflow_id) if workflow_id else None
            except Exception:  # noqa: BLE001 - the package only lends the fields their labels
                package = None
            WSHandler._write_order_brief(
                root, str(order_id), order, workflow_id=workflow_id, workflow_version=workflow_version, package=package,
            )
            # Keep the business scope on the durable runtime task as well as
            # the session.  Effect tools execute from the task context; if we
            # only annotate the session, a reminder proposal loses its
            # customer/environment identity before approval.
            if task is not None:
                task_metadata = dict(getattr(task, "metadata", {}) or {})
                task_metadata["order_id"] = str(order_id)
                customer_id = str(getattr(order, "customer_id", "") or "").strip()
                environment_id = str(getattr(order, "environment_id", "") or "").strip()
                if customer_id:
                    task_metadata["customer_id"] = customer_id
                if environment_id:
                    task_metadata["environment_id"] = environment_id
                # B5 : the sites the flow's connector steps name are the run's browser delegation, under
                # the console's own keys, so they reach every step's browser session (through the work items) and
                # the network permission card is not asked for them again. A delegation already on the run -- the
                # owner's from the console, or this flow's from an earlier launch of the same run -- is kept.
                from ampuly.computer_use.browser_scope import delegated_scope

                if not delegated_scope(task_metadata):
                    task_metadata.update(
                        _workflow_browser_scope(steps, workflow_id=workflow_id, workflow_version=workflow_version)
                    )
                task.metadata = task_metadata
                await store.save_task(task)
            logger.info("order {} works in {}", order_id, root)
        except Exception:
            logger.opt(exception=True).warning("could not pin a workspace for order {}", order_id)
            raise

    async def _run_task_budget_id(self, data: dict, order: Any) -> str:
        """The budget the order's run task spends from, or "" when there is no run or it cannot be read."""
        launched = str(getattr(order, "launched_task_id", "") or "").strip()
        if not launched:
            return ""
        try:
            engine, _pid = await self._engine_for_request(data)
            task = await engine.store.get_task(launched)
        except Exception:  # noqa: BLE001 - unknown is not a reason to refuse the grant
            return ""
        return str(dict(getattr(task, "metadata", {}) or {}).get("budget_id", "") or "").strip() if task is not None else ""

    async def _hold_order_run(self, project_id: str, task_id: str, order_id: str, *, engine: Any | None = None) -> None:
        """No order's run starts unheld (model-routing phase 0, C12). Called after the pins, before the first message.

        The launch seam opened the order's allowance and the pin put it on the run's task -- or, for a child order, the
        parent contract put the allowance of the order above it there. A run task that still spends from nothing (a
        child whose parent is not held) is given an allowance of its own now, without ceilings, and pinned. If that
        cannot be done the new allowance is closed again and the launch fails, rather than start a run nothing holds.
        """
        target_engine = engine if engine is not None else self.engine
        store = getattr(target_engine, "store", None)
        task = await store.get_task(task_id) if store is not None and task_id else None
        if task is None:
            raise RuntimeError(f"order {order_id}'s run task could not be read; not starting it unheld")
        if str(dict(getattr(task, "metadata", {}) or {}).get("budget_id", "") or "").strip():
            return
        business = self._console_api().business
        had = business.open_budget_for_order(str(order_id), project_id=project_id)
        allowance = business.ensure_order_allowance(str(order_id), project_id=project_id, actor="launch")
        try:
            pinned = await self._pin_order_allowance(project_id, task_id, order_id, engine=target_engine)
            task = await store.get_task(task_id)
            held = pinned and str(dict(getattr(task, "metadata", {}) or {}).get("budget_id", "") or "") == str(allowance["budget_id"])
        except Exception:
            held = False
            logger.opt(exception=True).warning("the allowance of order {} could not be pinned on its run {}", order_id, task_id)
        if not held:
            if had is None:
                business.close_run_budget(str(allowance["budget_id"]), actor="launch", reason="could not be pinned to the run")
            raise RuntimeError(f"order {order_id}'s run could not be held by an allowance; not starting it unheld")

    async def _pin_order_allowance(self, project_id: str, task_id: str, order_id: str, *, engine: Any | None = None) -> bool:
        """Pin the order's open allowance on the run's own task before the first message runs; say whether it has one.

        The spend guard finds a budget through the task that makes the paid call, and every work item inherits from
        this task. An allowance that cannot be read or cannot be written here raises: the launch fails and is retried,
        rather than starting a run the order row says is held while nothing holds it.
        """
        business = self._console_api().business
        allowance = business.open_budget_for_order(str(order_id), project_id=project_id)
        if allowance is None:
            return False
        from ampuly.layer4_tools.spend_guard import stamp_order_allowance

        target_engine = engine if engine is not None else self.engine
        store = getattr(target_engine, "store", None)
        task = await store.get_task(task_id) if store is not None and task_id else None
        if task is None:
            raise RuntimeError(f"order {order_id} has an allowance and its run task could not be read; not starting it unheld")
        order = business.get_order(str(order_id), project_id=project_id)
        metadata, changed = stamp_order_allowance(
            dict(getattr(task, "metadata", {}) or {}), budget_id=str(allowance["budget_id"]),
            ampuly_home=str(Path(business.path).parent), order_id=str(order_id),
            customer_id=str(getattr(order, "customer_id", "") or ""), environment_id=str(getattr(order, "environment_id", "") or ""),
            replace=tuple(business.closed_budget_ids_for_order(str(order_id))),
        )
        if str(metadata.get("budget_id", "") or "") != str(allowance["budget_id"]):
            raise RuntimeError(f"order {order_id}'s run task already spends from another budget; not starting it under two")
        if changed:
            task.metadata = metadata
            await store.save_task(task)
        return True

    async def _restamp_order_run(self, data: dict, order: Any, *, project_id: str, stamp: Any,
                                 child_stamp: Any | None = None) -> tuple[int, dict[str, Any] | None, list[str]]:
        """Apply ``stamp(metadata) -> (metadata, changed)`` to the run's own task and to every task working under it.

        Returns ``(tasks touched, the run task's metadata afterwards, ids of tasks that could not be written)`` -- the
        metadata is ``None`` when the run's own task could not be reached. The root work item names the run's task as
        its origin; the tasks made under it share the root's delegation run; the ones made later copy from the root
        work item, which is among the tasks touched here. The run's own task failing to save raises (the caller takes
        the grant back); any other task failing is reported and does not stop the rest.

        ``child_stamp`` is applied the same way to the runs of the child orders this run started (and theirs): they
        spend from this order's allowance, so taking it away or granting a new one has to reach them as well.
        """
        run_task_id = str(getattr(order, "launched_task_id", "") or "").strip()
        if not run_task_id:
            return 0, None, []
        engine, _pid = await self._engine_for_request(data)
        store = getattr(engine, "store", None)
        run_task = await store.get_task(run_task_id) if store is not None else None
        if run_task is None:
            return 0, None, []
        tasks = [run_task]
        lister = getattr(store, "get_tasks", None)
        if callable(lister):
            everything = [task for task in await lister(project_id=project_id) if str(getattr(task, "id", "") or "") != run_task_id]
            meta = lambda task: dict(getattr(task, "metadata", {}) or {})  # noqa: E731
            # The root work item names the run's task as its origin; the tasks made under it do not -- they share the
            # root's delegation run. Both are the order's, and both make (or will hand on) its paid calls.
            def working_under(run_id: str) -> list[Any]:
                roots = [task for task in everything if str(meta(task).get("origin_task_id", "") or "") == run_id]
                runs = {str(meta(task).get("delegation_run_id", "") or "").strip() for task in roots} - {""}
                seen = {id(task) for task in roots}
                return roots + [task for task in everything if id(task) not in seen and str(meta(task).get("delegation_run_id", "") or "").strip() in runs]

            tasks.extend(working_under(run_task_id))
            child_tasks: list[Any] = []
            if child_stamp is not None:
                # A child order's run names the task that invoked it in its parent contract. Walk down from this
                # order's tasks; a run is visited once, so a malformed chain cannot loop.
                frontier = {str(getattr(task, "id", "") or "") for task in tasks}
                visited_runs = {run_task_id}
                while frontier:
                    child_runs = [
                        task for task in everything
                        if str(getattr(task, "id", "") or "") not in visited_runs
                        and isinstance(meta(task).get("workflow_parent"), dict)
                        and str(meta(task)["workflow_parent"].get("parent_task_id", "") or "").strip() in frontier
                    ]
                    frontier = set()
                    for child_run in child_runs:
                        child_run_id = str(getattr(child_run, "id", "") or "")
                        visited_runs.add(child_run_id)
                        under = [child_run, *working_under(child_run_id)]
                        child_tasks.extend(under)
                        frontier.update(str(getattr(task, "id", "") or "") for task in under)
        else:
            child_tasks = []
        # A work item of a run whose controller holds a lease cannot be saved broadly: the Store refuses it, and the
        # refusal is a CancelledError by class. The engine's own road for "a write to a parked work item from outside
        # its dispatcher" (it is how a person's answer reaches one) writes under the run's lease instead.
        save = getattr(engine, "_save_task_respecting_run_lease", None)
        if not callable(save):
            save = store.save_task
        touched = 0
        unreached: list[str] = []
        for task, apply in [(task, stamp) for task in tasks] + [(task, child_stamp) for task in child_tasks]:
            current = dict(getattr(task, "metadata", {}) or {})
            metadata, changed = apply(dict(current))
            if changed:
                was = str(current.get("budget_id", "") or "").strip()
                if was and str(metadata.get("budget_id", "") or "").strip() != was:
                    # A harness session is bound, durably, to the budget it was opened with, and refuses a task that
                    # names another ("adopted task budget differs from the bound session"). Lifting or replacing an
                    # allowance would therefore stop the task's next turn outright. The next turn opens a new session
                    # under the budget the task carries now.
                    metadata.pop("harness_session_id", None)
                task.metadata = metadata
                try:
                    await save(task)
                except (Exception, CompanyRunControllerLeaseLost):
                    if task is run_task:
                        raise
                    # One work item that cannot be written (its turn is being claimed this instant, say) must not
                    # leave the ones after it on the old allowance as well. It keeps what it had, and is named.
                    task.metadata = current
                    unreached.append(str(getattr(task, "id", "") or ""))
                    logger.opt(exception=True).warning("order run {}: task {} could not take the change of allowance", run_task_id, getattr(task, "id", ""))
                    continue
                touched += 1
        return touched, dict(getattr(run_task, "metadata", {}) or {}), unreached

    async def _process_session_message_from_console(
        self,
        project_id: str,
        task_id: str,
        content: str,
        *,
        client_message_id: str = "",
        creation_source_task_id: str | None = None,
    ) -> None:
        """Send a message into a session without a client socket (order launches)."""

        if creation_source_task_id is not None:
            source_import_failed = False
            try:
                from ampuly.layer0_interaction.message_bus import _validate_creation_source_task_id
                from ampuly.core.models import Task, TaskStatus
                from ampuly.database.order_root_admission import FirstOwnedRootAdmissionFact, SOURCE_KIND
                from ampuly.layer2_organization.first_run_source_observation import (
                    FirstRunSourceObservation, _observation_values,
                )
            except Exception:
                source_import_failed = True
            if source_import_failed:
                raise RuntimeError("source launch handoff unavailable") from None

            _validate_creation_source_task_id(creation_source_task_id)
            from ampuly.database.source_project_scope import validate_source_project
            validate_source_project(project_id)
            if (
                type(project_id) is not str
                or type(task_id) is not str or task_id != creation_source_task_id
            ):
                raise RuntimeError("source launch handoff unavailable") from None
            run_engine, run_project_id = await self._engine_for_request(
                {"project_id": project_id}
            )
            if (type(run_project_id) is not str or run_project_id != project_id
                    or not self._store_is_ready(run_engine.store)):
                raise RuntimeError("source launch handoff unavailable") from None
            source_task = await run_engine.store.get_task(task_id)
            if (
                type(source_task) is not Task
                or any(type(value) is not str for value in (
                    source_task.id, source_task.project_id, source_task.session_id,
                ))
                or source_task.id != task_id or source_task.project_id != project_id
                or not source_task.session_id or source_task.status is not TaskStatus.PENDING
            ):
                raise RuntimeError("source launch handoff unavailable") from None
            source_session_id = source_task.session_id
            loop = asyncio.get_running_loop()
            receipt_future = loop.create_future()
            deadline = loop.time() + 30.0
            receipt_closed = False
            receipt_accepted = False
            pre_handoff_failure = None
            background = None

            def receive_handoff(
                fact: FirstOwnedRootAdmissionFact, observation: FirstRunSourceObservation,
            ) -> None:
                nonlocal receipt_closed, receipt_accepted
                # All validation precedes set_result. No user callback or await
                # occurs after the future is resolved; a rejected receipt
                # cannot resolve it and then raise.
                if receipt_closed or receipt_future.done() or loop.time() >= deadline:
                    raise RuntimeError("source launch handoff unavailable") from None
                if type(fact) is not FirstOwnedRootAdmissionFact:
                    raise RuntimeError("source launch handoff unavailable") from None
                selected = _observation_values(observation)
                fact_scope = (
                    fact.project_id, fact.session_id, fact.source_task_id,
                    fact.run_id, fact.root_work_item_id, fact.runtime_task_id,
                )
                fact_ids = (
                    fact.fact_id, fact.source_task_fact_id, fact.run_creation_fact_id,
                    fact.root_creation_fact_id, fact.root_task_binding_fact_id,
                    fact.record_sha256, fact.controller_owner_sha256,
                )
                if (
                    selected[:3] != (project_id, source_session_id, task_id)
                    or any(type(value) is not str for value in fact_scope)
                    or fact_scope != selected
                    or any(type(value) is not str or len(value) != 64
                           or any(char not in "0123456789abcdef" for char in value)
                           for value in fact_ids)
                    or type(fact.claim_attempt_seq) is not int or fact.claim_attempt_seq != 1
                    or type(fact.controller_lease_generation) is not int
                    or fact.controller_lease_generation <= 0
                    or type(fact.source_kind) is not str or fact.source_kind != SOURCE_KIND
                    or type(fact.record_bytes) is not bytes
                    or not fact.record_bytes or len(fact.record_bytes) > 65536
                ):
                    raise RuntimeError("source launch handoff unavailable") from None
                receipt_closed = True
                receipt_accepted = True
                receipt_future.set_result((fact, observation))

            async def run_source_message() -> None:
                nonlocal pre_handoff_failure
                try:
                    await self._process_session_message(
                        task_id, content, session_id=source_session_id,
                        message_metadata={"ui_message_id": client_message_id},
                        user_message_id=client_message_id,
                        run_engine=run_engine, run_project_id=run_project_id,
                        creation_source_task_id=creation_source_task_id,
                        _first_owned_source_handoff_sink=receive_handoff,
                    )
                except BaseException as error:
                    if receipt_accepted:
                        # A start receipt is not business completion: subsequent
                        # failures stay on the original tracked execution path.
                        raise
                    pre_handoff_failure = error if not isinstance(error, Exception) else False
                    # The original track callback sees a retrieved, completed
                    # startup wrapper, not an old FAILED/restart notification.
                finally:
                    if not receipt_accepted:
                        try:
                            current = asyncio.current_task()
                            if self._task_lock_holders.get(task_id) is current:
                                self._task_lock_holders.pop(task_id, None)
                                if source_lock is None:
                                    self._task_locks.pop(task_id, None)
                                self._active_runtime_children.pop(task_id, None)
                                if self._session_to_task.get(source_session_id) == task_id:
                                    self._session_to_task.pop(source_session_id, None)
                            if source_lock is not None:
                                WSHandler._prune_source_task_lock(self, task_id, source_lock)
                        except BaseException:
                            # Secondary local cleanup never changes the startup
                            # primary or starts an alternative business flow.
                            pass

            startup_failure = None
            startup_base_failure = None
            source_lock = None
            try:
                source_lock = WSHandler._mark_source_task_lock(self, task_id)
                background = self._track_session(
                    task_id, run_source_message(),
                    project_id=run_project_id, engine=run_engine,
                )
                if not issubclass(type(background), asyncio.Task):
                    raise RuntimeError("source launch handoff unavailable") from None
                await asyncio.wait(
                    (receipt_future, background),
                    timeout=max(0.0, deadline - loop.time()),
                    return_when=asyncio.FIRST_COMPLETED,
                )
                # Verified receipt has priority even if worker execution
                # completed/failed during this same wait wake-up.
                if receipt_accepted and receipt_future.done() and not receipt_future.cancelled():
                    receipt_future.result()
                    return
                if asyncio.Task.done(background):
                    if not asyncio.Task.cancelled(background):
                        asyncio.Task.exception(background)
                    if pre_handoff_failure is not None and pre_handoff_failure is not False:
                        raise pre_handoff_failure
                startup_failure = "source launch handoff outcome unknown"
            except Exception:
                startup_failure = "source launch handoff outcome unknown"
            except BaseException as error:
                startup_base_failure = error
            finally:
                if not receipt_accepted:
                    receipt_closed = True
                    # One cancellation request, no re-send, no retry or wait
                    # for the long-running business flow to terminate.
                    if background is not None and issubclass(type(background), asyncio.Task):
                        try:
                            if not asyncio.Task.done(background):
                                asyncio.Task.cancel(background)
                        except BaseException:
                            pass
                    if not receipt_future.done():
                        receipt_future.cancel()
                if source_lock is not None:
                    try:
                        WSHandler._prune_source_task_lock(self, task_id, source_lock)
                    except BaseException:
                        if startup_base_failure is None and startup_failure is None:
                            raise
            if startup_base_failure is not None:
                raise startup_base_failure
            raise RuntimeError(startup_failure or "source launch handoff outcome unknown") from None

        class _Sink:
            async def send_json(self, payload: Any) -> None:
                _ = payload

        existing_scope = (
            await self.chat_store.message_scope(client_message_id)
            if client_message_id
            else None
        )
        if existing_scope == (f"session:{task_id}", project_id):
            run_engine, run_project_id = await self._engine_for_request(
                {"project_id": project_id}
            )
            task = await run_engine.store.get_task(task_id) if run_engine.store else None
            status = str(
                getattr(getattr(task, "status", ""), "value", getattr(task, "status", ""))
                or ""
            ).strip()
            if task is not None and status == "pending":
                self._track_session(
                    task_id,
                    self._process_session_message(
                        task_id,
                        content,
                        session_id=str(getattr(task, "session_id", "") or "") or None,
                        message_metadata={"ui_message_id": client_message_id},
                        user_message_id=client_message_id,
                        run_engine=run_engine,
                        run_project_id=run_project_id,
                    ),
                    project_id=run_project_id,
                    engine=run_engine,
                )
            return
        await self._handle_session_send(_Sink(), {
            "project_id": project_id,
            "task_id": task_id,
            "content": content,
            "attachments": [],
            "metadata": (
                {"ui_message_id": client_message_id}
                if client_message_id
                else {}
            ),
        })

    async def _order_of_work_item(self, task: Any) -> Any | None:
        """The order whose production run this work item belongs to, or None when it cannot be established.

        The run's own task is the order's ``launched_task_id``. The root work item names that task as its origin; the
        work items the executor makes under it share the root's delegation run. Read-only. Callers that create a new
        child must refuse unknown lineage rather than treating an unresolved order as a new root.
        """
        try:
            metadata = dict(getattr(task, "metadata", {}) or {})
            project_id = str(getattr(task, "project_id", "") or "default").strip() or "default"
            business = getattr(self._console_api(), "business", None)
            if business is None:
                return None
            named = str(metadata.get("order_id", "") or "").strip()
            if named:
                return business.get_order(named, project_id=project_id)
            own_task_id = str(getattr(task, "id", "") or "").strip()
            if own_task_id:
                direct = business.order_for_launched_task(own_task_id, project_id=project_id)
                if direct is not None:
                    return direct
            run_task_id = str(metadata.get("origin_task_id", "") or "").strip()
            delegation_run = str(metadata.get("delegation_run_id", "") or "").strip()
            if not run_task_id and delegation_run:
                engine = await self.services_context.engine_for_project(project_id)
                lister = getattr(getattr(engine, "store", None), "get_tasks", None)
                for other in (await lister(project_id=project_id)) if callable(lister) else ():
                    other_metadata = dict(getattr(other, "metadata", {}) or {})
                    if (str(other_metadata.get("delegation_run_id", "") or "").strip() == delegation_run
                            and str(other_metadata.get("origin_task_id", "") or "").strip()):
                        run_task_id = str(other_metadata["origin_task_id"]).strip()
                        break
            return business.order_for_launched_task(run_task_id, project_id=project_id) if run_task_id else None
        except Exception:
            logger.opt(exception=True).debug("the order of work item {} could not be established", getattr(task, "id", ""))
            return None

    async def _invoke_workflow_node(self, task: Any, node: dict[str, Any]) -> dict[str, Any]:
        """An intake flow reached its invoke_workflow node: create the order, launch the production line."""
        from ampuly.layer4_tools.workspace_fs import workspace_roots_for_task
        from ampuly.plugins.office_ui.workflow_invocation_guard import (
            MAX_WORKFLOW_INVOCATION_DEPTH, WorkflowInvocationRejected, advance_workflow_ancestry,
        )
        from ampuly.plugins.office_ui.workflow_invocation_lineage import (
            preserve_child_invocation_fields, reconstruct_workflow_ancestry,
        )

        api = self._console_api()
        target = str(dict(node.get("invoke", {}) or {}).get("workflow", "") or "").strip()
        package = api.package(target)
        if package is None:
            raise RuntimeError(f"workflow {target!r} not found")
        project_id = str(getattr(task, "project_id", "") or "default").strip()
        invoking_order = await WSHandler._order_of_work_item(self, task)
        business = getattr(api, "business", None)
        get_order = getattr(business, "get_order", None)
        find_invocation = getattr(business, "order_by_invocation_key", None)
        if not callable(get_order) or not callable(find_invocation):
            raise WorkflowInvocationRejected("workflow_lineage_unavailable", "无法核实父子工单关系，尚未发起子流程。")
        ancestry = reconstruct_workflow_ancestry(
            invoking_order, project_id=project_id, get_order=get_order,
            max_depth=MAX_WORKFLOW_INVOCATION_DEPTH,
        )
        child_ancestry = advance_workflow_ancestry(
            current_workflow_id=invoking_order.workflow_id, target_workflow_id=target,
            ancestry=ancestry, max_depth=MAX_WORKFLOW_INVOCATION_DEPTH,
        )
        parent = _workflow_parent_contract(task, node, target, order=invoking_order)
        invocation_key = _workflow_invocation_key(parent)
        existing = find_invocation(invocation_key, project_id=project_id)
        if existing is not None:
            # Recover the original request: don't add today's ancestry/version
            # or reread an intake sheet which changed since the first launch.
            fields = preserve_child_invocation_fields(
                existing, invoking_order=invoking_order, project_id=project_id,
                invoking_task_id=str(getattr(task, "id", "") or ""),
                node_id=str(node.get("id", "") or ""), target_workflow_id=target,
                get_order=get_order, max_depth=MAX_WORKFLOW_INVOCATION_DEPTH,
            )
            order = await api.place_and_launch(
                workflow_id=target, fields=fields, actor=f"node:{node.get('id', '')}",
                project_id=project_id, customer_id=existing.customer_id,
                environment_id=existing.environment_id, source=existing.source,
                source_task_id=existing.source_task_id, invocation_key=invocation_key,
            )
            return {
                "order_id": order.order_id, "workflow_id": order.workflow_id,
                "task_id": order.launched_task_id,
                "summary": f"已核对关联工单 {order.order_id}（任务 {order.launched_task_id[:8]}）",
            }
        workspace_root, output_root = workspace_roots_for_task(task)
        intake_note = ""
        # The intake step writes its sheet where relative paths start (the
        # output root); an order made before data phase 1 may have it at the
        # order level.
        for root in (output_root, workspace_root):
            intake_path = Path(str(root)) / "intake" / "需求单.md" if root else None
            if intake_path is None or not intake_path.is_file():
                continue
            try:
                intake_note = intake_path.read_text(encoding="utf-8")[:6000]
            except OSError:
                intake_note = ""
            break
        original = str((getattr(task, "metadata", {}) or {}).get("original_message", "") or "")
        fields = _workflow_handoff_fields(
            dict(getattr(task, "metadata", {}) or {}),
            original=original,
            intake_note=intake_note,
        )
        parent["workflow_ancestry"] = list(child_ancestry)
        parent["target_workflow_version"] = str(
            dict(getattr(package, "manifest", {}) or {}).get("version", "") or ""
        ).strip()
        parent["target_manifest_sha256"] = str(
            dict(getattr(package, "release_evidence", {}) or {}).get("manifest_sha256", "") or ""
        ).strip()
        fields["_workflow_parent"] = parent
        order = await api.place_and_launch(
            workflow_id=target,
            fields=fields,
            actor=f"node:{node.get('id', '')}",
            project_id=project_id,
            customer_id=str(parent.get("customer_id", "") or ""),
            environment_id=str(parent.get("environment_id", "") or ""),
            source="intake_flow",
            source_task_id=str(getattr(task, "id", "") or ""),
            invocation_key=invocation_key,
        )
        return {
            "order_id": order.order_id,
            "workflow_id": order.workflow_id,
            "task_id": order.launched_task_id,
            "summary": f"已生成工单 {order.order_id} 并发起 {order.workflow_id}（任务 {order.launched_task_id[:8]}）",
        }

    async def _handle_order_list(self, ws: Any, data: dict) -> None:
        project_id = self._request_project_id(data)
        status = str(data.get("status", "") or "") or None
        me = self._client_accounts.get(ws) if hasattr(self, "_client_accounts") else None
        actor = str(getattr(me, "login", "") or "anonymous")
        environment_id = str(data.get("environment_id", "") or "").strip()
        if str(getattr(me, "role", "") or "").strip().lower() == "customer":
            # S3-6A: a customer account's list is narrowed to its own customers and answered in customer rows;
            # the owner's and the employee's list below is untouched.
            await WSHandler._customer_order_list(
                self, ws, data, me, project_id=project_id, status=status, environment_id=environment_id,
            )
            return
        allowed_customers = ws_customer_scope(self, ws)
        customer_id, scope_denied = resolve_customer_scope(allowed_customers, str(data.get("customer_id", "") or ""))
        self._console_api().record_observation(
            project_id=project_id,
            actor=actor,
            action="order_list",
            object_type="work_order_collection",
            object_id=status or "*",
            customer_id=customer_id or str(data.get("customer_id", "") or "").strip(),
            environment_id=environment_id,
            reason=str(data.get("reason", "") or "console_order_list"),
            outcome="denied" if scope_denied else "success",
            metadata={"status": status or "", "environment_id": environment_id, "account_customer_scope": list(allowed_customers)},
        )
        if scope_denied:
            await self._send_ack(
                ws,
                ok=False,
                action="order_list",
                project_id=project_id,
                error="customer_scope_denied",
                allowed_customers=list(allowed_customers),
            )
            return
        # The newest 200. One more is asked for so the reply can say there were more: without it a project past 200
        # orders lost the rest in silence and the list looked complete. ``truncated`` true = only the newest are here.
        limit = 200
        before = str(data.get("before", "") or "").strip()
        if data.get("page") is True or before:
            # 4.7-A08 「查看更早的工单」: pages in one stable order, each reply carrying the cursor of the next
            # (``next_cursor``, '' = nothing older). A request without ``page``/``before`` is answered exactly as before.
            from ampuly.plugins.office_ui.business_store import OrderTransitionError

            try:
                page, next_cursor = self._console_api().orders_page(
                    project_id=project_id, status=status, customer_id=customer_id or None,
                    environment_id=environment_id or None, limit=limit, before=before or None,
                )
            except OrderTransitionError as exc:
                await self._send_ack(ws, ok=False, action="order_list", project_id=project_id, customer_id=customer_id,
                                     environment_id=environment_id, before=before, error=str(exc))
                return
            orders = await WSHandler._with_current_nodes(
                self, WSHandler._with_running_child_counts(self, list(page), project_id=project_id), project_id=project_id,
            )
            orders, partial_projects = await WSHandler._with_order_attention(self, orders, project_id=project_id)
            await self._send_ack(
                ws, ok=True, action="order_list", project_id=project_id, customer_id=customer_id,
                environment_id=environment_id, orders=orders,
                truncated=bool(next_cursor), next_cursor=next_cursor, **({"before": before} if before else {}),
                partial_projects=partial_projects,
            )
            return
        rows = list(
            self._console_api().orders(
                project_id=project_id,
                status=status,
                customer_id=customer_id or None,
                environment_id=environment_id or None,
                limit=limit + 1,
            )
            or []
        )
        orders = await WSHandler._with_current_nodes(
            self, WSHandler._with_running_child_counts(self, rows[:limit], project_id=project_id), project_id=project_id,
        )
        orders, partial_projects = await WSHandler._with_order_attention(self, orders, project_id=project_id)
        await self._send_ack(
            ws,
            ok=True,
            action="order_list",
            project_id=project_id,
            customer_id=customer_id,
            environment_id=environment_id,
            orders=orders,
            truncated=len(rows) > limit,
            partial_projects=partial_projects,
        )

    # A work item in one of these has ended; every other one is a step the order currently stands at.
    _ENDED_WORK_ITEM_STATUSES = frozenset({"done", "failed", "cancelled"})

    async def _with_current_nodes(self, rows: list[dict[str, Any]], *, project_id: str) -> list[dict[str, Any]]:
        """S0-B: each order row with ``current_nodes`` and ``ended_as``.

        ``current_nodes`` is ``[{node_id, node_name}]``: the steps the order's live work items stand at (the run behind
        its launched task, by the timeline's rule ``order_timeline.work_items_of_root``), each step once; an ended order
        has none. ``ended_as`` is how it ended in the page's words -- ``rejected`` (the intake was refused), ``closed``,
        or ``cancelled`` (the closing event says so: ``order_liveness.order_ended_as``) -- "" while it is live; the
        same word ``attention.ended_as`` carries. The project's tasks are read ONCE for the whole page, never once per
        order, and only from an engine this process already runs (a read never builds one); an engine or a store that
        cannot be read leaves every row with no steps rather than failing the list.
        """
        from ampuly.plugins.office_ui.business_store import ENDED_ORDER_STATUSES
        from ampuly.plugins.office_ui.order_liveness import order_ended_as
        from ampuly.plugins.office_ui.order_timeline import work_items_of_root
        from types import SimpleNamespace

        business = getattr(self._console_api(), "business", None)
        open_rows: list[dict[str, Any]] = []
        for row in rows:
            row["current_nodes"] = []
            row["ended_as"] = ""
            status = str(row.get("status", "") or "")
            order_id = str(row.get("order_id", "") or "")
            if status not in ENDED_ORDER_STATUSES:
                if str(row.get("launched_task_id", "") or "").strip():
                    open_rows.append(row)
                continue
            if status != "closed":
                row["ended_as"] = status    # rejected: the intake was refused, nothing ran
                continue
            if business is None:
                continue
            try:
                row["ended_as"] = str(order_ended_as(business, SimpleNamespace(order_id=order_id, status=status)) or "")
            except Exception:
                logger.opt(exception=True).debug("order list: how order {} ended could not be read", order_id)
        if not open_rows:
            return rows
        try:
            store = getattr(self._project_engines().loaded(project_id), "store", None)
            if store is None or not self._store_is_ready(store):
                logger.debug("order list: no engine runs project {} in this process; steps not read", project_id)
                return rows
            tasks = list(await store.get_tasks(project_id=project_id) or [])
        except Exception:
            logger.opt(exception=True).debug("order list: the work items of project {} could not be read", project_id)
            return rows
        by_id = {str(getattr(task, "id", "") or ""): task for task in tasks}
        for row in open_rows:
            root = by_id.get(str(row.get("launched_task_id", "") or "").strip())
            if root is not None:
                row["current_nodes"] = WSHandler._current_nodes_of(work_items_of_root(tasks, root))
        return rows

    @staticmethod
    def _current_nodes_of(items: list[Any]) -> list[dict[str, str]]:
        """The steps the live work items among ``items`` stand at, each once, in the store's own order."""
        seen: set[str] = set()
        nodes: list[dict[str, str]] = []
        for task in items:
            status = str(getattr(getattr(task, "status", ""), "value", getattr(task, "status", "")) or "")
            if status in WSHandler._ENDED_WORK_ITEM_STATUSES:
                continue
            meta = dict(getattr(task, "metadata", {}) or {})
            node = meta.get("workflow_node")
            node = node if isinstance(node, dict) else {}
            node_id = str(node.get("id", "") or meta.get("workflow_node_id", "") or work_item_projection_id_from_metadata(meta) or "").strip()
            node_name = str(node.get("name", "") or "").strip()
            key = node_id or node_name
            if not key or key in seen:
                continue
            seen.add(key)
            nodes.append({"node_id": node_id, "node_name": node_name or node_id})
        return nodes

    async def _pending_checkpoints_for_attention(self, project_id: str) -> list[Any]:
        """The pending checkpoints of a project for the S0-A judgement, without loading anything.

        The engine this process already runs for the project answers from its store; any other project's store file
        is read read-only (``order_attention.pending_checkpoints_readonly``, the C4-FIX pattern); a project with no
        store file has no runs and so no pauses.  Raises when the home is unknown or the file cannot be read, so the
        judgement says it is partial rather than count nothing.
        """
        from ampuly.plugins.office_ui.order_attention import pending_checkpoints_readonly

        engine = self._project_engines().loaded(project_id)
        store = getattr(engine, "store", None)
        if store is not None and self._store_is_ready(store):
            return list(await store.get_pending_checkpoints(project_id=project_id) or [])
        home = getattr(getattr(self, "_root_engine", None), "ampuly_home", None)
        if not isinstance(home, (str, Path)):
            raise RuntimeError("the console's home is unknown; the project's pauses cannot be read")
        db_path = self._gate_retire_unloaded_db(project_id)
        if db_path is None:
            return []
        return await pending_checkpoints_readonly(db_path, project_id)

    async def _judge_order_attention(self, project_id: str, rows: list[dict[str, Any]]) -> tuple[dict[str, dict[str, Any]], bool]:
        """S0-A: the judgement of these order rows of one project -- who each waits on, abnormal, overdue -- by
        ``order_attention.judge_project``, over the console's business store and the project's pending checkpoints.
        Fails open: ``(verdicts with waiting_on '' and partial, True)`` when they cannot be read."""
        from ampuly.plugins.office_ui.order_attention import judge_project

        business = getattr(self._console_api(), "business", None)
        # The rows already say how each closed order ended (``_with_current_nodes`` read the closing events once);
        # hand that over so the judgement does not read them a second time. A closed row it could not read leaves
        # the judgement to read them itself.
        closed = [row for row in rows if str(row.get("status", "") or "") == "closed"]
        known = all(str(row.get("ended_as", "") or "") for row in closed)
        cancelled_ids = {str(row.get("order_id", "") or "") for row in closed if row.get("ended_as") == "cancelled"} if known else None
        return await judge_project(
            project_id, rows, business=business,
            pending=lambda pid: WSHandler._pending_checkpoints_for_attention(self, pid),
            cancelled_ids=cancelled_ids,
        )

    async def _with_order_attention(self, rows: list[dict[str, Any]], *, project_id: str) -> tuple[list[dict[str, Any]], list[str]]:
        """Each order row with ``attention`` (the S0-A verdict), and the projects whose judgement was partial
        (``[project_id]`` or ``[]``) for the ack to say so."""
        try:
            verdicts, partial = await WSHandler._judge_order_attention(self, project_id, rows)
        except Exception:
            logger.opt(exception=True).warning("order list: the attention of project {} could not be judged", project_id)
            from ampuly.plugins.office_ui.order_attention import judge_rows

            verdicts, partial = judge_rows(rows, partial=True), True
        for row in rows:
            row["attention"] = verdicts.get(str(row.get("order_id", "") or "").strip()) or {"waiting_on": "", "partial": True}
        return rows, ([project_id] if partial else [])

    # ── S3-3A 总控: 「等你处理」 across projects, and where a card lives (plugin only; read only; loads no engine) ──

    async def _handle_owner_attention_list(self, ws: Any, data: dict) -> None:
        """S3-3A 总控: the orders that wait on the owner across every project the account can see, in one query.

        Each item carries the S0-A verdict (``attention``), the S1 card the order waits on (``owner_card``; None when
        the wait is not a card -- an intake to accept, a delivery to accept) and ``due_days``; 逾期在前、其次等得最久,
        at most ``limit`` of them (default 3, at most 20; ``total`` says how many there were). ``counts`` are the
        状态句's three numbers over every row read; ``partial_projects`` names the projects whose orders or store could
        not be read -- their waiting is unknown, not zero. Owner only; a cross-project read has no single customer to
        narrow to, so an account bound to customers is refused. Every project is read once: its order rows, and its
        pauses through the engine this process runs for it or its store file read-only
        (``_pending_checkpoints_for_attention``); no engine is loaded for it. Nothing is recorded: it is the page's
        standing read. ``blockers_list`` is untouched.
        """
        from ampuly.plugins.office_ui.order_attention import collect_owner_attention, load_project_judgement
        from ampuly.plugins.office_ui.project_overview import project_order_rows

        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="owner_attention_list", error="owner_required")
            return
        allowed_customers = ws_customer_scope(self, ws)
        if allowed_customers:
            await self._send_ack(ws, ok=False, action="owner_attention_list", error="customer_scope_denied",
                                 allowed_customers=list(allowed_customers))
            return
        try:
            listed = await self._ensure_office_services().project.list(active_project_id=None)
        except ServiceError as exc:
            await self._send_service_error(ws, exc, action="owner_attention_list")
            return
        visible = visible_projects_for_scope(self, ws, list(dict(listed.payload).get("projects") or []))
        api = self._console_api()
        business = getattr(api, "business", None)

        def rows_of(project_id: str) -> list[dict[str, Any]]:
            return project_order_rows(api, [project_id]).get(project_id, ([], False))[0]

        async def judgement(project_id: str, rows: list[dict[str, Any]]) -> dict[str, Any]:
            return await load_project_judgement(
                project_id, rows, business=business,
                pending=lambda pid: WSHandler._pending_checkpoints_for_attention(self, pid),
            )

        result = await collect_owner_attention(
            visible, rows_of=rows_of, judgement=judgement, limit=data.get("limit", 3), zh=_ws_is_zh(),
            employee_names=await asyncio.to_thread(WSHandler._employee_display_names, self),
        )
        await self._send_ack(ws, ok=True, action="owner_attention_list", **result)

    def _employee_display_names(self) -> dict[str, str]:
        """Employee id -> the name the owner knows, from the console's accounts: one read, and the org engine of no
        other project is opened for it. {} when the accounts cannot be read (a card then says 负责人, never an id)."""
        list_accounts = getattr(self._accounts(), "list_accounts", None)
        if not callable(list_accounts):
            return {}
        names: dict[str, str] = {}
        try:
            for account in list_accounts():
                employee_id = str(getattr(account, "employee_id", "") or "").strip()
                name = str(getattr(account, "display_name", "") or "").strip()
                if employee_id and name:
                    names.setdefault(employee_id, name)
        except Exception:
            logger.opt(exception=True).debug("owner attention: the accounts could not be read for employee names")
            return {}
        return names

    async def _handle_checkpoint_locate(self, ws: Any, data: dict) -> None:
        """S3-3A: where a card lives -- ``{project_id, order_id}`` for a checkpoint id -- so the deep link
        ``?page=approvals&checkpoint_id=X`` keeps working once that page key is retired: the page lands on 总控 with
        that card's order selected.

        Owner only; reads only (``order_attention.locate_checkpoint``). The card row (the order a Feishu card was
        sent for) answers first; else every visible project's store is asked in turn -- the engine this process runs,
        or the file read-only (``_checkpoint_in_project``) -- and no engine is loaded for it. ``order_id`` is '' when
        the checkpoint is found but belongs to no order; ``checkpoint_not_found`` when it is nowhere.
        """
        from ampuly.plugins.office_ui.order_attention import locate_checkpoint

        checkpoint_id = str(data.get("checkpoint_id", "") or "").strip()
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="checkpoint_locate", checkpoint_id=checkpoint_id, error="owner_required")
            return
        if not checkpoint_id:
            await self._send_ack(ws, ok=False, action="checkpoint_locate", checkpoint_id="", error="checkpoint_id_required")
            return
        try:
            listed = await self._ensure_office_services().project.list(active_project_id=None)
        except ServiceError as exc:
            await self._send_service_error(ws, exc, action="checkpoint_locate")
            return
        visible = visible_projects_for_scope(self, ws, list(dict(listed.payload).get("projects") or []))
        project_ids = [str(entry.get("id", "") or entry.get("project_id", "") or "").strip() for entry in visible]
        found = await locate_checkpoint(
            checkpoint_id, business=getattr(self._console_api(), "business", None), project_ids=project_ids,
            checkpoint_in=lambda pid, cid: WSHandler._checkpoint_in_project(self, pid, cid),
        )
        if found is None:
            await self._send_ack(ws, ok=False, action="checkpoint_locate", checkpoint_id=checkpoint_id, error="checkpoint_not_found")
            return
        await self._send_ack(ws, ok=True, action="checkpoint_locate", checkpoint_id=checkpoint_id, **found)

    async def _checkpoint_in_project(self, project_id: str, checkpoint_id: str) -> Any:
        """One checkpoint of a project, whatever its status, without loading anything: through the engine this
        process already runs for the project, else in its store file read-only (``_gate_retire_unloaded_rows``).
        None when the project has no store on disk or the checkpoint is not in it."""
        engine = self._project_engines().loaded(project_id)
        store = getattr(engine, "store", None)
        if store is not None and self._store_is_ready(store):
            return await store.get_execution_checkpoint(checkpoint_id, project_id=project_id)
        db_path = self._gate_retire_unloaded_db(project_id)
        if db_path is None:
            return None
        found = await self._gate_retire_unloaded_rows(db_path, project_id, checkpoint_id=checkpoint_id)
        return found[0] if found else None

    def _with_running_child_counts(self, rows: list[dict[str, Any]], *, project_id: str) -> list[dict[str, Any]]:
        """Each order row with ``running_child_orders``: how many orders its run started (and theirs) are still going.

        The page offers "also cancel the N orders it started" from this number. It cannot count them itself: its own
        list is capped, narrowed by the customer filter, and the rows that matter may not be on it.
        """
        try:
            # Asked by status and lineage, not read off the newest 500 orders: a child older than that window that
            # was still running went uncounted, and the page never offered the cascade (B3).
            by_parent = self._console_api().business.running_child_lineage(project_id=project_id, lineage_field=PARENT_CONTRACT_FIELD)
        except Exception:
            logger.opt(exception=True).debug("order list: child orders of project {} could not be counted", project_id)
            return rows
        for row in rows:
            row["running_child_orders"] = len(WSHandler._orders_started_by(by_parent, str(row.get("order_id", "") or ""))) if by_parent else 0
        return rows

    async def _handle_order_get(self, ws: Any, data: dict) -> None:
        project_id = self._request_project_id(data)
        order_id = str(data.get("order_id", "") or "")
        order = self._console_api().order(order_id, project_id=project_id)
        me = self._client_accounts.get(ws) if hasattr(self, "_client_accounts") else None
        actor = str(getattr(me, "login", "") or "anonymous")
        requested_customer = str(data.get("customer_id", "") or "").strip()
        requested_environment = str(data.get("environment_id", "") or "").strip()
        allowed_customers = ws_customer_scope(self, ws)
        order_customer = str((order or {}).get("customer_id", "") or "").strip()
        customer_scope_denied = bool(
            order is not None
            and requested_customer
            and order_customer != requested_customer
        ) or bool(
            # The account's own binding, independent of what it asked for.
            order is not None
            and allowed_customers
            and order_customer not in allowed_customers
        )
        environment_scope_denied = bool(
            order is not None
            and requested_environment
            and str(order.get("environment_id", "") or "").strip() != requested_environment
        )
        self._console_api().record_observation(
            project_id=project_id,
            actor=actor,
            action="order_get",
            object_type="work_order",
            object_id=order_id,
            customer_id=requested_customer or str((order or {}).get("customer_id", "") or ""),
            environment_id=requested_environment or str((order or {}).get("environment_id", "") or ""),
            reason=str(data.get("reason", "") or "console_order_detail"),
            outcome="denied" if (customer_scope_denied or environment_scope_denied) else ("success" if order is not None else "not_found"),
        )
        if customer_scope_denied or environment_scope_denied:
            await self._send_ack(
                ws,
                ok=False,
                action="order_get",
                project_id=project_id,
                order_id=order_id,
                customer_id=requested_customer,
                environment_id=requested_environment,
                error="customer_scope_denied" if customer_scope_denied else "environment_scope_denied",
            )
            return
        if order is None:
            await self._send_ack(
                ws,
                ok=False,
                action="order_get",
                project_id=project_id,
                order_id=order_id,
                customer_id=requested_customer,
                environment_id=requested_environment,
                error="order_not_found",
            )
            return
        await self._send_ack(ws, ok=True, action="order_get", project_id=project_id, order=order)

    async def _handle_fde_control_plane_update(self, ws: Any, data: dict) -> None:
        """Update editable FDE planning fields for one scoped order."""
