    async def _handle_observation_audit_list(self, ws: Any, data: dict) -> None:
        project_id = self._request_project_id(data)
        customer_id = data.get("customer_id")
        environment_id = data.get("environment_id")
        allowed_customers = ws_customer_scope(self, ws)
        if allowed_customers:
            # Who looked at what is itself customer data: a bound account reads its own customer's trail only.
            narrowed, scope_denied = resolve_customer_scope(allowed_customers, str(customer_id or ""))
            if scope_denied:
                await self._send_ack(ws, ok=False, action="observation_audit_list", project_id=project_id,
                                     error="customer_scope_denied", allowed_customers=list(allowed_customers))
                return
            customer_id = narrowed
        try:
            limit = int(data.get("limit", 100) or 100)
        except (TypeError, ValueError):
            limit = 100
