    async def _handle_acceptance_decide(self, ws: Any, data: dict) -> None:
        from ampuly.plugins.office_ui import acceptance_round
        from ampuly.plugins.office_ui.business_store import OrderTransitionError

        project_id = self._request_project_id(data)
        order_id = str(data.get("order_id", "") or "").strip()
        me = self._client_accounts.get(ws) if hasattr(self, "_client_accounts") else None
        raw_exceptions = data.get("exceptions")
        exceptions = [str(item) for item in raw_exceptions] if isinstance(raw_exceptions, list) else []
        decision = str(data.get("decision", "") or "").strip().lower()
        note = str(data.get("note", "") or "")
        actor = str(getattr(me, "login", "") or "owner")

        async def close_pauses() -> Any:
            # What the order still has waiting is closed now, not at the next start's sweep (runtime contract),
            # and its run is ended (candidate 7).
            return await WSHandler._close_pauses_of_closed_order(self, project_id, order_id, actor=actor)

        try:
            engine, _pid = await self._engine_for_request({"project_id": project_id})
            if data.get("close_order"):
                # 确认收货并结案 (B5,; all or nothing since C5-2): one click takes a delivering order's round
                # to a passing decision -- the owner's receipt, the frozen round, the submission -- and closes it.
                outcome = await acceptance_round.confirm_receipt_and_close(
                    self._console_api(), engine, project_id, order_id, decision=decision, actor=actor, note=note,
                    exceptions=exceptions, close_pauses=close_pauses,
                )
            else:
                outcome = await acceptance_round.decide(
                    self._console_api(), engine, project_id, order_id, decision=decision, actor=actor, note=note,
                    exceptions=exceptions,
                )
        except (OrderTransitionError, ValueError) as exc:
            await self._send_ack(ws, ok=False, action="acceptance_decide", project_id=project_id, order_id=order_id, error=str(exc))
            return
        payload = await acceptance_round.verified_payload(engine, project_id, outcome.record)
        await self._send_ack(
            ws,
            ok=True,
            action="acceptance_decide",
            project_id=project_id,
            order_id=order_id,
            acceptance=payload,
            **({"order_status": outcome.order_status} if outcome.order_status else {}),
        )

    async def _close_pauses_of_closed_order(self, project_id: str, order_id: str, *, actor: str = "") -> dict[str, Any]:
        """确认收货并结案 closed ``order_id``: close what its run still has waiting, as the start-up sweep would later.

        runtime contract. The same closing as the sweep and the cancel
        (``close_order_pauses``: typed administrative closure, idempotent, an answered pause left to its answer), found
        the same way (the order's run task and its session). The delivery's lesson card, still open when the owner
        closes the order, says the order was closed and no lesson was left. Closing a card consumes no answer, so the
        paid self-evolution pass that 完全同意 / 写一句反馈 starts does not start. Candidate 7: the order's run is
        ended too (``end_company_runs_of_ended_order``, by ``actor``), so no restart parks it again; one a live
        controller still holds is ended by the next start. Never raises: the order is closed whatever happens here,
        and a pause left open is closed by the next start's sweep.
        """
        from ampuly.plugins.office_ui.order_cancel import (
            CLOSED_ORDER_PAUSE_REASON,
            NO_LESSON_LEFT_REASON,
            close_order_pauses,
        )

        try:
            engine, _project = await self._engine_for_request({"project_id": project_id})
            order = await asyncio.to_thread(self._console_api().business.get_order, order_id, project_id=project_id)
        except Exception:
            logger.opt(exception=True).warning("close: what order {} still had waiting was not looked at", order_id)
            return {}
        store = getattr(engine, "store", None)
        launched = str(getattr(order, "launched_task_id", "") or "").strip() if order is not None else ""
        if store is None or not launched:
            return {}
        end_runs = getattr(engine, "end_company_runs_of_ended_order", None)
        if callable(end_runs):
            try:
                runs = dict(await end_runs(
                    origin_task_id=launched, order_id=order_id, ended_as="closed",
                    actor=str(actor or "").strip() or "确认收货并结案", reason=CLOSED_ORDER_PAUSE_REASON,
                ) or {})
                logger.info(
                    "close: order {} ended {} run(s) ({} still held by a live controller: the next start ends them)",
                    order_id, len(list(runs.get("ended", []) or [])), len(list(runs.get("busy", []) or [])),
                )
            except Exception:
                logger.opt(exception=True).warning("close: the run of order {} was not marked ended; the next start does", order_id)
        sessions: set[str] = set()
        try:
            run_task = await store.get_task(launched)
        except Exception:
            run_task = None
        if str(getattr(run_task, "session_id", "") or "").strip():
            sessions.add(str(run_task.session_id).strip())
        try:
            outcome = await close_order_pauses(
                engine, project_id=project_id, order_id=order_id, task_ids={launched}, session_ids=sessions,
                reason=CLOSED_ORDER_PAUSE_REASON, reasons_by_type={"company_delivery_feedback": NO_LESSON_LEFT_REASON},
            )
        except Exception:
            logger.opt(exception=True).warning("close: what order {} still had waiting could not be closed", order_id)
            return {}
        logger.info(
            "close: order {} closed {} pause(s) it still had waiting ({} left to their answer, {} could not be closed)",
            order_id, len(list(outcome.get("closed", []) or [])), len(list(outcome.get("skipped", []) or [])),
            len(list(outcome.get("failed", []) or [])),
        )
        return outcome

    async def _receipt_evidence(self, project_id: str, order: Any) -> list[dict[str, Any]]:
        """What the owner's receipt for 确认收货并结案 points at -- the rule is ``acceptance_round.receipt_evidence``
        (C5-2); kept under this name for its callers."""
        from ampuly.plugins.office_ui import acceptance_round

        engine, _pid = await self._engine_for_request({"project_id": project_id})
        return await acceptance_round.receipt_evidence(self._console_api(), engine, project_id, order)

    async def _handle_acceptance_rework(self, ws: Any, data: dict) -> None:
        from ampuly.plugins.office_ui import acceptance_round
        from ampuly.plugins.office_ui.business_store import OrderTransitionError

        project_id = self._request_project_id(data)
        order_id = str(data.get("order_id", "") or "").strip()
        target_node = str(data.get("target_node", "") or "").strip()
        request_id = str(data.get("request_id", "") or "").strip()
        me = self._client_accounts.get(ws) if hasattr(self, "_client_accounts") else None
        try:
            engine, _pid = await self._engine_for_request({"project_id": project_id})
            acceptance = await acceptance_round.rework(
                self._console_api(), engine, project_id, order_id,
                target_node=target_node, actor=str(getattr(me, "login", "") or "owner"), request_id=request_id,
            )
        except (OrderTransitionError, ValueError, OSError, RuntimeError) as exc:
            await self._send_ack(
                ws,
                ok=False,
                action="acceptance_rework",
                project_id=project_id,
                order_id=order_id,
                error=str(exc),
            )
            return
        payload = await acceptance_round.verified_payload(engine, project_id, acceptance)
        await self._send_ack(
            ws,
            ok=True,
            action="acceptance_rework",
            project_id=project_id,
            order_id=order_id,
            acceptance=payload,
        )

