    async def _handle_workflow_invoke(self, ws: Any, data: dict) -> None:
        """The owner's one-click launch: an order is created and approved at once.

        Every launch leaves the same trail as an intake-flow launch, so the
        business layer sees test orders and real orders alike.
        """
        from ampuly.plugins.office_ui.business_store import OrderTransitionError

        workflow_id = str(data.get("workflow_id", "") or "").strip()
        raw_fields = data.get("fields")
        fields = dict(raw_fields) if isinstance(raw_fields, dict) else {}
        me = self._client_accounts.get(ws) if hasattr(self, "_client_accounts") else None
        raw_limits = data.get("budget_limits")
        _run_engine, pid = await self._engine_for_request(data)
        try:
            order = await self._console_api().place_and_launch(
                workflow_id=workflow_id,
                fields=fields,
                actor=str(getattr(me, "login", "") or "owner"),
                project_id=pid,
                customer_id=str(data.get("customer_id", "") or "").strip(),
                environment_id=str(data.get("environment_id", "") or "").strip(),
                source="console",
                budget_limits=dict(raw_limits) if isinstance(raw_limits, dict) and raw_limits else None,
            )
        except (OrderTransitionError, ValueError) as exc:
            await self._send_ack(ws, ok=False, action="workflow_invoke", project_id=pid, error=str(exc), workflow_id=workflow_id)
            return
        except Exception as exc:
            logger.opt(exception=True).warning("workflow invoke failed for {}", workflow_id)
            await self._send_ack(ws, ok=False, action="workflow_invoke", project_id=pid, error=f"launch_failed: {exc}", workflow_id=workflow_id)
            return
        await self._send_ack(
            ws,
            ok=True,
            action="workflow_invoke",
            project_id=pid,
            workflow_id=workflow_id,
            task_id=order.launched_task_id,
            org_id=order.org_id,
            order_id=order.order_id,
        )

    async def _handle_duty_log_list(self, ws: Any, data: dict) -> None:
        """What the duty officer's patrol has said recently, sent or not.

        The patrol records every line it would have paged even when no
        channel is configured, so the console can show the same judgement
        (who is waited on, what finished, what looks stuck) without a pager.
        """
        from ampuly.plugins.office_ui.notifier import notifier_from_env

        try:
            _engine, project_id = await self._engine_for_request(data)
        except ProjectScopeError as exc:
            await self._send_ack(ws, ok=False, action="duty_log_list", project_id=str(data.get("project_id", "") or "").strip(), error=str(exc))
            return
        entries = [
            item for item in self._duty_log[-20:]
            if str(item.get("project_id", "") or "").strip() == project_id
        ]
        await self._send_ack(
            ws,
            ok=True,
            action="duty_log_list",
            configured=notifier_from_env().configured,
            project_id=project_id,
            entries=entries,
        )

    def _public_base_url(self) -> str:
        """Where this console is reachable, for the links in messages (duty notes, test messages).

        The server hands over the real host and port at start-up (``_public_host`` / ``_public_port``). A handler
        that was not told reads what the console published into its home (console-address.json); only with
        neither does it fall back to 8765 -- which every link said while the console ran on 8766.
        """
        port = getattr(self, "_public_port", None) or getattr(self, "port", None)
        if not port:
            try:
                from ampuly.cli.ui_bridge import published_port

                port = published_port()
            except Exception:
                port = None
        host = str(getattr(self, "_public_host", "") or "").strip()
        if host in {"", "0.0.0.0", "::", "127.0.0.1"}:
            host = "localhost"
        return f"http://{host}:{int(port or 8765)}"

    async def _handle_settings_set_routing(self, ws: Any, data: dict) -> None:
        """Change the default model or a routing slot; every changed field is recorded (model-routing phase 0)."""
        from ampuly.plugins.office_ui.settings_service import ROUTING_CHANGE_SCOPE, apply_routing, build_settings_payload

        try:
            run_engine, _pid = await self._engine_for_request(data)
            # Customers resolved per call with a model key of their own: their key would follow the default to another
            # vendor (review R3), so such a move is refused as for an engine that holds a customer's key.
            resolver_bound = callable(getattr(getattr(run_engine, "llm", None), "_resolve_key_env", None))
            customer_model_keys = resolver_bound and any(
                str(reference.get("purpose", "") or "") == "model" and str(reference.get("customer_id", "") or "")
                for reference in self._accounts().business.list_credential_references()
            )
            outcome = apply_routing(
                run_engine,
                default_model=str(data.get("default_model", "") or "").strip() or None,
                routing_updates=dict(data.get("routing", {}) or {}),
                customer_model_keys=customer_model_keys,
            )
        except Exception as e:
            await self._send_ack(ws, ok=False, action="settings_set_routing", error=str(e))
            return
        recorded: list[dict[str, Any]] = []
        unrecorded = ""
        for change in outcome["changes"]:
            try:
                recorded.append(self._accounts().business.record_policy_change(
                    change["field"], change["old"], change["new"],
                    actor=_ws_actor_login(self, ws), reason=str(data.get("reason", "") or ""),
                    profile="model_routing", scope=ROUTING_CHANGE_SCOPE,
                ))
            except Exception as exc:
                # The change is live; its record is not. Say so rather than reporting a clean write.
                logger.warning("routing change applied but not recorded: {}", type(exc).__name__)
                unrecorded = type(exc).__name__
        payload = build_settings_payload(run_engine)
        extra: dict[str, Any] = {"changes": recorded}
        if unrecorded:
            extra["unrecorded"] = True
        if not outcome["saved"]:
            extra.update(saved=False, save_error=outcome["save_error"])
        await self._send_ack(ws, ok=True, action="settings_set_routing", **payload, **extra)

    async def _handle_settings_set_model_tiers(self, ws: Any, data: dict) -> None:
        """Set the model tier table: which model 轻 / 标准 / 强 mean, and the rules around them.

        A separate action from ``settings_set_routing``, with its own audit profile, because a tier is not a
        routing slot: pinning a model to a slot and saying what a tier means are different decisions and are
        recorded as different things.
        """
        from ampuly.plugins.office_ui.settings_service import (
            TIER_CHANGE_SCOPE, apply_model_tiers, build_settings_payload, plan_model_tiers,
        )

        def _optional(key: str, kind: Any) -> Any:
            return kind(data[key]) if key in data and data[key] is not None else None

        try:
            run_engine, _pid = await self._engine_for_request(data)
            changes = plan_model_tiers(
                run_engine,
                tiers=_optional("tiers", dict),
                tier_params=_optional("tier_params", dict),
                task_tiers=_optional("task_tiers", dict),
                residency=_optional("residency", str),
                no_training_optout=_optional("no_training_optout", dict),
                work_window_cap=_optional("work_window_cap", int),
            )
            outcome = apply_model_tiers(run_engine, changes, actor=_ws_actor_login(self, ws))
        except Exception as e:
            await self._send_ack(ws, ok=False, action="settings_set_model_tiers", error=str(e))
            return
        try:
            # The tiers file is machine-wide: every engine this process already runs takes the change live too.
            from ampuly.plugins.office_ui.settings_service import apply_tier_changes_live

            engines = self._project_engines()
            others = [engines.loaded(pid) for pid in engines.loaded_project_ids()]
            apply_tier_changes_live([other for other in others if other is not None and other is not run_engine],
                                    outcome["changes"])
        except Exception:
            logger.opt(exception=True).warning("tier change applied to the requesting project only")
        recorded: list[dict[str, Any]] = []
        unrecorded = ""
        for change in outcome["changes"]:
            try:
                recorded.append(self._accounts().business.record_policy_change(
                    change["field"], change["before"], change["after"],
                    actor=_ws_actor_login(self, ws), reason=str(data.get("reason", "") or ""),
                    profile="model_assignment", scope=TIER_CHANGE_SCOPE,
                ))
            except Exception as exc:
                # The change is live; its record is not. Say so rather than reporting a clean write.
                logger.warning("tier change applied but not recorded: {}", type(exc).__name__)
                unrecorded = type(exc).__name__
        payload = build_settings_payload(run_engine)
        extra: dict[str, Any] = {"changes": recorded}
        if unrecorded:
            extra["unrecorded"] = True
        if not outcome["saved"]:
            extra["saved"] = False
        await self._send_ack(ws, ok=True, action="settings_set_model_tiers", **payload, **extra)

    async def _handle_order_model_plan(self, ws: Any, data: dict) -> None:
        """What model settings one order was launched under.

        Answered from the order's own ``model_plan.pinned`` event, never from the live config: an order that has
        none answers ``null`` rather than being shown today's settings as though they were its own. Builds no
        engine, like every other read of an order's record.
        """
        order_id = str(data.get("order_id", "") or "").strip()
        if not order_id:
            await self._send_ack(ws, ok=False, action="order_model_plan", error="missing_order_id")
            return
        try:
            events = self._accounts().business.events(order_id)
        except Exception as exc:
            await self._send_ack(ws, ok=False, action="order_model_plan", error=type(exc).__name__)
            return
        pinned = [row for row in events if str(row.get("kind", "") or "") == "model_plan.pinned"]
        note = dict(pinned[-1].get("note") or {}) if pinned else {}
        await self._send_ack(ws, ok=True, action="order_model_plan", order_id=order_id,
                             plan=note or None, at=str(pinned[-1].get("at", "") or "") if pinned else "")

    # ── Project Management ──────────────────────────────────────────────

    async def _handle_list_projects(self, ws: Any, data: dict) -> None:
        """List available projects by scanning the projects directory.

        S3-2A (additive): each entry also carries ``profile`` (the project's business boundary -- the four
        owner-entered texts, empty until written or while the business database is still at schema version 2) and
        ``connections_summary`` ({lane: status code} of its four software & connection lanes, computed from real
        facts only; project_connections.py). Neither can fail the list: when they cannot be computed the entries are
        sent as before.
        """
        result = await self.services.project.list(active_project_id=self._client_active_project_id(ws))
        payload = dict(result.payload)
        entries = [dict(entry) for entry in list(payload.get("projects", []) or [])]
        try:
            fields = await asyncio.to_thread(
                self._project_center_fields, [str(entry.get("id", "") or "") for entry in entries])
            for entry in entries:
                entry.update(fields.get(str(entry.get("id", "") or ""), {}))
        except Exception:
            logger.opt(exception=True).debug("project centre fields could not be added to list_projects")
        payload["projects"] = entries
        await self._send_ack(ws, ok=True, **payload)

    # ── S3-2A 项目中心: business boundary and software & connections (plugin only; nothing here runs anything) ──

    def _project_center_fields(self, project_ids: list[str]) -> dict[str, dict[str, Any]]:
        """``profile`` and ``connections_summary`` per project for the project list. Read only."""
        from ampuly.plugins.office_ui.business_store import PROJECT_PROFILE_FIELDS
        from ampuly.plugins.office_ui.project_connections import project_connections, summary

        business = self._accounts().business
        profiles = business.project_profiles()
        empty = business.empty_project_profile()
        out: dict[str, dict[str, Any]] = {}
        for project_id in project_ids:
            profile = profiles.get(project_id, empty)
            try:
                summed = summary(project_connections(project_id, self._project_connection_sources(project_id)))
            except Exception:
                logger.opt(exception=True).debug("connections summary could not be computed for {}", project_id)
                summed = {}
            out[project_id] = {
                "profile": {name: str(profile.get(name, "") or "") for name in PROJECT_PROFILE_FIELDS},
                "connections_summary": summed,
            }
        return out

    def _project_connection_sources(self, project_id: str) -> Any:
        """The real facts one project's four lanes are judged by (project_connections.gather). Read only: the
        project's folder is probed, nothing is sent or written, and no engine is built."""
        from ampuly.core import project_paths
        from ampuly.plugins.office_ui.connector_candidate import list_registrations
        from ampuly.plugins.office_ui.project_connections import gather

        context = self.services.context
        home = Path(context.ampuly_home)
        folder = context.project_workplace(project_id)
        pinned = project_paths.mapping(home).pinned(project_id)
        chosen = pinned is not None and not project_paths.product_owned(home, project_id, pinned)
        try:
            registrations = list_registrations(self._connector_candidate_roots(project_id)[1])
        except Exception:
            registrations = []
        return gather(project_id, business=self._accounts().business, folder=folder, folder_chosen=chosen,
                      duty_log=list(getattr(self, "_duty_log", []) or []), registrations=registrations)

    def _project_stage_ids(self, project_id: str) -> set[str]:
        """The stage ids of every flow this project may run (their stages.yaml), for checking a lane's stage."""
        from ampuly.plugins.office_ui.workflow_packages import visible_packages

        packages = visible_packages(self._workflow_registry(), include_testing=True, include_drafts=True, project_id=project_id)
        return {str(item.get("id", "") or "") for package in packages for item in package.stages}

    async def _project_center_members(self, data: dict, project_id: str) -> tuple[set[str], set[str]]:
        """(who may be planned as the project's manager, the customer ids that never may).

        Members: enabled owner / employee accounts -- by login and employee id, and only those whose customer scope
        covers this project's customer -- the project org's employees, and the local console owner. A customer is
        not a member, whatever else is true. Planning a manager grants nothing.
        """
        business = self._accounts().business
        project_customer = str(business.project_customer(project_id) or "")
        members: set[str] = {"owner"}
        for account in self._accounts().list_accounts():
            if getattr(account, "disabled", False) or str(getattr(account, "role", "") or "") not in ("owner", "employee"):
                continue
            scope = tuple(str(item) for item in (getattr(account, "customer_ids", ()) or ()))
            if scope and project_customer and project_customer not in scope:
                continue
            for name in (getattr(account, "login", ""), getattr(account, "employee_id", "")):
                if str(name or "").strip():
                    members.add(str(name).strip())
        try:
            run_engine, _pid = await self._engine_for_request(data)
            for employee in list(getattr(getattr(getattr(run_engine, "config", None), "org", None), "employees", []) or []):
                emp_id = str(getattr(employee, "employee_id", "") or "").strip()
                if emp_id:
                    members.add(emp_id)
        except Exception:
            logger.opt(exception=True).debug("project org employees could not be read for the manager check")
        customers = {str(row.get("customer_id", "") or "") for row in business.list_customers()}
        customers.add(project_customer)
        return members, customers - {""}

    async def _handle_project_profile_get(self, ws: Any, data: dict) -> None:
        """The project's business boundary (owner only). Empty with ``needs_migration`` while the store is behind."""
        try:
            project_id = self._request_project_id(data)
        except ProjectScopeError as exc:
            await self._send_ack(ws, ok=False, action="project_profile_get", project_id=str(data.get("project_id", "") or "").strip(), error=str(exc))
            return
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="project_profile_get", project_id=project_id, error="owner_required")
            return
        business = self._accounts().business
        ready = business.project_center_ready()
        await self._send_ack(
            ws, ok=True, action="project_profile_get", project_id=project_id,
            profile=business.project_profile(project_id) if ready else business.empty_project_profile(),
            needs_migration=not ready, why_zh="" if ready else business.project_center_not_ready_text(),
        )

    async def _handle_project_profile_set(self, ws: Any, data: dict) -> None:
        """Write the project's business boundary (owner only). Grants nothing; refuses while the store is behind."""
        from ampuly.plugins.office_ui.business_store import ProjectProfileError

        try:
            project_id = self._request_project_id(data)
        except ProjectScopeError as exc:
            await self._send_ack(ws, ok=False, action="project_profile_set", project_id=str(data.get("project_id", "") or "").strip(), error=str(exc))
            return
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="project_profile_set", project_id=project_id, error="owner_required")
            return
        business = self._accounts().business
        if not business.project_center_ready():
            await self._send_ack(ws, ok=False, action="project_profile_set", project_id=project_id,
                                 error=business.project_center_not_ready_text(), error_code="needs_migration", needs_migration=True)
            return
        manager = str(data.get("manager_employee_id", "") or "").strip()
        if manager:
            members, customers = await self._project_center_members(data, project_id)
            if manager in customers:
                await self._send_ack(ws, ok=False, action="project_profile_set", project_id=project_id,
                                     error="客户不能被规划为管理者：管理者要是这个项目里的员工或负责人。", error_code="manager_is_customer")
                return
            if manager not in members:
                await self._send_ack(ws, ok=False, action="project_profile_set", project_id=project_id,
                                     error=f"「{manager}」不是这个项目的成员：规划管理者要是这个项目里的员工或负责人（这一步不授予任何权限）。",
                                     error_code="manager_not_member")
                return
        try:
            profile = business.set_project_profile(
                project_id, start=data.get("start", ""), scope=data.get("scope", ""), end=data.get("end", ""),
                manager_employee_id=manager, actor=_ws_actor_login(self, ws),
            )
        except ProjectProfileError as exc:
            await self._send_ack(ws, ok=False, action="project_profile_set", project_id=project_id, error=str(exc))
            return
        await self._send_ack(ws, ok=True, action="project_profile_set", project_id=project_id, profile=profile, needs_migration=False)

    async def _handle_project_connections_get(self, ws: Any, data: dict) -> None:
        """The project's four software & connection lanes with their status words (owner only). Status comes from
        real facts only; the owner's plans ride along, and are empty with ``needs_migration`` while the store is
        behind."""
        from ampuly.plugins.office_ui.project_connections import project_connections, summary

        try:
            project_id = self._request_project_id(data)
        except ProjectScopeError as exc:
            await self._send_ack(ws, ok=False, action="project_connections_get", project_id=str(data.get("project_id", "") or "").strip(), error=str(exc))
            return
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="project_connections_get", project_id=project_id, error="owner_required")
            return
        sources = await asyncio.to_thread(self._project_connection_sources, project_id)
        lanes = project_connections(project_id, sources)
        await self._send_ack(
            ws, ok=True, action="project_connections_get", project_id=project_id, lanes=lanes, summary=summary(lanes),
            needs_migration=not sources.plans_ready,
            why_zh="" if sources.plans_ready else self._accounts().business.project_center_not_ready_text(),
        )

    async def _handle_project_connections_set(self, ws: Any, data: dict) -> None:
        """Write the owner's plan for one or more lanes (owner only); answers with the lanes as they now stand.
        A plan is words: it connects nothing and never makes a lane 可用."""
        from ampuly.plugins.office_ui.business_store import CONNECTION_LANE_LABELS, ProjectProfileError
        from ampuly.plugins.office_ui.project_connections import project_connections, summary

        try:
            project_id = self._request_project_id(data)
        except ProjectScopeError as exc:
            await self._send_ack(ws, ok=False, action="project_connections_set", project_id=str(data.get("project_id", "") or "").strip(), error=str(exc))
            return
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="project_connections_set", project_id=project_id, error="owner_required")
            return
        business = self._accounts().business
        if not business.project_center_ready():
            await self._send_ack(ws, ok=False, action="project_connections_set", project_id=project_id,
                                 error=business.project_center_not_ready_text(), error_code="needs_migration", needs_migration=True)
            return
        lanes_in = data.get("lanes")
        items = ([dict(item) for item in lanes_in if isinstance(item, dict)] if isinstance(lanes_in, list)
                 else [{"lane": lane, **(dict(fields) if isinstance(fields, dict) else {})} for lane, fields in lanes_in.items()]
                 if isinstance(lanes_in, dict) else [])
        known = self._project_stage_ids(project_id)
        for item in items:
            stage = str(item.get("stage", "") or "").strip()
            if stage and stage not in known:
                label = CONNECTION_LANE_LABELS.get(str(item.get("lane", "") or ""), "这条线路")
                await self._send_ack(ws, ok=False, action="project_connections_set", project_id=project_id,
                                     error=f"「{label}」要挂的阶段「{stage}」不在这个项目的业务流里。", error_code="unknown_stage")
                return
        try:
            business.set_project_connection_plans(project_id, items, actor=_ws_actor_login(self, ws))
        except ProjectProfileError as exc:
            await self._send_ack(ws, ok=False, action="project_connections_set", project_id=project_id, error=str(exc))
            return
        sources = await asyncio.to_thread(self._project_connection_sources, project_id)
        lanes = project_connections(project_id, sources)
        await self._send_ack(ws, ok=True, action="project_connections_set", project_id=project_id, lanes=lanes,
                             summary=summary(lanes), needs_migration=False)

