    async def _handle_restore_preflight(self, ws: Any, data: dict) -> None:
        """Inspect a backup off this connection's receive loop, like the restore itself: checking every byte of a
        large archive outlasts the client's heartbeat allowance, and the report would go to a dropped socket."""
        tracker = getattr(self, "_track", None)
        if callable(tracker):
            tracker(WSHandler._restore_preflight(self, ws, data))
        else:  # a stand-in without background tasks
            await WSHandler._restore_preflight(self, ws, data)

    async def _restore_preflight(self, ws: Any, data: dict) -> None:
        """Say what a restore would bring back, and what it never held.

        Read-only: it opens the archive, reads the manifest and the entry
        list, and answers. People reach for a restore when something has
        already gone wrong, which is the worst moment to find out that it will
        be refused -- or that the business record was never in there.
        """
        from ampuly.plugins.office_ui.restore_preflight import inspect_backup

        project_id = self._request_project_id(data)
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="restore_preflight", project_id=project_id, error="owner_required")
            return
        context = self.services_context
        home = Path(getattr(context, "ampuly_home", None) or Path.cwd() / ".ampuly")

        def _exists(name: str) -> list[str]:
            # the restore's own rule, not an approximation of it
            return list(self.services.project.restore_target_occupied(name))

        try:
            report = await asyncio.to_thread(
                inspect_backup,
                str(data.get("archive_path", "") or ""),
                ampuly_home=home,
                project_id=str(data.get("target_project_id", "") or ""),
                project_exists=_exists,
            )
        except Exception as exc:
            await self._send_ack(ws, ok=False, action="restore_preflight", project_id=project_id, error=str(exc))
            return
        # A destroyed project keeps its customer binding, and a restore brings the project back under it: that
        # customer's accounts see it again the moment it is restored. Said before, not discovered after.
        report["bound_customer_id"] = ""
        restored_name = str(data.get("target_project_id", "") or report.get("project_id", "") or "").strip()
        if restored_name:
            try:
                lifecycle = await self.services.project.lifecycle(restored_name, limit=1)
                report["bound_customer_id"] = str((lifecycle.payload.get("lifecycle") or {}).get("customer_id", "") or "")
            except Exception:
                report["bound_customer_id"] = ""
        await self._send_ack(ws, ok=True, action="restore_preflight", project_id=project_id, preflight=report)

    async def _handle_restore_backup(self, ws: Any, data: dict) -> None:
        """Restore a backup without parking this connection's receive loop.

        One connection's messages are handled in order, and the heartbeat is one of them. Awaited here, a restore that
        took longer than the client's heartbeat allowance made the page drop its connection mid-restore: the receipt
        went to a dead socket and the owner was told "no receipt" for a restore that had succeeded.
        """
        actor = self._project_actor(ws)

        async def _restore() -> None:
            try:
                result = await self.services.project.restore_backup(
                    data.get("archive_path", ""), project_id=data.get("project_id"), actor=actor,
                )
                await self._publish_service_result(result)
                await self._send_ack(ws, ok=True, **result.payload)
            except ServiceError as exc:
                await self._send_service_error(ws, exc, action="restore_backup")
            except Exception as exc:  # noqa: BLE001 - outside the router's own net now: always answer
                logger.opt(exception=True).warning("restore_backup failed")
                await self._send_ack(ws, ok=False, action="restore_backup", error=str(exc) or type(exc).__name__)

        tracker = getattr(self, "_track", None)
        if callable(tracker):
            tracker(_restore())
        else:  # a stand-in without background tasks
            await _restore()

