    async def _handle_session_list(self, ws: Any, data: dict) -> None:
        """List a project's sessions for the CLI, from this console's engine.

        Read-only CLI commands used to build a second engine per invocation
        (loading skills, probing Providers, rehydrating message queues) while
        the console was live -- slow, and a second writer against the same
        store.  Serving the listing here keeps one engine per machine.
        """
        project_id = self._request_project_id(data)
        try:
            limit = max(1, min(500, int(data.get("limit", 50) or 50)))
        except (TypeError, ValueError):
            limit = 50
        try:
            result = await self._ensure_office_services().session.list(project_id=project_id, limit=limit)
        except ServiceError as exc:
            await self._send_service_error(ws, exc, action="session_list")
            return
        await self._send_ack(ws, ok=True, action="session_list", **result.payload)

