    async def _handle_project_order_overview(self, ws: Any, data: dict) -> None:
        """Where every visible project's orders stand, for the project centre's all-projects level.

        A cross-project read has no single customer to narrow to, so an account bound to customers is refused
        rather than shown part of the picture.  One observation is recorded per call (under the project the
        console is on), not one per project read; what was read is in its metadata.
        """
        from ampuly.plugins.office_ui.project_overview import project_order_overview_judged

        home_project = self._request_project_id(data) if hasattr(self, "_request_project_id") else str(data.get("project_id", "") or "default")
        home_project = str(home_project or "default")
        me = self._client_accounts.get(ws) if hasattr(self, "_client_accounts") else None
        actor = str(getattr(me, "login", "") or "anonymous")
        allowed_customers = ws_customer_scope(self, ws)
        api = self._console_api()
        if allowed_customers:
            api.record_observation(
                project_id=home_project, actor=actor, action="project_order_overview",
                object_type="work_order_collection", object_id="*", reason="console_project_overview",
                outcome="denied", metadata={"account_customer_scope": list(allowed_customers)},
            )
            await self._send_ack(ws, ok=False, action="project_order_overview", error="customer_scope_denied",
                                 allowed_customers=list(allowed_customers))
            return
        try:
            listed = await self._ensure_office_services().project.list(active_project_id=None)
        except ServiceError as exc:
            await self._send_service_error(ws, exc, action="project_order_overview")
            return
        visible = visible_projects_for_scope(self, ws, list(dict(listed.payload).get("projects") or []))
        project_ids = [str(entry.get("id", "") or entry.get("project_id", "") or "") for entry in visible]
        # S0-A: each project's facts carry the judgement (who each order waits on) and its standing (the four numbers),
        # counted on the server from the same verdicts; ``partial_projects`` names the projects whose pauses or
        # budgets could not be read.  Their engines are never loaded for it (``_pending_checkpoints_for_attention``).
        overview = await project_order_overview_judged(
            api, project_ids, judge=lambda project_id, rows: WSHandler._judge_order_attention(self, project_id, rows),
        )
        api.record_observation(
            project_id=home_project, actor=actor, action="project_order_overview",
            object_type="work_order_collection", object_id="*", reason="console_project_overview",
            outcome="success", metadata={"projects": sorted(overview["projects"])},
        )
        await self._send_ack(ws, ok=True, action="project_order_overview", **overview)

