    async def _handle_order_timeline(self, ws: Any, data: dict) -> None:
        """One order's business record and the runtime that ran it, merged.

        Answering "what happened to this order" used to mean joining two
        databases by hand: the signed business events live in business.db,
        the work-item events in the engine store.
        """
        from ampuly.plugins.office_ui.order_timeline import build_order_timeline

        project_id = self._request_project_id(data)
        order_id = str(data.get("order_id", "") or "").strip()
        actor = _ws_actor_login(self, ws)
        order = self._console_api().order(order_id, project_id=project_id)
        allowed = ws_customer_scope(self, ws)
        order_customer = str((order or {}).get("customer_id", "") or "").strip()
        denied = bool(order is not None and allowed and order_customer not in allowed)
        self._console_api().record_observation(
            project_id=project_id, actor=actor, action="order_timeline",
            object_type="work_order", object_id=order_id, customer_id=order_customer,
            reason=str(data.get("reason", "") or "console_order_timeline"),
            outcome="denied" if denied else ("success" if order is not None else "not_found"),
        )
        if denied:
            await self._send_ack(ws, ok=False, action="order_timeline", project_id=project_id, order_id=order_id, error="customer_scope_denied")
            return
        if order is None:
            await self._send_ack(ws, ok=False, action="order_timeline", project_id=project_id, order_id=order_id, error="order_not_found")
            return
        run_engine, _pid = await self._engine_for_request(data)
        timeline = await build_order_timeline(
            business=self._accounts().business,
            store=getattr(run_engine, "store", None),
            order=order,
        )
        # The registered console extensions add their own fields (extensions.py: order_timeline_extra), never one the
        # timeline already carries; one that fails adds nothing.
        from ampuly.plugins.office_ui import extensions as _extensions

        added = await _extensions.order_timeline_extra(self._extension_host(), ws, order)
        extra = {key: value for key, value in added.items() if key not in timeline and key not in {"ok", "action", "project_id"}}
        await self._send_ack(ws, ok=True, action="order_timeline", project_id=project_id, **timeline, **extra)

    async def _handle_project_set_customer(self, ws: Any, data: dict) -> None:
        """Bind a project to the customer whose delivery space it is (owner only)."""
        from ampuly.plugins.office_ui.business_store import OrderTransitionError

        project_id = str(data.get("project_id", "") or "").strip()
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="project_set_customer", project_id=project_id, error="owner_required")
            return
        try:
            record = self._accounts().business.set_project_customer(
                project_id, str(data.get("customer_id", "") or ""), actor=_ws_actor_login(self, ws),
            )
        except OrderTransitionError as exc:
            await self._send_ack(ws, ok=False, action="project_set_customer", project_id=project_id, error=str(exc))
            return
        await self._send_ack(
            ws, ok=True, action="project_set_customer", project_id=project_id,
            customer_id=record.customer_id, lifecycle=record.to_payload(),
        )

    # ── what is running where, and what is being moved ──

    def _visible_deployments(self, ws: Any) -> list[dict[str, Any]]:
        allowed = ws_customer_scope(self, ws)
        return self._accounts().business.list_deployments(customer_ids=allowed)

    def _visible_rollouts(self, ws: Any) -> list[dict[str, Any]]:
        """Rollouts this socket may see, whole or not at all.

        A rollout is one decision across several targets. Handing over a
        filtered copy would let an account read "this rollout succeeded" from
        the half it can see, so a rollout touching a customer outside the
        account's binding is not shown at all.
        """
        from ampuly.plugins.office_ui.business_store import ROLLOUT_LIST_LIMIT

        allowed = set(ws_customer_scope(self, ws))
        # The newest ROLLOUT_LIST_LIMIT only; the handlers that send this list say so (``rollouts_has_more``).
        rollouts = self._accounts().business.list_rollouts(limit=ROLLOUT_LIST_LIMIT)
        if not allowed:
            return rollouts
        return [
            record for record in rollouts
            if all(str(t.get("customer_id", "") or "") in allowed for t in record.get("targets", []))
        ]

    async def _handle_deployment_list(self, ws: Any, data: dict) -> None:
        """Which customer, on which environment, is running which version."""
        from ampuly.plugins.office_ui.business_store import ROLLOUT_LIST_LIMIT

        project_id = self._request_project_id(data)
        business = self._accounts().business
        await self._send_ack(
            ws, ok=True, action="deployment_list", project_id=project_id,
            deployments=self._visible_deployments(ws),
            packages=business.list_solution_packages(),
            rollouts=self._visible_rollouts(ws),
            # The list is the newest ROLLOUT_LIST_LIMIT; true = older ones exist that it does not show.
            rollouts_has_more=business.count_rollouts() > ROLLOUT_LIST_LIMIT,
        )

    async def _rollout_ack(self, ws: Any, action: str, data: dict, work) -> None:
        """Every rollout action answers with the whole rollout, or with why not.

        A partial ack would leave the page guessing which target moved; the
        record is small and it is the thing the operator is looking at.
        """
        from ampuly.plugins.office_ui.business_store import OrderTransitionError

        project_id = self._request_project_id(data)
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action=action, project_id=project_id, error="owner_required")
            return
        rollout_id = str(data.get("rollout_id", "") or "").strip()
        try:
            record = work(self._accounts().business, _ws_actor_login(self, ws))
        except (OrderTransitionError, TypeError, ValueError) as exc:
            await self._send_ack(
                ws, ok=False, action=action, project_id=project_id, rollout_id=rollout_id, error=str(exc)
            )
            return
        await self._send_ack(
            ws, ok=True, action=action, project_id=project_id,
            rollout_id=str(record.get("rollout_id", "") or rollout_id), rollout=record,
            deployments=self._visible_deployments(ws),
        )

