    def _credential_rows(self, ws: Any) -> list[dict[str, Any]]:
        """References this socket may see, each with whether its variable is set.

        Only the *name* and its presence: there is nowhere in this payload for
        a value to live, which is the point.
        """
        import os

        business = self._accounts().business
        rows = business.list_credential_references(customer_ids=ws_customer_scope(self, ws))
        out: list[dict[str, Any]] = []
        for row in rows:
            env_var = str(row.get("env_var", "") or "")
            out.append({
                "reference_id": row.get("reference_id", ""),
                "purpose": row.get("purpose", ""),
                "customer_id": row.get("customer_id", ""),
                "environment_id": row.get("environment_id", ""),
                "env_var": env_var,
                "is_set": bool(str(os.environ.get(env_var, "") or "").strip()),
                "note": row.get("note", ""),
            })
        return out

    async def _handle_credential_reference_list(self, ws: Any, data: dict) -> None:
        project_id = self._request_project_id(data)
        await self._send_ack(
            ws, ok=True, action="credential_reference_list", project_id=project_id,
            references=self._credential_rows(ws),
        )

