    async def _handle_run_budget_list(self, ws: Any, data: dict) -> None:
        """What each run may still spend, narrowed to the customers this socket sees."""
        project_id = self._request_project_id(data)
        business = self._accounts().business
        budgets = business.list_run_budgets(customer_ids=ws_customer_scope(self, ws))
        # The calls nobody knows the outcome of, for the budgets this socket sees. The page has had the buttons to settle
        # one since the resolve route existed and was never sent the list, so a held budget was a dead end.
        pending = business.unknown_reservations(budget_ids=[str(item.get("budget_id", "") or "") for item in budgets])
        # Why a budget is held, in the owner's words; the stored text stays beside it (P-c).
        await self._send_ack(ws, ok=True, action="run_budget_list", project_id=project_id, budgets=_budgets_for_owner(budgets),
                             pending_reservations=pending)

    async def _handle_run_compare(self, ws: Any, data: dict) -> None:
        """Why this run and that run were not the same.

        "It worked last time" is the most common report and the least
        actionable. Each launch pins what it ran, so this answers from the
        record instead of from memory -- and says outright when a run has no
        record, rather than reporting silence as agreement.
        """
        from ampuly.plugins.office_ui.run_diff import compare_runs

        # The runs of the project that was asked about. The console's own engine is whichever project was opened
        # last: read from its store, two runs of another project came back as "no record" -- and this route exists to
        # say outright when a run has no record, so that answer has to be true.
        try:
            engine, project_id = await self._engine_for_request(data)
        except Exception:
            logger.opt(exception=True).warning("run compare: the engine of the requested project could not be reached")
            engine, project_id = None, self._request_project_id(data)
        store = getattr(engine, "store", None)
        first = str(data.get("task_id", "") or "").strip()
        second = str(data.get("other_task_id", "") or "").strip()
        if not first or not second:
            await self._send_ack(ws, ok=False, action="run_compare", project_id=project_id, error="two runs are required")
            return
        if store is None or not self._store_is_ready(store):
            await self._send_ack(ws, ok=False, action="run_compare", project_id=project_id, error="runtime_unavailable")
            return
        tasks = []
        for task_id in (first, second):
            try:
                tasks.append(await store.get_task(task_id))
            except Exception:
                tasks.append(None)
        comparison = compare_runs(
            tasks[0] or {}, tasks[1] or {}, before_label=first[:8], after_label=second[:8],
        )
        await self._send_ack(
            ws, ok=True, action="run_compare", project_id=project_id,
            task_id=first, other_task_id=second, comparison=comparison.to_payload(),
        )

    async def _handle_order_metrics(self, ws: Any, data: dict) -> None:
        """What each order cost, saved and promised -- or which of those is unknown.

        Read-only and derived: nothing here is stored, so an order whose
        baseline arrives tomorrow answers differently tomorrow, which is the
        behaviour you want from a number that depends on evidence.
        """
        from ampuly.plugins.office_ui.business_store import ORDER_LIST_HARD_CAP

        project_id = self._request_project_id(data)
        business = self._accounts().business
        allowed = set(ws_customer_scope(self, ws))
        wanted = str(data.get("order_id", "") or "").strip()
        if wanted:
            # One order, by id: older than any list window, it still answers.
            one = business.get_order(wanted, project_id=project_id)
            orders = [one] if one is not None else []
            truncated = False
        else:
            # The store caps a list. The page is told when the cap cut something off, instead of a whole-looking list
            # that stopped at the newest 200 (B3).
            orders = business.list_orders(project_id=project_id, limit=ORDER_LIST_HARD_CAP)
            truncated = business.count_orders(project_id=project_id) > len(orders)
        metrics: list[dict[str, Any]] = []
        for order in orders:
            if wanted and order.order_id != wanted:
                continue
            if allowed and str(order.customer_id or "") not in allowed:
                continue
            try:
                metrics.append(business.order_metrics(order.order_id))
            except Exception:
                # One unreadable order must not blank the whole page; it is
                # simply absent, and the rest still answer.
                logger.opt(exception=True).debug("could not compute metrics for order {}", order.order_id)
        usage = await WSHandler._usage_by_purpose(self, data, project_id=project_id, order_ids=[str(item.get("order_id", "") or "") for item in metrics],
                                                  whole_project=not allowed and not wanted)
        await self._send_ack(ws, ok=True, action="order_metrics", project_id=project_id, metrics=metrics, usage_by_purpose=usage,
                             truncated=truncated)

    async def _usage_by_purpose(self, data: dict, *, project_id: str, order_ids: list[str], whole_project: bool) -> dict[str, Any] | None:
        """What the model calls were for -- work, or judging work -- for the orders this socket may see.

        Read from the rows that already exist (usage_by_purpose.py). ``None`` when it cannot be read: the page then
        shows nothing rather than a table of zeros. The project-wide total is given only to a socket that sees every
        customer; a bound account gets its own orders' figures and no total it could subtract from.
        """
        from ampuly.plugins.office_ui.usage_by_purpose import summarize

        try:
            engine, _pid = await self._engine_for_request(data)
            store = getattr(engine, "store", None)
            cost_by_task = await store.get_cost_by_task(project_id)
            tasks = await store.get_tasks(project_id=project_id)
        except Exception:
            logger.opt(exception=True).debug("usage by purpose could not be read for project {}", project_id)
            return None
        return {
            "project": summarize(cost_by_task, tasks) if whole_project else None,
            "orders": [summarize(cost_by_task, tasks, order_id=order_id) for order_id in order_ids if order_id],
        }

    async def _handle_run_budget_create(self, ws: Any, data: dict) -> None:
        """Give one order an allowance (owner only)."""
        from ampuly.plugins.office_ui.business_store import OrderTransitionError

        project_id = self._request_project_id(data)
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="run_budget_create", project_id=project_id, error="owner_required")
            return
        limits = {k: v for k, v in dict(data.get("limits", {}) or {}).items()}
        order_id = str(data.get("order_id", "") or "").strip()
        business = self._accounts().business
        try:
            # The ceiling is what the owner typed; say what is wrong with it before anything about the order. An order's
            # allowance has to be one its run can be held to; a budget that belongs to no order keeps the general rule.
            (business.clean_order_allowance if order_id else business.clean_budget_limits)(limits)
        except OrderTransitionError as exc:
            await self._send_ack(ws, ok=False, action="run_budget_create", project_id=project_id, **_budget_refusal(exc))
            return
        if order_id:
            # Under the launch lock: the grant lands either before the launch, which then pins it, or after the launch
            # has named its run, which is pinned here. Between the two a grant would bind to nothing.
            async with self._console_api()._launch_dispatch_lock:
                await WSHandler._grant_run_budget(self, ws, data, project_id=project_id, order_id=order_id, limits=limits)
            return
        await WSHandler._grant_run_budget(self, ws, data, project_id=project_id, order_id="", limits=limits)

    async def _grant_run_budget(self, ws: Any, data: dict, *, project_id: str, order_id: str, limits: dict) -> None:
        from ampuly.plugins.office_ui.business_store import OrderTransitionError

        business = self._accounts().business
        customer_id = str(data.get("customer_id", "") or "").strip()
        environment_id = str(data.get("environment_id", "") or "").strip()
        order = None
        if order_id:
            # An allowance for an order is the order's: its customer and environment are read from the order, never
            # typed in beside it -- the spend guard refuses a budget whose scope differs from the task's.
            order = business.get_order(order_id, project_id=project_id)
            if order is None:
                await self._send_ack(ws, ok=False, action="run_budget_create", project_id=project_id, order_id=order_id,
                                     **_budget_refusal("order_not_found"))
                return
            for given, recorded, name in ((customer_id, order.customer_id, "customer"), (environment_id, order.environment_id, "environment")):
                if given and given != str(recorded or ""):
                    await self._send_ack(ws, ok=False, action="run_budget_create", project_id=project_id, order_id=order_id,
                                         **_budget_refusal(f"budget_{name}_differs_from_the_order"))
                    return
            customer_id, environment_id = str(order.customer_id or ""), str(order.environment_id or "")
            existing = business.open_budget_for_order(order_id, project_id=project_id)
            if existing is not None and not dict(existing.get("limits") or {}):
                run_budget = await WSHandler._run_task_budget_id(self, data, order)
                if run_budget and run_budget != str(existing["budget_id"]):
                    # The run spends from another budget (review R5): this allowance holds nothing. It is closed, and the
                    # grant takes the path that puts the run on a budget it really spends from.
                    business.close_run_budget(str(existing["budget_id"]), actor=_ws_actor_login(self, ws),
                                              reason="held nothing: the run spends from another budget")
                    existing = None
            if existing is not None and not dict(existing.get("limits") or {}):
                # Every launched order holds an allowance without ceilings (model-routing phase 0, C12). Granting one sets
                # its ceilings in place: the same budget id is already on every task of the run, so nothing is re-pinned.
                try:
                    budget = business.set_run_budget_ceilings(str(existing["budget_id"]), limits=limits,
                                                              actor=_ws_actor_login(self, ws), reason="ceilings set by the owner")
                except OrderTransitionError as exc:
                    await self._send_ack(ws, ok=False, action="run_budget_create", project_id=project_id, order_id=order_id,
                                         **_budget_refusal(exc))
                    return
                await self._send_ack(
                    ws, ok=True, action="run_budget_create", project_id=project_id, order_id=order_id, budget=_budget_for_owner(budget),
                    run_started=bool(str(getattr(order, "launched_task_id", "") or "").strip()), in_place=True,
                    bound_to_run=bool(str(getattr(order, "launched_task_id", "") or "").strip()), bound_tasks=0, unreached_tasks=[],
                )
                return
            if existing is not None:
                await self._send_ack(ws, ok=False, action="run_budget_create", project_id=project_id, order_id=order_id,
                                     **_budget_refusal("order_already_has_an_open_budget"))
                return
            if str(order.status or "") == "launching":
                # The run is being started this very moment: its task has been pinned without an allowance and the order
                # does not name it yet, so a grant now could be bound to nothing.
                await self._send_ack(ws, ok=False, action="run_budget_create", project_id=project_id, order_id=order_id,
                                     **_budget_refusal("the order is being launched right now; grant the allowance in a moment"))
                return
        try:
            budget = business.create_run_budget(
                project_id=project_id, customer_id=customer_id, environment_id=environment_id, order_id=order_id,
                limits=limits, actor=_ws_actor_login(self, ws),
            )
        except OrderTransitionError as exc:
            await self._send_ack(ws, ok=False, action="run_budget_create", project_id=project_id, **_budget_refusal(exc))
            return
        bound_tasks, run_reached = 0, False
        unreached_tasks: list[str] = []
        if order is not None and str(getattr(order, "launched_task_id", "") or "").strip():
            # The order is already running: the run's own task and every task working under it take the allowance
            # now; the ones made later copy it from the root work item. A grant that cannot be bound is taken back --
            # an open budget that holds nothing is the very thing this route must never leave behind.
            from ampuly.layer4_tools.spend_guard import stamp_order_allowance, stamp_shared_allowance

            from ampuly.layer4_tools.spend_guard import is_order_allowance

            closed = tuple(business.closed_budget_ids_for_order(order_id))
            # Automatic allowances of child orders that gave way to this one (review R5): closed once the run is reached.
            gave_way: set[str] = set()

            def _gives_way(metadata: dict) -> tuple[str, ...]:
                """This order's earlier allowances -- and an order allowance that is no longer open, whoever's it was.

                A child order spends from the allowance of the order that started it. When that order ends, its
                allowance closes and stays on the child's tasks, refusing every paid call; the closed budget is not
                one of the child's own, so without this the child could never be given an allowance of its own.
                """
                carried = str(metadata.get("budget_id", "") or "").strip()
                if carried and carried not in closed and is_order_allowance(metadata):
                    record = business.run_budget(carried)
                    if record is not None and str(record.get("lifecycle", "") or "") != "open":
                        return (*closed, carried)
                    if (record is not None and not dict(record.get("limits") or {})
                            and str(record.get("order_id", "") or "") not in {"", order_id}):
                        # A child order that started while nothing above it was held opened an allowance of its own,
                        # without a ceiling (C12). A ceiling granted to this order now holds the child too.
                        gave_way.add(carried)
                        return (*closed, carried)
                return closed

            def _stamp(metadata: dict) -> tuple[dict, bool]:
                return stamp_order_allowance(
                    metadata, budget_id=str(budget["budget_id"]), ampuly_home=str(Path(business.path).parent), order_id=order_id,
                    customer_id=customer_id, environment_id=environment_id, replace=_gives_way(metadata),
                )

            def _stamp_child(metadata: dict) -> tuple[dict, bool]:
                # a child order this run started: it keeps its own order and spends from this allowance
                return stamp_shared_allowance(
                    metadata, budget_id=str(budget["budget_id"]), ampuly_home=str(Path(business.path).parent),
                    answers_to=order_id, order_allowance=True, customer_id=customer_id, environment_id=environment_id,
                    replace=_gives_way(metadata),
                )

            run_metadata: dict[str, Any] | None = None
            try:
                bound_tasks, run_metadata, unreached_tasks = await WSHandler._restamp_order_run(
                    self, data, order, project_id=project_id, stamp=_stamp, child_stamp=_stamp_child,
                )
            except (Exception, CompanyRunControllerLeaseLost):
                # A refused write under a run lease is a CancelledError by class: unnamed, it skipped this handler and
                # the "take the grant back" below, leaving an open allowance bound to nothing.
                logger.opt(exception=True).warning("budget {} could not be pinned to the run of order {}", budget.get("budget_id"), order_id)
            run_reached = run_metadata is not None and str(run_metadata.get("budget_id", "") or "") == str(budget["budget_id"])
            if run_reached and not unreached_tasks:
                for given in sorted(gave_way):
                    # Left open it would be the allowance the child's own row shows and a ceiling set there would land
                    # on, while the child spends from this one (review R5).
                    try:
                        business.close_run_budget(given, actor=_ws_actor_login(self, ws), reason=f"gave way to the allowance of order {order_id}")
                    except OrderTransitionError:
                        logger.opt(exception=True).warning("the allowance {} that gave way could not be closed", given)
            if not run_reached:
                # Unreachable, or already spending from a budget that is not this order's: either way this allowance
                # would hold nothing, so it is taken back rather than left looking like governance.
                business.close_run_budget(str(budget["budget_id"]), actor=_ws_actor_login(self, ws), reason="could not be bound to the running order")
                from ampuly.layer4_tools.spend_guard import budget_order_id

                holder = budget_order_id(run_metadata) if run_metadata is not None else ""
                await self._send_ack(
                    ws, ok=False, action="run_budget_create", project_id=project_id, order_id=order_id,
                    **_budget_refusal((f"this order was started by order {holder} and spends from that order's allowance; "
                                       "no second allowance was left behind" if holder and holder != order_id else
                                       "the running order already spends from another budget; no second allowance was left behind")
                                      if run_metadata is not None else
                                      "the running order could not be reached, so no allowance was left behind; try again"),
                )
                return
        await self._send_ack(
            ws, ok=True, action="run_budget_create", project_id=project_id, order_id=order_id, budget=_budget_for_owner(budget),
            run_started=bool(order is not None and str(getattr(order, "launched_task_id", "") or "").strip()),
            bound_to_run=run_reached, bound_tasks=bound_tasks, unreached_tasks=unreached_tasks,
        )

    async def _handle_run_budget_close(self, ws: Any, data: dict) -> None:
        """Take an order's ceilings away (owner only): the way out when a ceiling is reached, or was set wrong.

        A running order is never left unheld (model-routing phase 0, C12): its allowance is lifted in place -- the
        ceilings go, the budget stays, every paid call is still journaled and an unknown outcome still holds the order.
        An order that is not running has its allowance closed as before (what was only held goes back; what may have
        been spent stays for a person to settle) and its tasks stop carrying it; its launch opens a new one.
        """
        from ampuly.plugins.office_ui.business_store import OrderTransitionError

        project_id = self._request_project_id(data)
        order_id = str(data.get("order_id", "") or "").strip()
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="run_budget_close", project_id=project_id, order_id=order_id, error="owner_required")
            return
        business = self._accounts().business
        order = business.get_order(order_id, project_id=project_id) if order_id else None
        allowance = business.open_budget_for_order(order_id, project_id=project_id) if order is not None else None
        if order is None or allowance is None:
            await self._send_ack(ws, ok=False, action="run_budget_close", project_id=project_id, order_id=order_id,
                                 **_budget_refusal("order_not_found" if order is None else "order_has_no_open_budget"))
            return
        reason = str(data.get("reason", "") or "").strip()
        if len(reason) < 2:
            await self._send_ack(ws, ok=False, action="run_budget_close", project_id=project_id, order_id=order_id,
                                 **_budget_refusal("reason_required"))
            return
        if str(getattr(order, "launched_task_id", "") or "").strip() and str(order.status or "") not in {"closed", "rejected"}:
            try:
                lifted = business.set_run_budget_ceilings(str(allowance["budget_id"]), limits={}, actor=_ws_actor_login(self, ws), reason=reason)
            except OrderTransitionError as exc:
                await self._send_ack(ws, ok=False, action="run_budget_close", project_id=project_id, order_id=order_id, **_budget_refusal(exc))
                return
            await self._send_ack(
                ws, ok=True, action="run_budget_close", project_id=project_id, order_id=order_id, budget=_budget_for_owner(lifted), lifted=True,
                released_tasks=0, budgets=_budgets_for_owner(business.list_run_budgets(project_id=project_id, customer_ids=ws_customer_scope(self, ws))),
            )
            return
        try:
            closed = business.close_run_budget(str(allowance["budget_id"]), actor=_ws_actor_login(self, ws), reason=reason)
        except OrderTransitionError as exc:
            await self._send_ack(ws, ok=False, action="run_budget_close", project_id=project_id, order_id=order_id, **_budget_refusal(exc))
            return
        from ampuly.layer4_tools.spend_guard import clear_order_allowance

        released_tasks = 0
        try:
            _release = lambda metadata: clear_order_allowance(metadata, (str(allowance["budget_id"]),))  # noqa: E731
            released_tasks, _run_metadata, _unreached = await WSHandler._restamp_order_run(
                self, data, order, project_id=project_id, stamp=_release, child_stamp=_release,
            )
        except (Exception, CompanyRunControllerLeaseLost):
            logger.opt(exception=True).warning("budget {} was closed but the tasks of order {} could not be released from it", allowance.get("budget_id"), order_id)
        await self._send_ack(
            ws, ok=True, action="run_budget_close", project_id=project_id, order_id=order_id, budget=_budget_for_owner(closed),
            released_tasks=released_tasks,
            budgets=_budgets_for_owner(business.list_run_budgets(project_id=project_id, customer_ids=ws_customer_scope(self, ws))),
        )

    async def _handle_run_budget_raise(self, ws: Any, data: dict) -> None:
        """Raise the ceilings of an order's open allowance in place (owner only).

        The way to give a running order more room: the budget id does not change, so no task has to be restamped, no
        harness session is dropped, and the order is never without a ceiling in between.
        """
        from ampuly.plugins.office_ui.business_store import OrderTransitionError

        project_id = self._request_project_id(data)
        order_id = str(data.get("order_id", "") or "").strip()
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="run_budget_raise", project_id=project_id, order_id=order_id, error="owner_required")
            return
        business = self._accounts().business
        allowance = business.open_budget_for_order(order_id, project_id=project_id) if order_id else None
        if allowance is None:
            await self._send_ack(ws, ok=False, action="run_budget_raise", project_id=project_id, order_id=order_id,
                                 **_budget_refusal("order_has_no_open_budget"))
            return
        try:
            budget = business.raise_run_budget(
                str(allowance["budget_id"]), limits=data.get("limits") if isinstance(data.get("limits"), dict) else {},
                actor=_ws_actor_login(self, ws), reason=str(data.get("reason", "") or ""),
            )
        except (OrderTransitionError, TypeError, ValueError) as exc:
            await self._send_ack(ws, ok=False, action="run_budget_raise", project_id=project_id, order_id=order_id, **_budget_refusal(exc))
            return
        await self._send_ack(
            ws, ok=True, action="run_budget_raise", project_id=project_id, order_id=order_id, budget=_budget_for_owner(budget),
            budgets=_budgets_for_owner(business.list_run_budgets(customer_ids=ws_customer_scope(self, ws))),
        )

    async def _handle_run_budget_resolve(self, ws: Any, data: dict) -> None:
        """Say what happened to a call whose outcome nobody knows (owner only).

        This is the only door out of ``pending_verification``: the machine
        cannot decide, because deciding wrong either bills twice or hides a
        charge that already happened.
        """
        from ampuly.plugins.office_ui.business_store import OrderTransitionError

        project_id = self._request_project_id(data)
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="run_budget_resolve", project_id=project_id, error="owner_required")
            return
        reservation_id = str(data.get("reservation_id", "") or "")
        happened = data.get("happened")
        actual = data.get("actual")
        try:
            if type(happened) is not bool:
                raise OrderTransitionError("请明确选择这次调用是否已经发生。")
            if type(actual) is bool:
                raise OrderTransitionError("实际金额不能是真/假值。")
            reservation = self._accounts().business.resolve_unknown_reservation(
                reservation_id,
                happened=happened,
                actual=float(actual) if actual is not None else None,
                actor=_ws_actor_login(self, ws),
            )
        except (OrderTransitionError, TypeError, ValueError) as exc:
            await self._send_ack(ws, ok=False, action="run_budget_resolve", project_id=project_id, reservation_id=reservation_id,
                                 **_budget_refusal(exc))
            return
        await self._send_ack(
            ws, ok=True, action="run_budget_resolve", project_id=project_id,
            reservation=reservation, budgets=_budgets_for_owner(self._accounts().business.list_run_budgets(customer_ids=ws_customer_scope(self, ws))),
        )

    async def _handle_solution_blueprint_list(self, ws: Any, data: dict) -> None:
        """Reusable FDE plans, narrowed to the customers this socket may see."""
        project_id = self._request_project_id(data)
        business = self._accounts().business
        blueprints = business.list_solution_blueprints(customer_ids=ws_customer_scope(self, ws))
        await self._send_ack(ws, ok=True, action="solution_blueprint_list", project_id=project_id, blueprints=blueprints)

    def _order_workflow_version(self, order_id: str, project_id: str) -> str:
        """The version of the workflow package an order belongs to, or ''.

        A plan is written against a process. Recording which version it was
        proved on is what lets the console warn that the process has moved on
        since -- silence there would present an old plan as current.
        """
        try:
            order = self._accounts().business.get_order(str(order_id or ""), project_id=project_id)
            if order is None:
                return ""
            package = self._console_api().package(str(getattr(order, "workflow_id", "") or ""))
            return str((package.manifest.get("version", "") if package else "") or "")
        except Exception:
            return ""

    async def _handle_solution_blueprint_save(self, ws: Any, data: dict) -> None:
        """Save one order's authored FDE plan as a reusable blueprint (owner only)."""
        from ampuly.plugins.office_ui.business_store import OrderTransitionError

        project_id = self._request_project_id(data)
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="solution_blueprint_save", project_id=project_id, error="owner_required")
            return
        try:
            blueprint = self._accounts().business.save_solution_blueprint(
                str(data.get("order_id", "") or ""),
                name=str(data.get("name", "") or ""),
                actor=_ws_actor_login(self, ws),
                note=str(data.get("note", "") or ""),
                workflow_version=self._order_workflow_version(str(data.get("order_id", "") or ""), project_id),
                project_id=project_id,
            )
        except OrderTransitionError as exc:
            await self._send_ack(ws, ok=False, action="solution_blueprint_save", project_id=project_id, error=str(exc))
            return
        await self._send_ack(ws, ok=True, action="solution_blueprint_save", project_id=project_id, blueprint=blueprint)

    async def _handle_solution_blueprint_apply(self, ws: Any, data: dict) -> None:
        """Copy a blueprint's plan onto another order (owner only)."""
        from ampuly.plugins.office_ui.business_store import OrderTransitionError

        project_id = self._request_project_id(data)
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="solution_blueprint_apply", project_id=project_id, error="owner_required")
            return
        order_id = str(data.get("order_id", "") or "")
        try:
            target_version = self._order_workflow_version(order_id, project_id)
            order = self._accounts().business.apply_solution_blueprint(
                str(data.get("blueprint_id", "") or ""),
                order_id,
                actor=_ws_actor_login(self, ws),
                target_workflow_version=target_version,
                project_id=project_id,
            )
        except OrderTransitionError as exc:
            await self._send_ack(ws, ok=False, action="solution_blueprint_apply", project_id=project_id, order_id=order_id, error=str(exc))
            return
        blueprint = self._accounts().business.solution_blueprint(str(data.get("blueprint_id", "") or "")) or {}
        source_version = str(blueprint.get("workflow_version", "") or "")
        await self._send_ack(
            ws, ok=True, action="solution_blueprint_apply", project_id=project_id, order=order.to_payload(),
            workflow_version=source_version, target_workflow_version=target_version,
            workflow_version_changed=bool(source_version and target_version and source_version != target_version),
        )

    async def _handle_channel_config_check(self, ws: Any, data: dict) -> None:
        """Check the channel credentials' shape without sending anything.

        The control plane could show which fields were filled in, not whether
        they were filled in correctly. A chat id in the open_id box or a value
        that carried its quotes in from a shell costs one failed send to
        discover -- in front of a customer. This reads the process
        environment, reports shape only, never a value, and touches no
        network.
        """
        from ampuly.plugins.office_ui.notifier import channel_config_check

        project_id = self._request_project_id(data)
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="channel_config_check", project_id=project_id, error="owner_required")
            return
        await self._send_ack(ws, ok=True, action="channel_config_check", project_id=project_id, **channel_config_check())

    async def _handle_capability_reprobe(self, ws: Any, data: dict) -> None:
        """Re-run external Provider detection and return the refreshed control plane.

        The control plane was read-only, so a Provider installed after the
        console started stayed "unavailable" until a restart.  Detection only
        asks each adapter whether its binary answers, so this is the one
        operation the page can offer without any side effect.
        """
        project_id = self._request_project_id(data)
        if not _ws_is_owner(self, ws):
            await self._send_ack(ws, ok=False, action="capability_reprobe", project_id=project_id, error="owner_required")
            return
        registry = getattr(self.engine, "adapter_registry", None)
        initialize = getattr(registry, "initialize", None)
        if not callable(initialize):
            await self._send_ack(ws, ok=False, action="capability_reprobe", project_id=project_id, error="adapter_registry_unavailable")
            return
        try:
            await initialize()
        except Exception as exc:
            logger.opt(exception=True).warning("capability reprobe failed")
            await self._send_ack(ws, ok=False, action="capability_reprobe", project_id=project_id, error=f"reprobe_failed: {type(exc).__name__}")
            return
        result = await self._ensure_office_services().org.info()
        await ws.send_json({"type": "org_info", "payload": result.payload})
        profiles = list(result.payload.get("external_agent_profiles", []) or [])
        await self._send_ack(
            ws,
            ok=True,
            action="capability_reprobe",
            project_id=project_id,
            probed=len(profiles),
            available=sum(1 for p in profiles if p.get("available") is True),
        )

