    # Handler routing table
    async def _handle_employee_asset(self, ws: Any, data: dict) -> None:
        from ampuly.plugins.office_ui.ai_employee_ws import dispatch_owner_employee_action

        # Account role is also checked by the common router; the leaf repeats
        # server identity and exact project checks, including request replays.
        # Serialize awaited calls without a new service/background loop. If the
        # await is cancelled, its thread may still finish; storage lock/CAS and
        # the original request journal, not cancellation, determine effects.
        lock = self.__dict__.get("_employee_asset_action_lock")
        if lock is None:
            lock = self.__dict__["_employee_asset_action_lock"] = asyncio.Lock()
        async with lock:
            reply = await asyncio.to_thread(
                dispatch_owner_employee_action, self, _socket_behind(ws), data,
                actor_source=_ws_owner_actor,
                server_loop=asyncio.get_running_loop(),
            )
        # A failed send does not retry a write or replace its request ID. The
        # original durable request is the only recovery key.
        try:
            await ws.send_json(reply)
        except asyncio.CancelledError:
            raise
        except Exception:
            # A callback may have delivered bytes before raising. Do not retry
            # or let the router replace a committed write with a generic failure
            # lacking the request key. Client receipt timeout stays unknown.
            logger.warning("Employee asset receipt delivery uncertain; recover original request")

    async def _handle_employee_workflow_trial(self, ws: Any, data: dict) -> None:
        from .employee_workflow_trial_ws import dispatch_owner_employee_workflow_trial
        reply = await dispatch_owner_employee_workflow_trial(self, ws, data)
        try:
            await ws.send_json({"type": "ack", "payload": reply})
        except asyncio.CancelledError:
            raise
        except Exception:
            # The original request may already own an order. Never replay it
            # because ACK transport did not confirm delivery.
            logger.warning("Employee workflow trial receipt delivery uncertain; recover original request")

    async def _handle_human_review_rework_confirm(self, ws: Any, data: dict) -> None:
        from ampuly.plugins.office_ui.employee_rework_confirm import confirm_owner_rework
        from ampuly.layer2_organization.human_review_rework import HumanReviewReworkError
        try:
            reply = await confirm_owner_rework(self, ws, data)
        except HumanReviewReworkError as exc:
            # Invalid frames cannot contribute an unvalidated correlation id.
            reply = {"action": "human_review_rework_confirm", "ok": False, "error": exc.code}
        try:
            await ws.send_json({"type": "ack", "payload": reply})
        except asyncio.CancelledError:
            raise
        except Exception:
            logger.warning("Rework confirmation receipt delivery uncertain; recover original request")

    async def _handle_human_review_rework_pending(self, ws: Any, data: dict) -> None:
        from ampuly.plugins.office_ui.employee_rework_pending import read_owner_rework_pending, lookup_owner_rework
        read = lookup_owner_rework if data.get("type") == "human_review_rework_lookup" else read_owner_rework_pending
        reply = await read(self, ws, data)
        try:
            await ws.send_json({"type": "ack", "payload": reply})
        except asyncio.CancelledError:
            raise
        except Exception:
            logger.warning("Rework read receipt delivery uncertain")

    async def _handle_human_review_rework_inspect(self, ws: Any, data: dict) -> None:
        from ampuly.plugins.office_ui.employee_rework_inspection_source import inspect_owner_rework

        reply = await inspect_owner_rework(self, _socket_behind(ws), data)
        try:
            # Existing console WS consumes ack.payload. The source's flat
            # result is private normalization, not a second wire protocol.
            payload = {key: value for key, value in reply.items() if key != "type"}
            await ws.send_json({"type": "ack", "payload": payload})
        except asyncio.CancelledError:
            raise
        except Exception:
            # Delivery may already have happened. No repeat and no generic
            # replacement acknowledgement with an unrelated correlation.
            logger.warning("Rework inspection receipt delivery uncertain")

